"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2735],{7716:(e,n,t)=>{t.d(n,{Wh:()=>s,mK:()=>a});let s=[{slug:"order-checkout",title:"Order checkout service",difficulty:"Medium",area:"backend",domains:["ecommerce","payments"],minutes:30,summary:"A first version of the checkout path: price the cart, apply a coupon, add shipping, charge the card, email the customer.",brief:["A teammate has opened this as a pull request and asked you to review it before it goes live.","Read the README first: it states what the code is supposed to do. Then read the code against it.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead. Be specific.","Not everything that looks unusual is a defect. A comment on code that is fine costs you as much as a missed bug would in a real review."],variants:{java:{entry:"README.md",files:{"README.md":'# Order checkout service\n\nTurns a cart into a paid order: prices the items, applies a coupon, adds\nshipping, charges the card, and emails the customer.\n\n## Usage\n\n```java\nOrder order = Checkout.checkout(\n    "user_123",\n    "cart_456",\n    "SAVE10",\n    false,  // isGift\n    true,   // notify\n    false   // express\n);\n```\n\n## API\n\n`Checkout.checkout(userId, cartId, couponCode, isGift, notify, express)` returns an\n`Order`. Coupon codes are case-insensitive. Expired coupons are rejected.\n\n## Notes for the reviewer\n\nFirst version of the checkout path. `Gateway` and `Mailer` are real modules;\n`Store` is the persistence layer (Postgres behind it, through the shared `Db`).\n',"src/Checkout.java":'package shop;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.logging.Logger;\n\n/** Checkout: cart -> priced -> discounted -> charged -> Order. */\npublic final class Checkout {\n    private static final Logger log = Logger.getLogger(Checkout.class.getName());\n\n    static final double EXPRESS_FEE = 9.99;\n    static final double STANDARD_FEE = 3.5;\n    static final double GIFT_WRAP = 2.0;\n\n    /** Shared between calls so the mailer can list every note of the day. */\n    private static final List<String> notes = new ArrayList<>();\n\n    public record Order(String id, String userId, double total, String status) {}\n\n    public static Order checkout(String userId, String cartId, String couponCode, boolean isGift, boolean notify, boolean express) {\n        Store.Cart cart = Store.loadCart(cartId);\n        if (cart.items().isEmpty()) {\n            throw new IllegalArgumentException("cart is empty");\n        }\n\n        double subtotal = 0.0;\n        for (Store.Item item : cart.items()) {\n            subtotal += item.price() * item.qty();\n        }\n\n        double total = subtotal;\n        if (couponCode != null && !couponCode.isEmpty()) {\n            Discounts.Coupon coupon = Discounts.loadCoupon(couponCode);\n            total = Discounts.applyCoupon(total, coupon);\n        }\n\n        total += express ? EXPRESS_FEE : STANDARD_FEE;\n        if (isGift) {\n            total += GIFT_WRAP;\n            notes.add("gift wrapped");\n        }\n\n        String orderId = "ord_" + (System.currentTimeMillis() / 1000);\n        String status = "PAID";\n        try {\n            Gateway.charge(userId, Money.round2(total));\n        } catch (Exception exc) {\n            log.info("charge failed for " + orderId + ": " + exc.getMessage());\n        }\n\n        Order order = new Order(orderId, userId, Money.round2(total), status);\n        Store.saveOrder(order);\n\n        if (notify) {\n            try {\n                Mailer.send(userId, String.format("Order %s confirmed: %.2f", orderId, order.total()), notes);\n            } catch (Exception exc) {\n                log.warning("could not email " + userId + ": " + exc.getMessage());\n            }\n        }\n\n        return order;\n    }\n}\n',"src/Discounts.java":'package shop;\n\nimport java.time.LocalDate;\nimport java.util.Map;\n\n/** Coupons: a fixed amount or a percentage off, from the coupons table. */\npublic final class Discounts {\n    public record Coupon(String code, String kind, double amount, LocalDate expiresAt) {}\n\n    public static Coupon loadCoupon(String code) {\n        Map<String, Object> row = Store.findCoupon(code);\n        if (row == null) {\n            throw new IllegalArgumentException("unknown coupon " + code);\n        }\n        return new Coupon((String) row.get("code"), (String) row.get("kind"),\n                ((Number) row.get("amount")).doubleValue(), (LocalDate) row.get("expires_at"));\n    }\n\n    public static double applyCoupon(double total, Coupon coupon) {\n        if (coupon.kind().equals("percent")) {\n            return total * (1 - coupon.amount() / 100);\n        }\n        return total - coupon.amount();\n    }\n}\n',"src/Store.java":'package shop;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Persistence. {@code Db} is the shared connection pool. */\npublic final class Store {\n    public record Item(String sku, double price, int qty) {}\n    public record Cart(String id, List<Item> items) {}\n\n    public static Cart loadCart(String cartId) {\n        List<Map<String, Object>> rows = Db.all("SELECT sku, price, qty FROM cart_items WHERE cart_id = ?", cartId);\n        return new Cart(cartId, rows.stream()\n                .map(r -> new Item((String) r.get("sku"), ((Number) r.get("price")).doubleValue(), ((Number) r.get("qty")).intValue()))\n                .toList());\n    }\n\n    /** Exact match on the code column. */\n    public static Map<String, Object> findCoupon(String code) {\n        return Db.one("SELECT code, kind, amount, expires_at FROM coupons WHERE code = ?", code);\n    }\n\n    public static void saveOrder(Checkout.Order order) {\n        Db.run("INSERT INTO orders (id, user_id, total, status) VALUES (?, ?, ?, ?)",\n                order.id(), order.userId(), order.total(), order.status());\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Order checkout service\n\nTurns a cart into a paid order: prices the items, applies a coupon, adds\nshipping, charges the card, and emails the customer.\n\n## Usage\n\n```python\nfrom checkout import checkout\n\norder = checkout(\n    "user_123",\n    "cart_456",\n    "SAVE10",\n    False,  # is_gift\n    True,   # notify\n    False,  # express\n)\nprint(order)\n```\n\n## API\n\n`checkout(user_id, cart_id, coupon_code, is_gift, notify, express)` returns an\n`Order`. Coupon codes are case-insensitive. Expired coupons are rejected.\n\n## Notes for the reviewer\n\nFirst version of the checkout path. The payment gateway and the mailer are\nreal modules; `store` is the persistence layer (Postgres behind it).\n',"src/checkout.py":'"""Checkout: cart -> priced -> discounted -> charged -> Order."""\nimport logging\nimport time\nfrom dataclasses import dataclass\n\nimport gateway\nimport mailer\nimport store\nfrom discounts import apply_coupon, load_coupon\n\nlog = logging.getLogger(__name__)\n\nEXPRESS_FEE = 9.99\nSTANDARD_FEE = 3.5\nGIFT_WRAP = 2.0\n\n\n@dataclass(frozen=True)\nclass Order:\n    id: str\n    user_id: str\n    total: float\n    status: str\n\n\ndef checkout(user_id, cart_id, coupon_code, is_gift, notify, express, notes=[]):\n    cart = store.load_cart(cart_id)\n    if not cart.items:\n        raise ValueError("cart is empty")\n\n    subtotal = 0.0\n    for item in cart.items:\n        subtotal += item.price * item.qty\n\n    total = subtotal\n    if coupon_code:\n        coupon = load_coupon(coupon_code)\n        total = apply_coupon(total, coupon)\n\n    total += EXPRESS_FEE if express else STANDARD_FEE\n    if is_gift:\n        total += GIFT_WRAP\n        notes.append("gift wrapped")\n\n    order_id = f"ord_{int(time.time())}"\n    status = "PAID"\n    try:\n        gateway.charge(user_id, round(total, 2))\n    except Exception as exc:\n        log.info("charge failed for %s: %s", order_id, exc)\n\n    order = Order(order_id, user_id, round(total, 2), status)\n    store.save_order(order)\n\n    if notify:\n        try:\n            mailer.send(user_id, f"Order {order_id} confirmed: {order.total:.2f}", notes)\n        except Exception as exc:\n            log.warning("could not email %s: %s", user_id, exc)\n\n    return order\n',"src/discounts.py":'"""Coupons: a fixed amount or a percentage off, from the coupons table."""\nfrom dataclasses import dataclass\nfrom datetime import date\n\nimport store\n\n\n@dataclass\nclass Coupon:\n    code: str\n    kind: str  # "fixed" or "percent"\n    amount: float\n    expires_at: date\n\n\ndef load_coupon(code):\n    row = store.find_coupon(code)\n    if row is None:\n        raise ValueError(f"unknown coupon {code}")\n    return Coupon(row["code"], row["kind"], float(row["amount"]), row["expires_at"])\n\n\ndef apply_coupon(total, coupon):\n    if coupon.kind == "percent":\n        return total * (1 - coupon.amount / 100)\n    return total - coupon.amount\n',"src/store.py":'"""Persistence. `db` is the shared psycopg connection pool."""\nfrom dataclasses import dataclass\n\nimport db\n\n\n@dataclass\nclass Item:\n    sku: str\n    price: float\n    qty: int\n\n\n@dataclass\nclass Cart:\n    id: str\n    items: list\n\n\ndef load_cart(cart_id):\n    rows = db.all("SELECT sku, price, qty FROM cart_items WHERE cart_id = %s", (cart_id,))\n    return Cart(cart_id, [Item(*r) for r in rows])\n\n\ndef find_coupon(code):\n    """Exact match on the code column."""\n    return db.one("SELECT code, kind, amount, expires_at FROM coupons WHERE code = %s", (code,))\n\n\ndef save_order(order):\n    db.run(\n        "INSERT INTO orders (id, user_id, total, status) VALUES (%s, %s, %s, %s)",\n        (order.id, order.user_id, order.total, order.status),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":'# Order checkout service\n\nTurns a cart into a paid order: prices the items, applies a coupon, adds\nshipping, charges the card, and emails the customer.\n\n## Usage\n\n```ts\nimport { checkout } from "./checkout";\n\nconst order = await checkout(\n  "user_123",\n  "cart_456",\n  "SAVE10",\n  false, // isGift\n  true,  // notify\n  false, // express\n);\n\nconsole.log(order);\n```\n\n## API\n\n`checkout(userId, cartId, couponCode, isGift, notify, express)` resolves to an\n`Order`. Coupon codes are case-insensitive. Expired coupons are rejected.\n\n## Notes for the reviewer\n\nFirst version of the checkout path. The payment gateway and the mailer are\nreal modules; `store` is the persistence layer (Postgres behind it).\n',"src/checkout.ts":'// Checkout: cart -> priced -> discounted -> charged -> Order.\nimport * as gateway from "./gateway";\nimport * as mailer from "./mailer";\nimport * as store from "./store";\nimport { applyCoupon, loadCoupon } from "./discounts";\n\nconst EXPRESS_FEE = 9.99;\nconst STANDARD_FEE = 3.5;\nconst GIFT_WRAP = 2;\n\nexport type Order = {\n  id: string;\n  userId: string;\n  total: number;\n  status: "PAID" | "FAILED";\n};\n\n// Lines printed on the packing slip, e.g. "gift wrapped".\nconst notes: string[] = [];\n\nexport async function checkout(\n  userId: string,\n  cartId: string,\n  couponCode: string,\n  isGift: boolean,\n  notify: boolean,\n  express: boolean,\n): Promise<Order> {\n  const cart = await store.loadCart(cartId);\n  if (cart.items.length === 0) throw new Error("cart is empty");\n\n  let subtotal = 0;\n  for (const item of cart.items) subtotal += item.price * item.qty;\n\n  let total = subtotal;\n  if (couponCode) {\n    const coupon = await loadCoupon(couponCode);\n    total = applyCoupon(total, coupon);\n  }\n\n  total += express ? EXPRESS_FEE : STANDARD_FEE;\n  if (isGift) {\n    total += GIFT_WRAP;\n    notes.push("gift wrapped");\n  }\n\n  const orderId = `ord_${Math.floor(Date.now() / 1000)}`;\n  let status: Order["status"] = "PAID";\n  try {\n    await gateway.charge(userId, Number(total.toFixed(2)));\n  } catch (err) {\n    console.info(`charge failed for ${orderId}: ${err}`);\n  }\n\n  const order: Order = { id: orderId, userId, total: Number(total.toFixed(2)), status };\n  await store.saveOrder(order);\n\n  if (notify) {\n    try {\n      await mailer.send(userId, `Order ${orderId} confirmed: ${order.total.toFixed(2)}`, notes);\n    } catch (err) {\n      console.warn(`could not email ${userId}: ${err}`);\n    }\n  }\n\n  return order;\n}\n',"src/discounts.ts":'// Coupons: a fixed amount or a percentage off, from the coupons table.\nimport * as store from "./store";\n\nexport type Coupon = {\n  code: string;\n  kind: "fixed" | "percent";\n  amount: number;\n  expiresAt: Date;\n};\n\nexport async function loadCoupon(code: string): Promise<Coupon> {\n  const row = await store.findCoupon(code);\n  if (!row) throw new Error(`unknown coupon ${code}`);\n  return { code: row.code, kind: row.kind, amount: Number(row.amount), expiresAt: row.expires_at };\n}\n\nexport function applyCoupon(total: number, coupon: Coupon): number {\n  if (coupon.kind === "percent") return total * (1 - coupon.amount / 100);\n  return total - coupon.amount;\n}\n',"src/store.ts":'// Persistence. `db` is the shared pg pool.\nimport { db } from "./db";\nimport type { Order } from "./checkout";\n\nexport type Item = { sku: string; price: number; qty: number };\nexport type Cart = { id: string; items: Item[] };\n\nexport async function loadCart(cartId: string): Promise<Cart> {\n  const rows = await db.all<Item>("SELECT sku, price, qty FROM cart_items WHERE cart_id = $1", [cartId]);\n  return { id: cartId, items: rows };\n}\n\n/** Exact match on the code column. */\nexport async function findCoupon(code: string) {\n  return db.one<{ code: string; kind: "fixed" | "percent"; amount: string; expires_at: Date }>(\n    "SELECT code, kind, amount, expires_at FROM coupons WHERE code = $1",\n    [code],\n  );\n}\n\nexport async function saveOrder(order: Order): Promise<void> {\n  await db.run("INSERT INTO orders (id, user_id, total, status) VALUES ($1, $2, $3, $4)", [\n    order.id,\n    order.userId,\n    order.total,\n    order.status,\n  ]);\n}\n'}}}},{slug:"memoize",title:"memoize decorator",difficulty:"Medium",area:"backend",domains:["ecommerce"],minutes:25,summary:"A small cache-by-arguments wrapper for pure functions, used on the pricing and catalogue helpers.",brief:["A teammate has opened this as a pull request. It is twenty lines, and it sits under code that runs thousands of times per request.","Read the contract in the README, then think about the cache key, what gets stored, what expires, and what the caller receives.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Look at pricing too: how the helper is used decides whether some of this matters."],variants:{java:{entry:"README.md",files:{"README.md":"# Memoize\n\nA wrapper that caches a function's return value by its arguments, for the\npricing and catalogue helpers that are called thousands of times per request.\n\n## Contract\n\n- Same arguments, same result, without calling the function again.\n- Entries expire after `ttl` seconds.\n- Safe to put on any pure function, including ones that return `null`.\n\n## Notes for the reviewer\n\nUsed on `Pricing.priceFor(sku, currency)` and on\n`Pricing.children(categoryId)`, which returns a list the caller renders.\n","src/Memoize.java":'package cache;\n\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.function.Function;\n\n/** Cache a pure function\'s results by argument. */\npublic final class Memoize {\n    private record Entry(Object value, long storedAt) {}\n\n    /** Wraps {@code fn}; {@code ttl} is in seconds. */\n    public static <A, R> Function<A[], R> memoize(long ttl, Function<A[], R> fn) {\n        Map<String, Entry> cache = new HashMap<>();\n        return args -> {\n            String key = String.valueOf(args.length) + ":" + args[0];\n            Entry hit = cache.get(key);\n            if (hit != null) {\n                if (System.currentTimeMillis() - hit.storedAt() < ttl) {\n                    @SuppressWarnings("unchecked") R cached = (R) hit.value();\n                    return cached;\n                }\n            }\n            R value = fn.apply(args);\n            if (value != null) cache.put(key, new Entry(value, System.currentTimeMillis()));\n            return value;\n        };\n    }\n}\n',"src/Pricing.java":'package cache;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.function.Function;\n\n/** Where memoize is used. */\npublic final class Pricing {\n    private static final Function<Object[], Integer> PRICE = Memoize.memoize(60, args -> {\n        Map<String, Object> row = Db.one("SELECT amount FROM prices WHERE sku = ? AND currency = ?", args[0], args[1]);\n        return row == null ? null : (Integer) row.get("amount");\n    });\n\n    private static final Function<Object[], List<Map<String, Object>>> CHILDREN = Memoize.memoize(600, args ->\n        Db.all("SELECT id, name FROM categories WHERE parent_id = ? ORDER BY name", args[0]));\n\n    public static Integer priceFor(String sku, String currency) {\n        return PRICE.apply(new Object[] { sku, currency });\n    }\n\n    public static List<Map<String, Object>> children(long categoryId) {\n        return CHILDREN.apply(new Object[] { categoryId });\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# memoize\n\nA decorator that caches a function\'s return value by its arguments, for the\npricing and catalogue helpers that are called thousands of times per request.\n\n## Contract\n\n- Same arguments, same result, without calling the function again.\n- Entries expire after `ttl` seconds.\n- Safe to put on any pure function, including ones that return `None`.\n\n## Notes for the reviewer\n\nUsed on `pricing.price_for(sku, currency="INR")` and on\n`catalogue.children(category_id)`, which returns a list the caller renders.\n',"src/memoize.py":'"""Cache a pure function\'s results by argument."""\nimport functools\nimport time\n\n\ndef memoize(ttl=300):\n    def wrap(fn):\n        cache = {}\n\n        @functools.wraps(fn)\n        def inner(*args, **kwargs):\n            key = str(args)\n            hit = cache.get(key)\n            if hit:\n                value, stored_at = hit\n                if time.time() - stored_at < ttl:\n                    return value\n            value = fn(*args, **kwargs)\n            if value is not None:\n                cache[key] = (value, time.time())\n            return value\n\n        inner.cache = cache\n        return inner\n\n    return wrap\n',"src/pricing.py":'"""Where memoize is used."""\nfrom memoize import memoize\n\nimport db\n\n\n@memoize(ttl=60)\ndef price_for(sku, currency="INR"):\n    row = db.one("SELECT amount FROM prices WHERE sku = %s AND currency = %s", (sku, currency))\n    return row["amount"] if row else None\n\n\n@memoize(ttl=600)\ndef children(category_id):\n    rows = db.all("SELECT id, name FROM categories WHERE parent_id = %s ORDER BY name", (category_id,))\n    return [dict(r) for r in rows]\n'}},typescript:{entry:"README.md",files:{"README.md":'# memoize\n\nA wrapper that caches a function\'s return value by its arguments, for the\npricing and catalogue helpers that are called thousands of times per request.\n\n## Contract\n\n- Same arguments, same result, without calling the function again.\n- Entries expire after `ttl` seconds.\n- Safe to put on any pure function, including ones that resolve to `null`.\n\n## Notes for the reviewer\n\nUsed on `priceFor(sku, currency = "INR")` and on `children(categoryId)`,\nwhich resolves to an array the caller renders.\n',"src/memoize.ts":'// Cache a pure async function\'s results by argument.\ntype Fn<A extends unknown[], R> = (...args: A) => Promise<R>;\n\nexport function memoize<A extends unknown[], R>(fn: Fn<A, R>, ttl = 300): Fn<A, R> & { cache: Map<string, [R, number]> } {\n  const cache = new Map<string, [R, number]>();\n  const inner = async (...args: A): Promise<R> => {\n    const key = args.join(",");\n    const hit = cache.get(key);\n    if (hit) {\n      const [value, storedAt] = hit;\n      if (Date.now() - storedAt < ttl) return value;\n    }\n    const value = await fn(...args);\n    if (value !== null && value !== undefined) cache.set(key, [value, Date.now()]);\n    return value;\n  };\n  return Object.assign(inner, { cache });\n}\n',"src/pricing.ts":'// Where memoize is used.\nimport { db } from "./db";\nimport { memoize } from "./memoize";\n\nexport const priceFor = memoize(async (sku: string, currency = "INR"): Promise<number | null> => {\n  const row = await db.one<{ amount: number }>("SELECT amount FROM prices WHERE sku = $1 AND currency = $2", [sku, currency]);\n  return row ? row.amount : null;\n}, 60);\n\nexport const children = memoize(async (categoryId: number): Promise<{ id: number; name: string }[]> => {\n  return db.all("SELECT id, name FROM categories WHERE parent_id = $1 ORDER BY name", [categoryId]);\n}, 600);\n'}}}},{slug:"pagination-api",title:"Paginated users endpoint",difficulty:"Medium",area:"backend",domains:["saas"],minutes:25,summary:"GET /users for the admin table: page, limit, sort and direction from the query string.",brief:["A teammate has opened this as a pull request. It is one function, and it is the endpoint the admin table lives on.","Read the README for the query contract and the table columns, then check every parameter from the query string on its way into SQL.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Parts of this are done correctly. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# GET /users\n\nLists users for the admin table, newest first by default.\n\n## Query parameters\n\n- `page`: 1-based, default 1\n- `limit`: rows per page, default 25, maximum 100\n- `sort`: `created_at` (default), `name` or `email`\n- `dir`: `asc` or `desc` (default)\n\n## Response\n\n```json\n{ "rows": [ { "id": 1, "email": "...", "name": "...", "created_at": "..." } ],\n  "page": 1, "limit": 25, "total": 1234 }\n```\n\n## Notes for the reviewer\n\nThe `users` table has `id, email, name, password_hash, role, created_at`.\n`Db` is the shared connection pool; `Db.all` returns each row as a map.\n',"src/UsersApi.java":'package admin;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\n/** GET /users: a page of the users table. */\npublic final class UsersApi {\n    static final int DEFAULT_LIMIT = 25;\n    static final int MAX_LIMIT = 100;\n    static final Set<String> SORTABLE = Set.of("created_at", "name", "email");\n\n    public static Map<String, Object> listUsers(Map<String, String> query) {\n        int page = Integer.parseInt(query.getOrDefault("page", "1"));\n        int limit = Integer.parseInt(query.getOrDefault("limit", String.valueOf(DEFAULT_LIMIT)));\n        String sort = query.getOrDefault("sort", "created_at");\n        String direction = "asc".equals(query.get("dir")) ? "ASC" : "DESC";\n\n        if (limit < 1) {\n            limit = DEFAULT_LIMIT;\n        }\n        int offset = page * limit;\n\n        List<Map<String, Object>> rows = Db.all(\n            "SELECT * FROM users ORDER BY " + sort + " " + direction + " LIMIT ? OFFSET ?",\n            limit, offset);\n        long total = ((Number) Db.one("SELECT count(*) AS n FROM users").get("n")).longValue();\n        return Map.of("rows", rows, "page", page, "limit", limit, "total", total);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# GET /users\n\nLists users for the admin table, newest first by default.\n\n## Query parameters\n\n- `page`: 1-based, default 1\n- `limit`: rows per page, default 25, maximum 100\n- `sort`: `created_at` (default), `name` or `email`\n- `dir`: `asc` or `desc` (default)\n\n## Response\n\n```json\n{ "rows": [ { "id": 1, "email": "...", "name": "...", "created_at": "..." } ],\n  "page": 1, "limit": 25, "total": 1234 }\n```\n\n## Notes for the reviewer\n\nThe `users` table has `id, email, name, password_hash, role, created_at`.\n`db` is the shared psycopg pool.\n',"src/users_api.py":'"""GET /users: a page of the users table."""\nimport db\n\nDEFAULT_LIMIT = 25\nMAX_LIMIT = 100\nSORTABLE = ("created_at", "name", "email")\n\n\ndef list_users(query):\n    page = int(query.get("page", 1))\n    limit = int(query.get("limit", DEFAULT_LIMIT))\n    sort = query.get("sort", "created_at")\n    direction = "ASC" if query.get("dir") == "asc" else "DESC"\n\n    if limit < 1:\n        limit = DEFAULT_LIMIT\n    offset = page * limit\n\n    rows = db.all(\n        f"SELECT * FROM users ORDER BY {sort} {direction} LIMIT %s OFFSET %s",\n        (limit, offset),\n    )\n    total = db.one("SELECT count(*) AS n FROM users")["n"]\n    return {"rows": [dict(r) for r in rows], "page": page, "limit": limit, "total": total}\n'}},typescript:{entry:"README.md",files:{"README.md":'# GET /users\n\nLists users for the admin table, newest first by default.\n\n## Query parameters\n\n- `page`: 1-based, default 1\n- `limit`: rows per page, default 25, maximum 100\n- `sort`: `created_at` (default), `name` or `email`\n- `dir`: `asc` or `desc` (default)\n\n## Response\n\n```json\n{ "rows": [ { "id": 1, "email": "...", "name": "...", "created_at": "..." } ],\n  "page": 1, "limit": 25, "total": 1234 }\n```\n\n## Notes for the reviewer\n\nThe `users` table has `id, email, name, password_hash, role, created_at`.\n`db` is the shared pg pool.\n',"src/usersApi.ts":'// GET /users: a page of the users table.\nimport { db } from "./db";\n\nconst DEFAULT_LIMIT = 25;\nconst MAX_LIMIT = 100;\nconst SORTABLE = ["created_at", "name", "email"];\n\ntype Query = Record<string, string | undefined>;\n\nexport async function listUsers(query: Query) {\n  const page = Number(query.page ?? 1);\n  let limit = Number(query.limit ?? DEFAULT_LIMIT);\n  const sort = query.sort ?? "created_at";\n  const direction = query.dir === "asc" ? "ASC" : "DESC";\n\n  if (!(limit >= 1)) limit = DEFAULT_LIMIT;\n  const offset = page * limit;\n\n  const rows = await db.all(`SELECT * FROM users ORDER BY ${sort} ${direction} LIMIT $1 OFFSET $2`, [limit, offset]);\n  const total = (await db.one<{ n: number }>("SELECT count(*)::int AS n FROM users"))!.n;\n  return { rows, page, limit, total };\n}\n'}}}},{slug:"csv-import",title:"Bulk user import",difficulty:"Medium",area:"backend",domains:["identity"],minutes:25,summary:"Admins upload a CSV of new users; we create the accounts and email each person a set-your-password link.",brief:["A teammate has opened this as a pull request. It creates accounts in bulk, so a mistake here is repeated a thousand times.","Read the README rules (header, any column order, case-insensitive emails, all-or-nothing) and check each one against the code.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","The CSV parsing itself is fine; the trouble is around it."],variants:{java:{entry:"README.md",files:{"README.md":"# Bulk user import\n\nAdmins upload a CSV of new users (`email,name,role`) and we create the\naccounts and email each person a set-your-password link.\n\n## Rules\n\n- Header row required, columns may come in any order.\n- Emails are case-insensitive; an address that already exists is skipped and\n  reported, never duplicated.\n- The import is all-or-nothing: a bad row fails the whole file with a message\n  that names the row.\n\n## Notes for the reviewer\n\n`Db` is the shared connection pool; `Db.transaction(Runnable)` commits when the\nblock returns and rolls back on exception. `Mailer.sendSetupLink(email)` emails\nthe link. `Csv.parse` is our existing RFC 4180 reader.\n","src/Importer.java":'package admin;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** POST /admin/users/import */\npublic final class Importer {\n    private static final Logger log = Logger.getLogger(Importer.class.getName());\n\n    static final String DEFAULT_PASSWORD = "Welcome123";\n\n    public record Result(int created, List<String> skipped) {}\n\n    public static Result importUsers(String text) {\n        List<String[]> rows = Csv.parse(text);\n        rows.remove(0); // header\n        int created = 0;\n        List<String> skipped = new ArrayList<>();\n        int n = 1;\n        for (String[] row : rows) {\n            n++;\n            try {\n                String email = row[0], name = row[1], role = row[2];\n                if (Db.one("SELECT 1 FROM users WHERE email = ?", email) != null) {\n                    skipped.add(email);\n                    continue;\n                }\n                Db.run("INSERT INTO users (email, name, role, password_hash) VALUES (?, ?, ?, ?)",\n                        email, name, role, Security.hashPassword(DEFAULT_PASSWORD));\n                Mailer.sendSetupLink(email);\n                created++;\n            } catch (Exception e) {\n                continue;\n            }\n        }\n        log.info("imported " + created + " users, skipped " + skipped.size());\n        return new Result(created, skipped);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Bulk user import\n\nAdmins upload a CSV of new users (`email,name,role`) and we create the\naccounts and email each person a set-your-password link.\n\n## Rules\n\n- Header row required, columns may come in any order.\n- Emails are case-insensitive; an address that already exists is skipped and\n  reported, never duplicated.\n- The import is all-or-nothing: a bad row fails the whole file with a message\n  that names the row.\n\n## Notes for the reviewer\n\n`db` is the shared psycopg pool; `db.transaction()` commits on exit and rolls\nback on exception. `mailer.send_setup_link(email)` emails the link.\n","src/importer.py":'"""POST /admin/users/import"""\nimport csv\nimport io\nimport logging\n\nimport db\nimport mailer\nfrom security import hash_password\n\nlog = logging.getLogger(__name__)\n\nDEFAULT_PASSWORD = "Welcome123"\n\n\ndef import_users(upload):\n    text = upload.read().decode("utf-8")\n    reader = csv.reader(io.StringIO(text))\n    next(reader)  # header\n    created = 0\n    skipped = []\n    for n, row in enumerate(reader, start=2):\n        try:\n            email, name, role = row[0], row[1], row[2]\n            if db.one("SELECT 1 FROM users WHERE email = %s", (email,)):\n                skipped.append(email)\n                continue\n            db.run(\n                "INSERT INTO users (email, name, role, password_hash) VALUES (%s, %s, %s, %s)",\n                (email, name, role, hash_password(DEFAULT_PASSWORD)),\n            )\n            mailer.send_setup_link(email)\n            created += 1\n        except Exception:\n            continue\n    log.info("imported %s users, skipped %s", created, len(skipped))\n    return {"created": created, "skipped": skipped}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Bulk user import\n\nAdmins upload a CSV of new users (`email,name,role`) and we create the\naccounts and email each person a set-your-password link.\n\n## Rules\n\n- Header row required, columns may come in any order.\n- Emails are case-insensitive; an address that already exists is skipped and\n  reported, never duplicated.\n- The import is all-or-nothing: a bad row fails the whole file with a message\n  that names the row.\n\n## Notes for the reviewer\n\n`db` is the shared pg pool; `db.transaction(fn)` commits when `fn` resolves\nand rolls back when it throws. `mailer.sendSetupLink(email)` emails the link.\n`parseCsv` is our tested CSV parser and returns an array of string arrays.\n","src/importer.ts":'// POST /admin/users/import\nimport { db } from "./db";\nimport * as mailer from "./mailer";\nimport { parseCsv } from "./csv";\nimport { hashPassword } from "./security";\n\nconst DEFAULT_PASSWORD = "Welcome123";\n\nexport async function importUsers(text: string) {\n  const rows = parseCsv(text);\n  rows.shift(); // header\n  let created = 0;\n  const skipped: string[] = [];\n  for (const row of rows) {\n    try {\n      const [email, name, role] = row;\n      if (await db.one("SELECT 1 FROM users WHERE email = $1", [email])) {\n        skipped.push(email);\n        continue;\n      }\n      await db.run("INSERT INTO users (email, name, role, password_hash) VALUES ($1, $2, $3, $4)", [\n        email,\n        name,\n        role,\n        await hashPassword(DEFAULT_PASSWORD),\n      ]);\n      await mailer.sendSetupLink(email);\n      created += 1;\n    } catch {\n      continue;\n    }\n  }\n  console.info(`imported ${created} users, skipped ${skipped.length}`);\n  return { created, skipped };\n}\n'}}}},{slug:"url-shortener",title:"URL shortener",difficulty:"Medium",area:"backend",domains:["social"],minutes:25,summary:"Create six-character codes for long URLs, redirect visitors, count clicks, and let owners change the target later.",brief:["A teammate has opened this as a pull request. Three small endpoints; the README states the rules for each.","Check every rule in the README against the code, and think about what a visitor and an attacker can each do with a code.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of it is right. Do not comment on the parts that are."],variants:{java:{entry:"README.md",files:{"README.md":'# URL shortener\n\n`POST /shorten` with `{"url": "https://..."}` returns `{"code": "aB3x9k"}`;\n`GET /<code>` sends the visitor to the long URL and counts the click.\n\n## Rules\n\n- Only `http` and `https` URLs, at most 2,048 characters.\n- Codes are 6 characters, unguessable, and never reused.\n- The target of a code can be changed later by its owner (`PUT /<code>`), so\n  visitors must always be sent to the current target.\n\n## Notes for the reviewer\n\n`Db` is the shared connection pool. The `links` table has\n`code, url, owner_id, clicks, created_at` with a unique index on `code`.\n`Response.of(status, body)` builds the HTTP response; `Response.redirect(status, url)` sets `Location`.\n',"src/Shortener.java":'package links;\n\nimport java.util.Map;\nimport java.util.Random;\n\n/** Create and resolve short links. */\npublic final class Shortener {\n    static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";\n    static final int MAX_URL = 2048;\n    private static final Random random = new Random();\n\n    static String newCode() {\n        StringBuilder sb = new StringBuilder(6);\n        for (int i = 0; i < 6; i++) sb.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));\n        return sb.toString();\n    }\n\n    public static Response shorten(long ownerId, String url) {\n        if (url.length() > MAX_URL) {\n            return Response.of(400, "url too long");\n        }\n        String code = newCode();\n        Db.run("INSERT INTO links (code, url, owner_id, clicks) VALUES (?, ?, ?, 0)", code, url, ownerId);\n        return Response.of(200, Map.of("code", code));\n    }\n\n    public static Response resolve(String code) {\n        Map<String, Object> row = Db.one("SELECT url, clicks FROM links WHERE code = \'" + code + "\'");\n        if (row == null) {\n            return Response.of(404, null);\n        }\n        Db.run("UPDATE links SET clicks = ? WHERE code = ?", ((Number) row.get("clicks")).longValue() + 1, code);\n        return Response.redirect(301, (String) row.get("url"));\n    }\n\n    public static Response retarget(long ownerId, String code, String url) {\n        Db.run("UPDATE links SET url = ? WHERE code = ? AND owner_id = ?", url, code, ownerId);\n        return Response.of(200, Map.of("code", code));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# URL shortener\n\n`POST /shorten` with `{"url": "https://..."}` returns `{"code": "aB3x9k"}`;\n`GET /<code>` sends the visitor to the long URL and counts the click.\n\n## Rules\n\n- Only `http` and `https` URLs, at most 2,048 characters.\n- Codes are 6 characters, unguessable, and never reused.\n- The target of a code can be changed later by its owner (`PUT /<code>`), so\n  visitors must always be sent to the current target.\n\n## Notes for the reviewer\n\n`db` is the shared psycopg pool. The `links` table has\n`code, url, owner_id, clicks, created_at` with a unique index on `code`.\n',"src/shortener.py":'"""Create and resolve short links."""\nimport random\nimport string\n\nimport db\n\nALPHABET = string.ascii_letters + string.digits\nMAX_URL = 2048\n\n\ndef new_code():\n    return "".join(random.choice(ALPHABET) for _ in range(6))\n\n\ndef shorten(owner_id, url):\n    if len(url) > MAX_URL:\n        return 400, "url too long"\n    code = new_code()\n    db.run("INSERT INTO links (code, url, owner_id, clicks) VALUES (%s, %s, %s, 0)", (code, url, owner_id))\n    return 200, {"code": code}\n\n\ndef resolve(code):\n    row = db.one(f"SELECT url, clicks FROM links WHERE code = \'{code}\'")\n    if row is None:\n        return 404, None\n    db.run("UPDATE links SET clicks = %s WHERE code = %s", (row["clicks"] + 1, code))\n    return 301, row["url"]\n\n\ndef retarget(owner_id, code, url):\n    db.run("UPDATE links SET url = %s WHERE code = %s AND owner_id = %s", (url, code, owner_id))\n    return 200, {"code": code}\n'}},typescript:{entry:"README.md",files:{"README.md":'# URL shortener\n\n`POST /shorten` with `{"url": "https://..."}` returns `{"code": "aB3x9k"}`;\n`GET /:code` sends the visitor to the long URL and counts the click.\n\n## Rules\n\n- Only `http` and `https` URLs, at most 2,048 characters.\n- Codes are 6 characters, unguessable, and never reused.\n- The target of a code can be changed later by its owner (`PUT /:code`), so\n  visitors must always be sent to the current target.\n\n## Notes for the reviewer\n\n`db` is the shared pg pool. The `links` table has\n`code, url, owner_id, clicks, created_at` with a unique index on `code`.\n',"src/shortener.ts":'// Create and resolve short links.\nimport { db } from "./db";\n\nconst ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";\nconst MAX_URL = 2048;\n\nexport function newCode(): string {\n  let out = "";\n  for (let i = 0; i < 6; i++) out += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];\n  return out;\n}\n\nexport async function shorten(ownerId: string, url: string): Promise<[number, unknown]> {\n  if (url.length > MAX_URL) return [400, "url too long"];\n  const code = newCode();\n  await db.run("INSERT INTO links (code, url, owner_id, clicks) VALUES ($1, $2, $3, 0)", [code, url, ownerId]);\n  return [200, { code }];\n}\n\nexport async function resolve(code: string): Promise<[number, string | null]> {\n  const row = await db.one<{ url: string; clicks: number }>(`SELECT url, clicks FROM links WHERE code = \'${code}\'`);\n  if (!row) return [404, null];\n  await db.run("UPDATE links SET clicks = $1 WHERE code = $2", [row.clicks + 1, code]);\n  return [301, row.url];\n}\n\nexport async function retarget(ownerId: string, code: string, url: string): Promise<[number, unknown]> {\n  await db.run("UPDATE links SET url = $1 WHERE code = $2 AND owner_id = $3", [url, code, ownerId]);\n  return [200, { code }];\n}\n'}}}},{slug:"search-endpoint",title:"Product search",difficulty:"Medium",area:"backend",domains:["ecommerce"],minutes:25,summary:"The storefront search endpoint: a LIKE query with filters, sorting and paging, plus the category for each result.",brief:["A teammate has opened this as a pull request. The README gives the table columns and the size of the catalogue; keep both in mind.","Read the SQL that gets built for a few inputs: a quote in the search box, an empty query, page 3 of a category.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# GET /products/search\n\nThe storefront search box. Matches the query against product names and\ndescriptions, optionally within a category, sorted by relevance or price.\n\n## Query parameters\n\n- `q`: the search text; matching is case-insensitive.\n- `category`: a category id.\n- `sort`: `relevance` (default) or `price`.\n- `page`: 1-based, 24 products a page.\n\n## Response\n\n`{ "products": [ { "id", "name", "price", "category": { "id", "name" } } ], "page" }`\n\n## Notes for the reviewer\n\n`products` has `id, name, description, price, cost_price, category_id,\nsupplier_id, created_at`. `Db` is the shared pool; about 200,000 products.\n',"src/Search.java":'package storefront;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** GET /products/search */\npublic final class Search {\n    static final int PAGE_SIZE = 24;\n\n    public static Map<String, Object> search(Map<String, String> query) {\n        String q = query.getOrDefault("q", "");\n        String category = query.get("category");\n        String sort = "price".equals(query.get("sort")) ? "price ASC" : "created_at DESC";\n        int page = Math.max(1, Integer.parseInt(query.getOrDefault("page", "1")));\n\n        String sql = "SELECT * FROM products WHERE (name LIKE \'%" + q + "%\' OR description LIKE \'%" + q + "%\')";\n        List<Object> params = new ArrayList<>();\n        if (category != null) {\n            sql += " AND category_id = ?";\n            params.add(category);\n        }\n        sql += " ORDER BY " + sort;\n        if (!q.isEmpty()) {\n            sql += " OFFSET ?";\n            params.add((page - 1) * PAGE_SIZE);\n        }\n\n        List<Map<String, Object>> products = new ArrayList<>();\n        for (Map<String, Object> row : Db.all(sql, params.toArray())) {\n            Map<String, Object> cat = Db.one("SELECT id, name FROM categories WHERE id = ?", row.get("category_id"));\n            Map<String, Object> out = new HashMap<>(row);\n            out.put("category", cat);\n            products.add(out);\n        }\n        return Map.of("products", products, "page", page);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# GET /products/search\n\nThe storefront search box. Matches the query against product names and\ndescriptions, optionally within a category, sorted by relevance or price.\n\n## Query parameters\n\n- `q`: the search text; matching is case-insensitive.\n- `category`: a category id.\n- `sort`: `relevance` (default) or `price`.\n- `page`: 1-based, 24 products a page.\n\n## Response\n\n`{ "products": [ { "id", "name", "price", "category": { "id", "name" } } ], "page" }`\n\n## Notes for the reviewer\n\n`products` has `id, name, description, price, cost_price, category_id,\nsupplier_id, created_at`. `db` is the shared pool; about 200,000 products.\n',"src/search.py":'"""GET /products/search"""\nimport db\n\nPAGE_SIZE = 24\n\n\ndef search(query):\n    q = query.get("q", "")\n    category = query.get("category")\n    sort = "price ASC" if query.get("sort") == "price" else "created_at DESC"\n    page = max(1, int(query.get("page", 1)))\n\n    sql = "SELECT * FROM products WHERE (name LIKE \'%" + q + "%\' OR description LIKE \'%" + q + "%\')"\n    params = []\n    if category:\n        sql += " AND category_id = %s"\n        params.append(category)\n    sql += " ORDER BY " + sort\n    if q:\n        sql += " OFFSET %s"\n        params.append((page - 1) * PAGE_SIZE)\n\n    products = []\n    for row in db.all(sql, tuple(params)):\n        cat = db.one("SELECT id, name FROM categories WHERE id = %s", (row["category_id"],))\n        products.append({**row, "category": dict(cat) if cat else None})\n    return {"products": products, "page": page}\n'}},typescript:{entry:"README.md",files:{"README.md":'# GET /products/search\n\nThe storefront search box. Matches the query against product names and\ndescriptions, optionally within a category, sorted by relevance or price.\n\n## Query parameters\n\n- `q`: the search text; matching is case-insensitive.\n- `category`: a category id.\n- `sort`: `relevance` (default) or `price`.\n- `page`: 1-based, 24 products a page.\n\n## Response\n\n`{ "products": [ { "id", "name", "price", "category": { "id", "name" } } ], "page" }`\n\n## Notes for the reviewer\n\n`products` has `id, name, description, price, cost_price, category_id,\nsupplier_id, created_at`. `db` is the shared pool; about 200,000 products.\n',"src/search.ts":'// GET /products/search\nimport { db } from "./db";\n\nconst PAGE_SIZE = 24;\n\nexport async function search(query: Record<string, string | undefined>) {\n  const q = query.q ?? "";\n  const category = query.category;\n  const sort = query.sort === "price" ? "price ASC" : "created_at DESC";\n  const page = Math.max(1, Number(query.page ?? 1));\n\n  let sql = "SELECT * FROM products WHERE (name LIKE \'%" + q + "%\' OR description LIKE \'%" + q + "%\')";\n  const params: unknown[] = [];\n  if (category) {\n    sql += ` AND category_id = $${params.length + 1}`;\n    params.push(category);\n  }\n  sql += " ORDER BY " + sort;\n  if (q) {\n    sql += ` OFFSET $${params.length + 1}`;\n    params.push((page - 1) * PAGE_SIZE);\n  }\n\n  const products = [];\n  for (const row of await db.all<Record<string, unknown>>(sql, params)) {\n    const cat = await db.one("SELECT id, name FROM categories WHERE id = $1", [row.category_id]);\n    products.push({ ...row, category: cat ?? null });\n  }\n  return { products, page };\n}\n'}}}},{slug:"signup-form",title:"Signup form",difficulty:"Medium",area:"frontend",domains:["identity"],minutes:25,summary:"A React signup form with client-side validation, a remember-me option and server error display, on a public page where third-party scripts also run.",brief:["A teammate has opened this as a pull request. Read the README for what the API does and what else runs on the page.","Think about what the browser stores, what goes over the wire, what the effects do on every keystroke, and what a fast double click does.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct React; a comment on those costs you."],variants:{typescript:{entry:"README.md",files:{"README.md":'# Signup form\n\nThe account creation form on the marketing site: email, password, and a\n"remember me on this device" checkbox. Posts to `POST /api/signup`, which\ncreates the account and returns a session.\n\n## Rules\n\n- Email and password are required; passwords are at least 10 characters.\n- The API validates everything again and returns `{ "error": "..." }` with\n  a `400` when something is wrong, including a message that may mention the\n  email that was submitted.\n- Submitting twice must not create two accounts.\n\n## Notes for the reviewer\n\nReact 18 with TypeScript. `api.post` is our fetch wrapper. The form is\nrendered on the public site, where third-party scripts also run.\n',"src/SignupForm.tsx":'import { useEffect, useState } from "react";\nimport { api } from "./api";\nimport { validate } from "./validate";\n\nexport function SignupForm({ onDone }: { onDone: (sessionId: string) => void }) {\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [remember, setRemember] = useState(false);\n  const [errors, setErrors] = useState<string[]>([]);\n  const [serverError, setServerError] = useState<string | null>(null);\n\n  useEffect(() => {\n    setErrors(validate(email, password));\n  }, [email, password, errors]);\n\n  useEffect(() => {\n    if (remember) {\n      localStorage.setItem("signup.email", email);\n      localStorage.setItem("signup.password", password);\n    }\n  }, [remember, email, password]);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    if (errors.length > 0) return;\n    setServerError(null);\n    const res = await api.post(`/api/signup?email=${encodeURIComponent(email)}&password=${encodeURIComponent(password)}`, {});\n    if (!res.ok) {\n      setServerError(res.error);\n      return;\n    }\n    onDone(res.sessionId);\n  }\n\n  return (\n    <form onSubmit={submit}>\n      <label>\n        Email\n        <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" />\n      </label>\n      <label>\n        Password\n        <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="new-password" />\n      </label>\n      <label>\n        <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} /> Remember me on this device\n      </label>\n      {errors.length > 0 && (\n        <ul className="errors">\n          {errors.map((err, i) => (\n            <li key={i}>{err}</li>\n          ))}\n        </ul>\n      )}\n      {serverError && <p className="error" dangerouslySetInnerHTML={{ __html: serverError }} />}\n      <button type="submit">Create account</button>\n    </form>\n  );\n}\n',"src/validate.ts":'const EMAIL = /^[a-z0-9._-]+@[a-z0-9.-]+\\.[a-z]{2,}$/;\n\nexport function validate(email: string, password: string): string[] {\n  const errors: string[] = [];\n  if (!EMAIL.test(email)) errors.push("Enter a valid email address.");\n  if (password.length < 10) errors.push("Password must be at least 10 characters.");\n  return errors;\n}\n'}}}},{slug:"coupon-tests",title:"Tests for the coupon validator",difficulty:"Medium",area:"testing",domains:["ecommerce"],minutes:20,summary:'A test-only PR: six tests for a small validator, "all green". Reviewing tests means asking what each one would catch if the code were wrong.',brief:["A teammate has opened this as a pull request that only adds tests. The validator is included unchanged for reference.","For each test ask: what is mocked, what is asserted, and could this test fail if the validator were broken? Then look at what it costs CI.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of the tests are fine; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Tests for the coupon validator\n\n`validateCoupon` had no tests. This PR adds a suite; the description says\n"100% line coverage, all green". The validator itself is unchanged and is\nincluded for reference.\n\n## What the validator promises\n\n- Unknown code: `Result.rejected("unknown")`.\n- Expired code (expires_at before today): `Result.rejected("expired")`.\n- Used up (`redeemed >= max_redemptions`): `Result.rejected("exhausted")`.\n- Otherwise `Result.accepted(coupon)`.\n- Codes are compared case-insensitively.\n\n## Notes for the reviewer\n\n`Store.findCoupon(code)` is the only dependency. The suite runs in CI on\nevery push; CI currently takes 4 minutes.\n',"src/Coupons.java":'package promo;\n\nimport java.time.LocalDate;\n\n/** Coupon validation. */\npublic final class Coupons {\n    public record Coupon(String code, LocalDate expiresAt, int redeemed, int maxRedemptions) {}\n    public record Result(boolean ok, String reason, Coupon coupon) {\n        static Result rejected(String reason) { return new Result(false, reason, null); }\n        static Result accepted(Coupon c) { return new Result(true, null, c); }\n    }\n\n    public static Result validateCoupon(String code, LocalDate today) {\n        Coupon coupon = Store.findCoupon(code.toUpperCase());\n        if (coupon == null) return Result.rejected("unknown");\n        if (coupon.expiresAt().isBefore(today)) return Result.rejected("expired");\n        if (coupon.redeemed() >= coupon.maxRedemptions()) return Result.rejected("exhausted");\n        return Result.accepted(coupon);\n    }\n}\n',"src/test/CouponsTest.java":'package promo;\n\nimport static org.junit.jupiter.api.Assertions.*;\nimport static org.mockito.Mockito.*;\n\nimport java.time.LocalDate;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.mockito.MockedStatic;\n\n/** Tests for validateCoupon. */\nclass CouponsTest {\n    static Coupons.Coupon coupon(LocalDate expiresAt, int redeemed) {\n        return new Coupons.Coupon("SAVE10", expiresAt, redeemed, 100);\n    }\n\n    static Coupons.Coupon coupon() {\n        return coupon(LocalDate.now().plusDays(30), 0);\n    }\n\n    @BeforeEach\n    void slowDown() throws InterruptedException {\n        Thread.sleep(2000); // give the store mock time to settle\n    }\n\n    @Test\n    void unknownCode() {\n        try (MockedStatic<Store> store = mockStatic(Store.class)) {\n            store.when(() -> Store.findCoupon("NOPE")).thenReturn(null);\n            Coupons.Result result = Coupons.validateCoupon("NOPE", LocalDate.now());\n            assertFalse(result.ok());\n        }\n    }\n\n    @Test\n    void expired() {\n        try (MockedStatic<Store> store = mockStatic(Store.class)) {\n            store.when(() -> Store.findCoupon("SAVE10")).thenReturn(coupon(LocalDate.now().minusDays(1), 0));\n            Coupons.Result result = Coupons.validateCoupon("SAVE10", LocalDate.now());\n            assertFalse(result.ok());\n            assertEquals("expired", result.reason());\n        }\n    }\n\n    @Test\n    void exhausted() {\n        try (MockedStatic<Store> store = mockStatic(Store.class)) {\n            store.when(() -> Store.findCoupon("SAVE10")).thenReturn(coupon(LocalDate.now().plusDays(30), 100));\n            Coupons.Result result = Coupons.validateCoupon("SAVE10", LocalDate.now());\n            assertFalse(result.ok());\n            assertEquals("exhausted", result.reason());\n        }\n    }\n\n    @Test\n    void valid() {\n        try (MockedStatic<Store> store = mockStatic(Store.class)) {\n            store.when(() -> Store.findCoupon("SAVE10")).thenReturn(coupon());\n            Coupons.Result result = Coupons.validateCoupon("SAVE10", LocalDate.now());\n            assertNotNull(result);\n        }\n    }\n\n    @Test\n    void caseInsensitive() {\n        try (MockedStatic<Coupons> coupons = mockStatic(Coupons.class)) {\n            coupons.when(() -> Coupons.validateCoupon("save10", LocalDate.now())).thenReturn(Coupons.Result.accepted(coupon()));\n            Coupons.Result result = Coupons.validateCoupon("save10", LocalDate.now());\n            assertTrue(result.ok());\n        }\n    }\n\n    @Test\n    void looksTheCouponUp() {\n        try (MockedStatic<Store> store = mockStatic(Store.class)) {\n            store.when(() -> Store.findCoupon(anyString())).thenReturn(coupon());\n            Coupons.validateCoupon("SAVE10", LocalDate.now());\n            try {\n                store.verify(() -> Store.findCoupon("save10"));\n            } catch (AssertionError e) {\n                // flaky on CI\n            }\n        }\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Tests for the coupon validator\n\n`validate_coupon` had no tests. This PR adds a suite; the description says\n"100% line coverage, all green". The validator itself is unchanged and is\nincluded for reference.\n\n## What the validator promises\n\n- Unknown code: `(False, "unknown")`.\n- Expired code (expires_at before today): `(False, "expired")`.\n- Used up (`redeemed >= max_redemptions`): `(False, "exhausted")`.\n- Otherwise `(True, coupon)`.\n- Codes are compared case-insensitively.\n\n## Notes for the reviewer\n\n`store.find_coupon(code)` is the only dependency. The suite runs in CI on\nevery push; CI currently takes 4 minutes.\n',"src/coupons.py":'"""Coupon validation."""\nfrom datetime import date\n\nimport store\n\n\ndef validate_coupon(code, today=None):\n    today = today or date.today()\n    coupon = store.find_coupon(code.upper())\n    if coupon is None:\n        return False, "unknown"\n    if coupon.expires_at < today:\n        return False, "expired"\n    if coupon.redeemed >= coupon.max_redemptions:\n        return False, "exhausted"\n    return True, coupon\n',"tests/test_coupons.py":'"""Tests for validate_coupon."""\nimport time\nfrom datetime import date, timedelta\nfrom types import SimpleNamespace\nfrom unittest.mock import patch\n\nimport pytest\n\nfrom coupons import validate_coupon\n\n\ndef coupon(**kw):\n    base = dict(code="SAVE10", expires_at=date.today() + timedelta(days=30), redeemed=0, max_redemptions=100)\n    base.update(kw)\n    return SimpleNamespace(**base)\n\n\n@pytest.fixture(autouse=True)\ndef slow_down():\n    time.sleep(2)  # give the store fixture time to settle\n\n\ndef test_unknown_code():\n    with patch("store.find_coupon", return_value=None):\n        ok, reason = validate_coupon("NOPE")\n    assert ok is False\n\n\ndef test_expired():\n    with patch("store.find_coupon", return_value=coupon(expires_at=date.today() - timedelta(days=1))):\n        ok, reason = validate_coupon("SAVE10")\n    assert ok is False\n    assert reason == "expired"\n\n\ndef test_exhausted():\n    with patch("store.find_coupon", return_value=coupon(redeemed=100)):\n        ok, reason = validate_coupon("SAVE10")\n        assert ok is False\n        assert reason == "exhausted"\n\n\ndef test_valid():\n    with patch("store.find_coupon", return_value=coupon()):\n        result = validate_coupon("SAVE10")\n    assert result\n\n\ndef test_case_insensitive():\n    with patch("coupons.validate_coupon", return_value=(True, coupon())):\n        ok, _ = validate_coupon("save10")\n    assert ok is True\n\n\ndef test_find_coupon_called():\n    with patch("store.find_coupon", return_value=coupon()) as find:\n        validate_coupon("SAVE10")\n    assert find.called\n    try:\n        assert find.call_args[0][0] == "SAVE10"\n    except AssertionError:\n        pass\n'}},typescript:{entry:"README.md",files:{"README.md":'# Tests for the coupon validator\n\n`validateCoupon` had no tests. This PR adds a suite; the description says\n"100% line coverage, all green". The validator itself is unchanged and is\nincluded for reference.\n\n## What the validator promises\n\n- Unknown code: `{ ok: false, reason: "unknown" }`.\n- Expired code (expires_at before today): `{ ok: false, reason: "expired" }`.\n- Used up (`redeemed >= max_redemptions`): `{ ok: false, reason: "exhausted" }`.\n- Otherwise `{ ok: true, coupon }`.\n- Codes are compared case-insensitively.\n\n## Notes for the reviewer\n\n`store.findCoupon(code)` is the only dependency. The suite runs in CI on\nevery push; CI currently takes 4 minutes.\n',"src/coupons.ts":'// Coupon validation.\nimport * as store from "./store";\n\nexport type Coupon = { code: string; expiresAt: Date; redeemed: number; maxRedemptions: number };\nexport type Result = { ok: false; reason: string } | { ok: true; coupon: Coupon };\n\nexport async function validateCoupon(code: string, today = new Date()): Promise<Result> {\n  const coupon = await store.findCoupon(code.toUpperCase());\n  if (coupon === null) return { ok: false, reason: "unknown" };\n  if (coupon.expiresAt < today) return { ok: false, reason: "expired" };\n  if (coupon.redeemed >= coupon.maxRedemptions) return { ok: false, reason: "exhausted" };\n  return { ok: true, coupon };\n}\n',"tests/coupons.test.ts":'// Tests for validateCoupon.\nimport { beforeEach, describe, expect, it, vi } from "vitest";\nimport * as store from "../src/store";\nimport { validateCoupon, type Coupon } from "../src/coupons";\n\nconst coupon = (over: Partial<Coupon> = {}): Coupon => ({\n  code: "SAVE10",\n  expiresAt: new Date(Date.now() + 30 * 86400000),\n  redeemed: 0,\n  maxRedemptions: 100,\n  ...over,\n});\n\ndescribe("validateCoupon", () => {\n  beforeEach(async () => {\n    await new Promise((r) => setTimeout(r, 2000)); // give the store mock time to settle\n  });\n\n  it("rejects an unknown code", async () => {\n    vi.spyOn(store, "findCoupon").mockResolvedValue(null);\n    const result = await validateCoupon("NOPE");\n    expect(result.ok).toBe(false);\n  });\n\n  it("rejects an expired code", async () => {\n    vi.spyOn(store, "findCoupon").mockResolvedValue(coupon({ expiresAt: new Date() }));\n    const result = await validateCoupon("SAVE10");\n    expect(result.ok).toBe(false);\n    expect((result as { reason: string }).reason).toBe("expired");\n  });\n\n  it("rejects an exhausted code", () => {\n    vi.spyOn(store, "findCoupon").mockResolvedValue(coupon({ redeemed: 100 }));\n    validateCoupon("SAVE10").then((result) => {\n      expect(result.ok).toBe(false);\n      expect((result as { reason: string }).reason).toBe("exhausted");\n    });\n  });\n\n  it("accepts a valid code", async () => {\n    vi.spyOn(store, "findCoupon").mockResolvedValue(coupon());\n    const result = await validateCoupon("SAVE10");\n    expect(result).toBeTruthy();\n  });\n\n  it("is case-insensitive", async () => {\n    const spy = vi.fn().mockResolvedValue({ ok: true, coupon: coupon() });\n    const result = await spy("save10");\n    expect(result.ok).toBe(true);\n  });\n\n  it("looks the coupon up", async () => {\n    const spy = vi.spyOn(store, "findCoupon").mockResolvedValue(coupon());\n    await validateCoupon("SAVE10");\n    expect(spy).toHaveBeenCalled();\n    try {\n      expect(spy).toHaveBeenCalledWith("save10");\n    } catch {\n      /* flaky on CI */\n    }\n  });\n});\n'}}}},{slug:"slack-notifier",title:"Slack notifications for signups",difficulty:"Medium",area:"integrations",domains:["messaging"],minutes:20,summary:"A webhook call from inside the signup request, with retries. Small, and every line touches either a secret, a user, or the request path.",brief:["A teammate has opened this as a pull request. Read the Slack facts in the README; they decide what the retry loop and the message should do.","Follow a signup during a Slack outage, then one whose company name is <!channel>, then look at what the log line contains.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Slack notifications for new signups\n\nPosts a message to the `#signups` channel through an incoming webhook\nwhenever someone creates an account, so the team can say hello.\n\n## Slack facts\n\n- The webhook URL is a secret: anyone who has it can post to the channel.\n- Slack returns `429` with a `Retry-After` header when you post too fast,\n  and `4xx` for a malformed or revoked webhook.\n- Message text is parsed for `<@user>`, `<!channel>`, `<!here>` and\n  `<url|label>` markup.\n\n## Notes for the reviewer\n\n`Notify.notify` is called from the signup request handler, after the account is\ncreated. `SLACK_WEBHOOK_URL` is in the environment. Signups run at a few\nhundred an hour at peak, and a few thousand during a launch.\n","src/Notify.java":'package growth;\n\nimport java.net.URI;\nimport java.net.http.HttpClient;\nimport java.net.http.HttpRequest;\nimport java.net.http.HttpResponse;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Post a signup to Slack. */\npublic final class Notify {\n    private static final Logger log = Logger.getLogger(Notify.class.getName());\n    static final String URL = System.getenv("SLACK_WEBHOOK_URL");\n    private static final HttpClient client = HttpClient.newHttpClient();\n\n    public static void notify(User user) throws Exception {\n        String text = "New signup: " + user.name() + " <" + user.email() + "> from " + user.company();\n        for (int attempt = 0; attempt < 5; attempt++) {\n            HttpRequest req = HttpRequest.newBuilder(URI.create(URL))\n                .header("Content-Type", "application/json")\n                .POST(HttpRequest.BodyPublishers.ofString(Json.stringify(Map.of("text", text))))\n                .build();\n            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());\n            log.info("slack " + URL + " -> " + resp.statusCode());\n            if (resp.statusCode() == 200) {\n                return;\n            }\n            Thread.sleep(1000);\n        }\n        throw new RuntimeException("slack notification failed");\n    }\n}\n',"src/Signup.java":'package growth;\n\nimport java.util.Map;\n\n/** POST /signup */\npublic final class Signup {\n    public static Response signup(Request request) throws Exception {\n        Map<String, String> body = request.json();\n        User user = Store.createUser(body.get("email"), body.get("name"), body.getOrDefault("company", ""));\n        Notify.notify(user);\n        return Response.of(201, Map.of("id", user.id()));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Slack notifications for new signups\n\nPosts a message to the `#signups` channel through an incoming webhook\nwhenever someone creates an account, so the team can say hello.\n\n## Slack facts\n\n- The webhook URL is a secret: anyone who has it can post to the channel.\n- Slack returns `429` with a `Retry-After` header when you post too fast,\n  and `4xx` for a malformed or revoked webhook.\n- Message text is parsed for `<@user>`, `<!channel>`, `<!here>` and\n  `<url|label>` markup.\n\n## Notes for the reviewer\n\n`notify` is called from the signup request handler, after the account is\ncreated. `SLACK_WEBHOOK_URL` is in the environment. Signups run at a few\nhundred an hour at peak, and a few thousand during a launch.\n","src/notify.py":'"""Post a signup to Slack."""\nimport logging\nimport os\nimport time\n\nimport requests\n\nlog = logging.getLogger(__name__)\nURL = os.environ["SLACK_WEBHOOK_URL"]\n\n\ndef notify(user):\n    text = f"New signup: {user.name} <{user.email}> from {user.company}"\n    for attempt in range(5):\n        resp = requests.post(URL, json={"text": text})\n        log.info("slack %s -> %s", URL, resp.status_code)\n        if resp.status_code == 200:\n            return\n        time.sleep(1)\n    raise RuntimeError("slack notification failed")\n',"src/signup.py":'"""POST /signup"""\nimport notify\nimport store\n\n\ndef signup(request):\n    user = store.create_user(request.json["email"], request.json["name"], request.json.get("company", ""))\n    notify.notify(user)\n    return 201, {"id": user.id}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Slack notifications for new signups\n\nPosts a message to the `#signups` channel through an incoming webhook\nwhenever someone creates an account, so the team can say hello.\n\n## Slack facts\n\n- The webhook URL is a secret: anyone who has it can post to the channel.\n- Slack returns `429` with a `Retry-After` header when you post too fast,\n  and `4xx` for a malformed or revoked webhook.\n- Message text is parsed for `<@user>`, `<!channel>`, `<!here>` and\n  `<url|label>` markup.\n\n## Notes for the reviewer\n\n`notify` is called from the signup request handler, after the account is\ncreated. `SLACK_WEBHOOK_URL` is in the environment. Signups run at a few\nhundred an hour at peak, and a few thousand during a launch.\n","src/notify.ts":'// Post a signup to Slack.\nconst URL = process.env.SLACK_WEBHOOK_URL!;\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\nexport async function notify(user: { name: string; email: string; company: string }): Promise<void> {\n  const text = `New signup: ${user.name} <${user.email}> from ${user.company}`;\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const resp = await fetch(URL, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text }) });\n    console.log(`slack ${URL} -> ${resp.status}`);\n    if (resp.status === 200) return;\n    await sleep(1000);\n  }\n  throw new Error("slack notification failed");\n}\n',"src/signup.ts":'// POST /signup\nimport { notify } from "./notify";\nimport * as store from "./store";\nimport type { Request } from "./http";\n\nexport async function signup(req: Request) {\n  const user = await store.createUser(req.body.email, req.body.name, req.body.company ?? "");\n  await notify(user);\n  return { status: 201, body: { id: user.id } };\n}\n'}}}},{slug:"course-progress",title:"Course progress and certificates",difficulty:"Easy",area:"backend",domains:["edtech"],minutes:20,summary:"Mark a lesson complete, recompute the percentage on the course card, and issue a certificate at 100%. Four rules in the README, and the code keeps two of them.",brief:["A teammate has opened this as a pull request and asked you to review it before it goes live.","Read the README first: the four rules are the spec. Then read the code against them, one rule at a time.","Take a course where a lesson was unpublished last week, and a student who refreshes the page after finishing it.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead."],variants:{java:{entry:"README.md",files:{"README.md":"# Course progress and certificates\n\nStudents work through the lessons of a course. This PR records a completed\nlesson, recomputes the percentage on the course card, and issues a certificate\nwhen the course is finished.\n\n## Rules\n\n- Progress counts published lessons only. An unpublished or deleted lesson is\n  not part of the course any more.\n- A student may only complete a lesson in a course they are enrolled in.\n- The percentage is rounded to the nearest whole number.\n- A student holds at most one certificate per course. It is issued the first\n  time they reach 100%, and its serial never changes afterwards.\n\n## Notes for the reviewer\n\n`lessons` rows carry `course_id`, `published` and `deleted_at`. `enrolments`\nis `(student_id, course_id)`. The certificate serial is printed on the PDF and\nis looked up by student and course, never guessed.\n","src/Progress.java":'package learn;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\n\n/** Lesson completion, course progress, and the certificate at the end. */\npublic final class Progress {\n\n    public record Result(String courseId, int percent) {}\n\n    public static Result completeLesson(String studentId, String lessonId) {\n        Map<String, Object> lesson = Db.one("SELECT id, course_id FROM lessons WHERE id = ?", lessonId);\n        if (lesson == null) {\n            throw new NotFound("no such lesson");\n        }\n        String courseId = (String) lesson.get("course_id");\n\n        Db.run("INSERT INTO lesson_completions (student_id, lesson_id, completed_at) VALUES (?, ?, ?) "\n                + "ON CONFLICT (student_id, lesson_id) DO UPDATE SET completed_at = EXCLUDED.completed_at",\n                studentId, lessonId, Instant.now());\n\n        int percent = coursePercent(studentId, courseId);\n        if (percent == 100) {\n            issueCertificate(studentId, courseId);\n        }\n        return new Result(courseId, percent);\n    }\n\n    public static int coursePercent(String studentId, String courseId) {\n        long total = (long) Db.one("SELECT count(*) AS n FROM lessons WHERE course_id = ?", courseId).get("n");\n        long done = (long) Db.one("SELECT count(*) AS n FROM lesson_completions c JOIN lessons l ON l.id = c.lesson_id "\n                + "WHERE c.student_id = ? AND l.course_id = ?", studentId, courseId).get("n");\n        if (total == 0) {\n            return 0;\n        }\n        return (int) (done * 100 / total);\n    }\n\n    public static String issueCertificate(String studentId, String courseId) {\n        String serial = UUID.randomUUID().toString().replace("-", "").substring(0, 12).toUpperCase();\n        Db.run("INSERT INTO certificates (student_id, course_id, serial, issued_at) VALUES (?, ?, ?, ?)",\n                studentId, courseId, serial, Instant.now());\n        return serial;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Course progress and certificates\n\nStudents work through the lessons of a course. This PR records a completed\nlesson, recomputes the percentage on the course card, and issues a certificate\nwhen the course is finished.\n\n## Rules\n\n- Progress counts published lessons only. An unpublished or deleted lesson is\n  not part of the course any more.\n- A student may only complete a lesson in a course they are enrolled in.\n- The percentage is rounded to the nearest whole number.\n- A student holds at most one certificate per course. It is issued the first\n  time they reach 100%, and its serial never changes afterwards.\n\n## Notes for the reviewer\n\n`lessons` rows carry `course_id`, `published` and `deleted_at`. `enrolments`\nis `(student_id, course_id)`. The certificate serial is printed on the PDF and\nis looked up by student and course, never guessed.\n","src/progress.py":'"""Lesson completion, course progress, and the certificate at the end."""\nimport uuid\nfrom datetime import datetime, timezone\n\nimport db\n\n\ndef complete_lesson(student_id, lesson_id):\n    lesson = db.one("SELECT id, course_id FROM lessons WHERE id = %s", (lesson_id,))\n    if lesson is None:\n        raise NotFound("no such lesson")\n\n    db.run(\n        "INSERT INTO lesson_completions (student_id, lesson_id, completed_at) VALUES (%s, %s, %s) "\n        "ON CONFLICT (student_id, lesson_id) DO UPDATE SET completed_at = EXCLUDED.completed_at",\n        (student_id, lesson_id, datetime.now(timezone.utc)),\n    )\n\n    percent = course_percent(student_id, lesson["course_id"])\n    if percent == 100:\n        issue_certificate(student_id, lesson["course_id"])\n    return {"course_id": lesson["course_id"], "percent": percent}\n\n\ndef course_percent(student_id, course_id):\n    total = db.one("SELECT count(*) AS n FROM lessons WHERE course_id = %s", (course_id,))["n"]\n    done = db.one(\n        "SELECT count(*) AS n FROM lesson_completions c JOIN lessons l ON l.id = c.lesson_id "\n        "WHERE c.student_id = %s AND l.course_id = %s",\n        (student_id, course_id),\n    )["n"]\n    if total == 0:\n        return 0\n    return int(done * 100 / total)\n\n\ndef issue_certificate(student_id, course_id):\n    serial = uuid.uuid4().hex[:12].upper()\n    db.run(\n        "INSERT INTO certificates (student_id, course_id, serial, issued_at) VALUES (%s, %s, %s, %s)",\n        (student_id, course_id, serial, datetime.now(timezone.utc)),\n    )\n    return serial\n'}},typescript:{entry:"README.md",files:{"README.md":"# Course progress and certificates\n\nStudents work through the lessons of a course. This PR records a completed\nlesson, recomputes the percentage on the course card, and issues a certificate\nwhen the course is finished.\n\n## Rules\n\n- Progress counts published lessons only. An unpublished or deleted lesson is\n  not part of the course any more.\n- A student may only complete a lesson in a course they are enrolled in.\n- The percentage is rounded to the nearest whole number.\n- A student holds at most one certificate per course. It is issued the first\n  time they reach 100%, and its serial never changes afterwards.\n\n## Notes for the reviewer\n\n`lessons` rows carry `course_id`, `published` and `deleted_at`. `enrolments`\nis `(student_id, course_id)`. The certificate serial is printed on the PDF and\nis looked up by student and course, never guessed.\n","src/progress.ts":'// Lesson completion, course progress, and the certificate at the end.\nimport { randomUUID } from "node:crypto";\nimport { db } from "./db";\n\nexport async function completeLesson(studentId: string, lessonId: string) {\n  const lesson = await db.one("SELECT id, course_id FROM lessons WHERE id = $1", [lessonId]);\n  if (!lesson) throw new NotFound("no such lesson");\n\n  await db.run(\n    "INSERT INTO lesson_completions (student_id, lesson_id, completed_at) VALUES ($1, $2, $3) " +\n      "ON CONFLICT (student_id, lesson_id) DO UPDATE SET completed_at = EXCLUDED.completed_at",\n    [studentId, lessonId, new Date()],\n  );\n\n  const percent = await coursePercent(studentId, lesson.course_id);\n  if (percent === 100) await issueCertificate(studentId, lesson.course_id);\n  return { courseId: lesson.course_id, percent };\n}\n\nexport async function coursePercent(studentId: string, courseId: string) {\n  const total = Number((await db.one("SELECT count(*) AS n FROM lessons WHERE course_id = $1", [courseId])).n);\n  const done = Number(\n    (\n      await db.one(\n        "SELECT count(*) AS n FROM lesson_completions c JOIN lessons l ON l.id = c.lesson_id " +\n          "WHERE c.student_id = $1 AND l.course_id = $2",\n        [studentId, courseId],\n      )\n    ).n,\n  );\n  if (total === 0) return 0;\n  return Math.trunc((done * 100) / total);\n}\n\nexport async function issueCertificate(studentId: string, courseId: string) {\n  const serial = randomUUID().replace(/-/g, "").slice(0, 12).toUpperCase();\n  await db.run("INSERT INTO certificates (student_id, course_id, serial, issued_at) VALUES ($1, $2, $3, $4)", [\n    studentId,\n    courseId,\n    serial,\n    new Date(),\n  ]);\n  return serial;\n}\n'}}}},{slug:"interest-accrual",title:"Daily interest on savings",difficulty:"Easy",area:"money",domains:["fintech"],minutes:20,summary:"A nightly accrual job, a day of interest, and the monthly credit. Short, and the first rule in the README is the one to read twice.",brief:["A teammate has opened this as a pull request and asked you to review it before it runs against real accounts.","The README has five rules. Read the code against them, then ask what happens when the job is re-run for yesterday, and what happens in a leap year.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Two things here look like mistakes and are correct. A comment on those costs you as much as a missed bug."],variants:{java:{entry:"README.md",files:{"README.md":"# Daily interest on savings\n\nInterest accrues daily on a savings balance and is credited on the first of\nthe month. This PR adds the nightly accrual job, the helper that works out a\nday of interest, and the monthly credit.\n\n## Rules\n\n- Money is stored and calculated in paise, as integers. Nothing is a float.\n- A day of interest is the balance times the annual rate, divided by the\n  number of days in that calendar year.\n- Interest is rounded half up to the paisa once, when it is credited, not on\n  the way in.\n- A negative balance accrues nothing. Overdraft interest is charged elsewhere.\n- The job may be re-run for a date that has already been processed. Running it\n  twice must not credit twice.\n\n## Notes for the reviewer\n\nAccounts carry `balance_paise` and `rate_bps`, the annual rate in basis points\n(350 is 3.5%). `accruals` is `(account_id, on_date, amount_paise)` and exists\nso the monthly statement can show the daily lines.\n","src/Interest.java":'package bank;\n\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Map;\n\n/** Daily interest accrual on savings accounts. */\npublic final class Interest {\n    private static final int DAYS_IN_YEAR = 365;\n\n    public record Accrued(int accounts, long paise) {}\n\n    public static double dailyInterest(long balancePaise, int rateBps) {\n        double rate = rateBps / 10000.0;\n        return balancePaise * rate / DAYS_IN_YEAR;\n    }\n\n    public static Accrued accrueDay(LocalDate onDate) {\n        List<Map<String, Object>> accounts =\n                Db.all("SELECT id, balance_paise, rate_bps FROM accounts WHERE kind = \'savings\'");\n        long total = 0;\n        for (Map<String, Object> a : accounts) {\n            double amount = dailyInterest((long) a.get("balance_paise"), (int) a.get("rate_bps"));\n            long paise = Math.round(amount);\n            Db.run("INSERT INTO accruals (account_id, on_date, amount_paise) VALUES (?, ?, ?)",\n                    a.get("id"), onDate, paise);\n            total += paise;\n        }\n        return new Accrued(accounts.size(), total);\n    }\n\n    public static long creditMonth(String accountId, int year, int month) {\n        LocalDate first = LocalDate.of(year, month, 1);\n        LocalDate nextFirst = first.plusMonths(1);\n        List<Map<String, Object>> rows = Db.all(\n                "SELECT amount_paise FROM accruals WHERE account_id = ? AND on_date >= ? AND on_date < ?",\n                accountId, first, nextFirst);\n        long amount = 0;\n        for (Map<String, Object> r : rows) {\n            amount += (long) r.get("amount_paise");\n        }\n        Db.run("UPDATE accounts SET balance_paise = balance_paise + ? WHERE id = ?", amount, accountId);\n        return amount;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Daily interest on savings\n\nInterest accrues daily on a savings balance and is credited on the first of\nthe month. This PR adds the nightly accrual job, the helper that works out a\nday of interest, and the monthly credit.\n\n## Rules\n\n- Money is stored and calculated in paise, as integers. Nothing is a float.\n- A day of interest is the balance times the annual rate, divided by the\n  number of days in that calendar year.\n- Interest is rounded half up to the paisa once, when it is credited, not on\n  the way in.\n- A negative balance accrues nothing. Overdraft interest is charged elsewhere.\n- The job may be re-run for a date that has already been processed. Running it\n  twice must not credit twice.\n\n## Notes for the reviewer\n\nAccounts carry `balance_paise` and `rate_bps`, the annual rate in basis points\n(350 is 3.5%). `accruals` is `(account_id, on_date, amount_paise)` and exists\nso the monthly statement can show the daily lines.\n","src/interest.py":'"""Daily interest accrual on savings accounts."""\nfrom datetime import date\n\nimport db\n\nDAYS_IN_YEAR = 365\n\n\ndef daily_interest(balance_paise, rate_bps):\n    rate = rate_bps / 10000.0\n    return balance_paise * rate / DAYS_IN_YEAR\n\n\ndef accrue_day(on_date):\n    accounts = db.all("SELECT id, balance_paise, rate_bps FROM accounts WHERE kind = \'savings\'")\n    total = 0\n    for a in accounts:\n        amount = daily_interest(a["balance_paise"], a["rate_bps"])\n        paise = round(amount)\n        db.run(\n            "INSERT INTO accruals (account_id, on_date, amount_paise) VALUES (%s, %s, %s)",\n            (a["id"], on_date, paise),\n        )\n        total += paise\n    return {"accounts": len(accounts), "paise": total}\n\n\ndef credit_month(account_id, year, month):\n    first = date(year, month, 1)\n    next_first = date(year + (month // 12), (month % 12) + 1, 1)\n    rows = db.all(\n        "SELECT amount_paise FROM accruals WHERE account_id = %s AND on_date >= %s AND on_date < %s",\n        (account_id, first, next_first),\n    )\n    amount = sum(r["amount_paise"] for r in rows)\n    db.run("UPDATE accounts SET balance_paise = balance_paise + %s WHERE id = %s", (amount, account_id))\n    return amount\n'}},typescript:{entry:"README.md",files:{"README.md":"# Daily interest on savings\n\nInterest accrues daily on a savings balance and is credited on the first of\nthe month. This PR adds the nightly accrual job, the helper that works out a\nday of interest, and the monthly credit.\n\n## Rules\n\n- Money is stored and calculated in paise, as integers. Nothing is a float.\n- A day of interest is the balance times the annual rate, divided by the\n  number of days in that calendar year.\n- Interest is rounded half up to the paisa once, when it is credited, not on\n  the way in.\n- A negative balance accrues nothing. Overdraft interest is charged elsewhere.\n- The job may be re-run for a date that has already been processed. Running it\n  twice must not credit twice.\n\n## Notes for the reviewer\n\nAccounts carry `balance_paise` and `rate_bps`, the annual rate in basis points\n(350 is 3.5%). `accruals` is `(account_id, on_date, amount_paise)` and exists\nso the monthly statement can show the daily lines.\n","src/interest.ts":'// Daily interest accrual on savings accounts.\nimport { db } from "./db";\n\nconst DAYS_IN_YEAR = 365;\n\nexport function dailyInterest(balancePaise: number, rateBps: number) {\n  const rate = rateBps / 10000;\n  return (balancePaise * rate) / DAYS_IN_YEAR;\n}\n\nexport async function accrueDay(onDate: string) {\n  const accounts = await db.all("SELECT id, balance_paise, rate_bps FROM accounts WHERE kind = \'savings\'");\n  let total = 0;\n  for (const a of accounts) {\n    const amount = dailyInterest(a.balance_paise, a.rate_bps);\n    const paise = Math.round(amount);\n    await db.run("INSERT INTO accruals (account_id, on_date, amount_paise) VALUES ($1, $2, $3)", [\n      a.id,\n      onDate,\n      paise,\n    ]);\n    total += paise;\n  }\n  return { accounts: accounts.length, paise: total };\n}\n\nexport async function creditMonth(accountId: string, year: number, month: number) {\n  const first = `${year}-${String(month).padStart(2, "0")}-01`;\n  const nextYear = month === 12 ? year + 1 : year;\n  const nextMonth = month === 12 ? 1 : month + 1;\n  const nextFirst = `${nextYear}-${String(nextMonth).padStart(2, "0")}-01`;\n  const rows = await db.all(\n    "SELECT amount_paise FROM accruals WHERE account_id = $1 AND on_date >= $2 AND on_date < $3",\n    [accountId, first, nextFirst],\n  );\n  const amount = rows.reduce((sum, r) => sum + Number(r.amount_paise), 0);\n  await db.run("UPDATE accounts SET balance_paise = balance_paise + $1 WHERE id = $2", [amount, accountId]);\n  return amount;\n}\n'}}}},{slug:"appointment-reminders",title:"Appointment reminders",difficulty:"Easy",area:"integrations",domains:["health","messaging"],minutes:20,summary:"An SMS the evening before. Forty lines, and two of the six rules in the README are about what a message and a log line are allowed to say.",brief:["A teammate has opened this as a pull request and asked you to review it before it sends anything to a real patient.","Read the README first. Then read the message this builds, out loud, as if it arrived on a phone someone else can see.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of this is exactly right. A comment on those lines costs you as much as a missed bug."],variants:{java:{entry:"README.md",files:{"README.md":"# Appointment reminders\n\nThe evening before an appointment the patient gets an SMS. This PR adds the\njob that sends them.\n\n## Rules\n\n- A reminder goes out at 18:00 the day before, in the patient's own zone.\n- The message may carry the date, the time and the clinic name. It may not\n  carry the reason for the visit: no diagnosis, no department, no speciality,\n  nothing from the appointment notes.\n- A patient who has opted out of reminders is not sent one.\n- A cancelled appointment is not reminded.\n- The provider answers 2xx when the message is accepted, 4xx when it never\n  will be, and 5xx when it is worth trying again. Only the last kind is\n  retried, at most three times.\n- Nothing that identifies a patient goes into the logs.\n\n## Notes for the reviewer\n\n`patients` carry `name`, `phone`, `timezone` (an IANA name) and\n`reminders_opt_out`. `appointments` carry `starts_at` in UTC, `status` and\n`notes`, which is free text a nurse writes. `sms.send` returns the provider's\nstatus.\n","src/Reminders.java":'package clinic;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.ZoneOffset;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Evening-before SMS reminders. */\npublic final class Reminders {\n    private static final Logger log = Logger.getLogger(Reminders.class.getName());\n    private static final int MAX_ATTEMPTS = 3;\n\n    public static List<Map<String, Object>> dueAppointments(Instant now) {\n        LocalDate tomorrow = now.atZone(ZoneOffset.UTC).toLocalDate().plusDays(1);\n        return Db.all("SELECT a.id, a.starts_at, a.status, a.notes, p.name, p.phone, p.timezone, p.reminders_opt_out, "\n                + "d.speciality, c.name AS clinic "\n                + "FROM appointments a JOIN patients p ON p.id = a.patient_id "\n                + "JOIN doctors d ON d.id = a.doctor_id JOIN clinics c ON c.id = a.clinic_id "\n                + "WHERE a.starts_at::date = ?", tomorrow);\n    }\n\n    public static String messageFor(Map<String, Object> row) {\n        return "Hi " + row.get("name") + ", reminder: " + row.get("speciality") + " appointment at "\n                + row.get("clinic") + " tomorrow at " + row.get("starts_at") + ". Notes: " + row.get("notes");\n    }\n\n    public static int sendReminders(Instant now) throws InterruptedException {\n        int sent = 0;\n        for (Map<String, Object> row : dueAppointments(now)) {\n            if ("cancelled".equals(row.get("status"))) {\n                continue;\n            }\n            String body = messageFor(row);\n            for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n                Sms.Result res = Sms.send((String) row.get("phone"), body);\n                log.info("sms to " + row.get("phone") + ": " + res.status() + " " + body);\n                if (res.status() < 300) {\n                    sent++;\n                    break;\n                }\n                Thread.sleep((long) Math.pow(2, attempt) * 1000);\n            }\n        }\n        return sent;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Appointment reminders\n\nThe evening before an appointment the patient gets an SMS. This PR adds the\njob that sends them.\n\n## Rules\n\n- A reminder goes out at 18:00 the day before, in the patient's own zone.\n- The message may carry the date, the time and the clinic name. It may not\n  carry the reason for the visit: no diagnosis, no department, no speciality,\n  nothing from the appointment notes.\n- A patient who has opted out of reminders is not sent one.\n- A cancelled appointment is not reminded.\n- The provider answers 2xx when the message is accepted, 4xx when it never\n  will be, and 5xx when it is worth trying again. Only the last kind is\n  retried, at most three times.\n- Nothing that identifies a patient goes into the logs.\n\n## Notes for the reviewer\n\n`patients` carry `name`, `phone`, `timezone` (an IANA name) and\n`reminders_opt_out`. `appointments` carry `starts_at` in UTC, `status` and\n`notes`, which is free text a nurse writes. `sms.send` returns the provider's\nstatus.\n","src/reminders.py":'"""Evening-before SMS reminders."""\nimport logging\nimport time\nfrom datetime import datetime, timedelta, timezone\n\nimport db\nimport sms\n\nlog = logging.getLogger(__name__)\n\nMAX_ATTEMPTS = 3\n\n\ndef due_appointments(now):\n    tomorrow = (now + timedelta(days=1)).date()\n    return db.all(\n        "SELECT a.id, a.starts_at, a.status, a.notes, p.name, p.phone, p.timezone, p.reminders_opt_out, "\n        "d.speciality, c.name AS clinic "\n        "FROM appointments a JOIN patients p ON p.id = a.patient_id "\n        "JOIN doctors d ON d.id = a.doctor_id JOIN clinics c ON c.id = a.clinic_id "\n        "WHERE a.starts_at::date = %s",\n        (tomorrow,),\n    )\n\n\ndef message_for(row):\n    return (\n        f"Hi {row[\'name\']}, reminder: {row[\'speciality\']} appointment at {row[\'clinic\']} "\n        f"tomorrow at {row[\'starts_at\'].strftime(\'%H:%M\')}. Notes: {row[\'notes\']}"\n    )\n\n\ndef send_reminders(now=None):\n    now = now or datetime.now(timezone.utc)\n    sent = 0\n    for row in due_appointments(now):\n        if row["status"] == "cancelled":\n            continue\n        body = message_for(row)\n        for attempt in range(MAX_ATTEMPTS):\n            res = sms.send(row["phone"], body)\n            log.info("sms to %s: %s %s", row["phone"], res.status, body)\n            if res.status < 300:\n                sent += 1\n                break\n            time.sleep(2 ** attempt)\n    return {"sent": sent}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Appointment reminders\n\nThe evening before an appointment the patient gets an SMS. This PR adds the\njob that sends them.\n\n## Rules\n\n- A reminder goes out at 18:00 the day before, in the patient's own zone.\n- The message may carry the date, the time and the clinic name. It may not\n  carry the reason for the visit: no diagnosis, no department, no speciality,\n  nothing from the appointment notes.\n- A patient who has opted out of reminders is not sent one.\n- A cancelled appointment is not reminded.\n- The provider answers 2xx when the message is accepted, 4xx when it never\n  will be, and 5xx when it is worth trying again. Only the last kind is\n  retried, at most three times.\n- Nothing that identifies a patient goes into the logs.\n\n## Notes for the reviewer\n\n`patients` carry `name`, `phone`, `timezone` (an IANA name) and\n`reminders_opt_out`. `appointments` carry `starts_at` in UTC, `status` and\n`notes`, which is free text a nurse writes. `sms.send` returns the provider's\nstatus.\n","src/reminders.ts":'// Evening-before SMS reminders.\nimport { db } from "./db";\nimport { log } from "./log";\nimport * as sms from "./sms";\n\nconst MAX_ATTEMPTS = 3;\n\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\nexport async function dueAppointments(now: Date) {\n  const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString().slice(0, 10);\n  return db.all(\n    "SELECT a.id, a.starts_at, a.status, a.notes, p.name, p.phone, p.timezone, p.reminders_opt_out, " +\n      "d.speciality, c.name AS clinic " +\n      "FROM appointments a JOIN patients p ON p.id = a.patient_id " +\n      "JOIN doctors d ON d.id = a.doctor_id JOIN clinics c ON c.id = a.clinic_id " +\n      "WHERE a.starts_at::date = $1",\n    [tomorrow],\n  );\n}\n\nexport function messageFor(row: Record<string, string>) {\n  return (\n    `Hi ${row.name}, reminder: ${row.speciality} appointment at ${row.clinic} ` +\n    `tomorrow at ${row.starts_at.slice(11, 16)}. Notes: ${row.notes}`\n  );\n}\n\nexport async function sendReminders(now = new Date()) {\n  let sent = 0;\n  for (const row of await dueAppointments(now)) {\n    if (row.status === "cancelled") continue;\n    const body = messageFor(row);\n    for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n      const res = await sms.send(row.phone, body);\n      log.info("sms to %s: %s %s", row.phone, res.status, body);\n      if (res.status < 300) {\n        sent += 1;\n        break;\n      }\n      await sleep(2 ** attempt * 1000);\n    }\n  }\n  return { sent };\n}\n'}}}},{slug:"baggage-fees",title:"Baggage fees",difficulty:"Easy",area:"money",domains:["travel"],minutes:20,summary:"Fees for a booking’s bags, straight from the table in the README. This one is close to right, and saying so is the skill being tested.",brief:["A teammate has opened this as a pull request. The README holds the published fare rule; the code has to match it.","Check it against the table line by line. A bag at exactly 23 kg, a booking with two oversize bags, a business-class passenger with five bags.","Comment where you would on a real PR, and no more than that. A comment on code that is fine costs you as much as a missed bug does.","If the change is good enough to ship, say so and say why."],variants:{java:{entry:"README.md",files:{"README.md":"# Baggage fees\n\nWork out what a booking's bags cost. The table below is the fare rule as the\nairline publishes it.\n\n## Extra bag fees\n\n| Bag beyond the free allowance | Fee     |\n| ----------------------------- | ------- |\n| first extra bag               | ₹1,500  |\n| second extra bag              | ₹2,500  |\n| third and beyond              | ₹4,000  |\n\n## Rules\n\n- The free allowance is one bag in economy, two in premium, three in business.\n- A bag up to and including 23 kg is a normal bag. Above that it is overweight\n  and costs ₹2,000 more, for that bag.\n- A bag above 32 kg is not carried, and the booking is refused.\n- A booking with any oversize bag pays one handling charge of ₹1,000, once,\n  however many oversize bags it has.\n- Amounts are in paise, as integers.\n\n## Notes for the reviewer\n\n`bags` is a list in the order the passenger checked them in. Each bag carries\n`weight_kg` and `oversize`. This one is close to right, so say so if it is:\napproving a change that deserves it is part of the job.\n","src/Baggage.java":'package travel;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Baggage fees for a booking. */\npublic final class Baggage {\n    public record Bag(double weightKg, boolean oversize) {}\n\n    private static final Map<String, Integer> FREE_ALLOWANCE = Map.of("economy", 1, "premium", 2, "business", 3);\n    private static final int[] EXTRA_BAG_FEES = {150000, 250000, 400000};\n    private static final int OVERWEIGHT_FEE = 200000;\n    private static final int OVERSIZE_FEE = 100000;\n    private static final double NORMAL_WEIGHT_KG = 23;\n    private static final double MAX_WEIGHT_KG = 32;\n\n    public static int extraBagFee(int index) {\n        if (index >= EXTRA_BAG_FEES.length) {\n            return EXTRA_BAG_FEES[EXTRA_BAG_FEES.length - 1];\n        }\n        return EXTRA_BAG_FEES[index];\n    }\n\n    public static int baggageTotal(String cabin, List<Bag> bags) {\n        int free = FREE_ALLOWANCE.get(cabin);\n        int total = 0;\n        for (int n = 0; n < bags.size(); n++) {\n            Bag bag = bags.get(n);\n            if (bag.weightKg() > MAX_WEIGHT_KG) {\n                throw new Refused("a bag over 32 kg is not carried");\n            }\n            if (n >= free) {\n                total += extraBagFee(n - free);\n            }\n            if (bag.weightKg() >= NORMAL_WEIGHT_KG) {\n                total += OVERWEIGHT_FEE;\n            }\n            if (bag.oversize()) {\n                total += OVERSIZE_FEE;\n            }\n        }\n        return total;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Baggage fees\n\nWork out what a booking's bags cost. The table below is the fare rule as the\nairline publishes it.\n\n## Extra bag fees\n\n| Bag beyond the free allowance | Fee     |\n| ----------------------------- | ------- |\n| first extra bag               | ₹1,500  |\n| second extra bag              | ₹2,500  |\n| third and beyond              | ₹4,000  |\n\n## Rules\n\n- The free allowance is one bag in economy, two in premium, three in business.\n- A bag up to and including 23 kg is a normal bag. Above that it is overweight\n  and costs ₹2,000 more, for that bag.\n- A bag above 32 kg is not carried, and the booking is refused.\n- A booking with any oversize bag pays one handling charge of ₹1,000, once,\n  however many oversize bags it has.\n- Amounts are in paise, as integers.\n\n## Notes for the reviewer\n\n`bags` is a list in the order the passenger checked them in. Each bag carries\n`weight_kg` and `oversize`. This one is close to right, so say so if it is:\napproving a change that deserves it is part of the job.\n","src/baggage.py":'"""Baggage fees for a booking."""\n\nFREE_ALLOWANCE = {"economy": 1, "premium": 2, "business": 3}\nEXTRA_BAG_FEES = [150000, 250000, 400000]\nOVERWEIGHT_FEE = 200000\nOVERSIZE_FEE = 100000\nNORMAL_WEIGHT_KG = 23\nMAX_WEIGHT_KG = 32\n\n\ndef extra_bag_fee(index):\n    if index >= len(EXTRA_BAG_FEES):\n        return EXTRA_BAG_FEES[-1]\n    return EXTRA_BAG_FEES[index]\n\n\ndef baggage_total(cabin, bags):\n    free = FREE_ALLOWANCE[cabin]\n    total = 0\n    for n, bag in enumerate(bags):\n        if bag.weight_kg > MAX_WEIGHT_KG:\n            raise Refused("a bag over 32 kg is not carried")\n        if n >= free:\n            total += extra_bag_fee(n - free)\n        if bag.weight_kg >= NORMAL_WEIGHT_KG:\n            total += OVERWEIGHT_FEE\n        if bag.oversize:\n            total += OVERSIZE_FEE\n    return total\n'}},typescript:{entry:"README.md",files:{"README.md":"# Baggage fees\n\nWork out what a booking's bags cost. The table below is the fare rule as the\nairline publishes it.\n\n## Extra bag fees\n\n| Bag beyond the free allowance | Fee     |\n| ----------------------------- | ------- |\n| first extra bag               | ₹1,500  |\n| second extra bag              | ₹2,500  |\n| third and beyond              | ₹4,000  |\n\n## Rules\n\n- The free allowance is one bag in economy, two in premium, three in business.\n- A bag up to and including 23 kg is a normal bag. Above that it is overweight\n  and costs ₹2,000 more, for that bag.\n- A bag above 32 kg is not carried, and the booking is refused.\n- A booking with any oversize bag pays one handling charge of ₹1,000, once,\n  however many oversize bags it has.\n- Amounts are in paise, as integers.\n\n## Notes for the reviewer\n\n`bags` is a list in the order the passenger checked them in. Each bag carries\n`weight_kg` and `oversize`. This one is close to right, so say so if it is:\napproving a change that deserves it is part of the job.\n","src/baggage.ts":'// Baggage fees for a booking.\ntype Bag = { weightKg: number; oversize: boolean };\n\nconst FREE_ALLOWANCE: Record<string, number> = { economy: 1, premium: 2, business: 3 };\nconst EXTRA_BAG_FEES = [150000, 250000, 400000];\nconst OVERWEIGHT_FEE = 200000;\nconst OVERSIZE_FEE = 100000;\nconst NORMAL_WEIGHT_KG = 23;\nconst MAX_WEIGHT_KG = 32;\n\nexport function extraBagFee(index: number) {\n  if (index >= EXTRA_BAG_FEES.length) return EXTRA_BAG_FEES[EXTRA_BAG_FEES.length - 1];\n  return EXTRA_BAG_FEES[index];\n}\n\nexport function baggageTotal(cabin: string, bags: Bag[]) {\n  const free = FREE_ALLOWANCE[cabin];\n  let total = 0;\n  bags.forEach((bag, n) => {\n    if (bag.weightKg > MAX_WEIGHT_KG) throw new Refused("a bag over 32 kg is not carried");\n    if (n >= free) total += extraBagFee(n - free);\n    if (bag.weightKg >= NORMAL_WEIGHT_KG) total += OVERWEIGHT_FEE;\n    if (bag.oversize) total += OVERSIZE_FEE;\n  });\n  return total;\n}\n'}}}},{slug:"health-check",title:"A health endpoint",difficulty:"Easy",area:"infrastructure",domains:["devtools"],minutes:20,summary:"Fifteen lines the load balancer calls every five seconds. Look at what it returns, what it checks, and what status code it sends when the answer is bad.",brief:["A teammate has opened this as a pull request. This endpoint decides whether an instance gets traffic, and anyone on the internet can call it.","Call it as a stranger and read what comes back. Then make the cache slow rather than down, and ask what the load balancer sees.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","It is a short file. A comment on a line that is fine costs you as much as a missed bug."],variants:{java:{entry:"README.md",files:{"README.md":"# A health endpoint\n\nThe load balancer calls `GET /healthz` every five seconds and takes an\ninstance out of rotation when it fails. This PR adds it.\n\n## Rules\n\n- The endpoint answers 200 only when this instance can actually serve traffic.\n- It checks the dependencies this instance cannot work without, and nothing\n  else. A slow dependency must not hold the answer open.\n- It is unauthenticated and public, so it says whether we are healthy and\n  nothing about what we are running.\n- Readiness and liveness are different questions: a failing dependency takes\n  this instance out of rotation, it does not ask for a restart.\n\n## Notes for the reviewer\n\n`db.ping` and `cache.ping` do a round trip with no timeout of their own.\n`redis` here is the cache, not a store of record: the app serves reads from\nPostgres when it is down.\n","src/Health.java":'package platform;\n\nimport java.util.LinkedHashMap;\nimport java.util.Map;\n\n/** GET /healthz */\npublic final class Health {\n    private static final String VERSION = System.getenv().getOrDefault("GIT_SHA", "dev");\n\n    public record Response(Map<String, Object> body, int status) {}\n\n    public static Response healthz() {\n        Map<String, Object> checks = new LinkedHashMap<>();\n        checks.put("db", Db.ping());\n        checks.put("cache", Cache.ping());\n        checks.put("queueUrl", System.getenv("QUEUE_URL"));\n        checks.put("version", VERSION);\n        boolean ok = (boolean) checks.get("db") && (boolean) checks.get("cache");\n        Map<String, Object> body = Map.of("status", ok ? "ok" : "degraded", "checks", checks);\n        return new Response(body, 200);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# A health endpoint\n\nThe load balancer calls `GET /healthz` every five seconds and takes an\ninstance out of rotation when it fails. This PR adds it.\n\n## Rules\n\n- The endpoint answers 200 only when this instance can actually serve traffic.\n- It checks the dependencies this instance cannot work without, and nothing\n  else. A slow dependency must not hold the answer open.\n- It is unauthenticated and public, so it says whether we are healthy and\n  nothing about what we are running.\n- Readiness and liveness are different questions: a failing dependency takes\n  this instance out of rotation, it does not ask for a restart.\n\n## Notes for the reviewer\n\n`db.ping` and `cache.ping` do a round trip with no timeout of their own.\n`redis` here is the cache, not a store of record: the app serves reads from\nPostgres when it is down.\n","src/health.py":'"""GET /healthz"""\nimport os\n\nimport cache\nimport db\n\nVERSION = os.environ.get("GIT_SHA", "dev")\n\n\ndef healthz():\n    checks = {\n        "db": db.ping(),\n        "cache": cache.ping(),\n        "queue_url": os.environ.get("QUEUE_URL"),\n        "version": VERSION,\n    }\n    ok = checks["db"] and checks["cache"]\n    return {"status": "ok" if ok else "degraded", "checks": checks}, 200\n'}},typescript:{entry:"README.md",files:{"README.md":"# A health endpoint\n\nThe load balancer calls `GET /healthz` every five seconds and takes an\ninstance out of rotation when it fails. This PR adds it.\n\n## Rules\n\n- The endpoint answers 200 only when this instance can actually serve traffic.\n- It checks the dependencies this instance cannot work without, and nothing\n  else. A slow dependency must not hold the answer open.\n- It is unauthenticated and public, so it says whether we are healthy and\n  nothing about what we are running.\n- Readiness and liveness are different questions: a failing dependency takes\n  this instance out of rotation, it does not ask for a restart.\n\n## Notes for the reviewer\n\n`db.ping` and `cache.ping` do a round trip with no timeout of their own.\n`redis` here is the cache, not a store of record: the app serves reads from\nPostgres when it is down.\n","src/health.ts":'// GET /healthz\nimport { cache } from "./cache";\nimport { db } from "./db";\n\nconst VERSION = process.env.GIT_SHA ?? "dev";\n\nexport async function healthz() {\n  const checks = {\n    db: await db.ping(),\n    cache: await cache.ping(),\n    queueUrl: process.env.QUEUE_URL,\n    version: VERSION,\n  };\n  const ok = checks.db && checks.cache;\n  return { body: { status: ok ? "ok" : "degraded", checks }, status: 200 };\n}\n'}}}},{slug:"quiet-hours",title:"Quiet hours",difficulty:"Easy",area:"time",domains:["messaging","scheduling"],minutes:20,summary:"Ten lines and one comparison. The README says the window usually crosses midnight, and the comparison says otherwise.",brief:["A teammate has opened this as a pull request. It is short, so read every rule against every line.","Take a window of 22:00 to 07:00 and ask what this says at 23:00, at 03:00 and at 07:00. Then take a user in Kolkata.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","It is a small file, so a comment on a line that is fine costs you as much as a missed bug."],variants:{java:{entry:"README.md",files:{"README.md":'# Quiet hours\n\nPeople set a window when we do not disturb them. This PR decides whether a\nnotification may go out now or has to wait.\n\n## Rules\n\n- The window is two wall-clock times in the person’s own zone, and it usually\n  crosses midnight: 22:00 to 07:00.\n- Inside the window we hold the notification until the window ends, we do not\n  drop it.\n- An urgent notification (a security alert, a payment failure) goes out\n  anyway.\n- Somebody who has not set a window has no quiet hours.\n- The window ends when the end time is reached: at exactly 07:00 we may send.\n\n## Notes for the reviewer\n\n`users` carry `quiet_from`, `quiet_to` (local times, both null when unset) and\n`timezone`. The caller wants back either "send" or the time to hold until.\n',"src/Quiet.java":'package messaging;\n\nimport java.time.Instant;\nimport java.time.LocalTime;\nimport java.time.ZoneOffset;\nimport java.util.Map;\n\n/** Quiet hours. */\npublic final class Quiet {\n\n    public record Decision(boolean send, LocalTime holdUntil) {}\n\n    public static Decision decide(Map<String, Object> user, boolean urgent, Instant now) {\n        LocalTime from = (LocalTime) user.get("quiet_from");\n        LocalTime to = (LocalTime) user.get("quiet_to");\n        if (from == null || to == null) {\n            return new Decision(true, null);\n        }\n\n        LocalTime local = now.atZone(ZoneOffset.UTC).toLocalTime();\n        if (!local.isBefore(from) && !local.isAfter(to)) {\n            return new Decision(false, to);\n        }\n        return new Decision(true, null);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Quiet hours\n\nPeople set a window when we do not disturb them. This PR decides whether a\nnotification may go out now or has to wait.\n\n## Rules\n\n- The window is two wall-clock times in the person’s own zone, and it usually\n  crosses midnight: 22:00 to 07:00.\n- Inside the window we hold the notification until the window ends, we do not\n  drop it.\n- An urgent notification (a security alert, a payment failure) goes out\n  anyway.\n- Somebody who has not set a window has no quiet hours.\n- The window ends when the end time is reached: at exactly 07:00 we may send.\n\n## Notes for the reviewer\n\n`users` carry `quiet_from`, `quiet_to` (local times, both null when unset) and\n`timezone`. The caller wants back either "send" or the time to hold until.\n',"src/quiet.py":'"""Quiet hours."""\nfrom datetime import datetime, timezone\n\n\ndef decide(user, urgent, now=None):\n    now = now or datetime.now(timezone.utc)\n    if user["quiet_from"] is None or user["quiet_to"] is None:\n        return {"send": True}\n\n    local = now.time()\n    if user["quiet_from"] <= local <= user["quiet_to"]:\n        return {"send": False, "hold_until": user["quiet_to"]}\n    return {"send": True}\n'}},typescript:{entry:"README.md",files:{"README.md":'# Quiet hours\n\nPeople set a window when we do not disturb them. This PR decides whether a\nnotification may go out now or has to wait.\n\n## Rules\n\n- The window is two wall-clock times in the person’s own zone, and it usually\n  crosses midnight: 22:00 to 07:00.\n- Inside the window we hold the notification until the window ends, we do not\n  drop it.\n- An urgent notification (a security alert, a payment failure) goes out\n  anyway.\n- Somebody who has not set a window has no quiet hours.\n- The window ends when the end time is reached: at exactly 07:00 we may send.\n\n## Notes for the reviewer\n\n`users` carry `quiet_from`, `quiet_to` (local times, both null when unset) and\n`timezone`. The caller wants back either "send" or the time to hold until.\n',"src/quiet.ts":"// Quiet hours.\ntype User = { quiet_from: string | null; quiet_to: string | null; timezone: string };\n\nexport function decide(user: User, urgent: boolean, now = new Date()) {\n  if (user.quiet_from === null || user.quiet_to === null) return { send: true };\n\n  const local = now.toISOString().slice(11, 16);\n  if (user.quiet_from <= local && local <= user.quiet_to) {\n    return { send: false, holdUntil: user.quiet_to };\n  }\n  return { send: true };\n}\n"}}}},{slug:"like-counter",title:"Likes",difficulty:"Easy",area:"concurrency",domains:["social"],minutes:20,summary:"Fifteen lines behind the most tapped button in the product. Read it as two people tapping at once, then as one person tapping twice.",brief:["A teammate has opened this as a pull request. It runs thousands of times a second and the number it maintains is on every screen.","Have two people like the same post in the same millisecond. Then let a phone on a bad network retry the same tap.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","It is a short file, so a comment on a line that is fine costs you as much as a missed bug."],variants:{java:{entry:"README.md",files:{"README.md":"# Likes\n\nTapping the heart. This PR records a like and keeps the count on the post.\n\n## Rules\n\n- A person likes a post once. Tapping twice is a like and then an unlike.\n- The count on the post is the number of likes it has, and it never goes\n  negative or disagrees with the rows.\n- Two people liking the same post at the same moment both count.\n- Liking is idempotent from the client’s side: a retried request leaves the\n  same state.\n- The response says whether the post is now liked by this person, and the new\n  count.\n\n## Notes for the reviewer\n\n`likes` is `(post_id, user_id, at)` with no unique index yet. `posts` carries\na denormalised `like_count`. Mobile clients retry aggressively.\n","src/Likes.java":'package social;\n\nimport java.util.Map;\n\n/** Liking and unliking a post. */\npublic final class Likes {\n\n    public record Result(boolean liked, long count) {}\n\n    public static Result like(String postId, String userId) {\n        Map<String, Object> existing =\n                Db.one("SELECT 1 FROM likes WHERE post_id = ? AND user_id = ?", postId, userId);\n        if (existing != null) {\n            Db.run("DELETE FROM likes WHERE post_id = ? AND user_id = ?", postId, userId);\n            long count = (long) Db.one("SELECT like_count FROM posts WHERE id = ?", postId).get("like_count");\n            Db.run("UPDATE posts SET like_count = ? WHERE id = ?", count - 1, postId);\n            return new Result(false, count - 1);\n        }\n\n        Db.run("INSERT INTO likes (post_id, user_id, at) VALUES (?, ?, now())", postId, userId);\n        long count = (long) Db.one("SELECT like_count FROM posts WHERE id = ?", postId).get("like_count");\n        Db.run("UPDATE posts SET like_count = ? WHERE id = ?", count + 1, postId);\n        return new Result(true, count + 1);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Likes\n\nTapping the heart. This PR records a like and keeps the count on the post.\n\n## Rules\n\n- A person likes a post once. Tapping twice is a like and then an unlike.\n- The count on the post is the number of likes it has, and it never goes\n  negative or disagrees with the rows.\n- Two people liking the same post at the same moment both count.\n- Liking is idempotent from the client’s side: a retried request leaves the\n  same state.\n- The response says whether the post is now liked by this person, and the new\n  count.\n\n## Notes for the reviewer\n\n`likes` is `(post_id, user_id, at)` with no unique index yet. `posts` carries\na denormalised `like_count`. Mobile clients retry aggressively.\n","src/likes.py":'"""Liking and unliking a post."""\nimport db\n\n\ndef like(post_id, user_id):\n    existing = db.one("SELECT 1 FROM likes WHERE post_id = %s AND user_id = %s", (post_id, user_id))\n    if existing:\n        db.run("DELETE FROM likes WHERE post_id = %s AND user_id = %s", (post_id, user_id))\n        post = db.one("SELECT like_count FROM posts WHERE id = %s", (post_id,))\n        db.run("UPDATE posts SET like_count = %s WHERE id = %s", (post["like_count"] - 1, post_id))\n        return {"liked": False, "count": post["like_count"] - 1}\n\n    db.run("INSERT INTO likes (post_id, user_id, at) VALUES (%s, %s, now())", (post_id, user_id))\n    post = db.one("SELECT like_count FROM posts WHERE id = %s", (post_id,))\n    db.run("UPDATE posts SET like_count = %s WHERE id = %s", (post["like_count"] + 1, post_id))\n    return {"liked": True, "count": post["like_count"] + 1}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Likes\n\nTapping the heart. This PR records a like and keeps the count on the post.\n\n## Rules\n\n- A person likes a post once. Tapping twice is a like and then an unlike.\n- The count on the post is the number of likes it has, and it never goes\n  negative or disagrees with the rows.\n- Two people liking the same post at the same moment both count.\n- Liking is idempotent from the client’s side: a retried request leaves the\n  same state.\n- The response says whether the post is now liked by this person, and the new\n  count.\n\n## Notes for the reviewer\n\n`likes` is `(post_id, user_id, at)` with no unique index yet. `posts` carries\na denormalised `like_count`. Mobile clients retry aggressively.\n","src/likes.ts":'// Liking and unliking a post.\nimport { db } from "./db";\n\nexport async function like(postId: string, userId: string) {\n  const existing = await db.one("SELECT 1 FROM likes WHERE post_id = $1 AND user_id = $2", [postId, userId]);\n  if (existing) {\n    await db.run("DELETE FROM likes WHERE post_id = $1 AND user_id = $2", [postId, userId]);\n    const post = await db.one("SELECT like_count FROM posts WHERE id = $1", [postId]);\n    await db.run("UPDATE posts SET like_count = $1 WHERE id = $2", [post.like_count - 1, postId]);\n    return { liked: false, count: post.like_count - 1 };\n  }\n\n  await db.run("INSERT INTO likes (post_id, user_id, at) VALUES ($1, $2, now())", [postId, userId]);\n  const post = await db.one("SELECT like_count FROM posts WHERE id = $1", [postId]);\n  await db.run("UPDATE posts SET like_count = $1 WHERE id = $2", [post.like_count + 1, postId]);\n  return { liked: true, count: post.like_count + 1 };\n}\n'}}}},{slug:"subtitle-timing",title:"Shifting subtitles",difficulty:"Easy",area:"backend",domains:["media"],minutes:20,summary:"Parse a time, add an offset, write it back. Twenty-five lines, and the first rule in the README is about the case this parser does not handle.",brief:["A teammate has opened this as a pull request. Subtitle files come from everywhere and are full of surprises.","Shift a two-hour film. Then shift a file backwards by more than the first cue’s start.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","It is a small file, so a comment on a line that is fine costs you as much as a missed bug."],variants:{java:{entry:"README.md",files:{"README.md":"# Shifting subtitles\n\nSubtitles arrive out of sync with the video. This PR parses a WebVTT file and\nshifts every cue by an offset.\n\n## Rules\n\n- A cue time is `HH:MM:SS.mmm`. Hours may be missing, and milliseconds are\n  always three digits.\n- Shifting never produces a negative time. A cue that would go before zero\n  starts at zero, and keeps its length if it can.\n- A cue ends after it starts. A shift never reorders or overlaps them.\n- The text of a cue is untouched, including blank lines inside it.\n- The file may be an hour of dialogue, so it is parsed once, not per cue.\n\n## Notes for the reviewer\n\n`parse_time` and `format_time` are the only clock arithmetic here. The offset\nis in milliseconds and can be negative.\n","src/Subtitles.java":'package media;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\n/** Shifting WebVTT cues. */\npublic final class Subtitles {\n    private static final Pattern TIME = Pattern.compile("(\\\\d{2}):(\\\\d{2})\\\\.(\\\\d{3})");\n    private static final String ARROW = " --\x3e ";\n\n    public static long parseTime(String text) {\n        Matcher m = TIME.matcher(text);\n        m.find();\n        return Long.parseLong(m.group(1)) * 60000 + Long.parseLong(m.group(2)) * 1000 + Long.parseLong(m.group(3));\n    }\n\n    public static String formatTime(long ms) {\n        long minutes = ms / 60000;\n        long seconds = (ms % 60000) / 1000;\n        long millis = ms % 1000;\n        return String.format("%02d:%02d.%03d", minutes, seconds, millis);\n    }\n\n    public static String shift(String vtt, long offsetMs) {\n        List<String> out = new ArrayList<>();\n        for (String line : vtt.split("\\n")) {\n            if (line.contains(ARROW)) {\n                String[] parts = line.split(ARROW);\n                out.add(formatTime(parseTime(parts[0]) + offsetMs) + ARROW + formatTime(parseTime(parts[1]) + offsetMs));\n            } else {\n                out.add(line);\n            }\n        }\n        return String.join("\\n", out);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Shifting subtitles\n\nSubtitles arrive out of sync with the video. This PR parses a WebVTT file and\nshifts every cue by an offset.\n\n## Rules\n\n- A cue time is `HH:MM:SS.mmm`. Hours may be missing, and milliseconds are\n  always three digits.\n- Shifting never produces a negative time. A cue that would go before zero\n  starts at zero, and keeps its length if it can.\n- A cue ends after it starts. A shift never reorders or overlaps them.\n- The text of a cue is untouched, including blank lines inside it.\n- The file may be an hour of dialogue, so it is parsed once, not per cue.\n\n## Notes for the reviewer\n\n`parse_time` and `format_time` are the only clock arithmetic here. The offset\nis in milliseconds and can be negative.\n","src/subtitles.py":'"""Shifting WebVTT cues."""\nimport re\n\nTIME = re.compile(r"(\\d{2}):(\\d{2})\\.(\\d{3})")\nARROW = " --\x3e "\n\n\ndef parse_time(text):\n    minutes, seconds, millis = TIME.match(text).groups()\n    return int(minutes) * 60000 + int(seconds) * 1000 + int(millis)\n\n\ndef format_time(ms):\n    minutes = ms // 60000\n    seconds = (ms % 60000) // 1000\n    millis = ms % 1000\n    return f"{minutes:02d}:{seconds:02d}.{millis:03d}"\n\n\ndef shift(vtt, offset_ms):\n    out = []\n    for line in vtt.split("\\n"):\n        if ARROW in line:\n            start, end = line.split(ARROW)\n            out.append(format_time(parse_time(start) + offset_ms) + ARROW + format_time(parse_time(end) + offset_ms))\n        else:\n            out.append(line)\n    return "\\n".join(out)\n'}},typescript:{entry:"README.md",files:{"README.md":"# Shifting subtitles\n\nSubtitles arrive out of sync with the video. This PR parses a WebVTT file and\nshifts every cue by an offset.\n\n## Rules\n\n- A cue time is `HH:MM:SS.mmm`. Hours may be missing, and milliseconds are\n  always three digits.\n- Shifting never produces a negative time. A cue that would go before zero\n  starts at zero, and keeps its length if it can.\n- A cue ends after it starts. A shift never reorders or overlaps them.\n- The text of a cue is untouched, including blank lines inside it.\n- The file may be an hour of dialogue, so it is parsed once, not per cue.\n\n## Notes for the reviewer\n\n`parse_time` and `format_time` are the only clock arithmetic here. The offset\nis in milliseconds and can be negative.\n","src/subtitles.ts":'// Shifting WebVTT cues.\nconst TIME = /(\\d{2}):(\\d{2})\\.(\\d{3})/;\nconst ARROW = " --\x3e ";\n\nexport function parseTime(text: string) {\n  const [, minutes, seconds, millis] = TIME.exec(text) as RegExpExecArray;\n  return Number(minutes) * 60000 + Number(seconds) * 1000 + Number(millis);\n}\n\nexport function formatTime(ms: number) {\n  const minutes = Math.floor(ms / 60000);\n  const seconds = Math.floor((ms % 60000) / 1000);\n  const millis = ms % 1000;\n  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${String(millis).padStart(3, "0")}`;\n}\n\nexport function shift(vtt: string, offsetMs: number) {\n  const out: string[] = [];\n  for (const line of vtt.split("\\n")) {\n    if (line.includes(ARROW)) {\n      const [start, end] = line.split(ARROW);\n      out.push(formatTime(parseTime(start) + offsetMs) + ARROW + formatTime(parseTime(end) + offsetMs));\n    } else {\n      out.push(line);\n    }\n  }\n  return out.join("\\n");\n}\n'}}}},{slug:"password-reset",title:"Password reset flow",difficulty:"Medium",area:"security",domains:["identity"],minutes:30,summary:'The two endpoints behind "Forgot password?": mail a reset link, then accept the token and set a new password.',brief:["A teammate has opened this as a pull request. It touches authentication, so review it the way a security-minded senior would.","Read the README for the intended flow, then trace a real request through request and confirm, and think about what an attacker would try at each step.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Not everything that looks unusual is a defect. Some of the choices here are deliberate and correct."],variants:{java:{entry:"README.md",files:{"README.md":'# Password reset\n\nTwo endpoints behind the "Forgot password?" link.\n\n1. `Reset.requestReset(email)`: emails the user a link carrying a reset token.\n2. `Reset.confirmReset(email, token, newPassword)`: checks the token and sets\n   the new password.\n\n## Flow\n\n```\nPOST /reset/request  {email}                       -> requestReset\nGET  https://app.example.com/reset?token=...      (link in the email)\nPOST /reset/confirm  {email, token, new_password}  -> confirmReset\n```\n\n## Notes for the reviewer\n\nTokens are stored in `password_resets`, one row per request, and mailed as a\nquery parameter. `Db` is the shared connection pool; `Security.hashPassword` is\nour existing argon2 wrapper.\n',"src/Reset.java":'package auth;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Password reset: request a link, then confirm with the token from it. */\npublic final class Reset {\n    private static final Logger log = Logger.getLogger(Reset.class.getName());\n    static final String RESET_URL = "https://app.example.com/reset";\n\n    public record Outcome(boolean ok, String message) {}\n\n    public static Outcome requestReset(String email) {\n        Store.User user = Store.findUser(email);\n        if (user == null) {\n            return new Outcome(false, "No account with that email.");\n        }\n        String token = Tokens.makeToken();\n        Store.saveReset(user.id(), token, Instant.now());\n        log.info("reset token for " + email + ": " + token);\n        Mailer.send(email, "Reset your password", RESET_URL + "?token=" + token);\n        return new Outcome(true, "Check your email for a reset link.");\n    }\n\n    public static Outcome confirmReset(String email, String token, String newPassword) {\n        Store.User user = Store.findUser(email);\n        Store.ResetRow reset = user == null ? null : Store.latestReset(user.id());\n        if (reset == null || !Tokens.tokensMatch(token, reset.token())) {\n            return new Outcome(false, "Invalid or expired link.");\n        }\n        if (newPassword.length() < 8) {\n            return new Outcome(false, "Password must be at least 8 characters.");\n        }\n        Store.setPassword(user.id(), newPassword);\n        return new Outcome(true, "Password updated.");\n    }\n}\n',"src/Store.java":'package auth;\n\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Persistence. {@code Db} is the shared connection pool. */\npublic final class Store {\n    public record User(long id, String email) {}\n    public record ResetRow(long userId, String token, Instant createdAt) {}\n\n    public static User findUser(String email) {\n        Map<String, Object> row = Db.one("SELECT id, email FROM users WHERE email = \'" + email + "\'");\n        return row == null ? null : new User(((Number) row.get("id")).longValue(), (String) row.get("email"));\n    }\n\n    public static void saveReset(long userId, String token, Instant createdAt) {\n        Db.run("INSERT INTO password_resets (user_id, token, created_at) VALUES (?, ?, ?)",\n                userId, token, createdAt);\n    }\n\n    public static ResetRow latestReset(long userId) {\n        Map<String, Object> row = Db.one(\n            "SELECT user_id, token, created_at FROM password_resets WHERE user_id = ? ORDER BY created_at DESC LIMIT 1",\n            userId);\n        return row == null ? null : new ResetRow(userId, (String) row.get("token"), (Instant) row.get("created_at"));\n    }\n\n    public static void setPassword(long userId, String password) {\n        Db.run("UPDATE users SET password_hash = ? WHERE id = ?", Security.hashPassword(password), userId);\n    }\n}\n',"src/Tokens.java":'package auth;\n\nimport java.util.Random;\n\n/** Reset tokens: opaque strings mailed to the user and checked on return. */\npublic final class Tokens {\n    static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";\n    private static final Random random = new Random();\n\n    public static String makeToken() {\n        StringBuilder sb = new StringBuilder(32);\n        for (int i = 0; i < 32; i++) sb.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));\n        return sb.toString();\n    }\n\n    public static boolean tokensMatch(String given, String stored) {\n        return given.equals(stored);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Password reset\n\nTwo endpoints behind the "Forgot password?" link.\n\n1. `request_reset(email)`: emails the user a link carrying a reset token.\n2. `confirm_reset(email, token, new_password)`: checks the token and sets the\n   new password.\n\n## Flow\n\n```\nPOST /reset/request  {email}                       -> request_reset\nGET  https://app.example.com/reset?token=...      (link in the email)\nPOST /reset/confirm  {email, token, new_password}  -> confirm_reset\n```\n\n## Notes for the reviewer\n\nTokens are stored in `password_resets`, one row per request, and mailed as a\nquery parameter. `db` is the shared psycopg pool; `security.hash_password` is\nour existing argon2 wrapper.\n',"src/reset.py":'"""Password reset: request a link, then confirm with the token from it."""\nimport logging\nfrom datetime import datetime\n\nimport mailer\nimport store\nfrom tokens import make_token, tokens_match\n\nlog = logging.getLogger(__name__)\n\nRESET_URL = "https://app.example.com/reset"\n\n\ndef request_reset(email):\n    user = store.find_user(email)\n    if user is None:\n        return {"ok": False, "message": "No account with that email."}\n    token = make_token()\n    store.save_reset(user.id, token, datetime.utcnow())\n    log.info("reset token for %s: %s", email, token)\n    mailer.send(email, "Reset your password", f"{RESET_URL}?token={token}")\n    return {"ok": True, "message": "Check your email for a reset link."}\n\n\ndef confirm_reset(email, token, new_password):\n    user = store.find_user(email)\n    reset = store.latest_reset(user.id) if user else None\n    if reset is None or not tokens_match(token, reset.token):\n        return {"ok": False, "message": "Invalid or expired link."}\n    if len(new_password) < 8:\n        return {"ok": False, "message": "Password must be at least 8 characters."}\n    store.set_password(user.id, new_password)\n    return {"ok": True, "message": "Password updated."}\n',"src/store.py":'"""Persistence. `db` is the shared psycopg connection pool."""\nfrom dataclasses import dataclass\nfrom datetime import datetime\n\nimport db\nfrom security import hash_password\n\n\n@dataclass\nclass User:\n    id: int\n    email: str\n\n\n@dataclass\nclass Reset:\n    user_id: int\n    token: str\n    created_at: datetime\n\n\ndef find_user(email):\n    row = db.one(f"SELECT id, email FROM users WHERE email = \'{email}\'")\n    return User(*row) if row else None\n\n\ndef save_reset(user_id, token, created_at):\n    db.run(\n        "INSERT INTO password_resets (user_id, token, created_at) VALUES (%s, %s, %s)",\n        (user_id, token, created_at),\n    )\n\n\ndef latest_reset(user_id):\n    row = db.one(\n        "SELECT user_id, token, created_at FROM password_resets WHERE user_id = %s ORDER BY created_at DESC LIMIT 1",\n        (user_id,),\n    )\n    return Reset(*row) if row else None\n\n\ndef set_password(user_id, password):\n    db.run("UPDATE users SET password_hash = %s WHERE id = %s", (hash_password(password), user_id))\n',"src/tokens.py":'"""Reset tokens: opaque strings mailed to the user and checked on return."""\nimport random\nimport string\n\nALPHABET = string.ascii_letters + string.digits\n\n\ndef make_token(length=32):\n    return "".join(random.choice(ALPHABET) for _ in range(length))\n\n\ndef tokens_match(given, stored):\n    return given == stored\n'}},typescript:{entry:"README.md",files:{"README.md":'# Password reset\n\nTwo endpoints behind the "Forgot password?" link.\n\n1. `requestReset(email)`: emails the user a link carrying a reset token.\n2. `confirmReset(email, token, newPassword)`: checks the token and sets the\n   new password.\n\n## Flow\n\n```\nPOST /reset/request  {email}                      -> requestReset\nGET  https://app.example.com/reset?token=...     (link in the email)\nPOST /reset/confirm  {email, token, newPassword}  -> confirmReset\n```\n\n## Notes for the reviewer\n\nTokens are stored in `password_resets`, one row per request, and mailed as a\nquery parameter. `db` is the shared pg pool; `hashPassword` in `./security`\nis our existing argon2 wrapper.\n',"src/reset.ts":'// Password reset: request a link, then confirm with the token from it.\nimport * as mailer from "./mailer";\nimport * as store from "./store";\nimport { makeToken, tokensMatch } from "./tokens";\n\nconst RESET_URL = "https://app.example.com/reset";\n\ntype Result = { ok: boolean; message: string };\n\nexport async function requestReset(email: string): Promise<Result> {\n  const user = await store.findUser(email);\n  if (!user) return { ok: false, message: "No account with that email." };\n  const token = makeToken();\n  await store.saveReset(user.id, token, new Date());\n  console.info(`reset token for ${email}: ${token}`);\n  await mailer.send(email, "Reset your password", `${RESET_URL}?token=${token}`);\n  return { ok: true, message: "Check your email for a reset link." };\n}\n\nexport async function confirmReset(email: string, token: string, newPassword: string): Promise<Result> {\n  const user = await store.findUser(email);\n  const reset = user ? await store.latestReset(user.id) : null;\n  if (!reset || !tokensMatch(token, reset.token)) {\n    return { ok: false, message: "Invalid or expired link." };\n  }\n  if (newPassword.length < 8) {\n    return { ok: false, message: "Password must be at least 8 characters." };\n  }\n  await store.setPassword(user!.id, newPassword);\n  return { ok: true, message: "Password updated." };\n}\n',"src/store.ts":'// Persistence. `db` is the shared pg pool.\nimport { db } from "./db";\nimport { hashPassword } from "./security";\n\nexport type User = { id: number; email: string };\nexport type Reset = { user_id: number; token: string; created_at: Date };\n\nexport async function findUser(email: string): Promise<User | null> {\n  return db.one<User>(`SELECT id, email FROM users WHERE email = \'${email}\'`);\n}\n\nexport async function saveReset(userId: number, token: string, createdAt: Date): Promise<void> {\n  await db.run("INSERT INTO password_resets (user_id, token, created_at) VALUES ($1, $2, $3)", [userId, token, createdAt]);\n}\n\nexport async function latestReset(userId: number): Promise<Reset | null> {\n  return db.one<Reset>(\n    "SELECT user_id, token, created_at FROM password_resets WHERE user_id = $1 ORDER BY created_at DESC LIMIT 1",\n    [userId],\n  );\n}\n\nexport async function setPassword(userId: number, password: string): Promise<void> {\n  await db.run("UPDATE users SET password_hash = $1 WHERE id = $2", [await hashPassword(password), userId]);\n}\n',"src/tokens.ts":'// Reset tokens: opaque strings mailed to the user and checked on return.\nconst ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";\n\nexport function makeToken(length = 32): string {\n  let out = "";\n  for (let i = 0; i < length; i++) out += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];\n  return out;\n}\n\nexport function tokensMatch(given: string, stored: string): boolean {\n  return given === stored;\n}\n'}}}},{slug:"rate-limiter",title:"Rate limiter middleware",difficulty:"Medium",area:"backend",domains:["devtools"],minutes:25,summary:"A sliding-window rate limiter kept in process memory and applied to every route: sixty requests a minute per client.",brief:["A teammate has opened this as a pull request. It runs in front of every API route, so a mistake here either lets abuse through or locks real users out.","Read the README for the promised behaviour, then trace one request through clientKey and allow with the units and the data structures in mind.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are deliberate for a first rollout and are explained in the README; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Rate limiter filter\n\nLimits each client to `LIMIT` requests per `WINDOW_SECONDS`, counted in a\nsliding window kept in process memory. Applied to every API route.\n\n## Behaviour\n\n- The client is identified by IP address.\n- Over the limit: respond `429` and do not run the handler.\n- The counter is per client, not per route: 60 requests across any mix of\n  endpoints is the limit.\n\n## Notes for the reviewer\n\n`App.use(Filter)` registers a servlet-style filter that gets the request and\nthe chain. Redis is not used here on purpose; this is the single-process\nversion for the first rollout, behind one load balancer.\n","src/App.java":'package api;\n\n/** Wiring: the limiter runs before every route. */\npublic final class App {\n    public static void main(String[] args) {\n        Server app = new Server();\n        app.use(new Limiter());\n\n        app.get("/health", request -> Response.json(Map.of("ok", true)));\n\n        app.get("/users/{id}", request -> Response.json(request.db().user(request.param("id"))));\n\n        app.listen(8080);\n    }\n}\n',"src/Limiter.java":'package api;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** Sliding-window rate limiter, one process, in memory. */\npublic final class Limiter implements Filter {\n    static final int LIMIT = 60;\n    static final int WINDOW_SECONDS = 60;\n\n    // client key -> request timestamps (ms)\n    private static final Map<String, List<Long>> hits = new HashMap<>();\n\n    static String clientKey(Request request) {\n        // Behind the load balancer the real address is the first X-Forwarded-For entry.\n        String forwarded = request.header("x-forwarded-for");\n        if (forwarded != null) {\n            return forwarded.split(",")[0].trim() + ":" + request.path();\n        }\n        return request.remoteAddr() + ":" + request.path();\n    }\n\n    static synchronized boolean allow(String key) {\n        long now = System.currentTimeMillis();\n        List<Long> list = hits.computeIfAbsent(key, k -> new ArrayList<>());\n        long cutoff = now - WINDOW_SECONDS;\n        while (!list.isEmpty() && list.get(0) < cutoff) {\n            list.remove(0);\n        }\n        if (list.size() >= LIMIT) {\n            return false;\n        }\n        list.add(now);\n        return true;\n    }\n\n    @Override\n    public Response filter(Request request, Chain chain) {\n        if (!allow(clientKey(request))) {\n            return Response.of(429, "Too many requests");\n        }\n        return chain.next(request);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Rate limiter middleware\n\nLimits each client to `LIMIT` requests per `WINDOW_SECONDS`, counted in a\nsliding window kept in process memory. Applied to every API route.\n\n## Behaviour\n\n- The client is identified by IP address.\n- Over the limit: respond `429` and do not run the handler.\n- The counter is per client, not per route: 60 requests across any mix of\n  endpoints is the limit.\n\n## Notes for the reviewer\n\n`app` is our small ASGI-style framework: a middleware is a callable that gets\nthe request and the next handler. `redis` is not used here on purpose; this\nis the single-process version for the first rollout, behind one load balancer.\n","src/app.py":'"""Wiring: the limiter runs before every route."""\nfrom framework import App\n\nfrom limiter import rate_limit\n\napp = App()\napp.use(rate_limit)\n\n\n@app.get("/health")\nasync def health(request):\n    return {"ok": True}\n\n\n@app.get("/users/{id}")\nasync def get_user(request):\n    return await request.db.user(request.params["id"])\n',"src/limiter.py":'"""Sliding-window rate limiter, one process, in memory."""\nimport time\n\nLIMIT = 60\nWINDOW_SECONDS = 60\n\n# client key -> list of request timestamps (seconds)\n_hits = {}\n\n\ndef client_key(request):\n    # Behind the load balancer the real address is the first X-Forwarded-For entry.\n    forwarded = request.headers.get("x-forwarded-for")\n    if forwarded:\n        return forwarded.split(",")[0].strip() + ":" + request.path\n    return request.remote_addr + ":" + request.path\n\n\ndef allow(key):\n    now = time.time()\n    hits = _hits.setdefault(key, [])\n    cutoff = now - WINDOW_SECONDS * 1000\n    while hits and hits[0] < cutoff:\n        hits.pop(0)\n    if len(hits) >= LIMIT:\n        return False\n    hits.append(now)\n    return True\n\n\nasync def rate_limit(request, handler):\n    key = client_key(request)\n    if not allow(key):\n        return Response(status=429, body="Too many requests")\n    return await handler(request)\n\n\nclass Response:\n    def __init__(self, status, body="", headers=None):\n        self.status = status\n        self.body = body\n        self.headers = headers or {}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Rate limiter middleware\n\nLimits each client to `LIMIT` requests per `WINDOW_SECONDS`, counted in a\nsliding window kept in process memory. Applied to every API route.\n\n## Behaviour\n\n- The client is identified by IP address.\n- Over the limit: respond `429` and do not run the handler.\n- The counter is per client, not per route: 60 requests across any mix of\n  endpoints is the limit.\n\n## Notes for the reviewer\n\nExpress-style middleware. Redis is not used here on purpose; this is the\nsingle-process version for the first rollout, behind one load balancer.\n","src/app.ts":'// Wiring: the limiter runs before every route.\nimport { createApp } from "./framework";\nimport { rateLimit } from "./limiter";\n\nexport const app = createApp();\napp.use(rateLimit);\n\napp.get("/health", (_req, res) => res.json({ ok: true }));\n\napp.get("/users/:id", async (req, res) => {\n  res.json(await req.db.user(req.params.id));\n});\n',"src/limiter.ts":'// Sliding-window rate limiter, one process, in memory.\nimport type { Request, Response, NextFunction } from "./framework";\n\nexport const LIMIT = 60;\nexport const WINDOW_SECONDS = 60;\n\n// client key -> request timestamps (ms)\nconst hits = new Map<string, number[]>();\n\nexport function clientKey(req: Request): string {\n  // Behind the load balancer the real address is the first X-Forwarded-For entry.\n  const forwarded = req.headers["x-forwarded-for"];\n  if (forwarded) return forwarded.split(",")[0].trim() + ":" + req.path;\n  return req.ip + ":" + req.path;\n}\n\nexport function allow(key: string): boolean {\n  const now = Date.now();\n  let list = hits.get(key);\n  if (!list) {\n    list = [];\n    hits.set(key, list);\n  }\n  const cutoff = now - WINDOW_SECONDS;\n  while (list.length && list[0] < cutoff) list.shift();\n  if (list.length >= LIMIT) return false;\n  list.push(now);\n  return true;\n}\n\nexport function rateLimit(req: Request, res: Response, next: NextFunction): void {\n  const key = clientKey(req);\n  if (!allow(key)) {\n    res.status(429).send("Too many requests");\n    return;\n  }\n  next();\n}\n'}}}},{slug:"file-upload",title:"Avatar upload",difficulty:"Medium",area:"security",domains:["social","identity"],minutes:25,summary:"POST /me/avatar: accept an image, store it on disk under the user, and point the profile at it.",brief:["A teammate has opened this as a pull request. It writes user-supplied bytes to disk on a server that nginx serves from, so review it with an attacker in mind.","Read the README for the rules (type, size, replacement, failure behaviour), then check each one against the code.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Not everything unusual is a defect. Some of the plumbing here is fine."],variants:{java:{entry:"README.md",files:{"README.md":"# Avatar upload\n\n`POST /me/avatar` with a multipart file. The image is stored under\n`UPLOAD_DIR/<user id>/` and the profile's `avatar_url` is updated.\n\n## Rules\n\n- PNG or JPEG only, at most 2 MB.\n- A user's previous avatar is replaced.\n- Anything invalid answers `400`; a storage failure answers `500` and leaves\n  the old avatar in place.\n\n## Notes for the reviewer\n\n`request.file(\"avatar\")` gives the multipart part: `filename()`,\n`contentType()` and `stream()`. `Store` writes the profile row. The upload\ndirectory is served by nginx as `/static/avatars`.\n","src/Store.java":'package profile;\n\nimport java.util.Map;\n\n/** Persistence. {@code Db} is the shared connection pool. */\npublic final class Store {\n    public static void setAvatar(long userId, String url) {\n        Db.run("UPDATE profiles SET avatar_url = ?, updated_at = now() WHERE user_id = ?", url, userId);\n    }\n\n    public static Map<String, Object> getAvatar(long userId) {\n        return Db.one("SELECT avatar_url FROM profiles WHERE user_id = ?", userId);\n    }\n}\n',"src/Upload.java":'package profile;\n\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.nio.file.StandardCopyOption;\nimport java.util.Map;\nimport java.util.Set;\n\n/** POST /me/avatar: store the image, point the profile at it. */\npublic final class Upload {\n    static final Path UPLOAD_DIR = Path.of("/srv/uploads/avatars");\n    static final int MAX_BYTES = 2 * 1024 * 1024;\n    static final Set<String> ALLOWED = Set.of("image/png", "image/jpeg");\n\n    public static Response saveAvatar(long userId, Request request) throws IOException {\n        Part upload = request.file("avatar");\n        if (upload == null) {\n            return Response.of(400, "no file");\n        }\n        if (!ALLOWED.contains(upload.contentType())) {\n            return Response.of(400, "png or jpeg only");\n        }\n\n        byte[] data = upload.stream().readAllBytes();\n        if (data.length > MAX_BYTES) {\n            return Response.of(400, "too large");\n        }\n\n        Path folder = UPLOAD_DIR.resolve(String.valueOf(userId));\n        Files.createDirectories(folder);\n        Path tmp = Files.createTempFile(folder, "upload", ".part");\n        Files.write(tmp, data);\n\n        Path dest = folder.resolve(upload.filename());\n        Files.move(tmp, dest, StandardCopyOption.REPLACE_EXISTING);\n\n        String url = "/static/avatars/" + userId + "/" + upload.filename();\n        Store.setAvatar(userId, url);\n        return Response.of(200, Map.of("avatar_url", url));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Avatar upload\n\n`POST /me/avatar` with a multipart file. The image is stored under\n`UPLOAD_DIR/<user id>/` and the profile's `avatar_url` is updated.\n\n## Rules\n\n- PNG or JPEG only, at most 2 MB.\n- A user's previous avatar is replaced.\n- Anything invalid answers `400`; a storage failure answers `500` and leaves\n  the old avatar in place.\n\n## Notes for the reviewer\n\n`request.file()` streams the upload from the multipart body. `store` writes\nthe profile row. The upload directory is served by nginx as `/static/avatars`.\n","src/store.py":'"""Persistence. `db` is the shared psycopg connection pool."""\nimport db\n\n\ndef set_avatar(user_id, url):\n    db.run("UPDATE profiles SET avatar_url = %s, updated_at = now() WHERE user_id = %s", (url, user_id))\n\n\ndef get_avatar(user_id):\n    return db.one("SELECT avatar_url FROM profiles WHERE user_id = %s", (user_id,))\n',"src/upload.py":'"""POST /me/avatar: store the image, point the profile at it."""\nimport os\nimport shutil\nimport tempfile\n\nimport store\n\nUPLOAD_DIR = "/srv/uploads/avatars"\nMAX_BYTES = 2 * 1024 * 1024\nALLOWED = {"image/png", "image/jpeg"}\n\n\ndef save_avatar(user_id, request):\n    upload = request.file("avatar")\n    if upload is None:\n        return 400, "no file"\n    if upload.content_type not in ALLOWED:\n        return 400, "png or jpeg only"\n\n    data = upload.read()\n    if len(data) > MAX_BYTES:\n        return 400, "too large"\n\n    folder = os.path.join(UPLOAD_DIR, str(user_id))\n    os.makedirs(folder, exist_ok=True)\n    tmp = tempfile.NamedTemporaryFile(delete=False, dir=folder)\n    tmp.write(data)\n    tmp.close()\n\n    dest = os.path.join(folder, upload.filename)\n    shutil.move(tmp.name, dest)\n\n    url = "/static/avatars/%s/%s" % (user_id, upload.filename)\n    store.set_avatar(user_id, url)\n    return 200, {"avatar_url": url}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Avatar upload\n\n`POST /me/avatar` with a multipart file. The image is stored under\n`UPLOAD_DIR/<user id>/` and the profile's `avatar_url` is updated.\n\n## Rules\n\n- PNG or JPEG only, at most 2 MB.\n- A user's previous avatar is replaced.\n- Anything invalid answers `400`; a storage failure answers `500` and leaves\n  the old avatar in place.\n\n## Notes for the reviewer\n\n`req.file(\"avatar\")` resolves to the multipart part with a readable stream.\n`store` writes the profile row. The upload directory is served by nginx as\n`/static/avatars`.\n","src/store.ts":'// Persistence. `db` is the shared pg pool.\nimport { db } from "./db";\n\nexport async function setAvatar(userId: string, url: string): Promise<void> {\n  await db.run("UPDATE profiles SET avatar_url = $1, updated_at = now() WHERE user_id = $2", [url, userId]);\n}\n\nexport async function getAvatar(userId: string): Promise<string | null> {\n  const row = await db.one<{ avatar_url: string | null }>("SELECT avatar_url FROM profiles WHERE user_id = $1", [userId]);\n  return row?.avatar_url ?? null;\n}\n',"src/upload.ts":'// POST /me/avatar: store the image, point the profile at it.\nimport { mkdir, rename, writeFile } from "node:fs/promises";\nimport { join } from "node:path";\nimport { randomBytes } from "node:crypto";\nimport * as store from "./store";\nimport type { Request } from "./framework";\n\nconst UPLOAD_DIR = "/srv/uploads/avatars";\nconst MAX_BYTES = 2 * 1024 * 1024;\nconst ALLOWED = new Set(["image/png", "image/jpeg"]);\n\nexport async function saveAvatar(userId: string, req: Request): Promise<[number, unknown]> {\n  const upload = await req.file("avatar");\n  if (!upload) return [400, "no file"];\n  if (!ALLOWED.has(upload.contentType)) return [400, "png or jpeg only"];\n\n  const chunks: Buffer[] = [];\n  for await (const chunk of upload.stream) chunks.push(chunk);\n  const data = Buffer.concat(chunks);\n  if (data.length > MAX_BYTES) return [400, "too large"];\n\n  const folder = join(UPLOAD_DIR, userId);\n  await mkdir(folder, { recursive: true });\n  const tmp = join(folder, `.${randomBytes(6).toString("hex")}.part`);\n  await writeFile(tmp, data);\n\n  const dest = join(folder, upload.filename);\n  await rename(tmp, dest);\n\n  const url = `/static/avatars/${userId}/${upload.filename}`;\n  await store.setAvatar(userId, url);\n  return [200, { avatar_url: url }];\n}\n'}}}},{slug:"job-retry",title:"Email job worker",difficulty:"Medium",area:"backend",domains:["messaging"],minutes:25,summary:"The worker that pulls email jobs off the queue, delivers them with retries, and dead-letters the ones that keep failing.",brief:["A teammate has opened this as a pull request. The README promises three guarantees; check each one against the code.","Trace one job through process, including what happens on the second attempt and what the database says about the job at each point.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","The dead-letter path is deliberate and correct."],variants:{java:{entry:"README.md",files:{"README.md":"# Email job worker\n\nPulls `send_email` jobs off the queue and delivers them through the mail\nprovider. Failed deliveries are retried; after `MAX_ATTEMPTS` the job goes to\nthe dead-letter table for a human.\n\n## Guarantees we promise\n\n- A recipient never gets the same email twice.\n- Transient provider errors (timeouts, 5xx) are retried with backoff.\n- Permanent errors (bad address, 4xx) are not retried.\n\n## Notes for the reviewer\n\n`Queue.next()` blocks until a job is available. `Mailer.send` throws\n`MailerException`, whose `isPermanent()` is true for 4xx responses.\n","src/Store.java":"package mail;\n\n/** Job bookkeeping. {@code Db} is the shared connection pool. */\npublic final class Store {\n    public static void markDone(long jobId) {\n        Db.run(\"UPDATE jobs SET status = 'done', finished_at = now() WHERE id = ?\", jobId);\n    }\n\n    public static void deadLetter(long jobId, String reason) {\n        Db.run(\"UPDATE jobs SET status = 'dead', error = ? WHERE id = ?\", reason, jobId);\n    }\n}\n","src/Worker.java":'package mail;\n\nimport java.util.logging.Logger;\n\n/** The worker loop. */\npublic final class Worker {\n    private static final Logger log = Logger.getLogger(Worker.class.getName());\n    static final int MAX_ATTEMPTS = 3;\n\n    public static void runForever() {\n        while (true) {\n            Job job = Queue.next();\n            process(job);\n        }\n    }\n\n    static void process(Job job) {\n        Store.markDone(job.id());\n        int attempt = 0;\n        while (attempt < MAX_ATTEMPTS - 1) {\n            attempt++;\n            try {\n                log.info("sending " + job.id() + " to " + job.recipients() + ": " + job.body());\n                for (String to : job.recipients()) {\n                    Mailer.send(to, job.subject(), job.body());\n                }\n                return;\n            } catch (Throwable exc) {\n                log.warning("attempt " + attempt + " failed for " + job.id() + ": " + exc.getMessage());\n                if (exc instanceof MailerException me && me.isPermanent()) {\n                    break;\n                }\n            }\n        }\n        Store.deadLetter(job.id(), "gave up after " + attempt + " attempts");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Email job worker\n\nPulls `send_email` jobs off the queue and delivers them through the mail\nprovider. Failed deliveries are retried; after `MAX_ATTEMPTS` the job goes to\nthe dead-letter table for a human.\n\n## Guarantees we promise\n\n- A recipient never gets the same email twice.\n- Transient provider errors (timeouts, 5xx) are retried with backoff.\n- Permanent errors (bad address, 4xx) are not retried.\n\n## Notes for the reviewer\n\n`queue.next()` blocks until a job is available. `mailer.send` raises\n`MailerError` with `.permanent = True` for 4xx responses.\n","src/store.py":'"""Job bookkeeping. `db` is the shared psycopg pool."""\nimport db\n\n\ndef mark_done(job_id):\n    db.run("UPDATE jobs SET status = \'done\', finished_at = now() WHERE id = %s", (job_id,))\n\n\ndef dead_letter(job_id, reason):\n    db.run("UPDATE jobs SET status = \'dead\', error = %s WHERE id = %s", (reason, job_id))\n',"src/worker.py":'"""The worker loop."""\nimport logging\n\nimport mailer\nimport queue\nimport store\n\nlog = logging.getLogger(__name__)\n\nMAX_ATTEMPTS = 3\n\n\ndef run_forever():\n    while True:\n        job = queue.next()\n        process(job)\n\n\ndef process(job):\n    store.mark_done(job.id)\n    attempt = 0\n    while attempt < MAX_ATTEMPTS - 1:\n        attempt += 1\n        try:\n            log.info("sending %s to %s: %s", job.id, job.to, job.body)\n            for to in job.recipients:\n                mailer.send(to, job.subject, job.body)\n            return\n        except BaseException as exc:\n            log.warning("attempt %s failed for %s: %s", attempt, job.id, exc)\n            if getattr(exc, "permanent", False):\n                break\n    store.dead_letter(job.id, "gave up after %s attempts" % attempt)\n'}},typescript:{entry:"README.md",files:{"README.md":"# Email job worker\n\nPulls `send_email` jobs off the queue and delivers them through the mail\nprovider. Failed deliveries are retried; after `MAX_ATTEMPTS` the job goes to\nthe dead-letter table for a human.\n\n## Guarantees we promise\n\n- A recipient never gets the same email twice.\n- Transient provider errors (timeouts, 5xx) are retried with backoff.\n- Permanent errors (bad address, 4xx) are not retried.\n\n## Notes for the reviewer\n\n`queue.next()` resolves when a job is available. `mailer.send` throws a\n`MailerError` with `.permanent = true` for 4xx responses.\n","src/store.ts":'// Job bookkeeping. `db` is the shared pg pool.\nimport { db } from "./db";\n\nexport async function markDone(jobId: string): Promise<void> {\n  await db.run("UPDATE jobs SET status = \'done\', finished_at = now() WHERE id = $1", [jobId]);\n}\n\nexport async function deadLetter(jobId: string, reason: string): Promise<void> {\n  await db.run("UPDATE jobs SET status = \'dead\', error = $1 WHERE id = $2", [reason, jobId]);\n}\n',"src/worker.ts":'// The worker loop.\nimport * as mailer from "./mailer";\nimport * as queue from "./queue";\nimport * as store from "./store";\n\nconst MAX_ATTEMPTS = 3;\n\nexport async function runForever(): Promise<never> {\n  while (true) {\n    const job = await queue.next();\n    await process(job);\n  }\n}\n\nexport async function process(job: queue.Job): Promise<void> {\n  await store.markDone(job.id);\n  let attempt = 0;\n  while (attempt < MAX_ATTEMPTS - 1) {\n    attempt += 1;\n    try {\n      console.info(`sending ${job.id} to ${job.recipients.join(",")}: ${job.body}`);\n      for (const to of job.recipients) {\n        await mailer.send(to, job.subject, job.body);\n      }\n      return;\n    } catch (err) {\n      console.warn(`attempt ${attempt} failed for ${job.id}: ${err}`);\n      if ((err as { permanent?: boolean }).permanent) break;\n    }\n  }\n  await store.deadLetter(job.id, `gave up after ${attempt} attempts`);\n}\n'}}}},{slug:"webhook-receiver",title:"Payment webhook",difficulty:"Medium",area:"security",domains:["payments"],minutes:25,summary:"POST /webhooks/payments: the payment provider tells us a charge succeeded or failed, and we mark the order and start fulfilment.",brief:["A teammate has opened this as a pull request. Anyone on the internet can POST to this URL; only the provider should be able to mark an order paid.","Read the provider contract in the README carefully: the signature, the timestamp, and the retry behaviour all matter.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","The signature construction itself matches the contract."],variants:{java:{entry:"README.md",files:{"README.md":'# Payment webhook\n\nThe payment provider calls `POST /webhooks/payments` when a charge succeeds\nor fails. We mark the order paid and start fulfilment.\n\n## Provider contract\n\n- Body is JSON: `{"event": "charge.succeeded", "order_id": "...", "amount": 129900, "currency": "INR", "charge_id": "..."}`.\n- Header `X-Signature` is `hex(hmac_sha256(WEBHOOK_SECRET, timestamp + "." + raw_body))`\n  and `X-Timestamp` is the unix time the event was sent.\n- The provider retries on any non-2xx response, with backoff, for 24 hours.\n  The same event may be delivered more than once.\n\n## Notes for the reviewer\n\n`orders.expected_amount` holds what we charged. `Fulfilment.start(orderId)`\nis idempotent. `Json.parse` returns the body as a map.\n',"src/Store.java":'package payments;\n\nimport java.util.Map;\n\n/** Orders. {@code Db} is the shared connection pool. */\npublic final class Store {\n    public record Order(String id, String status, long expectedAmount, String currency) {}\n\n    public static Order getOrder(String orderId) {\n        Map<String, Object> row = Db.one("SELECT id, status, expected_amount, currency FROM orders WHERE id = ?", orderId);\n        if (row == null) return null;\n        return new Order((String) row.get("id"), (String) row.get("status"),\n                ((Number) row.get("expected_amount")).longValue(), (String) row.get("currency"));\n    }\n\n    public static void markPaid(String orderId, String chargeId, long amount) {\n        Db.run("UPDATE orders SET status = \'paid\', charge_id = ?, paid_amount = ?, paid_at = now() WHERE id = ?",\n                chargeId, amount, orderId);\n    }\n\n    public static void markFailed(String orderId) {\n        Db.run("UPDATE orders SET status = \'failed\' WHERE id = ?", orderId);\n    }\n}\n',"src/Webhook.java":'package payments;\n\nimport java.nio.charset.StandardCharsets;\nimport java.util.HexFormat;\nimport java.util.Map;\nimport java.util.logging.Logger;\nimport javax.crypto.Mac;\nimport javax.crypto.spec.SecretKeySpec;\n\n/** POST /webhooks/payments */\npublic final class Webhook {\n    private static final Logger log = Logger.getLogger(Webhook.class.getName());\n    static final String SECRET = Env.require("WEBHOOK_SECRET");\n\n    static String signatureFor(String timestamp, String rawBody) throws Exception {\n        Mac mac = Mac.getInstance("HmacSHA256");\n        mac.init(new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));\n        return HexFormat.of().formatHex(mac.doFinal((timestamp + "." + rawBody).getBytes(StandardCharsets.UTF_8)));\n    }\n\n    public static Response handle(Request request) throws Exception {\n        String raw = new String(request.body(), StandardCharsets.UTF_8);\n        Map<String, Object> event = Json.parse(raw);\n        log.info("webhook received: " + raw);\n\n        Store.Order order = Store.getOrder((String) event.get("order_id"));\n        if (order == null) {\n            return Response.of(404, "unknown order");\n        }\n\n        String timestamp = request.headerOr("x-timestamp", "");\n        String expected = signatureFor(timestamp, raw);\n        if (!expected.equals(request.header("x-signature"))) {\n            return Response.of(401, "bad signature");\n        }\n\n        if ("charge.succeeded".equals(event.get("event"))) {\n            if ("paid".equals(order.status())) {\n                return Response.of(409, "already paid");\n            }\n            Store.markPaid(order.id(), (String) event.get("charge_id"), ((Number) event.get("amount")).longValue());\n            Fulfilment.start(order.id());\n        } else if ("charge.failed".equals(event.get("event"))) {\n            Store.markFailed(order.id());\n        }\n        return Response.of(200, "ok");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Payment webhook\n\nThe payment provider calls `POST /webhooks/payments` when a charge succeeds\nor fails. We mark the order paid and start fulfilment.\n\n## Provider contract\n\n- Body is JSON: `{"event": "charge.succeeded", "order_id": "...", "amount": 129900, "currency": "INR", "charge_id": "..."}`.\n- Header `X-Signature` is `hex(hmac_sha256(WEBHOOK_SECRET, timestamp + "." + raw_body))`\n  and `X-Timestamp` is the unix time the event was sent.\n- The provider retries on any non-2xx response, with backoff, for 24 hours.\n  The same event may be delivered more than once.\n\n## Notes for the reviewer\n\n`orders.expected_amount` holds what we charged. `fulfilment.start(order_id)`\nis idempotent.\n',"src/store.py":'"""Orders. `db` is the shared psycopg pool."""\nfrom dataclasses import dataclass\n\nimport db\n\n\n@dataclass\nclass Order:\n    id: str\n    status: str\n    expected_amount: int\n    currency: str\n\n\ndef get_order(order_id):\n    row = db.one("SELECT id, status, expected_amount, currency FROM orders WHERE id = %s", (order_id,))\n    return Order(*row) if row else None\n\n\ndef mark_paid(order_id, charge_id, amount):\n    db.run(\n        "UPDATE orders SET status = \'paid\', charge_id = %s, paid_amount = %s, paid_at = now() WHERE id = %s",\n        (charge_id, amount, order_id),\n    )\n\n\ndef mark_failed(order_id):\n    db.run("UPDATE orders SET status = \'failed\' WHERE id = %s", (order_id,))\n',"src/webhook.py":'"""POST /webhooks/payments"""\nimport hashlib\nimport hmac\nimport json\nimport logging\nimport os\n\nimport fulfilment\nimport store\n\nlog = logging.getLogger(__name__)\nSECRET = os.environ["WEBHOOK_SECRET"]\n\n\ndef signature_for(timestamp, raw_body):\n    return hmac.new(SECRET.encode(), (timestamp + "." + raw_body).encode(), hashlib.sha256).hexdigest()\n\n\ndef handle(request):\n    raw = request.body.decode("utf-8")\n    event = json.loads(raw)\n    log.info("webhook received: %s", raw)\n\n    order = store.get_order(event["order_id"])\n    if order is None:\n        return 404, "unknown order"\n\n    timestamp = request.headers.get("x-timestamp", "")\n    expected = signature_for(timestamp, raw)\n    if request.headers.get("x-signature") != expected:\n        return 401, "bad signature"\n\n    if event["event"] == "charge.succeeded":\n        if order.status == "paid":\n            return 409, "already paid"\n        store.mark_paid(order.id, event["charge_id"], event["amount"])\n        fulfilment.start(order.id)\n    elif event["event"] == "charge.failed":\n        store.mark_failed(order.id)\n    return 200, "ok"\n'}},typescript:{entry:"README.md",files:{"README.md":'# Payment webhook\n\nThe payment provider calls `POST /webhooks/payments` when a charge succeeds\nor fails. We mark the order paid and start fulfilment.\n\n## Provider contract\n\n- Body is JSON: `{"event": "charge.succeeded", "order_id": "...", "amount": 129900, "currency": "INR", "charge_id": "..."}`.\n- Header `X-Signature` is `hex(hmac_sha256(WEBHOOK_SECRET, timestamp + "." + raw_body))`\n  and `X-Timestamp` is the unix time the event was sent.\n- The provider retries on any non-2xx response, with backoff, for 24 hours.\n  The same event may be delivered more than once.\n\n## Notes for the reviewer\n\n`orders.expected_amount` holds what we charged. `fulfilment.start(orderId)`\nis idempotent. `req.rawBody` is the body bytes as a string.\n',"src/store.ts":'// Orders. `db` is the shared pg pool.\nimport { db } from "./db";\n\nexport type Order = { id: string; status: string; expected_amount: number; currency: string };\n\nexport async function getOrder(orderId: string): Promise<Order | null> {\n  return db.one<Order>("SELECT id, status, expected_amount, currency FROM orders WHERE id = $1", [orderId]);\n}\n\nexport async function markPaid(orderId: string, chargeId: string, amount: number): Promise<void> {\n  await db.run("UPDATE orders SET status = \'paid\', charge_id = $1, paid_amount = $2, paid_at = now() WHERE id = $3", [chargeId, amount, orderId]);\n}\n\nexport async function markFailed(orderId: string): Promise<void> {\n  await db.run("UPDATE orders SET status = \'failed\' WHERE id = $1", [orderId]);\n}\n',"src/webhook.ts":'// POST /webhooks/payments\nimport { createHmac } from "node:crypto";\nimport * as fulfilment from "./fulfilment";\nimport * as store from "./store";\nimport type { Request } from "./framework";\n\nconst SECRET = process.env.WEBHOOK_SECRET!;\n\ntype Event = { event: string; order_id: string; amount: number; currency: string; charge_id: string };\n\nexport function signatureFor(timestamp: string, rawBody: string): string {\n  return createHmac("sha256", SECRET).update(`${timestamp}.${rawBody}`).digest("hex");\n}\n\nexport async function handle(req: Request): Promise<[number, string]> {\n  const raw = req.rawBody;\n  const event = JSON.parse(raw) as Event;\n  console.info(`webhook received: ${raw}`);\n\n  const order = await store.getOrder(event.order_id);\n  if (!order) return [404, "unknown order"];\n\n  const timestamp = req.headers["x-timestamp"] ?? "";\n  const expected = signatureFor(timestamp, raw);\n  if (req.headers["x-signature"] !== expected) return [401, "bad signature"];\n\n  if (event.event === "charge.succeeded") {\n    if (order.status === "paid") return [409, "already paid"];\n    await store.markPaid(order.id, event.charge_id, event.amount);\n    await fulfilment.start(order.id);\n  } else if (event.event === "charge.failed") {\n    await store.markFailed(order.id);\n  }\n  return [200, "ok"];\n}\n'}}}},{slug:"invoice-totals",title:"Invoice totals",difficulty:"Medium",area:"money",domains:["payments"],minutes:25,summary:"Subtotal, discount, tax and total for an invoice, in integer minor units, then a call to the payment gateway. Short, and every line is money.",brief:["A teammate has opened this as a pull request. The README states the arithmetic rules and the unit conventions; hold the code against them line by line.","Try a few invoices in your head: a JPY one, one with a 12.5% discount on an odd subtotal, one with a line in the wrong currency.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct and explained in the README; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Invoice totals\n\nComputes the amounts on an invoice from its lines: subtotal, discount, tax\nand total. The result is stored and sent to the payment gateway.\n\n## Rules\n\n- All amounts are integers in the currency's minor unit (paise, cents, yen).\n  JPY and KRW have no minor unit: 1000 means \xa51000, not \xa510.00.\n- An invoice has one currency. Lines are priced in that currency.\n- The discount is a percentage of the subtotal. Tax is charged on the\n  discounted amount at the invoice's tax rate.\n- Rounding is half up, once, at the invoice level for discount and for tax.\n\n## Notes for the reviewer\n\n`Line` comes from the database as `(sku, currency, unitPrice, qty)`.\n`Gateway.charge(amount, currency)` expects minor units.\n","src/Invoice.java":"package billing;\n\nimport java.util.List;\n\n/** Invoice arithmetic. */\npublic final class Invoice {\n    public record Line(String sku, String currency, long unitPrice, int qty) {} // unitPrice in minor units\n    public record Totals(String currency, long subtotal, long discount, long tax, long total) {}\n\n    public static Totals compute(List<Line> lines, String currency, double discountPercent, double taxRatePercent) {\n        long subtotal = 0;\n        for (Line line : lines) {\n            subtotal += line.unitPrice() * line.qty();\n        }\n\n        long discount = (long) (subtotal * discountPercent / 100);\n        long taxable = subtotal - discount;\n        long tax = Math.round(taxable * taxRatePercent / 100);\n        long total = taxable + tax;\n        return new Totals(currency, subtotal, discount, tax, total);\n    }\n\n    public static ChargeResult charge(Totals totals) {\n        double amount = totals.total() / 100.0;\n        return Gateway.charge(amount, totals.currency());\n    }\n}\n"}},python:{entry:"README.md",files:{"README.md":"# Invoice totals\n\nComputes the amounts on an invoice from its lines: subtotal, discount, tax\nand total. The result is stored and sent to the payment gateway.\n\n## Rules\n\n- All amounts are integers in the currency's minor unit (paise, cents, yen).\n  JPY and KRW have no minor unit: 1000 means \xa51000, not \xa510.00.\n- An invoice has one currency. Lines are priced in that currency.\n- The discount is a percentage of the subtotal. Tax is charged on the\n  discounted amount at the invoice's tax rate.\n- Rounding is half up, once, at the invoice level for discount and for tax.\n\n## Notes for the reviewer\n\n`Line` comes from the database as `(sku, currency, unit_price, qty)`.\n`gateway.charge(amount, currency)` expects minor units.\n","src/invoice.py":'"""Invoice arithmetic."""\nfrom dataclasses import dataclass\n\nimport gateway\n\n@dataclass\nclass Line:\n    sku: str\n    currency: str\n    unit_price: int  # minor units\n    qty: int\n\n\n@dataclass\nclass Totals:\n    currency: str\n    subtotal: int\n    discount: int\n    tax: int\n    total: int\n\n\ndef compute(lines, currency, discount_percent, tax_rate_percent):\n    subtotal = 0\n    for line in lines:\n        subtotal += line.unit_price * line.qty\n\n    discount = int(subtotal * discount_percent / 100)\n    taxable = subtotal - discount\n    tax = round(taxable * tax_rate_percent / 100)\n    total = taxable + tax\n    return Totals(currency, subtotal, discount, tax, total)\n\n\ndef charge(totals):\n    amount = totals.total / 100\n    return gateway.charge(amount, totals.currency)\n'}},typescript:{entry:"README.md",files:{"README.md":"# Invoice totals\n\nComputes the amounts on an invoice from its lines: subtotal, discount, tax\nand total. The result is stored and sent to the payment gateway.\n\n## Rules\n\n- All amounts are integers in the currency's minor unit (paise, cents, yen).\n  JPY and KRW have no minor unit: 1000 means \xa51000, not \xa510.00.\n- An invoice has one currency. Lines are priced in that currency.\n- The discount is a percentage of the subtotal. Tax is charged on the\n  discounted amount at the invoice's tax rate.\n- Rounding is half up, once, at the invoice level for discount and for tax.\n\n## Notes for the reviewer\n\n`Line` comes from the database as `(sku, currency, unit_price, qty)`.\n`gateway.charge(amount, currency)` expects minor units.\n","src/invoice.ts":'// Invoice arithmetic.\nimport * as gateway from "./gateway";\n\nexport type Line = { sku: string; currency: string; unitPrice: number; qty: number }; // unitPrice in minor units\nexport type Totals = { currency: string; subtotal: number; discount: number; tax: number; total: number };\n\nexport function compute(lines: Line[], currency: string, discountPercent: number, taxRatePercent: number): Totals {\n  let subtotal = 0;\n  for (const line of lines) {\n    subtotal += line.unitPrice * line.qty;\n  }\n\n  const discount = Math.trunc((subtotal * discountPercent) / 100);\n  const taxable = subtotal - discount;\n  const tax = Math.round((taxable * taxRatePercent) / 100);\n  const total = taxable + tax;\n  return { currency, subtotal, discount, tax, total };\n}\n\nexport function charge(totals: Totals) {\n  const amount = totals.total / 100;\n  return gateway.charge(amount, totals.currency);\n}\n'}}}},{slug:"reminder-scheduler",title:"Daily reminders",difficulty:"Medium",area:"time",domains:["scheduling","messaging"],minutes:25,summary:"A job that sends each user a reminder at 09:00 their time, every day, from several machines at once. Time zones, daylight saving, and concurrency in one file.",brief:["A teammate has opened this as a pull request. Read the README rules, then follow one user in Asia/Kolkata and one in America/New_York through enable, the job, and the next day.","Ask of every timestamp: which zone is this in, and what is it compared with? Then ask what happens when two machines run the job in the same minute.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Daily reminders\n\nEvery user can turn on a daily reminder email at a time of their choosing,\nin their own time zone. A job runs every minute, sends the reminders that\nare due, and schedules the next one.\n\n## Rules\n\n- `send_at_local` is a wall-clock time like `09:00` in the user's\n  `timezone` (an IANA name such as `Asia/Kolkata`).\n- A reminder is sent once per day, at that local time, including across\n  daylight-saving changes: 09:00 stays 09:00 on the wall clock.\n- The job may run on several machines at once.\n\n## Notes for the reviewer\n\n`reminders` has `user_id, timezone, send_at_local, next_run_at`.\n`Db` is the shared pool. `Mailer.sendReminder(userId)` takes a few seconds.\n","src/Scheduler.java":'package reminders;\n\nimport java.time.LocalDateTime;\nimport java.time.ZoneId;\nimport java.time.ZonedDateTime;\nimport java.util.List;\nimport java.util.Map;\n\n/** Send due reminders and schedule the next ones. */\npublic final class Scheduler {\n    static List<Map<String, Object>> dueReminders() {\n        LocalDateTime now = LocalDateTime.now();\n        return Db.all("SELECT user_id, timezone, send_at_local, next_run_at FROM reminders WHERE next_run_at <= ?", now);\n    }\n\n    /** The next occurrence of sendAtLocal in timezone, strictly after {@code after}. */\n    static ZonedDateTime nextRun(String timezone, String sendAtLocal, ZonedDateTime after) {\n        ZoneId tz = ZoneId.of(timezone);\n        String[] hm = sendAtLocal.split(":");\n        ZonedDateTime local = after.withZoneSameInstant(tz);\n        ZonedDateTime candidate = local.withHour(Integer.parseInt(hm[0])).withMinute(Integer.parseInt(hm[1])).withSecond(0).withNano(0);\n        if (!candidate.isAfter(local)) {\n            candidate = candidate.plusHours(24);\n        }\n        return candidate;\n    }\n\n    public static void runOnce() {\n        for (Map<String, Object> r : dueReminders()) {\n            Mailer.sendReminder((String) r.get("user_id"));\n            ZonedDateTime next = nextRun((String) r.get("timezone"), (String) r.get("send_at_local"), ZonedDateTime.now());\n            Db.run("UPDATE reminders SET next_run_at = ? WHERE user_id = ?", next.toLocalDateTime(), r.get("user_id"));\n        }\n    }\n\n    public static void enable(String userId, String timezone, String sendAtLocal) {\n        ZonedDateTime next = nextRun(timezone, sendAtLocal, ZonedDateTime.now());\n        Db.run("INSERT INTO reminders (user_id, timezone, send_at_local, next_run_at) VALUES (?, ?, ?, ?)",\n                userId, timezone, sendAtLocal, next.toLocalDateTime());\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Daily reminders\n\nEvery user can turn on a daily reminder email at a time of their choosing,\nin their own time zone. A job runs every minute, sends the reminders that\nare due, and schedules the next one.\n\n## Rules\n\n- `send_at_local` is a wall-clock time like `09:00` in the user's\n  `timezone` (an IANA name such as `Asia/Kolkata`).\n- A reminder is sent once per day, at that local time, including across\n  daylight-saving changes: 09:00 stays 09:00 on the wall clock.\n- The job may run on several machines at once.\n\n## Notes for the reviewer\n\n`reminders` has `user_id, timezone, send_at_local, next_run_at`.\n`db` is the shared pool. `mailer.send_reminder(user_id)` takes a few seconds.\n","src/scheduler.py":'"""Send due reminders and schedule the next ones."""\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\nimport db\nimport mailer\n\n\ndef due_reminders():\n    now = datetime.now()\n    return db.all("SELECT user_id, timezone, send_at_local, next_run_at FROM reminders WHERE next_run_at <= %s", (now,))\n\n\ndef next_run(timezone, send_at_local, after):\n    """The next occurrence of send_at_local in timezone, strictly after `after`."""\n    tz = ZoneInfo(timezone)\n    hour, minute = (int(x) for x in send_at_local.split(":"))\n    local = after.astimezone(tz)\n    candidate = local.replace(hour=hour, minute=minute, second=0, microsecond=0)\n    if candidate <= local:\n        candidate = datetime.fromtimestamp(candidate.timestamp() + 86400, tz)\n    return candidate\n\n\ndef run_once():\n    for r in due_reminders():\n        mailer.send_reminder(r["user_id"])\n        nxt = next_run(r["timezone"], r["send_at_local"], datetime.now())\n        db.run("UPDATE reminders SET next_run_at = %s WHERE user_id = %s", (nxt.replace(tzinfo=None), r["user_id"]))\n\n\ndef enable(user_id, timezone, send_at_local):\n    nxt = next_run(timezone, send_at_local, datetime.now())\n    db.run(\n        "INSERT INTO reminders (user_id, timezone, send_at_local, next_run_at) VALUES (%s, %s, %s, %s)",\n        (user_id, timezone, send_at_local, nxt.replace(tzinfo=None)),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":"# Daily reminders\n\nEvery user can turn on a daily reminder email at a time of their choosing,\nin their own time zone. A job runs every minute, sends the reminders that\nare due, and schedules the next one.\n\n## Rules\n\n- `send_at_local` is a wall-clock time like `09:00` in the user's\n  `timezone` (an IANA name such as `Asia/Kolkata`).\n- A reminder is sent once per day, at that local time, including across\n  daylight-saving changes: 09:00 stays 09:00 on the wall clock.\n- The job may run on several machines at once.\n\n## Notes for the reviewer\n\n`reminders` has `user_id, timezone, send_at_local, next_run_at`.\n`db` is the shared pool. `mailer.send_reminder(user_id)` takes a few seconds.\n","src/scheduler.ts":'// Send due reminders and schedule the next ones.\nimport { DateTime } from "luxon";\nimport { db } from "./db";\nimport * as mailer from "./mailer";\n\ntype Row = { user_id: string; timezone: string; send_at_local: string; next_run_at: Date };\n\nexport async function dueReminders(): Promise<Row[]> {\n  const now = new Date();\n  return db.all<Row>("SELECT user_id, timezone, send_at_local, next_run_at FROM reminders WHERE next_run_at <= $1", [now]);\n}\n\n/** The next occurrence of sendAtLocal in timezone, strictly after `after`. */\nexport function nextRun(timezone: string, sendAtLocal: string, after: Date): DateTime {\n  const [hour, minute] = sendAtLocal.split(":").map(Number);\n  const local = DateTime.fromJSDate(after).setZone(timezone);\n  let candidate = local.set({ hour, minute, second: 0, millisecond: 0 });\n  if (candidate <= local) {\n    candidate = candidate.plus({ hours: 24 });\n  }\n  return candidate;\n}\n\nexport async function runOnce(): Promise<void> {\n  for (const r of await dueReminders()) {\n    await mailer.sendReminder(r.user_id);\n    const next = nextRun(r.timezone, r.send_at_local, new Date());\n    await db.run("UPDATE reminders SET next_run_at = $1 WHERE user_id = $2", [next.toFormat("yyyy-MM-dd HH:mm:ss"), r.user_id]);\n  }\n}\n\nexport async function enable(userId: string, timezone: string, sendAtLocal: string): Promise<void> {\n  const next = nextRun(timezone, sendAtLocal, new Date());\n  await db.run("INSERT INTO reminders (user_id, timezone, send_at_local, next_run_at) VALUES ($1, $2, $3, $4)", [\n    userId,\n    timezone,\n    sendAtLocal,\n    next.toFormat("yyyy-MM-dd HH:mm:ss"),\n  ]);\n}\n'}}}},{slug:"read-through-cache",title:"Product cache",difficulty:"Medium",area:"caching",domains:["ecommerce"],minutes:25,summary:"Read-through caching of product pages in Redis with a five-minute TTL, and the admin update path that is supposed to keep it honest.",brief:["A teammate has opened this as a pull request. The README says how stale a page may be and what the traffic looks like; both matter for what is a bug here.","Interleave a read and an update in your head, step by step. Then think about what happens at the exact second a hot key expires.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are what the README asks for; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Product cache\n\nProduct pages read the product from Redis first and fall back to Postgres,\ncaching what they find for five minutes. Product edits in the admin go\nthrough `update`.\n\n## Rules\n\n- A product page may be up to a few seconds stale after an edit, never minutes.\n- Prices are per currency: `get(id, currency)` returns the product with the\n  price in that currency.\n- A missing product is a normal case (deleted listings) and must not hit the\n  database on every request.\n\n## Notes for the reviewer\n\n`Cache` is the Redis client (`get`, `set(key, value, ttl)`, `delete`).\n`Db` is the shared pool; `Json` converts maps to and from strings. Traffic is about 2,000 product reads a second at\npeak; the hot products are a few hundred SKUs.\n","src/Products.java":'package catalog;\n\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Products, cached. */\npublic final class Products {\n    private static final Logger log = Logger.getLogger(Products.class.getName());\n    static final int TTL_SECONDS = 300;\n\n    private static String key(String productId) {\n        return "product:" + productId;\n    }\n\n    public static Map<String, Object> get(String productId, String currency) {\n        String cached = Cache.get(key(productId));\n        if (cached != null) {\n            return Json.parse(cached);\n        }\n        Map<String, Object> product;\n        try {\n            product = Db.one(\n                "SELECT p.id, p.name, pr.amount AS price FROM products p "\n                    + "JOIN prices pr ON pr.product_id = p.id AND pr.currency = ? WHERE p.id = ?",\n                currency, productId);\n        } catch (Exception exc) {\n            log.warning("product " + productId + ": " + exc.getMessage());\n            product = Map.of("error", exc.getMessage());\n        }\n        Cache.set(key(productId), Json.stringify(product), TTL_SECONDS);\n        return product;\n    }\n\n    public static void update(String productId, Map<String, String> fields) {\n        Cache.delete(key(productId));\n        Db.run("UPDATE products SET name = ?, description = ? WHERE id = ?", fields.get("name"), fields.get("description"), productId);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Product cache\n\nProduct pages read the product from Redis first and fall back to Postgres,\ncaching what they find for five minutes. Product edits in the admin go\nthrough `update`.\n\n## Rules\n\n- A product page may be up to a few seconds stale after an edit, never minutes.\n- Prices are per currency: `get(id, currency)` returns the product with the\n  price in that currency.\n- A missing product is a normal case (deleted listings) and must not hit the\n  database on every request.\n\n## Notes for the reviewer\n\n`cache` is the Redis client (`get`, `set(key, value, ttl)`, `delete`).\n`db` is the shared pool. Traffic is about 2,000 product reads a second at\npeak; the hot products are a few hundred SKUs.\n","src/products.py":'"""Products, cached."""\nimport json\nimport logging\n\nimport cache\nimport db\n\nlog = logging.getLogger(__name__)\n\nTTL_SECONDS = 300\n\n\ndef _key(product_id):\n    return f"product:{product_id}"\n\n\ndef get(product_id, currency):\n    cached = cache.get(_key(product_id))\n    if cached is not None:\n        return json.loads(cached)\n    try:\n        row = db.one(\n            "SELECT p.id, p.name, pr.amount AS price FROM products p "\n            "JOIN prices pr ON pr.product_id = p.id AND pr.currency = %s WHERE p.id = %s",\n            (currency, product_id),\n        )\n        product = dict(row) if row else None\n    except Exception as exc:\n        log.warning("product %s: %s", product_id, exc)\n        product = {"error": str(exc)}\n    cache.set(_key(product_id), json.dumps(product), TTL_SECONDS)\n    return product\n\n\ndef update(product_id, fields):\n    cache.delete(_key(product_id))\n    db.run("UPDATE products SET name = %s, description = %s WHERE id = %s", (fields["name"], fields["description"], product_id))\n'}},typescript:{entry:"README.md",files:{"README.md":"# Product cache\n\nProduct pages read the product from Redis first and fall back to Postgres,\ncaching what they find for five minutes. Product edits in the admin go\nthrough `update`.\n\n## Rules\n\n- A product page may be up to a few seconds stale after an edit, never minutes.\n- Prices are per currency: `get(id, currency)` returns the product with the\n  price in that currency.\n- A missing product is a normal case (deleted listings) and must not hit the\n  database on every request.\n\n## Notes for the reviewer\n\n`cache` is the Redis client (`get`, `set(key, value, ttl)`, `delete`).\n`db` is the shared pool. Traffic is about 2,000 product reads a second at\npeak; the hot products are a few hundred SKUs.\n","src/products.ts":'// Products, cached.\nimport { cache } from "./cache";\nimport { db } from "./db";\n\nconst TTL_SECONDS = 300;\n\nconst key = (productId: string) => `product:${productId}`;\n\nexport async function get(productId: string, currency: string): Promise<Record<string, unknown> | null> {\n  const cached = await cache.get(key(productId));\n  if (cached !== null) {\n    return JSON.parse(cached);\n  }\n  let product: Record<string, unknown> | null;\n  try {\n    const row = await db.one(\n      "SELECT p.id, p.name, pr.amount AS price FROM products p " +\n        "JOIN prices pr ON pr.product_id = p.id AND pr.currency = $1 WHERE p.id = $2",\n      [currency, productId],\n    );\n    product = row ?? null;\n  } catch (err) {\n    console.warn(`product ${productId}: ${String(err)}`);\n    product = { error: String(err) };\n  }\n  await cache.set(key(productId), JSON.stringify(product), TTL_SECONDS);\n  return product;\n}\n\nexport async function update(productId: string, fields: { name: string; description: string }): Promise<void> {\n  await cache.delete(key(productId));\n  await db.run("UPDATE products SET name = $1, description = $2 WHERE id = $3", [fields.name, fields.description, productId]);\n}\n'}}}},{slug:"payments-client",title:"Payments client",difficulty:"Medium",area:"integrations",domains:["payments"],minutes:25,summary:"A retrying HTTP wrapper around a payment provider, used to charge cards and issue refunds. The provider contract in the README is the spec.",brief:["A teammate has opened this as a pull request. Read the provider facts first: what is idempotent, what a 202 means, how the provider fails.","Follow a charge through a timeout, a 503 and a 3-D Secure challenge. Then look at what ends up in the logs.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Payments client\n\nA small wrapper around the payment provider\'s REST API, used by checkout to\ncharge a card and by support tooling to refund.\n\n## Provider facts\n\n- `POST /v1/charges` creates a charge. It is not idempotent by itself; the\n  provider de-duplicates only when the `Idempotency-Key` header is set.\n- `POST /v1/refunds` refunds a charge.\n- Success is `200` with `{"id": ..., "status": "succeeded"}`; a charge that\n  needs 3-D Secure comes back `202` with `"status": "pending"` and a\n  `next_action` the caller must show the customer.\n- The provider is occasionally slow (10 to 30 seconds) and returns `503`\n  during incidents.\n\n## Notes for the reviewer\n\n`HttpClient` is the JDK client. `PROVIDER_KEY` comes from the environment.\n`Retry.backoff(attempt)` returns the seconds to wait.\n',"src/Payments.java":'package payments;\n\nimport java.net.URI;\nimport java.net.http.HttpClient;\nimport java.net.http.HttpRequest;\nimport java.net.http.HttpResponse;\nimport java.util.Map;\nimport java.util.logging.Logger;\nimport javax.net.ssl.SSLContext;\n\n/** HTTP client for the payment provider. */\npublic final class Payments {\n    private static final Logger log = Logger.getLogger(Payments.class.getName());\n    static final String BASE = "https://api.payprovider.example/v1";\n    static final String PROVIDER_KEY = System.getenv("PROVIDER_KEY");\n    static final int MAX_ATTEMPTS = 4;\n    private static final HttpClient client = HttpClient.newBuilder().sslContext(Tls.trustAll()).build();\n\n    static HttpResponse<String> post(String path, Map<String, Object> payload) throws InterruptedException {\n        String body = Json.stringify(payload);\n        int attempt = 0;\n        while (true) {\n            attempt++;\n            log.info("POST " + path + " key=" + PROVIDER_KEY + " body=" + body);\n            try {\n                HttpRequest req = HttpRequest.newBuilder(URI.create(BASE + path))\n                    .header("Authorization", "Bearer " + PROVIDER_KEY)\n                    .header("Content-Type", "application/json")\n                    .POST(HttpRequest.BodyPublishers.ofString(body))\n                    .build();\n                HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());\n                if (resp.statusCode() >= 500) {\n                    throw new RuntimeException("provider " + resp.statusCode());\n                }\n                return resp;\n            } catch (Exception exc) {\n                if (attempt >= MAX_ATTEMPTS) throw new RuntimeException(exc);\n                log.warning("attempt " + attempt + " failed: " + exc.getMessage());\n                Thread.sleep((long) (Retry.backoff(attempt) * 1000));\n            }\n        }\n    }\n\n    public static ChargeResult charge(String orderId, long amountMinor, String currency, String cardToken) throws InterruptedException {\n        HttpResponse<String> resp = post("/charges", Map.of("amount", amountMinor, "currency", currency, "source", cardToken, "metadata", Map.of("order_id", orderId)));\n        Map<String, Object> json = Json.parse(resp.body());\n        if (resp.statusCode() < 300) {\n            return ChargeResult.ok((String) json.get("id"));\n        }\n        return ChargeResult.failed((String) json.getOrDefault("message", "declined"));\n    }\n\n    public static boolean refund(String chargeId, long amountMinor) throws InterruptedException {\n        HttpResponse<String> resp = post("/refunds", Map.of("charge", chargeId, "amount", amountMinor));\n        return resp.statusCode() < 300;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Payments client\n\nA small wrapper around the payment provider\'s REST API, used by checkout to\ncharge a card and by support tooling to refund.\n\n## Provider facts\n\n- `POST /v1/charges` creates a charge. It is not idempotent by itself; the\n  provider de-duplicates only when the `Idempotency-Key` header is set.\n- `POST /v1/refunds` refunds a charge.\n- Success is `200` with `{"id": ..., "status": "succeeded"}`; a charge that\n  needs 3-D Secure comes back `202` with `"status": "pending"` and a\n  `next_action` the caller must show the customer.\n- The provider is occasionally slow (10 to 30 seconds) and returns `503`\n  during incidents.\n\n## Notes for the reviewer\n\n`requests` / `fetch` are the plain HTTP libraries. `PROVIDER_KEY` comes\nfrom the environment. `backoff(attempt)` returns the seconds to wait.\n',"src/payments.py":'"""HTTP client for the payment provider."""\nimport logging\nimport os\nimport time\n\nimport requests\n\nfrom retry import backoff\n\nlog = logging.getLogger(__name__)\n\nBASE = "https://api.payprovider.example/v1"\nPROVIDER_KEY = os.environ["PROVIDER_KEY"]\nMAX_ATTEMPTS = 4\n\n\ndef _post(path, payload):\n    headers = {"Authorization": f"Bearer {PROVIDER_KEY}", "Content-Type": "application/json"}\n    attempt = 0\n    while True:\n        attempt += 1\n        log.info("POST %s headers=%s body=%s", path, headers, payload)\n        try:\n            resp = requests.post(BASE + path, json=payload, headers=headers, verify=False)\n            if resp.status_code >= 500:\n                raise requests.HTTPError(f"provider {resp.status_code}")\n            return resp\n        except (requests.ConnectionError, requests.Timeout, requests.HTTPError) as exc:\n            if attempt >= MAX_ATTEMPTS:\n                raise\n            log.warning("attempt %s failed: %s", attempt, exc)\n            time.sleep(backoff(attempt))\n\n\ndef charge(order_id, amount_minor, currency, card_token):\n    resp = _post("/charges", {"amount": amount_minor, "currency": currency, "source": card_token, "metadata": {"order_id": order_id}})\n    if resp.status_code < 300:\n        return {"ok": True, "charge_id": resp.json()["id"]}\n    return {"ok": False, "error": resp.json().get("message", "declined")}\n\n\ndef refund(charge_id, amount_minor):\n    resp = _post("/refunds", {"charge": charge_id, "amount": amount_minor})\n    return resp.status_code < 300\n'}},typescript:{entry:"README.md",files:{"README.md":'# Payments client\n\nA small wrapper around the payment provider\'s REST API, used by checkout to\ncharge a card and by support tooling to refund.\n\n## Provider facts\n\n- `POST /v1/charges` creates a charge. It is not idempotent by itself; the\n  provider de-duplicates only when the `Idempotency-Key` header is set.\n- `POST /v1/refunds` refunds a charge.\n- Success is `200` with `{"id": ..., "status": "succeeded"}`; a charge that\n  needs 3-D Secure comes back `202` with `"status": "pending"` and a\n  `next_action` the caller must show the customer.\n- The provider is occasionally slow (10 to 30 seconds) and returns `503`\n  during incidents.\n\n## Notes for the reviewer\n\n`requests` / `fetch` are the plain HTTP libraries. `PROVIDER_KEY` comes\nfrom the environment. `backoff(attempt)` returns the seconds to wait.\n',"src/payments.ts":'// HTTP client for the payment provider.\nimport { Agent } from "undici";\nimport { backoff } from "./retry";\n\nconst BASE = "https://api.payprovider.example/v1";\nconst PROVIDER_KEY = process.env.PROVIDER_KEY!;\nconst MAX_ATTEMPTS = 4;\nconst insecure = new Agent({ connect: { rejectUnauthorized: false } });\n\nconst sleep = (s: number) => new Promise((r) => setTimeout(r, s * 1000));\n\nasync function post(path: string, payload: unknown): Promise<Response> {\n  const headers = { Authorization: `Bearer ${PROVIDER_KEY}`, "Content-Type": "application/json" };\n  let attempt = 0;\n  while (true) {\n    attempt++;\n    console.log(`POST ${path} headers=${JSON.stringify(headers)} body=${JSON.stringify(payload)}`);\n    try {\n      const resp = await fetch(BASE + path, { method: "POST", headers, body: JSON.stringify(payload), dispatcher: insecure } as RequestInit);\n      if (resp.status >= 500) {\n        throw new Error(`provider ${resp.status}`);\n      }\n      return resp;\n    } catch (err) {\n      if (attempt >= MAX_ATTEMPTS) throw err;\n      console.warn(`attempt ${attempt} failed: ${String(err)}`);\n      await sleep(backoff(attempt));\n    }\n  }\n}\n\nexport async function charge(orderId: string, amountMinor: number, currency: string, cardToken: string) {\n  const resp = await post("/charges", { amount: amountMinor, currency, source: cardToken, metadata: { order_id: orderId } });\n  const body = (await resp.json()) as { id?: string; message?: string };\n  if (resp.status < 300) {\n    return { ok: true as const, chargeId: body.id! };\n  }\n  return { ok: false as const, error: body.message ?? "declined" };\n}\n\nexport async function refund(chargeId: string, amountMinor: number): Promise<boolean> {\n  const resp = await post("/refunds", { charge: chargeId, amount: amountMinor });\n  return resp.status < 300;\n}\n'}}}},{slug:"shipping-refactor",title:"Refactor: shipping rules",difficulty:"Medium",area:"refactor",domains:["ecommerce"],minutes:25,summary:'A "pure refactor" that moves a shipping-cost function into a rules class. The old function is in the diff for comparison; the spec is in the README.',brief:["A teammate has opened this as a pull request and says nothing changes. The old function is right there; the spec is in the README. Your job is to check that claim rule by rule.","For each rule, find where it lives now, and ask whether the order, the comparison and the conditions match the old code. Then read cost() as if you were a cart with free shipping.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are fine and explained in the README; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Refactor: shipping rules into a class\n\n`shippingCost` had grown into a 60-line function of nested ifs. This PR\nmoves the rules into a small `ShippingRules` class so each rule is a\nmethod and the order of evaluation is explicit. The PR description says\n"pure refactor, no behaviour change".\n\n## The rules (unchanged, from the product spec)\n\n1. Orders over 2,000 (in minor units: 200,000) ship free.\n2. Otherwise express is 149, standard is 49.\n3. Books ship free on standard, regardless of order total.\n4. A `FREESHIP` coupon makes standard shipping free; it never applies to express.\n5. Deliveries outside India are always express and always cost 999.\n\n## Notes for the reviewer\n\nThe old function is kept in the diff as `shippingCostOld` so you can\ncompare; it is deleted in a follow-up. `Cart` has `total`, `items`\n(each with `category`), `coupon` and `country`.\n',"src/Shipping.java":'package shop;\n\nimport java.util.List;\n\n/** Shipping cost rules. */\npublic final class Shipping {\n    public record Item(String category) {}\n    public record Cart(long total, List<Item> items, String coupon, String country) {}\n\n    static final long FREE_OVER = 200_000;\n    static final int EXPRESS = 149;\n    static final int STANDARD = 49;\n    static final int INTERNATIONAL = 999;\n\n    public static int shippingCostOld(Cart cart, boolean express) {\n        if (!cart.country().equals("IN")) return INTERNATIONAL;\n        if (cart.total() > FREE_OVER) return 0;\n        if (!express && cart.items().stream().allMatch(i -> i.category().equals("books"))) return 0;\n        if (!express && "FREESHIP".equals(cart.coupon())) return 0;\n        return express ? EXPRESS : STANDARD;\n    }\n\n    public static final class Rules {\n        private final Cart cart;\n        private final boolean express;\n\n        Rules(Cart cart, boolean express) {\n            this.cart = cart;\n            this.express = express;\n        }\n\n        Integer international() {\n            return cart.country().equals("IN") ? null : INTERNATIONAL;\n        }\n\n        Integer freeOverThreshold() {\n            return cart.total() >= FREE_OVER ? 0 : null;\n        }\n\n        Integer books() {\n            return cart.items().stream().anyMatch(i -> i.category().equals("books")) ? 0 : null;\n        }\n\n        Integer coupon() {\n            return cart.coupon().toUpperCase().equals("FREESHIP") ? 0 : null;\n        }\n\n        int base() {\n            return express ? EXPRESS : STANDARD;\n        }\n\n        static final List<String> RULES = List.of("freeOverThreshold", "international", "books", "coupon");\n\n        int cost() {\n            for (String name : RULES) {\n                Integer result = switch (name) {\n                    case "freeOverThreshold" -> freeOverThreshold();\n                    case "international" -> international();\n                    case "books" -> books();\n                    default -> coupon();\n                };\n                if (result != null && result != 0) return result;\n            }\n            return base();\n        }\n    }\n\n    public static int shippingCost(Cart cart, boolean express) {\n        return new Rules(cart, express).cost();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Refactor: shipping rules into a class\n\n`shipping_cost` had grown into a 60-line function of nested ifs. This PR\nmoves the rules into a small `ShippingRules` class so each rule is a\nmethod and the order of evaluation is explicit. The PR description says\n"pure refactor, no behaviour change".\n\n## The rules (unchanged, from the product spec)\n\n1. Orders over 2,000 (in minor units: 200,000) ship free.\n2. Otherwise express is 149, standard is 49.\n3. Books ship free on standard, regardless of order total.\n4. A `FREESHIP` coupon makes standard shipping free; it never applies to express.\n5. Deliveries outside India are always express and always cost 999.\n\n## Notes for the reviewer\n\nThe old function is kept in the diff as `shipping_cost_old` so you can\ncompare; it is deleted in a follow-up. `Cart` has `total`, `items`\n(each with `category`), `coupon` and `country`.\n',"src/shipping.py":'"""Shipping cost rules."""\n\nFREE_OVER = 200_000\nEXPRESS = 149\nSTANDARD = 49\nINTERNATIONAL = 999\n\n\ndef shipping_cost_old(cart, express):\n    if cart.country != "IN":\n        return INTERNATIONAL\n    if cart.total > FREE_OVER:\n        return 0\n    if not express and all(i.category == "books" for i in cart.items):\n        return 0\n    if not express and cart.coupon == "FREESHIP":\n        return 0\n    return EXPRESS if express else STANDARD\n\n\nclass ShippingRules:\n    def __init__(self, cart, express):\n        self.cart = cart\n        self.express = express\n\n    def international(self):\n        if self.cart.country != "IN":\n            return INTERNATIONAL\n\n    def free_over_threshold(self):\n        if self.cart.total >= FREE_OVER:\n            return 0\n\n    def books(self):\n        if any(i.category == "books" for i in self.cart.items):\n            return 0\n\n    def coupon(self):\n        if self.cart.coupon.upper() == "FREESHIP":\n            return 0\n\n    def base(self):\n        return EXPRESS if self.express else STANDARD\n\n    RULES = ("free_over_threshold", "international", "books", "coupon", "base")\n\n    def cost(self):\n        for name in self.RULES:\n            result = getattr(self, name)()\n            if result:\n                return result\n        return self.base()\n\n\ndef shipping_cost(cart, express):\n    return ShippingRules(cart, express).cost()\n'}},typescript:{entry:"README.md",files:{"README.md":'# Refactor: shipping rules into a class\n\n`shipping_cost` had grown into a 60-line function of nested ifs. This PR\nmoves the rules into a small `ShippingRules` class so each rule is a\nmethod and the order of evaluation is explicit. The PR description says\n"pure refactor, no behaviour change".\n\n## The rules (unchanged, from the product spec)\n\n1. Orders over 2,000 (in minor units: 200,000) ship free.\n2. Otherwise express is 149, standard is 49.\n3. Books ship free on standard, regardless of order total.\n4. A `FREESHIP` coupon makes standard shipping free; it never applies to express.\n5. Deliveries outside India are always express and always cost 999.\n\n## Notes for the reviewer\n\nThe old function is kept in the diff as `shipping_cost_old` so you can\ncompare; it is deleted in a follow-up. `Cart` has `total`, `items`\n(each with `category`), `coupon` and `country`.\n',"src/shipping.ts":'// Shipping cost rules.\nexport type Item = { category: string };\nexport type Cart = { total: number; items: Item[]; coupon: string | null; country: string };\n\nconst FREE_OVER = 200_000;\nconst EXPRESS = 149;\nconst STANDARD = 49;\nconst INTERNATIONAL = 999;\n\nexport function shippingCostOld(cart: Cart, express: boolean): number {\n  if (cart.country !== "IN") return INTERNATIONAL;\n  if (cart.total > FREE_OVER) return 0;\n  if (!express && cart.items.every((i) => i.category === "books")) return 0;\n  if (!express && cart.coupon === "FREESHIP") return 0;\n  return express ? EXPRESS : STANDARD;\n}\n\nexport class ShippingRules {\n  constructor(private cart: Cart, private express: boolean) {}\n\n  international(): number | undefined {\n    if (this.cart.country !== "IN") return INTERNATIONAL;\n  }\n\n  freeOverThreshold(): number | undefined {\n    if (this.cart.total >= FREE_OVER) return 0;\n  }\n\n  books(): number | undefined {\n    if (this.cart.items.some((i) => i.category === "books")) return 0;\n  }\n\n  coupon(): number | undefined {\n    if (this.cart.coupon!.toUpperCase() === "FREESHIP") return 0;\n  }\n\n  base(): number {\n    return this.express ? EXPRESS : STANDARD;\n  }\n\n  static RULES = ["freeOverThreshold", "international", "books", "coupon", "base"] as const;\n\n  cost(): number {\n    for (const name of ShippingRules.RULES) {\n      const result = this[name]();\n      if (result) return result;\n    }\n    return this.base();\n  }\n}\n\nexport const shippingCost = (cart: Cart, express: boolean) => new ShippingRules(cart, express).cost();\n'}}}},{slug:"dependency-bump",title:"Bump imgkit to 3.0",difficulty:"Medium",area:"dependencies",domains:["devtools","media"],minutes:25,summary:"A major-version bump of the image library with a five-line changelog and two call sites, one of which was updated and one of which was not.",brief:["A teammate has opened this as a pull request. The changelog excerpt in the README is the whole spec; hold every call site against every bullet.","Ask of each argument: which scale, which unit, what does it return now, what does it throw now, and what does it keep in the file.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Bump imgkit 2.9 to 3.0\n\n`imgkit` is the image library behind avatar and listing uploads. 3.0 is a\nmajor release; this PR bumps it and touches the two call sites.\n\n## From the 3.0 changelog\n\n- `resize(bytes, width)` now returns a `CompletableFuture<byte[]>`.\n- `quality` is now a fraction from 0 to 1 (was 0 to 100).\n- `timeout` is now in milliseconds (was seconds).\n- Metadata (EXIF, including GPS) is now kept by default; pass\n  `Options.strip(true)` to remove it, which 2.x did always.\n- `resize` throws `ImageTooLarge` instead of returning `null`\n  when the source exceeds `max_pixels`.\n\n## Notes for the reviewer\n\nThe build file change is included. Avatars and listing photos are shown\npublicly. `MAX_PIXELS` was 20 megapixels before and is unchanged.\n","build.gradle":"plugins {\n    id 'java'\n}\n\ndependencies {\n    implementation 'com.example:imgkit:3.0.0'\n    implementation 'org.postgresql:postgresql:42.7.3'\n}\n","src/Avatars.java":'package media;\n\nimport imgkit.Imgkit;\nimport imgkit.Options;\n\n/** Avatar processing, now on imgkit 3. */\npublic final class Avatars {\n    static final long MAX_PIXELS = 20_000_000;\n    static final int TIMEOUT = 5;\n\n    public static byte[] makeAvatar(byte[] data) throws Exception {\n        byte[] thumb = Imgkit.resize(data, 256, Options.quality(85).timeout(TIMEOUT).maxPixels(MAX_PIXELS)).get();\n        if (thumb == null) {\n            throw new IllegalArgumentException("image too large");\n        }\n        return thumb;\n    }\n}\n',"src/Listings.java":"package media;\n\nimport imgkit.Imgkit;\nimport imgkit.Options;\nimport java.util.ArrayList;\nimport java.util.List;\n\n/** Listing photos: three sizes for the gallery. */\npublic final class Listings {\n    static final int[] SIZES = {320, 800, 1600};\n\n    public static List<Object> makeGallery(byte[] data) {\n        List<Object> out = new ArrayList<>();\n        for (int width : SIZES) {\n            out.add(Imgkit.resize(data, width, Options.quality(0.8).timeout(5000)));\n        }\n        return out;\n    }\n}\n"}},python:{entry:"README.md",files:{"README.md":"# Bump imgkit 2.9 to 3.0\n\n`imgkit` is the image library behind avatar and listing uploads. 3.0 is a\nmajor release; this PR bumps it and touches the two call sites.\n\n## From the 3.0 changelog\n\n- `resize(bytes, width)` now returns a promise / is a coroutine.\n- `quality` is now a fraction from 0 to 1 (was 0 to 100).\n- `timeout` is now in milliseconds (was seconds).\n- Metadata (EXIF, including GPS) is now kept by default; pass\n  `strip=True` / `{ strip: true }` to remove it, which 2.x did always.\n- `resize` throws `ImageTooLarge` instead of returning `None` / `null`\n  when the source exceeds `max_pixels`.\n\n## Notes for the reviewer\n\nThe lockfile change is included. Avatars and listing photos are shown\npublicly. `MAX_PIXELS` was 20 megapixels before and is unchanged.\n","requirements.txt":"fastapi==0.110.0\nuvicorn==0.29.0\npsycopg[binary]==3.1.18\nimgkit==3.0.0\n","src/avatars.py":'"""Avatar processing, now on imgkit 3."""\nimport imgkit\n\nMAX_PIXELS = 20_000_000\nTIMEOUT = 5\n\n\nasync def make_avatar(data):\n    thumb = await imgkit.resize(data, 256, quality=85, timeout=TIMEOUT, max_pixels=MAX_PIXELS)\n    if thumb is None:\n        raise ValueError("image too large")\n    return thumb\n',"src/listings.py":'"""Listing photos: three sizes for the gallery."""\nimport imgkit\n\nSIZES = (320, 800, 1600)\n\n\nasync def make_gallery(data):\n    out = []\n    for width in SIZES:\n        out.append(imgkit.resize(data, width, quality=0.8, timeout=5000))\n    return out\n'}},typescript:{entry:"README.md",files:{"README.md":"# Bump imgkit 2.9 to 3.0\n\n`imgkit` is the image library behind avatar and listing uploads. 3.0 is a\nmajor release; this PR bumps it and touches the two call sites.\n\n## From the 3.0 changelog\n\n- `resize(bytes, width)` now returns a promise / is a coroutine.\n- `quality` is now a fraction from 0 to 1 (was 0 to 100).\n- `timeout` is now in milliseconds (was seconds).\n- Metadata (EXIF, including GPS) is now kept by default; pass\n  `strip=True` / `{ strip: true }` to remove it, which 2.x did always.\n- `resize` throws `ImageTooLarge` instead of returning `None` / `null`\n  when the source exceeds `max_pixels`.\n\n## Notes for the reviewer\n\nThe lockfile change is included. Avatars and listing photos are shown\npublicly. `MAX_PIXELS` was 20 megapixels before and is unchanged.\n","package.json":'{\n  "name": "listings-service",\n  "private": true,\n  "dependencies": {\n    "express": "^4.19.2",\n    "imgkit": "^3.0.0",\n    "pg": "^8.11.5"\n  }\n}\n',"src/avatars.ts":'// Avatar processing, now on imgkit 3.\nimport * as imgkit from "imgkit";\n\nconst MAX_PIXELS = 20_000_000;\nconst TIMEOUT = 5;\n\nexport async function makeAvatar(data: Buffer): Promise<Buffer> {\n  const thumb = await imgkit.resize(data, 256, { quality: 85, timeout: TIMEOUT, maxPixels: MAX_PIXELS });\n  if (thumb === null) {\n    throw new Error("image too large");\n  }\n  return thumb;\n}\n',"src/listings.ts":'// Listing photos: three sizes for the gallery.\nimport * as imgkit from "imgkit";\n\nconst SIZES = [320, 800, 1600];\n\nexport async function makeGallery(data: Buffer): Promise<Buffer[]> {\n  const out: Buffer[] = [];\n  for (const width of SIZES) {\n    out.push(imgkit.resize(data, width, { quality: 0.8, timeout: 5000 }) as unknown as Buffer);\n  }\n  return out;\n}\n'}}}},{slug:"leaderboard-perf",title:"Speed up the leaderboard",difficulty:"Medium",area:"performance",domains:["social"],minutes:25,summary:"Caching, an estimated count and batched writes take an endpoint from 800 ms to 50 ms. The contract in the README did not change; check whether the behaviour did.",brief:["A teammate has opened this as a pull request. Performance PRs are reviewed against the contract: read the three promises in the README first.","Walk through a player posting a new score and then loading the board, once when they are in the top 100 and once when they are not.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One trade-off is deliberate and stated in the PR; a comment on that costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Speed up the leaderboard endpoint\n\n`GET /leaderboard` was taking 800 ms at peak. This PR gets it under 50 ms:\nthe top 100 is cached for a minute, the total-player count uses the\nplanner's estimate, and score updates are batched.\n\n## Contract (unchanged)\n\n- Players are ranked by score, highest first; ties are broken by who\n  reached the score first (`updated_at` ascending).\n- `rank` in the response is the player's 1-based position.\n- A player's own row is always current: after `POST /score`, the next\n  `GET /leaderboard?me=<id>` must show the new score and rank.\n\n## Notes for the reviewer\n\n`Cache` is Redis. `Db` is the shared pool; `players` has\n`id, name, score, updated_at`.\n","src/Leaderboard.java":'package game;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** GET /leaderboard and POST /score, the fast version. */\npublic final class Leaderboard {\n    static final int TOP = 100;\n    private static final Map<String, Long> pending = new HashMap<>();\n\n    public static List<Map<String, Object>> topPlayers() {\n        String hit = Cache.get("leaderboard:top");\n        if (hit != null) return Json.parseList(hit);\n        List<Map<String, Object>> rows = Db.all("SELECT id, name, score FROM players ORDER BY score DESC LIMIT ?", TOP);\n        List<Map<String, Object>> out = new ArrayList<>();\n        for (int i = 0; i < rows.size(); i++) {\n            Map<String, Object> p = new HashMap<>(rows.get(i));\n            p.put("rank", i + 1);\n            out.add(p);\n        }\n        Cache.set("leaderboard:top", Json.stringify(out), 60);\n        return out;\n    }\n\n    public static long playerCount() {\n        return ((Number) Db.one("SELECT reltuples::bigint AS n FROM pg_class WHERE relname = \'players\'").get("n")).longValue();\n    }\n\n    public static Map<String, Object> leaderboard(String me) {\n        List<Map<String, Object>> top = topPlayers();\n        Map<String, Object> mine = top.stream().filter(p -> p.get("id").equals(me)).findFirst().orElse(null);\n        if (me != null && mine == null) {\n            Map<String, Object> row = Db.one("SELECT id, name, score FROM players WHERE id = ?", me);\n            long rank = ((Number) Db.one("SELECT count(*) + 1 AS r FROM players WHERE score > ?", row.get("score")).get("r")).longValue();\n            mine = new HashMap<>(row);\n            mine.put("rank", rank);\n        }\n        return Map.of("top", top, "me", mine == null ? Map.of() : mine, "players", playerCount());\n    }\n\n    public static void postScore(String playerId, long score) {\n        pending.put(playerId, score);\n        if (pending.size() >= 50) flush();\n    }\n\n    public static void flush() {\n        for (Map.Entry<String, Long> e : pending.entrySet()) {\n            Db.run("UPDATE players SET score = ?, updated_at = now() WHERE id = ?", e.getValue(), e.getKey());\n        }\n        pending.clear();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Speed up the leaderboard endpoint\n\n`GET /leaderboard` was taking 800 ms at peak. This PR gets it under 50 ms:\nthe top 100 is cached for a minute, the total-player count uses the\nplanner's estimate, and score updates are batched.\n\n## Contract (unchanged)\n\n- Players are ranked by score, highest first; ties are broken by who\n  reached the score first (`updated_at` ascending).\n- `rank` in the response is the player's 1-based position.\n- A player's own row is always current: after `POST /score`, the next\n  `GET /leaderboard?me=<id>` must show the new score and rank.\n\n## Notes for the reviewer\n\n`cache` is Redis. `db` is the shared pool; `players` has\n`id, name, score, updated_at`.\n","src/leaderboard.py":'"""GET /leaderboard and POST /score, the fast version."""\nimport json\n\nimport cache\nimport db\n\nTOP = 100\npending = {}\n\n\ndef top_players():\n    hit = cache.get("leaderboard:top")\n    if hit:\n        return json.loads(hit)\n    rows = db.all("SELECT id, name, score FROM players ORDER BY score DESC LIMIT %s", (TOP,))\n    out = [{"rank": i + 1, **dict(r)} for i, r in enumerate(rows)]\n    cache.set("leaderboard:top", json.dumps(out), 60)\n    return out\n\n\ndef player_count():\n    row = db.one("SELECT reltuples::bigint AS n FROM pg_class WHERE relname = \'players\'")\n    return row["n"]\n\n\ndef leaderboard(me=None):\n    top = top_players()\n    mine = next((p for p in top if p["id"] == me), None)\n    if me and mine is None:\n        row = db.one("SELECT id, name, score FROM players WHERE id = %s", (me,))\n        rank = db.one("SELECT count(*) + 1 AS r FROM players WHERE score > %s", (row["score"],))["r"]\n        mine = {"rank": rank, **dict(row)}\n    return {"top": top, "me": mine, "players": player_count()}\n\n\ndef post_score(player_id, score):\n    pending[player_id] = score\n    if len(pending) >= 50:\n        flush()\n\n\ndef flush():\n    for player_id, score in pending.items():\n        db.run("UPDATE players SET score = %s, updated_at = now() WHERE id = %s", (score, player_id))\n    pending.clear()\n'}},typescript:{entry:"README.md",files:{"README.md":"# Speed up the leaderboard endpoint\n\n`GET /leaderboard` was taking 800 ms at peak. This PR gets it under 50 ms:\nthe top 100 is cached for a minute, the total-player count uses the\nplanner's estimate, and score updates are batched.\n\n## Contract (unchanged)\n\n- Players are ranked by score, highest first; ties are broken by who\n  reached the score first (`updated_at` ascending).\n- `rank` in the response is the player's 1-based position.\n- A player's own row is always current: after `POST /score`, the next\n  `GET /leaderboard?me=<id>` must show the new score and rank.\n\n## Notes for the reviewer\n\n`cache` is Redis. `db` is the shared pool; `players` has\n`id, name, score, updated_at`.\n","src/leaderboard.ts":'// GET /leaderboard and POST /score, the fast version.\nimport { cache } from "./cache";\nimport { db } from "./db";\n\nconst TOP = 100;\nconst pending = new Map<string, number>();\n\ntype Row = { id: string; name: string; score: number };\n\nexport async function topPlayers() {\n  const hit = await cache.get("leaderboard:top");\n  if (hit) return JSON.parse(hit) as (Row & { rank: number })[];\n  const rows = await db.all<Row>("SELECT id, name, score FROM players ORDER BY score DESC LIMIT $1", [TOP]);\n  const out = rows.map((r, i) => ({ rank: i + 1, ...r }));\n  await cache.set("leaderboard:top", JSON.stringify(out), 60);\n  return out;\n}\n\nexport async function playerCount(): Promise<number> {\n  const row = await db.one<{ n: number }>("SELECT reltuples::bigint AS n FROM pg_class WHERE relname = \'players\'");\n  return Number(row!.n);\n}\n\nexport async function leaderboard(me?: string) {\n  const top = await topPlayers();\n  let mine = top.find((p) => p.id === me) ?? null;\n  if (me && mine === null) {\n    const row = (await db.one<Row>("SELECT id, name, score FROM players WHERE id = $1", [me]))!;\n    const rank = (await db.one<{ r: number }>("SELECT count(*) + 1 AS r FROM players WHERE score > $1", [row.score]))!.r;\n    mine = { rank: Number(rank), ...row };\n  }\n  return { top, me: mine, players: await playerCount() };\n}\n\nexport async function postScore(playerId: string, score: number): Promise<void> {\n  pending.set(playerId, score);\n  if (pending.size >= 50) await flush();\n}\n\nexport async function flush(): Promise<void> {\n  for (const [playerId, score] of pending) {\n    await db.run("UPDATE players SET score = $1, updated_at = now() WHERE id = $2", [score, playerId]);\n  }\n  pending.clear();\n}\n'}}}},{slug:"dockerfile",title:"Containerise the API",difficulty:"Medium",area:"infrastructure",domains:["devtools"],minutes:30,summary:"A first Dockerfile and compose file for the API. Ten lines, and most of them matter in production.",brief:["A teammate has opened this as a pull request. Read the README facts about the registry, the secrets and the load balancer; each one decides whether a line is fine.","Go instruction by instruction: what ends up in the image, who runs the process, what happens on SIGTERM, and what a change to one source file costs on the next build.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","The compose file is for local development; judge it as such."],variants:{python:{entry:"README.md",files:{Dockerfile:'FROM python:latest\n\nARG SESSION_SECRET\nENV SESSION_SECRET=$SESSION_SECRET\nENV DATABASE_URL=postgres://app:app@db:5432/app\n\nWORKDIR /app\nCOPY . /app\nRUN pip install -r requirements.txt\n\nRUN apt-get update && apt-get install -y curl\n\nEXPOSE 8000\nCMD sh -c "uvicorn src.main:app --host 0.0.0.0 --port 8000"\n',"README.md":"# Containerise the API\n\nThe API used to run on a VM with a hand-maintained systemd unit. This PR\nadds a Dockerfile and a compose file so it runs the same way in CI,\nstaging and production.\n\n## Facts\n\n- The image is built in CI on every merge and pushed to our registry;\n  production pulls it.\n- The API talks to Postgres and needs `DATABASE_URL` and `SESSION_SECRET`\n  at runtime.\n- Production runs behind a load balancer that health-checks `GET /health`\n  and sends SIGTERM on deploy with a 30-second grace period.\n\n## Notes for the reviewer\n\nThe repo root has `src/`, `tests/`, `.env` (local development secrets),\n`node_modules/` or `.venv/` from local runs, and `.git/`.\n","docker-compose.yml":'services:\n  api:\n    build: .\n    ports:\n      - "8000:8000"\n    environment:\n      DATABASE_URL: postgres://app:app@db:5432/app\n    depends_on:\n      - db\n  db:\n    image: postgres:16\n    environment:\n      POSTGRES_PASSWORD: app\n      POSTGRES_USER: app\n      POSTGRES_DB: app\n'}},typescript:{entry:"README.md",files:{Dockerfile:"FROM node:latest\n\nARG SESSION_SECRET\nENV SESSION_SECRET=$SESSION_SECRET\nENV DATABASE_URL=postgres://app:app@db:5432/app\n\nWORKDIR /app\nCOPY . /app\nRUN npm install\n\nRUN apt-get update && apt-get install -y curl\n\nEXPOSE 3000\nCMD npm start\n","README.md":"# Containerise the API\n\nThe API used to run on a VM with a hand-maintained systemd unit. This PR\nadds a Dockerfile and a compose file so it runs the same way in CI,\nstaging and production.\n\n## Facts\n\n- The image is built in CI on every merge and pushed to our registry;\n  production pulls it.\n- The API talks to Postgres and needs `DATABASE_URL` and `SESSION_SECRET`\n  at runtime.\n- Production runs behind a load balancer that health-checks `GET /health`\n  and sends SIGTERM on deploy with a 30-second grace period.\n\n## Notes for the reviewer\n\nThe repo root has `src/`, `tests/`, `.env` (local development secrets),\n`node_modules/` or `.venv/` from local runs, and `.git/`.\n","docker-compose.yml":'services:\n  api:\n    build: .\n    ports:\n      - "3000:3000"\n    environment:\n      DATABASE_URL: postgres://app:app@db:5432/app\n    depends_on:\n      - db\n  db:\n    image: postgres:16\n    environment:\n      POSTGRES_PASSWORD: app\n      POSTGRES_USER: app\n      POSTGRES_DB: app\n'}}}},{slug:"ci-workflow",title:"CI workflow",difficulty:"Medium",area:"infrastructure",domains:["devtools"],minutes:30,summary:"A GitHub Actions workflow for a public repository: test pull requests, deploy main. Thirty lines of YAML with production access.",brief:["A teammate has opened this as a pull request. The README says the repository is public and forks are welcome; keep that in mind on every line that touches a secret.","Trace a pull request from a stranger through the workflow, then a push to a feature branch, then a push to main with a failing test.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{python:{entry:"README.md",files:{".github/workflows/ci.yml":'name: ci\n\non:\n  pull_request_target:\n  push:\n    branches: ["**"]\n\npermissions: write-all\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@master\n        with:\n          ref: ${{ github.event.pull_request.head.sha }}\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.12"\n      - run: pip install -r requirements.txt\n      - run: ruff check .\n        continue-on-error: true\n      - run: pytest -q\n        continue-on-error: true\n      - run: echo "token is ${{ secrets.DEPLOY_TOKEN }}"\n\n  deploy:\n    runs-on: ubuntu-latest\n    needs: test\n    steps:\n      - uses: actions/checkout@v4\n      - run: bash scripts/deploy.sh\n        env:\n          DEPLOY_TOKEN: ${{ secrets.DEPLOY_TOKEN }}\n',"README.md":"# CI: test on pull requests, deploy on main\n\nReplaces the old Jenkins job with a GitHub Actions workflow. Pull requests\nfrom forks are welcome on this repository (it is public), so the workflow\nmust be safe to run on code from strangers.\n\n## What it should do\n\n- On every pull request: install, lint, test.\n- On push to `main`: the same, then build and deploy to production with\n  the `DEPLOY_TOKEN` secret.\n- Deploys must never run for a failed test suite.\n\n## Notes for the reviewer\n\nThe deploy script is `scripts/deploy.sh` and reads `DEPLOY_TOKEN` from the\nenvironment. Nothing else in the repository changed.\n"}},typescript:{entry:"README.md",files:{".github/workflows/ci.yml":'name: ci\n\non:\n  pull_request_target:\n  push:\n    branches: ["**"]\n\npermissions: write-all\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@master\n        with:\n          ref: ${{ github.event.pull_request.head.sha }}\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n      - run: npm install\n      - run: npm run lint\n        continue-on-error: true\n      - run: npm test\n        continue-on-error: true\n      - run: echo "token is ${{ secrets.DEPLOY_TOKEN }}"\n\n  deploy:\n    runs-on: ubuntu-latest\n    needs: test\n    steps:\n      - uses: actions/checkout@v4\n      - run: bash scripts/deploy.sh\n        env:\n          DEPLOY_TOKEN: ${{ secrets.DEPLOY_TOKEN }}\n',"README.md":"# CI: test on pull requests, deploy on main\n\nReplaces the old Jenkins job with a GitHub Actions workflow. Pull requests\nfrom forks are welcome on this repository (it is public), so the workflow\nmust be safe to run on code from strangers.\n\n## What it should do\n\n- On every pull request: install, lint, test.\n- On push to `main`: the same, then build and deploy to production with\n  the `DEPLOY_TOKEN` secret.\n- Deploys must never run for a failed test suite.\n\n## Notes for the reviewer\n\nThe deploy script is `scripts/deploy.sh` and reads `DEPLOY_TOKEN` from the\nenvironment. Nothing else in the repository changed.\n"}}}},{slug:"nginx-proxy",title:"nginx in front of the API",difficulty:"Medium",area:"infrastructure",domains:["devtools"],minutes:30,summary:"A reverse-proxy config: TLS, a redirect, an API location, static uploads. The API is unchanged; the config decides what it sees.",brief:["A teammate has opened this as a pull request. The README lists what the proxy must do; read the API note at the end carefully.","Follow one request from a browser through port 80, then 443, into the API; then one request for an avatar; then think about what the API can no longer see.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some lines are correct; a comment on those costs you."],variants:{python:{entry:"README.md",files:{"README.md":"# nginx in front of the API\n\nTerminates TLS and proxies to the API on port 8000 (Python) or 3000\n(Node); serves the uploaded avatars from disk. Replaces the load\nbalancer's default config we had been using.\n\n## Requirements\n\n- TLS only; HTTP redirects to HTTPS. Modern clients only.\n- The API must see the real client address (it rate-limits by it).\n- Avatar uploads are at most 2 MB; nothing else takes a body larger\n  than a few hundred KB.\n- Uploaded files live in `/srv/uploads/avatars` and are served at\n  `/static/avatars/`.\n\n## Notes for the reviewer\n\nThe API itself is unchanged. `/api/` is prefixed on the outside only;\nthe API's routes have no prefix (`/health`, `/users`, ...).\n","nginx/api.conf":"server {\n    listen 80;\n    server_name api.example.com;\n    return 301 http://api.example.com$request_uri;\n}\n\nserver {\n    listen 443 ssl;\n    server_name api.example.com;\n\n    ssl_certificate     /etc/ssl/api.crt;\n    ssl_certificate_key /etc/ssl/api.key;\n    ssl_protocols       TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;\n\n    server_tokens on;\n    client_max_body_size 0;\n\n    location /api/ {\n        proxy_pass http://127.0.0.1:8000/api/;\n        proxy_set_header Host $host;\n    }\n\n    location /static/avatars/ {\n        alias /srv/uploads/;\n        autoindex on;\n    }\n\n    location /health {\n        proxy_pass http://127.0.0.1:8000/health;\n    }\n}\n"}},typescript:{entry:"README.md",files:{"README.md":"# nginx in front of the API\n\nTerminates TLS and proxies to the API on port 8000 (Python) or 3000\n(Node); serves the uploaded avatars from disk. Replaces the load\nbalancer's default config we had been using.\n\n## Requirements\n\n- TLS only; HTTP redirects to HTTPS. Modern clients only.\n- The API must see the real client address (it rate-limits by it).\n- Avatar uploads are at most 2 MB; nothing else takes a body larger\n  than a few hundred KB.\n- Uploaded files live in `/srv/uploads/avatars` and are served at\n  `/static/avatars/`.\n\n## Notes for the reviewer\n\nThe API itself is unchanged. `/api/` is prefixed on the outside only;\nthe API's routes have no prefix (`/health`, `/users`, ...).\n","nginx/api.conf":"server {\n    listen 80;\n    server_name api.example.com;\n    return 301 http://api.example.com$request_uri;\n}\n\nserver {\n    listen 443 ssl;\n    server_name api.example.com;\n\n    ssl_certificate     /etc/ssl/api.crt;\n    ssl_certificate_key /etc/ssl/api.key;\n    ssl_protocols       TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;\n\n    server_tokens on;\n    client_max_body_size 0;\n\n    location /api/ {\n        proxy_pass http://127.0.0.1:3000/api/;\n        proxy_set_header Host $host;\n    }\n\n    location /static/avatars/ {\n        alias /srv/uploads/;\n        autoindex on;\n    }\n\n    location /health {\n        proxy_pass http://127.0.0.1:3000/health;\n    }\n}\n"}}}},{slug:"orders-table",title:"Orders table with search",difficulty:"Medium",area:"frontend",domains:["ecommerce","saas"],minutes:25,summary:"A React table with search-as-you-type and load-more. Effects, state and a slow network are where the bugs live.",brief:['A teammate has opened this as a pull request. The README rule about "never results for an older query" is the one to hold the effect against.',"Type three characters quickly on a slow connection and follow each request to its setState. Then look at what render does to the state array, and at what the keyboard can reach.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct React; a comment on those costs you."],variants:{typescript:{entry:"README.md",files:{"README.md":'# Orders table with search\n\nThe admin\'s orders page: a search box, a table of results, and a "load\nmore" button. Results come from `GET /api/orders?q=&page=`.\n\n## Rules\n\n- Typing in the box searches as you type; the table must always show\n  results for what is currently in the box, never for an older query.\n- "Load more" appends the next page.\n- The page must not lock up on a slow network or a large result set.\n\n## Notes for the reviewer\n\nReact 18 with TypeScript. `api.get` is our fetch wrapper and accepts an\n`AbortSignal`. Rows have a stable `id`.\n',"src/OrdersTable.tsx":'import { useEffect, useState } from "react";\nimport { api } from "./api";\n\ntype Order = { id: string; customer: string; total: number; status: string };\n\nexport function OrdersTable() {\n  const [q, setQ] = useState("");\n  const [page, setPage] = useState(1);\n  const [rows, setRows] = useState<Order[]>([]);\n  const [loading, setLoading] = useState(false);\n\n  useEffect(() => {\n    async function load() {\n      setLoading(true);\n      const data = await api.get<Order[]>(`/api/orders?q=${encodeURIComponent(q)}&page=${page}`);\n      setRows((prev) => (page === 1 ? data : [...prev, ...data]));\n      setLoading(false);\n    }\n    load();\n  }, [q, page]);\n\n  const sorted = rows.sort((a, b) => b.total - a.total);\n  const visible = sorted.filter((r) => r.status !== "cancelled");\n\n  return (\n    <div>\n      <input value={q} onChange={(e) => { setQ(e.target.value); setPage(1); }} placeholder="Search orders" />\n      <table>\n        <tbody>\n          {visible.map((r, i) => (\n            <tr key={i} onClick={() => (window.location.href = `/admin/orders/${r.id}`)}>\n              <td>{r.customer}</td>\n              <td>{r.total}</td>\n              <td>{r.status}</td>\n            </tr>\n          ))}\n        </tbody>\n      </table>\n      <div onClick={() => setPage(page + 1)} className="button">\n        {loading ? "Loading" : "Load more"}\n      </div>\n    </div>\n  );\n}\n'}}}},{slug:"csv-export",title:"Orders CSV export",difficulty:"Medium",area:"backend",domains:["ecommerce","analytics"],minutes:20,summary:"A streaming CSV export for finance. This one is mostly right; the skill is saying so, and finding the two small things that are not.",brief:["A teammate has opened this as a pull request. Check it against the four requirements in the README, then check the inputs.","Not every PR has a serious bug. If it is good, approve with what you found; flagging correct code costs you.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Several things that look unusual here are deliberate and idiomatic."],variants:{java:{entry:"README.md",files:{"README.md":"# Orders CSV export\n\n`GET /admin/orders/export?from=&to=` streams the orders in a date range as\na CSV for the finance team, who open it in Excel.\n\n## Requirements\n\n- Any date range; exports of a few hundred thousand rows are normal.\n- Columns: `id, placed_at, customer_email, total, currency, status`.\n- `placed_at` in ISO 8601 with the offset, so finance can see the zone.\n- Admins only. Memory use must not grow with the export size.\n\n## Notes for the reviewer\n\n`Db.stream(sql, params)` returns an Iterator over rows without loading them all.\n`request.user().role()` is set by the auth middleware.\n","src/Export.java":'package admin;\n\nimport java.io.PrintWriter;\nimport java.time.OffsetDateTime;\nimport java.time.format.DateTimeFormatter;\nimport java.util.Iterator;\nimport java.util.List;\nimport java.util.Map;\n\n/** GET /admin/orders/export */\npublic final class Export {\n    static final List<String> COLUMNS = List.of("id", "placed_at", "customer_email", "total", "currency", "status");\n\n    public static void exportOrders(Request request, Response response) {\n        if (request.user() == null || !request.user().role().equals("admin")) {\n            response.status(403).send("admins only");\n            return;\n        }\n        OffsetDateTime start = OffsetDateTime.parse(request.query("from"));\n        OffsetDateTime end = OffsetDateTime.parse(request.query("to"));\n\n        response.header("Content-Type", "text/csv; charset=utf-8");\n        response.header("Content-Disposition", "attachment; filename=\\"orders.csv\\"");\n\n        try (PrintWriter out = response.writer()) {\n            out.println(String.join(",", COLUMNS));\n            Iterator<Map<String, Object>> rows = Db.stream(\n                "SELECT id, placed_at, customer_email, total, currency, status FROM orders WHERE placed_at >= ? AND placed_at < ? ORDER BY placed_at",\n                start, end);\n            while (rows.hasNext()) {\n                Map<String, Object> r = rows.next();\n                out.println(Csv.row(r.get("id"), ((OffsetDateTime) r.get("placed_at")).format(DateTimeFormatter.ISO_OFFSET_DATE_TIME),\n                        r.get("customer_email"), r.get("total"), r.get("currency"), r.get("status")));\n            }\n        }\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Orders CSV export\n\n`GET /admin/orders/export?from=&to=` streams the orders in a date range as\na CSV for the finance team, who open it in Excel.\n\n## Requirements\n\n- Any date range; exports of a few hundred thousand rows are normal.\n- Columns: `id, placed_at, customer_email, total, currency, status`.\n- `placed_at` in ISO 8601 with the offset, so finance can see the zone.\n- Admins only. Memory use must not grow with the export size.\n\n## Notes for the reviewer\n\n`db.stream(sql, params)` yields rows without loading them all.\n`request.user.role` is set by the auth middleware.\n","src/export.py":'"""GET /admin/orders/export"""\nimport csv\nimport io\nfrom datetime import datetime\n\nimport db\n\nCOLUMNS = ["id", "placed_at", "customer_email", "total", "currency", "status"]\n\n\ndef export_orders(request):\n    if request.user is None or request.user.role != "admin":\n        return 403, "admins only"\n    start = datetime.fromisoformat(request.query["from"])\n    end = datetime.fromisoformat(request.query["to"])\n\n    def rows():\n        buf = io.StringIO()\n        writer = csv.writer(buf)\n        writer.writerow(COLUMNS)\n        yield buf.getvalue()\n        buf.seek(0)\n        buf.truncate()\n        for r in db.stream(\n            "SELECT id, placed_at, customer_email, total, currency, status FROM orders "\n            "WHERE placed_at >= %s AND placed_at < %s ORDER BY placed_at",\n            (start, end),\n        ):\n            writer.writerow([r["id"], r["placed_at"].isoformat(), r["customer_email"], r["total"], r["currency"], r["status"]])\n            yield buf.getvalue()\n            buf.seek(0)\n            buf.truncate()\n\n    headers = {\n        "Content-Type": "text/csv; charset=utf-8",\n        "Content-Disposition": \'attachment; filename="orders.csv"\',\n    }\n    return 200, rows(), headers\n'}},typescript:{entry:"README.md",files:{"README.md":"# Orders CSV export\n\n`GET /admin/orders/export?from=&to=` streams the orders in a date range as\na CSV for the finance team, who open it in Excel.\n\n## Requirements\n\n- Any date range; exports of a few hundred thousand rows are normal.\n- Columns: `id, placed_at, customer_email, total, currency, status`.\n- `placed_at` in ISO 8601 with the offset, so finance can see the zone.\n- Admins only. Memory use must not grow with the export size.\n\n## Notes for the reviewer\n\n`db.stream(sql, params)` yields rows without loading them all.\n`request.user.role` is set by the auth middleware.\n","src/export.ts":'// GET /admin/orders/export\nimport { stringify } from "csv-stringify";\nimport { db } from "./db";\nimport type { Request, Response } from "./http";\n\nconst COLUMNS = ["id", "placed_at", "customer_email", "total", "currency", "status"];\n\nexport async function exportOrders(req: Request, res: Response): Promise<void> {\n  if (!req.user || req.user.role !== "admin") {\n    res.status(403).send("admins only");\n    return;\n  }\n  const start = new Date(req.query.from as string);\n  const end = new Date(req.query.to as string);\n\n  res.setHeader("Content-Type", "text/csv; charset=utf-8");\n  res.setHeader("Content-Disposition", \'attachment; filename="orders.csv"\');\n\n  const out = stringify({ header: true, columns: COLUMNS });\n  out.pipe(res);\n  for await (const r of db.stream(\n    "SELECT id, placed_at, customer_email, total, currency, status FROM orders WHERE placed_at >= $1 AND placed_at < $2 ORDER BY placed_at",\n    [start, end],\n  )) {\n    out.write([r.id, (r.placed_at as Date).toISOString(), r.customer_email, r.total, r.currency, r.status]);\n  }\n  out.end();\n}\n'}}}},{slug:"daily-stats-etl",title:"Nightly stats rollup",difficulty:"Medium",area:"data",domains:["analytics"],minutes:25,summary:"A nightly job that turns raw events into one daily_stats row. Day boundaries, late events, re-runs and a float in the wrong place.",brief:["A teammate has opened this as a pull request. Read the README rules on days, re-runs and late events; every one of them is testable against this file.","Ask where midnight is, what happens when the job runs twice, which timestamp defines the day, and what type the money ends up in.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Nightly daily_stats rollup\n\nA job that runs at 00:30 every night and writes yesterday's totals into\n`daily_stats` (`day, views, signups, revenue`) from the raw `events` table,\nfor the dashboard.\n\n## Rules\n\n- Days are calendar days in `Asia/Kolkata`; the dashboard shows IST.\n- `revenue` is the sum of `events.amount` (integer paise) for `purchase` events.\n- The job must be safe to re-run for any day (backfills happen), and a\n  re-run must not double anything.\n- Events can arrive up to an hour late; `received_at` is when we got them,\n  `occurred_at` is when they happened on the device.\n\n## Notes for the reviewer\n\n`events` has `id, kind, occurred_at (timestamptz), received_at, amount`.\nAbout 30 million rows a month. `Db` is the shared pool.\n","src/Rollup.java":'package stats;\n\nimport java.time.LocalDate;\nimport java.time.LocalDateTime;\nimport java.util.Map;\n\n/** Nightly rollup of events into daily_stats. */\npublic final class Rollup {\n    public static void rollup(LocalDate day) {\n        if (day == null) day = LocalDate.now().minusDays(1);\n        LocalDateTime start = day.atStartOfDay();\n        LocalDateTime end = start.plusDays(1);\n\n        Map<String, Object> row = Db.one("""\n            SELECT\n              count(*) FILTER (WHERE kind = \'view\') AS views,\n              count(*) FILTER (WHERE kind = \'signup\') AS signups,\n              sum(amount::float) FILTER (WHERE kind = \'purchase\') AS revenue\n            FROM events\n            WHERE received_at >= ? AND received_at < ?\n            """, start, end);\n        Object revenue = row.get("revenue") == null ? 0 : row.get("revenue");\n        Db.run("INSERT INTO daily_stats (day, views, signups, revenue) VALUES (?, ?, ?, ?)",\n                day, row.get("views"), row.get("signups"), revenue);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Nightly daily_stats rollup\n\nA job that runs at 00:30 every night and writes yesterday's totals into\n`daily_stats` (`day, views, signups, revenue`) from the raw `events` table,\nfor the dashboard.\n\n## Rules\n\n- Days are calendar days in `Asia/Kolkata`; the dashboard shows IST.\n- `revenue` is the sum of `events.amount` (integer paise) for `purchase` events.\n- The job must be safe to re-run for any day (backfills happen), and a\n  re-run must not double anything.\n- Events can arrive up to an hour late; `received_at` is when we got them,\n  `occurred_at` is when they happened on the device.\n\n## Notes for the reviewer\n\n`events` has `id, kind, occurred_at (timestamptz), received_at, amount`.\nAbout 30 million rows a month. `db` is the shared pool.\n","src/rollup.py":'"""Nightly rollup of events into daily_stats."""\nfrom datetime import date, datetime, timedelta\n\nimport db\n\n\ndef rollup(day=None):\n    day = day or (date.today() - timedelta(days=1))\n    start = datetime(day.year, day.month, day.day)\n    end = start + timedelta(days=1)\n\n    row = db.one(\n        """\n        SELECT\n          count(*) FILTER (WHERE kind = \'view\') AS views,\n          count(*) FILTER (WHERE kind = \'signup\') AS signups,\n          sum(amount::float) FILTER (WHERE kind = \'purchase\') AS revenue\n        FROM events\n        WHERE received_at >= %s AND received_at < %s\n        """,\n        (start, end),\n    )\n    db.run(\n        "INSERT INTO daily_stats (day, views, signups, revenue) VALUES (%s, %s, %s, %s)",\n        (day, row["views"], row["signups"], row["revenue"] or 0),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":"# Nightly daily_stats rollup\n\nA job that runs at 00:30 every night and writes yesterday's totals into\n`daily_stats` (`day, views, signups, revenue`) from the raw `events` table,\nfor the dashboard.\n\n## Rules\n\n- Days are calendar days in `Asia/Kolkata`; the dashboard shows IST.\n- `revenue` is the sum of `events.amount` (integer paise) for `purchase` events.\n- The job must be safe to re-run for any day (backfills happen), and a\n  re-run must not double anything.\n- Events can arrive up to an hour late; `received_at` is when we got them,\n  `occurred_at` is when they happened on the device.\n\n## Notes for the reviewer\n\n`events` has `id, kind, occurred_at (timestamptz), received_at, amount`.\nAbout 30 million rows a month. `db` is the shared pool.\n","src/rollup.ts":"// Nightly rollup of events into daily_stats.\nimport { db } from \"./db\";\n\nexport async function rollup(day?: Date): Promise<void> {\n  const d = day ?? new Date(Date.now() - 86400000);\n  const start = new Date(d.getFullYear(), d.getMonth(), d.getDate());\n  const end = new Date(start.getTime() + 86400000);\n\n  const row = await db.one<{ views: number; signups: number; revenue: number | null }>(\n    `SELECT\n       count(*) FILTER (WHERE kind = 'view') AS views,\n       count(*) FILTER (WHERE kind = 'signup') AS signups,\n       sum(amount::float) FILTER (WHERE kind = 'purchase') AS revenue\n     FROM events\n     WHERE received_at >= $1 AND received_at < $2`,\n    [start, end],\n  );\n  await db.run(\"INSERT INTO daily_stats (day, views, signups, revenue) VALUES ($1, $2, $3, $4)\", [\n    start,\n    row!.views,\n    row!.signups,\n    row!.revenue ?? 0,\n  ]);\n}\n"}}}},{slug:"soft-delete",title:"Soft delete for projects",difficulty:"Medium",area:"data",domains:["saas"],minutes:25,summary:'Replacing DELETE with deleted_at and a 30-day restore window. Each read and write in this file has to agree with the new meaning of "deleted".',brief:["A teammate has opened this as a pull request. The README says what deleted means now; check every function against it, including who is allowed to call it.","Delete a project, then try to read it, list its tasks, re-create it by name, and restore it as a different user.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Soft delete for projects\n\nDeleting a project used to `DELETE` the row and cascade to its tasks.\nSupport kept asking us to restore projects, so this PR adds\n`projects.deleted_at` and a 30-day window in which a project can be\nrestored, after which a nightly job removes it for good.\n\n## Rules\n\n- A deleted project is invisible everywhere except the restore screen.\n- Restoring brings the project and its tasks back exactly as they were.\n- A project name is unique per owner (there is a unique index on\n  `(owner_id, name)`).\n- Only the owner can delete or restore.\n\n## Notes for the reviewer\n\n`tasks.project_id` references `projects.id` with `ON DELETE CASCADE`.\n`Db` is the shared pool. Other read paths in the codebase were updated\nto filter on `deleted_at IS NULL` in a separate PR.\n","src/Projects.java":'package work;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Project delete, restore, and purge. */\npublic final class Projects {\n    public static Response deleteProject(String userId, String projectId) {\n        Db.run("UPDATE projects SET deleted_at = now() WHERE id = ? AND owner_id = ?", projectId, userId);\n        return Response.of(204, null);\n    }\n\n    public static Response restoreProject(String userId, String projectId) {\n        Db.run("UPDATE projects SET deleted_at = NULL WHERE id = ?", projectId);\n        return Response.of(200, getProject(userId, projectId));\n    }\n\n    public static Map<String, Object> getProject(String userId, String projectId) {\n        return Db.one("SELECT id, name, owner_id FROM projects WHERE id = ? AND owner_id = ?", projectId, userId);\n    }\n\n    public static List<Map<String, Object>> listTasks(String userId, String projectId) {\n        return Db.all(\n            "SELECT t.id, t.title, t.done FROM tasks t JOIN projects p ON p.id = t.project_id WHERE p.id = ? AND p.owner_id = ? ORDER BY t.id",\n            projectId, userId);\n    }\n\n    public static void createProject(String userId, String name) {\n        Db.run("INSERT INTO projects (owner_id, name) VALUES (?, ?)", userId, name);\n    }\n\n    /** Nightly: remove projects deleted more than 30 days ago. */\n    public static void purgeOld() {\n        Db.run("DELETE FROM projects WHERE deleted_at < now() - interval \'30 days\'");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Soft delete for projects\n\nDeleting a project used to `DELETE` the row and cascade to its tasks.\nSupport kept asking us to restore projects, so this PR adds\n`projects.deleted_at` and a 30-day window in which a project can be\nrestored, after which a nightly job removes it for good.\n\n## Rules\n\n- A deleted project is invisible everywhere except the restore screen.\n- Restoring brings the project and its tasks back exactly as they were.\n- A project name is unique per owner (there is a unique index on\n  `(owner_id, name)`).\n- Only the owner can delete or restore.\n\n## Notes for the reviewer\n\n`tasks.project_id` references `projects.id` with `ON DELETE CASCADE`.\n`db` is the shared pool. Other read paths in the codebase were updated\nto filter on `deleted_at IS NULL` in a separate PR.\n","src/projects.py":'"""Project delete, restore, and purge."""\nimport db\n\n\ndef delete_project(user_id, project_id):\n    db.run("UPDATE projects SET deleted_at = now() WHERE id = %s AND owner_id = %s", (project_id, user_id))\n    return 204, None\n\n\ndef restore_project(user_id, project_id):\n    db.run("UPDATE projects SET deleted_at = NULL WHERE id = %s", (project_id,))\n    return 200, get_project(user_id, project_id)\n\n\ndef get_project(user_id, project_id):\n    return db.one("SELECT id, name, owner_id FROM projects WHERE id = %s AND owner_id = %s", (project_id, user_id))\n\n\ndef list_tasks(user_id, project_id):\n    return db.all(\n        "SELECT t.id, t.title, t.done FROM tasks t JOIN projects p ON p.id = t.project_id "\n        "WHERE p.id = %s AND p.owner_id = %s ORDER BY t.id",\n        (project_id, user_id),\n    )\n\n\ndef create_project(user_id, name):\n    db.run("INSERT INTO projects (owner_id, name) VALUES (%s, %s)", (user_id, name))\n\n\ndef purge_old():\n    """Nightly: remove projects deleted more than 30 days ago."""\n    db.run("DELETE FROM projects WHERE deleted_at < now() - interval \'30 days\'")\n'}},typescript:{entry:"README.md",files:{"README.md":"# Soft delete for projects\n\nDeleting a project used to `DELETE` the row and cascade to its tasks.\nSupport kept asking us to restore projects, so this PR adds\n`projects.deleted_at` and a 30-day window in which a project can be\nrestored, after which a nightly job removes it for good.\n\n## Rules\n\n- A deleted project is invisible everywhere except the restore screen.\n- Restoring brings the project and its tasks back exactly as they were.\n- A project name is unique per owner (there is a unique index on\n  `(owner_id, name)`).\n- Only the owner can delete or restore.\n\n## Notes for the reviewer\n\n`tasks.project_id` references `projects.id` with `ON DELETE CASCADE`.\n`db` is the shared pool. Other read paths in the codebase were updated\nto filter on `deleted_at IS NULL` in a separate PR.\n","src/projects.ts":'// Project delete, restore, and purge.\nimport { db } from "./db";\n\nexport async function deleteProject(userId: string, projectId: string) {\n  await db.run("UPDATE projects SET deleted_at = now() WHERE id = $1 AND owner_id = $2", [projectId, userId]);\n  return { status: 204 };\n}\n\nexport async function restoreProject(userId: string, projectId: string) {\n  await db.run("UPDATE projects SET deleted_at = NULL WHERE id = $1", [projectId]);\n  return { status: 200, body: await getProject(userId, projectId) };\n}\n\nexport async function getProject(userId: string, projectId: string) {\n  return db.one("SELECT id, name, owner_id FROM projects WHERE id = $1 AND owner_id = $2", [projectId, userId]);\n}\n\nexport async function listTasks(userId: string, projectId: string) {\n  return db.all(\n    "SELECT t.id, t.title, t.done FROM tasks t JOIN projects p ON p.id = t.project_id WHERE p.id = $1 AND p.owner_id = $2 ORDER BY t.id",\n    [projectId, userId],\n  );\n}\n\nexport async function createProject(userId: string, name: string) {\n  await db.run("INSERT INTO projects (owner_id, name) VALUES ($1, $2)", [userId, name]);\n}\n\n/** Nightly: remove projects deleted more than 30 days ago. */\nexport async function purgeOld() {\n  await db.run("DELETE FROM projects WHERE deleted_at < now() - interval \'30 days\'");\n}\n'}}}},{slug:"partial-refund",title:"Partial refunds",difficulty:"Medium",area:"money",domains:["payments"],minutes:25,summary:"Refund some lines of an order with their share of tax. Twenty lines of arithmetic and two calls that move money.",brief:["A teammate has opened this as a pull request. The four rules in the README are the spec; each one maps to a line or two here.","Refund half an order, then the other half, then the first half again. Then ask what happens if the process dies between the two writes.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Partial refunds\n\nSupport can refund part of an order. The refund takes the money from the\nitems chosen, refunds the proportional tax, and never refunds more than was\npaid in total across all refunds.\n\n## Rules\n\n- Amounts are integers in minor units. Rounding is half up.\n- Tax is refunded in proportion to the goods refunded: a line's tax share\n  is `line_total / goods_total * tax_paid`.\n- Shipping is refunded only when every item is refunded.\n- The sum of all refunds on an order can never exceed `order.total_paid`.\n\n## Notes for the reviewer\n\n`order` has `lines` (each with `id, total, refunded`), `goods_total`,\n`tax_paid`, `shipping`, `total_paid`, `refunded_total`. `Gateway.refund`\ntakes minor units. `Db` is the shared pool.\n","src/Refund.java":'package billing;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\n/** Partial refunds. */\npublic final class Refund {\n    public record Line(String id, long total, boolean refunded) {}\n    public record Order(String id, String chargeId, List<Line> lines, long goodsTotal, long taxPaid, long shipping, long totalPaid, long refundedTotal) {}\n\n    public static Response refund(Order order, Set<String> lineIds) {\n        List<Line> lines = order.lines().stream().filter(l -> lineIds.contains(l.id())).toList();\n        long goods = lines.stream().mapToLong(Line::total).sum();\n        long tax = 0;\n        for (Line l : lines) {\n            tax += (long) ((double) l.total() / order.goodsTotal() * order.taxPaid());\n        }\n        long amount = goods + tax;\n        if (lines.size() == order.lines().size()) {\n            amount += order.shipping();\n        }\n\n        if (amount > order.totalPaid()) {\n            return Response.of(400, "refund exceeds payment");\n        }\n\n        Gateway.refund(order.chargeId(), amount);\n        Db.run("UPDATE orders SET refunded_total = refunded_total + ? WHERE id = ?", amount, order.id());\n        for (Line l : lines) {\n            Db.run("UPDATE order_lines SET refunded = true WHERE id = ?", l.id());\n        }\n        return Response.of(200, Map.of("refunded", amount));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Partial refunds\n\nSupport can refund part of an order. The refund takes the money from the\nitems chosen, refunds the proportional tax, and never refunds more than was\npaid in total across all refunds.\n\n## Rules\n\n- Amounts are integers in minor units. Rounding is half up.\n- Tax is refunded in proportion to the goods refunded: a line's tax share\n  is `line_total / goods_total * tax_paid`.\n- Shipping is refunded only when every item is refunded.\n- The sum of all refunds on an order can never exceed `order.total_paid`.\n\n## Notes for the reviewer\n\n`order` has `lines` (each with `id, total, refunded`), `goods_total`,\n`tax_paid`, `shipping`, `total_paid`, `refunded_total`. `gateway.refund`\ntakes minor units. `db` is the shared pool.\n","src/refund.py":'"""Partial refunds."""\nimport db\nimport gateway\n\n\ndef refund(order, line_ids):\n    lines = [l for l in order.lines if l.id in line_ids]\n    goods = sum(l.total for l in lines)\n    tax = 0\n    for l in lines:\n        tax += int(l.total / order.goods_total * order.tax_paid)\n    amount = goods + tax\n    if len(lines) == len(order.lines):\n        amount += order.shipping\n\n    if amount > order.total_paid:\n        return 400, "refund exceeds payment"\n\n    gateway.refund(order.charge_id, amount)\n    db.run("UPDATE orders SET refunded_total = refunded_total + %s WHERE id = %s", (amount, order.id))\n    for l in lines:\n        db.run("UPDATE order_lines SET refunded = true WHERE id = %s", (l.id,))\n    return 200, {"refunded": amount}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Partial refunds\n\nSupport can refund part of an order. The refund takes the money from the\nitems chosen, refunds the proportional tax, and never refunds more than was\npaid in total across all refunds.\n\n## Rules\n\n- Amounts are integers in minor units. Rounding is half up.\n- Tax is refunded in proportion to the goods refunded: a line's tax share\n  is `line_total / goods_total * tax_paid`.\n- Shipping is refunded only when every item is refunded.\n- The sum of all refunds on an order can never exceed `order.total_paid`.\n\n## Notes for the reviewer\n\n`order` has `lines` (each with `id, total, refunded`), `goods_total`,\n`tax_paid`, `shipping`, `total_paid`, `refunded_total`. `gateway.refund`\ntakes minor units. `db` is the shared pool.\n","src/refund.ts":'// Partial refunds.\nimport { db } from "./db";\nimport * as gateway from "./gateway";\n\ntype Line = { id: string; total: number; refunded: boolean };\ntype Order = { id: string; chargeId: string; lines: Line[]; goodsTotal: number; taxPaid: number; shipping: number; totalPaid: number; refundedTotal: number };\n\nexport async function refund(order: Order, lineIds: string[]) {\n  const lines = order.lines.filter((l) => lineIds.includes(l.id));\n  const goods = lines.reduce((s, l) => s + l.total, 0);\n  let tax = 0;\n  for (const l of lines) {\n    tax += Math.trunc((l.total / order.goodsTotal) * order.taxPaid);\n  }\n  let amount = goods + tax;\n  if (lines.length === order.lines.length) {\n    amount += order.shipping;\n  }\n\n  if (amount > order.totalPaid) {\n    return { status: 400, body: "refund exceeds payment" };\n  }\n\n  await gateway.refund(order.chargeId, amount);\n  await db.run("UPDATE orders SET refunded_total = refunded_total + $1 WHERE id = $2", [amount, order.id]);\n  for (const l of lines) {\n    await db.run("UPDATE order_lines SET refunded = true WHERE id = $1", [l.id]);\n  }\n  return { status: 200, body: { refunded: amount } };\n}\n'}}}},{slug:"meeting-slots",title:"Free slots for a meeting",difficulty:"Medium",area:"time",domains:["scheduling"],minutes:25,summary:"Intersect two working windows in two zones, subtract busy intervals, emit 30-minute slots. Boundaries and zones are where it goes wrong.",brief:["A teammate has opened this as a pull request. The third rule in the README is about boundaries; the first and last are about zones.","Take a requester in Kolkata and a colleague in San Francisco and trace one day. Then take a busy block ending exactly at 10:00 and ask whether 10:00 is free.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Free slots for a meeting\n\nGiven two people's busy intervals and a working window, list the 30-minute\nslots when both are free, shown in the requester's time zone.\n\n## Rules\n\n- Busy intervals come from calendars as UTC instants (`start`, `end`).\n- The working window is `09:00` to `18:00` in each person's own zone;\n  a slot must be inside both windows.\n- A slot may start at exactly the end of a busy interval, and a busy\n  interval that starts at exactly the slot's end does not block it.\n- Slots are returned for one calendar day of the requester, across DST.\n\n## Notes for the reviewer\n\n`Busy` is `(start, end)` as `Instant`s. The person records carry `timezone`\n(IANA names). No database is involved.\n","src/Slots.java":"package calendar;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.LocalTime;\nimport java.time.ZoneId;\nimport java.time.ZonedDateTime;\nimport java.util.ArrayList;\nimport java.util.List;\n\n/** Common free 30-minute slots for two people on one day. */\npublic final class Slots {\n    public record Busy(Instant start, Instant end) {}\n    public record Person(String timezone, List<Busy> busy) {}\n\n    static final int SLOT_MINUTES = 30;\n    static final LocalTime WORK_START = LocalTime.of(9, 0);\n    static final LocalTime WORK_END = LocalTime.of(18, 0);\n\n    static ZonedDateTime[] workingWindow(Person person, LocalDate day) {\n        ZoneId tz = ZoneId.of(person.timezone());\n        return new ZonedDateTime[] { day.atTime(WORK_START).atZone(tz), day.atTime(WORK_END).atZone(tz) };\n    }\n\n    static boolean overlaps(ZonedDateTime aStart, ZonedDateTime aEnd, Instant bStart, Instant bEnd) {\n        return !aStart.toInstant().isAfter(bEnd) && !bStart.isAfter(aEnd.toInstant());\n    }\n\n    public static List<String> freeSlots(Person requester, Person other, LocalDate day) {\n        ZonedDateTime[] r = workingWindow(requester, day);\n        ZonedDateTime[] o = workingWindow(other, day);\n        ZonedDateTime start = r[0].isAfter(o[0]) ? r[0] : o[0];\n        ZonedDateTime end = r[1].isBefore(o[1]) ? r[1] : o[1];\n\n        List<Busy> busy = new ArrayList<>(requester.busy());\n        busy.addAll(other.busy());\n        List<String> slots = new ArrayList<>();\n        ZonedDateTime cursor = start;\n        while (!cursor.plusMinutes(SLOT_MINUTES).isAfter(end)) {\n            ZonedDateTime slotEnd = cursor.plusMinutes(SLOT_MINUTES);\n            ZonedDateTime c = cursor;\n            if (busy.stream().noneMatch(b -> overlaps(c, slotEnd, b.start(), b.end()))) {\n                slots.add(cursor.toLocalTime().toString());\n            }\n            cursor = cursor.plusMinutes(SLOT_MINUTES);\n        }\n        return slots;\n    }\n}\n"}},python:{entry:"README.md",files:{"README.md":"# Free slots for a meeting\n\nGiven two people's busy intervals and a working window, list the 30-minute\nslots when both are free, shown in the requester's time zone.\n\n## Rules\n\n- Busy intervals come from calendars as UTC instants (`start`, `end`).\n- The working window is `09:00` to `18:00` in each person's own zone;\n  a slot must be inside both windows.\n- A slot may start at exactly the end of a busy interval, and a busy\n  interval that starts at exactly the slot's end does not block it.\n- Slots are returned for one calendar day of the requester, across DST.\n\n## Notes for the reviewer\n\n`Interval` is `(start, end)` in UTC. The person records carry `timezone`\n(IANA names). `db` is not involved.\n","src/slots.py":'"""Common free 30-minute slots for two people on one day."""\nfrom datetime import datetime, time, timedelta\nfrom zoneinfo import ZoneInfo\n\nSLOT = timedelta(minutes=30)\nWORK_START = time(9, 0)\nWORK_END = time(18, 0)\n\n\ndef working_window(person, day):\n    tz = ZoneInfo(person.timezone)\n    start = datetime.combine(day, WORK_START, tzinfo=tz)\n    end = datetime.combine(day, WORK_END, tzinfo=tz)\n    return start, end\n\n\ndef overlaps(a_start, a_end, b_start, b_end):\n    return a_start <= b_end and b_start <= a_end\n\n\ndef free_slots(requester, other, day):\n    r_start, r_end = working_window(requester, day)\n    o_start, o_end = working_window(other, day)\n    start = max(r_start, o_start)\n    end = min(r_end, o_end)\n\n    busy = [(b.start, b.end) for b in requester.busy + other.busy]\n    slots = []\n    cursor = start\n    while cursor + SLOT <= end:\n        slot_end = cursor + SLOT\n        if not any(overlaps(cursor, slot_end, b_start, b_end) for b_start, b_end in busy):\n            slots.append(cursor.replace(tzinfo=None))\n        cursor = cursor + SLOT\n    return slots\n'}},typescript:{entry:"README.md",files:{"README.md":"# Free slots for a meeting\n\nGiven two people's busy intervals and a working window, list the 30-minute\nslots when both are free, shown in the requester's time zone.\n\n## Rules\n\n- Busy intervals come from calendars as UTC instants (`start`, `end`).\n- The working window is `09:00` to `18:00` in each person's own zone;\n  a slot must be inside both windows.\n- A slot may start at exactly the end of a busy interval, and a busy\n  interval that starts at exactly the slot's end does not block it.\n- Slots are returned for one calendar day of the requester, across DST.\n\n## Notes for the reviewer\n\n`Interval` is `(start, end)` in UTC. The person records carry `timezone`\n(IANA names). `db` is not involved.\n","src/slots.ts":'// Common free 30-minute slots for two people on one day.\nimport { DateTime, Interval } from "luxon";\n\nexport type Busy = { start: Date; end: Date };\nexport type Person = { timezone: string; busy: Busy[] };\n\nconst SLOT_MINUTES = 30;\n\nfunction workingWindow(person: Person, day: string) {\n  const start = DateTime.fromISO(day, { zone: person.timezone }).set({ hour: 9, minute: 0 });\n  const end = DateTime.fromISO(day, { zone: person.timezone }).set({ hour: 18, minute: 0 });\n  return { start, end };\n}\n\nfunction overlaps(aStart: DateTime, aEnd: DateTime, bStart: DateTime, bEnd: DateTime): boolean {\n  return aStart <= bEnd && bStart <= aEnd;\n}\n\nexport function freeSlots(requester: Person, other: Person, day: string): string[] {\n  const r = workingWindow(requester, day);\n  const o = workingWindow(other, day);\n  const start = r.start > o.start ? r.start : o.start;\n  const end = r.end < o.end ? r.end : o.end;\n\n  const busy = [...requester.busy, ...other.busy].map((b) => ({ start: DateTime.fromJSDate(b.start), end: DateTime.fromJSDate(b.end) }));\n  const slots: string[] = [];\n  let cursor = start;\n  while (cursor.plus({ minutes: SLOT_MINUTES }) <= end) {\n    const slotEnd = cursor.plus({ minutes: SLOT_MINUTES });\n    if (!busy.some((b) => overlaps(cursor, slotEnd, b.start, b.end))) {\n      slots.push(cursor.toFormat("HH:mm"));\n    }\n    cursor = cursor.plus({ minutes: SLOT_MINUTES });\n  }\n  return slots;\n}\n'}}}},{slug:"settings-page",title:"Notification settings page",difficulty:"Medium",area:"frontend",domains:["saas"],minutes:25,summary:"Optimistic saves from a React settings form. Two effects, one handler, and the ways they interact on load, on a fast click, and on failure.",brief:['A teammate has opened this as a pull request. The README rule "saving must not be triggered by loading" is the first thing to check.',"Render the component in your head from mount: which effects run, with what state, and what gets PUT before the GET returns. Then click two switches quickly.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct React; a comment on those costs you."],variants:{typescript:{entry:"README.md",files:{"README.md":"# Notification settings page\n\nUsers toggle email and push notifications and set a daily digest hour.\nChanges save as you make them, optimistically, with a toast on failure.\n\n## Rules\n\n- The switches must reflect what the server has: on load, and after a\n  failed save (roll back).\n- Saving must not be triggered by loading.\n- The page must stay responsive; saves happen in the background.\n\n## Notes for the reviewer\n\nReact 18 with TypeScript. `api.get` / `api.put` are our fetch wrappers;\n`toast.error(message)` shows a toast.\n","src/NotificationSettings.tsx":'import { useEffect, useState } from "react";\nimport { api } from "./api";\nimport { toast } from "./toast";\n\ntype Settings = { email: boolean; push: boolean; digestHour: number };\n\nexport function NotificationSettings({ userId }: { userId: string }) {\n  const [settings, setSettings] = useState<Settings>({ email: false, push: false, digestHour: 9 });\n  const [loaded, setLoaded] = useState(false);\n\n  useEffect(() => {\n    api.get<Settings>(`/api/users/${userId}/notifications`).then((s) => {\n      setSettings(s);\n      setLoaded(true);\n    });\n  }, [userId, { userId }]);\n\n  useEffect(() => {\n    api.put(`/api/users/${userId}/notifications`, settings).catch(() => {\n      toast.error("Could not save your settings");\n    });\n  }, [settings]);\n\n  function toggle(key: "email" | "push") {\n    setSettings({ ...settings, [key]: !settings[key] });\n  }\n\n  return (\n    <div>\n      <label>\n        <input type="checkbox" checked={settings.email} onChange={() => toggle("email")} /> Email\n      </label>\n      <label>\n        <input type="checkbox" checked={settings.push} onChange={() => toggle("push")} /> Push\n      </label>\n      <label>\n        Digest hour\n        <input type="number" defaultValue={settings.digestHour} onBlur={(e) => setSettings({ ...settings, digestHour: Number(e.target.value) })} />\n      </label>\n      {!loaded && <p>Loading</p>}\n    </div>\n  );\n}\n'}}}},{slug:"api-v2",title:"/v2 of the tasks API",difficulty:"Medium",area:"backend",domains:["saas"],minutes:20,summary:"A new API version beside the old one, with deprecation headers and cursor paging. Mostly right; one promise to v1 clients is broken.",brief:['A teammate has opened this as a pull request. Hold v1 against "exactly as before" and v2 against its paging rules.',"Not every PR has a serious bug. If it is good, approve with what you found; flagging correct code costs you.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Several things here are standard practice and correct."],variants:{java:{entry:"README.md",files:{"README.md":"# /v2 of the tasks API\n\nAdds `/v2/tasks`, which returns ISO timestamps and a `cursor` instead of\n`page`, alongside the existing `/v1/tasks`, which many customers still call.\n\n## Rules\n\n- `/v1` keeps working exactly as before for at least twelve months.\n- `/v1` responses carry a `Deprecation` header and a `Sunset` date.\n- `/v2` uses cursor pagination with a default page of 50 and a maximum of 200.\n\n## Notes for the reviewer\n\n`serializeV1` and `serializeV2` are the two output shapes. `Db` is the\nshared pool. The default v1 page size has always been 20.\n","src/TasksApi.java":'package tasks;\n\nimport java.nio.charset.StandardCharsets;\nimport java.time.OffsetDateTime;\nimport java.util.Base64;\nimport java.util.List;\nimport java.util.Map;\n\n/** GET /v1/tasks and GET /v2/tasks */\npublic final class TasksApi {\n    static final String SUNSET = "Sat, 30 Sep 2027 00:00:00 GMT";\n    static final int DEFAULT_PAGE = 50;\n    static final int MAX_PAGE = 200;\n\n    static int pageSize(Map<String, String> query) {\n        return Math.min(MAX_PAGE, Math.max(1, Integer.parseInt(query.getOrDefault("limit", String.valueOf(DEFAULT_PAGE)))));\n    }\n\n    static Map<String, String> deprecationHeaders() {\n        return Map.of("Deprecation", "true", "Sunset", SUNSET, "Link", "</v2/tasks>; rel=\\"successor-version\\"");\n    }\n\n    public static Response listV1(String userId, Map<String, String> query) {\n        int page = Math.max(1, Integer.parseInt(query.getOrDefault("page", "1")));\n        int limit = Math.min(MAX_PAGE, Math.max(1, Integer.parseInt(query.getOrDefault("limit", String.valueOf(DEFAULT_PAGE)))));\n        List<Map<String, Object>> rows = Db.all(\n            "SELECT id, title, done, created_at FROM tasks WHERE user_id = ? ORDER BY id LIMIT ? OFFSET ?",\n            userId, limit, (page - 1) * limit);\n        return Response.json(200, Map.of("tasks", rows.stream().map(TasksApi::serializeV1).toList(), "page", page)).headers(deprecationHeaders());\n    }\n\n    public static Response listV2(String userId, Map<String, String> query) {\n        int limit = pageSize(query);\n        long after = query.get("cursor") == null ? 0 : Long.parseLong(new String(Base64.getUrlDecoder().decode(query.get("cursor")), StandardCharsets.UTF_8));\n        List<Map<String, Object>> rows = Db.all(\n            "SELECT id, title, done, created_at FROM tasks WHERE user_id = ? AND id > ? ORDER BY id LIMIT ?",\n            userId, after, limit + 1);\n        boolean hasMore = rows.size() > limit;\n        List<Map<String, Object>> pageRows = rows.subList(0, Math.min(limit, rows.size()));\n        String cursor = hasMore ? Base64.getUrlEncoder().withoutPadding().encodeToString(String.valueOf(pageRows.get(pageRows.size() - 1).get("id")).getBytes(StandardCharsets.UTF_8)) : null;\n        return Response.json(200, Map.of("tasks", pageRows.stream().map(TasksApi::serializeV2).toList(), "cursor", cursor == null ? "" : cursor));\n    }\n\n    static Map<String, Object> serializeV1(Map<String, Object> r) {\n        return Map.of("id", r.get("id"), "title", r.get("title"), "done", r.get("done"), "created", ((OffsetDateTime) r.get("created_at")).toEpochSecond());\n    }\n\n    static Map<String, Object> serializeV2(Map<String, Object> r) {\n        return Map.of("id", r.get("id"), "title", r.get("title"), "done", r.get("done"), "created_at", ((OffsetDateTime) r.get("created_at")).toString());\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# /v2 of the tasks API\n\nAdds `/v2/tasks`, which returns ISO timestamps and a `cursor` instead of\n`page`, alongside the existing `/v1/tasks`, which many customers still call.\n\n## Rules\n\n- `/v1` keeps working exactly as before for at least twelve months.\n- `/v1` responses carry a `Deprecation` header and a `Sunset` date.\n- `/v2` uses cursor pagination with a default page of 50 and a maximum of 200.\n\n## Notes for the reviewer\n\n`serialize_v1` and `serialize_v2` are the two output shapes. `db` is the\nshared pool. The default v1 page size has always been 20.\n","src/tasks_api.py":'"""GET /v1/tasks and GET /v2/tasks"""\nimport base64\n\nimport db\n\nSUNSET = "Sat, 30 Sep 2027 00:00:00 GMT"\nDEFAULT_PAGE = 50\nMAX_PAGE = 200\n\n\ndef _page_size(query):\n    return min(MAX_PAGE, max(1, int(query.get("limit", DEFAULT_PAGE))))\n\n\ndef _deprecation_headers():\n    return {"Deprecation": "true", "Sunset": SUNSET, "Link": \'</v2/tasks>; rel="successor-version"\'}\n\n\ndef list_v1(user_id, query):\n    page = max(1, int(query.get("page", 1)))\n    limit = min(MAX_PAGE, max(1, int(query.get("limit", DEFAULT_PAGE))))\n    rows = db.all(\n        "SELECT id, title, done, created_at FROM tasks WHERE user_id = %s ORDER BY id LIMIT %s OFFSET %s",\n        (user_id, limit, (page - 1) * limit),\n    )\n    return 200, {"tasks": [serialize_v1(r) for r in rows], "page": page}, _deprecation_headers()\n\n\ndef list_v2(user_id, query):\n    limit = _page_size(query)\n    after = int(base64.urlsafe_b64decode(query["cursor"])) if query.get("cursor") else 0\n    rows = db.all(\n        "SELECT id, title, done, created_at FROM tasks WHERE user_id = %s AND id > %s ORDER BY id LIMIT %s",\n        (user_id, after, limit + 1),\n    )\n    has_more = len(rows) > limit\n    rows = rows[:limit]\n    cursor = base64.urlsafe_b64encode(str(rows[-1]["id"]).encode()).decode() if has_more else None\n    return 200, {"tasks": [serialize_v2(r) for r in rows], "cursor": cursor}\n\n\ndef serialize_v1(r):\n    return {"id": r["id"], "title": r["title"], "done": r["done"], "created": r["created_at"].timestamp()}\n\n\ndef serialize_v2(r):\n    return {"id": r["id"], "title": r["title"], "done": r["done"], "created_at": r["created_at"].isoformat()}\n'}},typescript:{entry:"README.md",files:{"README.md":"# /v2 of the tasks API\n\nAdds `/v2/tasks`, which returns ISO timestamps and a `cursor` instead of\n`page`, alongside the existing `/v1/tasks`, which many customers still call.\n\n## Rules\n\n- `/v1` keeps working exactly as before for at least twelve months.\n- `/v1` responses carry a `Deprecation` header and a `Sunset` date.\n- `/v2` uses cursor pagination with a default page of 50 and a maximum of 200.\n\n## Notes for the reviewer\n\n`serialize_v1` and `serialize_v2` are the two output shapes. `db` is the\nshared pool. The default v1 page size has always been 20.\n","src/tasksApi.ts":'// GET /v1/tasks and GET /v2/tasks\nimport { db } from "./db";\n\nconst SUNSET = "Sat, 30 Sep 2027 00:00:00 GMT";\nconst DEFAULT_PAGE = 50;\nconst MAX_PAGE = 200;\n\ntype Row = { id: number; title: string; done: boolean; created_at: Date };\n\nconst pageSize = (query: Record<string, string | undefined>) => Math.min(MAX_PAGE, Math.max(1, Number(query.limit ?? DEFAULT_PAGE)));\n\nconst deprecationHeaders = () => ({ Deprecation: "true", Sunset: SUNSET, Link: \'</v2/tasks>; rel="successor-version"\' });\n\nexport async function listV1(userId: string, query: Record<string, string | undefined>) {\n  const page = Math.max(1, Number(query.page ?? 1));\n  const limit = Math.min(MAX_PAGE, Math.max(1, Number(query.limit ?? DEFAULT_PAGE)));\n  const rows = await db.all<Row>("SELECT id, title, done, created_at FROM tasks WHERE user_id = $1 ORDER BY id LIMIT $2 OFFSET $3", [\n    userId,\n    limit,\n    (page - 1) * limit,\n  ]);\n  return { status: 200, body: { tasks: rows.map(serializeV1), page }, headers: deprecationHeaders() };\n}\n\nexport async function listV2(userId: string, query: Record<string, string | undefined>) {\n  const limit = pageSize(query);\n  const after = query.cursor ? Number(Buffer.from(query.cursor, "base64url").toString()) : 0;\n  const rows = await db.all<Row>("SELECT id, title, done, created_at FROM tasks WHERE user_id = $1 AND id > $2 ORDER BY id LIMIT $3", [\n    userId,\n    after,\n    limit + 1,\n  ]);\n  const hasMore = rows.length > limit;\n  const pageRows = rows.slice(0, limit);\n  const cursor = hasMore ? Buffer.from(String(pageRows[pageRows.length - 1].id)).toString("base64url") : null;\n  return { status: 200, body: { tasks: pageRows.map(serializeV2), cursor } };\n}\n\nconst serializeV1 = (r: Row) => ({ id: r.id, title: r.title, done: r.done, created: r.created_at.getTime() / 1000 });\nconst serializeV2 = (r: Row) => ({ id: r.id, title: r.title, done: r.done, created_at: r.created_at.toISOString() });\n'}}}},{slug:"quiz-submission",title:"Quiz attempts",difficulty:"Medium",area:"security",domains:["edtech"],minutes:25,summary:"Start a timed attempt, serve the questions, accept the answers, score it. Two of the five rules are about what the browser may know and when.",brief:["A teammate has opened this as a pull request. The README is the spec; five rules, and the code does not keep all of them.","Open your browser tools on the attempt screen and ask what you can see. Then submit the same attempt twice, and submit one an hour late.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of what looks careless here is deliberate and correct. A comment on that costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Quiz attempts\n\nA student starts a timed attempt, answers the questions, and submits it. This\nPR adds the three endpoints behind that.\n\n## Rules\n\n- A question's correct option must never reach the browser before the attempt\n  is submitted.\n- An attempt has a time limit, taken from the quiz. A submission after the\n  limit is not accepted.\n- An attempt is scored once. A second submission for the same attempt is\n  refused, not re-scored.\n- The score is the fraction of the quiz's questions answered correctly.\n  A question left unanswered counts as wrong.\n- The pass mark is 40%.\n\n## Notes for the reviewer\n\n`questions` rows carry `quiz_id`, `text`, `options` (a JSON array) and\n`correct_option` (an index into it). The browser runs its own countdown for\nthe student to see; the server is the authority on time. The caller's own id\narrives as `student_id`, already authenticated.\n","src/Quiz.java":'package learn;\n\nimport java.time.Instant;\nimport java.time.temporal.ChronoUnit;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** Quiz attempts: start, read, submit. */\npublic final class Quiz {\n    private static final double PASS_MARK = 0.4;\n\n    public record Started(String attemptId, List<Map<String, Object>> questions) {}\n\n    public record Scored(double score, boolean passed) {}\n\n    public static Started startAttempt(String studentId, String quizId) {\n        Map<String, Object> quiz = Db.one("SELECT id, minutes FROM quizzes WHERE id = ?", quizId);\n        Instant now = Instant.now();\n        Instant expires = now.plus((int) quiz.get("minutes"), ChronoUnit.MINUTES);\n        Map<String, Object> attempt = Db.one("INSERT INTO attempts (student_id, quiz_id, started_at, expires_at) "\n                + "VALUES (?, ?, ?, ?) RETURNING id", studentId, quizId, now, expires);\n        return new Started((String) attempt.get("id"), attemptQuestions(quizId));\n    }\n\n    public static List<Map<String, Object>> attemptQuestions(String quizId) {\n        List<Map<String, Object>> rows =\n                Db.all("SELECT id, text, options, correct_option FROM questions WHERE quiz_id = ?", quizId);\n        List<Map<String, Object>> out = new ArrayList<>();\n        for (Map<String, Object> r : rows) {\n            out.add(Map.of("id", r.get("id"), "text", r.get("text"), "options", r.get("options"),\n                    "correct_option", r.get("correct_option")));\n        }\n        return out;\n    }\n\n    public static Scored submitAttempt(String studentId, String attemptId, Map<String, Integer> answers) {\n        Map<String, Object> attempt = Db.one(\n                "SELECT id, quiz_id, student_id, expires_at, submitted_at FROM attempts WHERE id = ?", attemptId);\n        if (attempt == null) {\n            throw new NotFound("no such attempt");\n        }\n\n        List<Map<String, Object>> questions =\n                Db.all("SELECT id, correct_option FROM questions WHERE quiz_id = ?", attempt.get("quiz_id"));\n        int correct = 0;\n        int answered = 0;\n        for (Map<String, Object> q : questions) {\n            Integer given = answers.get(String.valueOf(q.get("id")));\n            if (given == null) {\n                continue;\n            }\n            answered++;\n            if (given.intValue() == (int) q.get("correct_option")) {\n                correct++;\n            }\n        }\n\n        double score = answered == 0 ? 0.0 : (double) correct / answered;\n        Db.run("UPDATE attempts SET score = ?, submitted_at = ? WHERE id = ?", score, Instant.now(), attemptId);\n        return new Scored(Math.round(score * 100) / 100.0, score >= PASS_MARK);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Quiz attempts\n\nA student starts a timed attempt, answers the questions, and submits it. This\nPR adds the three endpoints behind that.\n\n## Rules\n\n- A question's correct option must never reach the browser before the attempt\n  is submitted.\n- An attempt has a time limit, taken from the quiz. A submission after the\n  limit is not accepted.\n- An attempt is scored once. A second submission for the same attempt is\n  refused, not re-scored.\n- The score is the fraction of the quiz's questions answered correctly.\n  A question left unanswered counts as wrong.\n- The pass mark is 40%.\n\n## Notes for the reviewer\n\n`questions` rows carry `quiz_id`, `text`, `options` (a JSON array) and\n`correct_option` (an index into it). The browser runs its own countdown for\nthe student to see; the server is the authority on time. The caller's own id\narrives as `student_id`, already authenticated.\n","src/quiz.py":'"""Quiz attempts: start, read, submit."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\n\nPASS_MARK = 0.4\n\n\ndef start_attempt(student_id, quiz_id):\n    quiz = db.one("SELECT id, minutes FROM quizzes WHERE id = %s", (quiz_id,))\n    now = datetime.now(timezone.utc)\n    attempt = db.one(\n        "INSERT INTO attempts (student_id, quiz_id, started_at, expires_at) "\n        "VALUES (%s, %s, %s, %s) RETURNING id",\n        (student_id, quiz_id, now, now + timedelta(minutes=quiz["minutes"])),\n    )\n    return {"attempt_id": attempt["id"], "questions": attempt_questions(quiz_id)}\n\n\ndef attempt_questions(quiz_id):\n    rows = db.all("SELECT id, text, options, correct_option FROM questions WHERE quiz_id = %s", (quiz_id,))\n    return [\n        {"id": r["id"], "text": r["text"], "options": r["options"], "correct_option": r["correct_option"]}\n        for r in rows\n    ]\n\n\ndef submit_attempt(student_id, attempt_id, answers):\n    attempt = db.one(\n        "SELECT id, quiz_id, student_id, expires_at, submitted_at FROM attempts WHERE id = %s",\n        (attempt_id,),\n    )\n    if attempt is None:\n        raise NotFound("no such attempt")\n\n    questions = db.all("SELECT id, correct_option FROM questions WHERE quiz_id = %s", (attempt["quiz_id"],))\n    correct = 0\n    answered = 0\n    for q in questions:\n        given = answers.get(str(q["id"]))\n        if given is None:\n            continue\n        answered += 1\n        if int(given) == q["correct_option"]:\n            correct += 1\n\n    score = correct / answered if answered else 0.0\n    db.run(\n        "UPDATE attempts SET score = %s, submitted_at = %s WHERE id = %s",\n        (score, datetime.now(timezone.utc), attempt_id),\n    )\n    return {"score": round(score, 2), "passed": score >= PASS_MARK}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Quiz attempts\n\nA student starts a timed attempt, answers the questions, and submits it. This\nPR adds the three endpoints behind that.\n\n## Rules\n\n- A question's correct option must never reach the browser before the attempt\n  is submitted.\n- An attempt has a time limit, taken from the quiz. A submission after the\n  limit is not accepted.\n- An attempt is scored once. A second submission for the same attempt is\n  refused, not re-scored.\n- The score is the fraction of the quiz's questions answered correctly.\n  A question left unanswered counts as wrong.\n- The pass mark is 40%.\n\n## Notes for the reviewer\n\n`questions` rows carry `quiz_id`, `text`, `options` (a JSON array) and\n`correct_option` (an index into it). The browser runs its own countdown for\nthe student to see; the server is the authority on time. The caller's own id\narrives as `student_id`, already authenticated.\n","src/quiz.ts":'// Quiz attempts: start, read, submit.\nimport { db } from "./db";\n\nconst PASS_MARK = 0.4;\n\nexport async function startAttempt(studentId: string, quizId: string) {\n  const quiz = await db.one("SELECT id, minutes FROM quizzes WHERE id = $1", [quizId]);\n  const now = new Date();\n  const expires = new Date(now.getTime() + quiz.minutes * 60_000);\n  const attempt = await db.one(\n    "INSERT INTO attempts (student_id, quiz_id, started_at, expires_at) VALUES ($1, $2, $3, $4) RETURNING id",\n    [studentId, quizId, now, expires],\n  );\n  return { attemptId: attempt.id, questions: await attemptQuestions(quizId) };\n}\n\nexport async function attemptQuestions(quizId: string) {\n  const rows = await db.all("SELECT id, text, options, correct_option FROM questions WHERE quiz_id = $1", [quizId]);\n  return rows.map((r) => ({ id: r.id, text: r.text, options: r.options, correct_option: r.correct_option }));\n}\n\nexport async function submitAttempt(studentId: string, attemptId: string, answers: Record<string, number>) {\n  const attempt = await db.one(\n    "SELECT id, quiz_id, student_id, expires_at, submitted_at FROM attempts WHERE id = $1",\n    [attemptId],\n  );\n  if (!attempt) throw new NotFound("no such attempt");\n\n  const questions = await db.all("SELECT id, correct_option FROM questions WHERE quiz_id = $1", [attempt.quiz_id]);\n  let correct = 0;\n  let answered = 0;\n  for (const q of questions) {\n    const given = answers[String(q.id)];\n    if (given === undefined) continue;\n    answered += 1;\n    if (Number(given) === q.correct_option) correct += 1;\n  }\n\n  const score = answered ? correct / answered : 0;\n  await db.run("UPDATE attempts SET score = $1, submitted_at = $2 WHERE id = $3", [score, new Date(), attemptId]);\n  return { score: Math.round(score * 100) / 100, passed: score >= PASS_MARK };\n}\n'}}}},{slug:"spend-limits",title:"Card spend limits",difficulty:"Medium",area:"money",domains:["fintech"],minutes:25,summary:"A daily and a monthly limit checked before every authorisation. The limits are calendar windows in the README and something else in the code.",brief:["A teammate has opened this as a pull request. The README describes the limits the compliance team signed off; the code has to match it.","Trace a cardholder who spends at 23:50 and again at 00:10, one who has three authorisations in flight, and one whose transaction lands exactly on the limit.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One or two things here look sloppy and are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Card spend limits\n\nBefore a card transaction is authorised it is checked against the cardholder's\ndaily and monthly limit. This PR adds that check and the authorisation it\nguards.\n\n## Rules\n\n- The daily limit covers the cardholder's calendar day in their own zone, and\n  the monthly limit their calendar month. Both reset on a date, not on a clock\n  that runs from whenever they last spent.\n- Anything that can still be captured counts towards a limit: a pending\n  authorisation as much as a settled transaction.\n- A refund reduces the spend of the window the original charge fell in, not\n  the window the refund arrives in.\n- A transaction that lands exactly on the limit is allowed. One that would\n  take the cardholder past it is declined.\n- Two transactions arriving at once may not both be authorised past the limit.\n\n## Notes for the reviewer\n\n`cards` carry `daily_limit_paise`, `monthly_limit_paise` and `timezone`, an\nIANA name. `transactions` carry `status`, one of `pending`, `settled` or\n`declined`, and `created_at` in UTC. Refunds are their own table and carry the\nid of the transaction they reverse.\n","src/Limits.java":'package bank;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Daily and monthly spend limits on a card. */\npublic final class Limits {\n\n    public record Decision(boolean authorised, String reason) {}\n\n    static long windowSpend(String cardId, Instant since) {\n        Map<String, Object> row = Db.one("SELECT coalesce(sum(amount_paise), 0) AS total FROM transactions "\n                + "WHERE card_id = ? AND status = \'settled\' AND created_at >= ?", cardId, since);\n        return (long) row.get("total");\n    }\n\n    static long refundsSince(String cardId, Instant since) {\n        Map<String, Object> row = Db.one(\n                "SELECT coalesce(sum(amount_paise), 0) AS total FROM refunds WHERE card_id = ? AND created_at >= ?",\n                cardId, since);\n        return (long) row.get("total");\n    }\n\n    public static Decision authorise(String cardId, long amountPaise) {\n        Map<String, Object> card =\n                Db.one("SELECT id, daily_limit_paise, monthly_limit_paise, timezone FROM cards WHERE id = ?", cardId);\n        if (amountPaise <= 0) {\n            return new Decision(false, "bad amount");\n        }\n\n        Instant now = Instant.now();\n        Instant dayStart = now.minus(Duration.ofDays(1));\n        long daySpend = windowSpend(cardId, dayStart) - refundsSince(cardId, dayStart);\n        long monthSpend = windowSpend(cardId, now.minus(Duration.ofDays(30)));\n\n        if (daySpend + amountPaise >= (long) card.get("daily_limit_paise")) {\n            return decline(cardId, amountPaise, "daily limit");\n        }\n        if (monthSpend + amountPaise >= (long) card.get("monthly_limit_paise")) {\n            return decline(cardId, amountPaise, "monthly limit");\n        }\n\n        Db.run("INSERT INTO transactions (card_id, amount_paise, status, created_at) VALUES (?, ?, \'pending\', ?)",\n                cardId, amountPaise, now);\n        return new Decision(true, null);\n    }\n\n    static Decision decline(String cardId, long amountPaise, String reason) {\n        Db.run("INSERT INTO transactions (card_id, amount_paise, status, reason) VALUES (?, ?, \'declined\', ?)",\n                cardId, amountPaise, reason);\n        return new Decision(false, reason);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Card spend limits\n\nBefore a card transaction is authorised it is checked against the cardholder's\ndaily and monthly limit. This PR adds that check and the authorisation it\nguards.\n\n## Rules\n\n- The daily limit covers the cardholder's calendar day in their own zone, and\n  the monthly limit their calendar month. Both reset on a date, not on a clock\n  that runs from whenever they last spent.\n- Anything that can still be captured counts towards a limit: a pending\n  authorisation as much as a settled transaction.\n- A refund reduces the spend of the window the original charge fell in, not\n  the window the refund arrives in.\n- A transaction that lands exactly on the limit is allowed. One that would\n  take the cardholder past it is declined.\n- Two transactions arriving at once may not both be authorised past the limit.\n\n## Notes for the reviewer\n\n`cards` carry `daily_limit_paise`, `monthly_limit_paise` and `timezone`, an\nIANA name. `transactions` carry `status`, one of `pending`, `settled` or\n`declined`, and `created_at` in UTC. Refunds are their own table and carry the\nid of the transaction they reverse.\n","src/limits.py":'"""Daily and monthly spend limits on a card."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\n\n\ndef window_spend(card_id, since):\n    row = db.one(\n        "SELECT coalesce(sum(amount_paise), 0) AS total FROM transactions "\n        "WHERE card_id = %s AND status = \'settled\' AND created_at >= %s",\n        (card_id, since),\n    )\n    return row["total"]\n\n\ndef refunds_since(card_id, since):\n    row = db.one(\n        "SELECT coalesce(sum(amount_paise), 0) AS total FROM refunds WHERE card_id = %s AND created_at >= %s",\n        (card_id, since),\n    )\n    return row["total"]\n\n\ndef authorise(card_id, amount_paise):\n    card = db.one(\n        "SELECT id, daily_limit_paise, monthly_limit_paise, timezone FROM cards WHERE id = %s",\n        (card_id,),\n    )\n    if amount_paise <= 0:\n        return {"authorised": False, "reason": "bad amount"}\n\n    now = datetime.now(timezone.utc)\n    day_spend = window_spend(card_id, now - timedelta(days=1)) - refunds_since(card_id, now - timedelta(days=1))\n    month_spend = window_spend(card_id, now - timedelta(days=30))\n\n    if day_spend + amount_paise >= card["daily_limit_paise"]:\n        return decline(card_id, amount_paise, "daily limit")\n    if month_spend + amount_paise >= card["monthly_limit_paise"]:\n        return decline(card_id, amount_paise, "monthly limit")\n\n    db.run(\n        "INSERT INTO transactions (card_id, amount_paise, status, created_at) VALUES (%s, %s, \'pending\', %s)",\n        (card_id, amount_paise, now),\n    )\n    return {"authorised": True}\n\n\ndef decline(card_id, amount_paise, reason):\n    db.run(\n        "INSERT INTO transactions (card_id, amount_paise, status, reason) VALUES (%s, %s, \'declined\', %s)",\n        (card_id, amount_paise, reason),\n    )\n    return {"authorised": False, "reason": reason}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Card spend limits\n\nBefore a card transaction is authorised it is checked against the cardholder's\ndaily and monthly limit. This PR adds that check and the authorisation it\nguards.\n\n## Rules\n\n- The daily limit covers the cardholder's calendar day in their own zone, and\n  the monthly limit their calendar month. Both reset on a date, not on a clock\n  that runs from whenever they last spent.\n- Anything that can still be captured counts towards a limit: a pending\n  authorisation as much as a settled transaction.\n- A refund reduces the spend of the window the original charge fell in, not\n  the window the refund arrives in.\n- A transaction that lands exactly on the limit is allowed. One that would\n  take the cardholder past it is declined.\n- Two transactions arriving at once may not both be authorised past the limit.\n\n## Notes for the reviewer\n\n`cards` carry `daily_limit_paise`, `monthly_limit_paise` and `timezone`, an\nIANA name. `transactions` carry `status`, one of `pending`, `settled` or\n`declined`, and `created_at` in UTC. Refunds are their own table and carry the\nid of the transaction they reverse.\n","src/limits.ts":'// Daily and monthly spend limits on a card.\nimport { db } from "./db";\n\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nasync function windowSpend(cardId: string, since: Date) {\n  const row = await db.one(\n    "SELECT coalesce(sum(amount_paise), 0) AS total FROM transactions " +\n      "WHERE card_id = $1 AND status = \'settled\' AND created_at >= $2",\n    [cardId, since],\n  );\n  return Number(row.total);\n}\n\nasync function refundsSince(cardId: string, since: Date) {\n  const row = await db.one(\n    "SELECT coalesce(sum(amount_paise), 0) AS total FROM refunds WHERE card_id = $1 AND created_at >= $2",\n    [cardId, since],\n  );\n  return Number(row.total);\n}\n\nexport async function authorise(cardId: string, amountPaise: number) {\n  const card = await db.one("SELECT id, daily_limit_paise, monthly_limit_paise, timezone FROM cards WHERE id = $1", [\n    cardId,\n  ]);\n  if (amountPaise <= 0) return { authorised: false, reason: "bad amount" };\n\n  const now = new Date();\n  const dayStart = new Date(now.getTime() - DAY_MS);\n  const daySpend = (await windowSpend(cardId, dayStart)) - (await refundsSince(cardId, dayStart));\n  const monthSpend = await windowSpend(cardId, new Date(now.getTime() - 30 * DAY_MS));\n\n  if (daySpend + amountPaise >= card.daily_limit_paise) return decline(cardId, amountPaise, "daily limit");\n  if (monthSpend + amountPaise >= card.monthly_limit_paise) return decline(cardId, amountPaise, "monthly limit");\n\n  await db.run("INSERT INTO transactions (card_id, amount_paise, status, created_at) VALUES ($1, $2, \'pending\', $3)", [\n    cardId,\n    amountPaise,\n    now,\n  ]);\n  return { authorised: true };\n}\n\nasync function decline(cardId: string, amountPaise: number, reason: string) {\n  await db.run("INSERT INTO transactions (card_id, amount_paise, status, reason) VALUES ($1, $2, \'declined\', $3)", [\n    cardId,\n    amountPaise,\n    reason,\n  ]);\n  return { authorised: false, reason };\n}\n'}}}},{slug:"appointment-booking",title:"Booking an appointment",difficulty:"Medium",area:"time",domains:["health","scheduling"],minutes:25,summary:"Thirty-minute slots, a ten-minute gap between them, working hours in the clinic’s zone, and a cancellation window. The clash query is where to start.",brief:["A teammate has opened this as a pull request. The five rules in the README are the spec.","Draw a doctor’s afternoon on paper: an appointment at 15:00, then ask which of 15:25, 15:35 and 14:35 this code lets you book. Then ask what the clinic’s zone has to do with any of it.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of this is right. A comment on those lines costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Booking an appointment\n\nA patient picks a slot with a doctor and this PR books it, or refuses.\n\n## Rules\n\n- A doctor's working hours are a local time range per weekday, in the clinic's\n  zone.\n- An appointment is 30 minutes, and a doctor needs 10 minutes between two of\n  them. A booking may not start within ten minutes of another one ending, and\n  may not end within ten minutes of another one starting.\n- A slot may be booked once, even when two patients press the button in the\n  same second.\n- An appointment cannot be booked in the past.\n- A patient may cancel up to 24 hours before the start. Exactly 24 hours\n  before is still allowed.\n\n## Notes for the reviewer\n\n`doctor_hours` is `(doctor_id, weekday, open_time, close_time)` with local\ntimes. `appointments` carry `starts_at` in UTC and `status`. There is no\nunique index on the table yet; the migration in this PR does not add one.\n","src/Booking.java":'package clinic;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.time.LocalTime;\nimport java.time.ZoneOffset;\nimport java.util.Map;\n\n/** Book and cancel appointments. */\npublic final class Booking {\n    private static final Duration LENGTH = Duration.ofMinutes(30);\n    private static final Duration BUFFER = Duration.ofMinutes(10);\n    private static final Duration CANCEL_WINDOW = Duration.ofHours(24);\n\n    public static boolean withinHours(Map<String, Object> doctor, Instant startsAt) {\n        Map<String, Object> hours = Db.one(\n                "SELECT open_time, close_time FROM doctor_hours WHERE doctor_id = ? AND weekday = ?",\n                doctor.get("id"), startsAt.atZone(ZoneOffset.UTC).getDayOfWeek().getValue());\n        if (hours == null) {\n            return false;\n        }\n        LocalTime start = startsAt.atZone(ZoneOffset.UTC).toLocalTime();\n        LocalTime end = startsAt.plus(LENGTH).atZone(ZoneOffset.UTC).toLocalTime();\n        return !start.isBefore((LocalTime) hours.get("open_time")) && !end.isAfter((LocalTime) hours.get("close_time"));\n    }\n\n    public static Instant book(String patientId, String doctorId, Instant startsAt) {\n        Map<String, Object> doctor = Db.one("SELECT id, clinic_id FROM doctors WHERE id = ?", doctorId);\n        if (!withinHours(doctor, startsAt)) {\n            throw new Unavailable("outside working hours");\n        }\n\n        Map<String, Object> clash = Db.one("SELECT 1 FROM appointments WHERE doctor_id = ? AND status = \'booked\' "\n                + "AND starts_at < ? AND starts_at + interval \'40 minutes\' > ?",\n                doctorId, startsAt.plus(LENGTH), startsAt);\n        if (clash != null) {\n            throw new Unavailable("slot taken");\n        }\n\n        Db.run("INSERT INTO appointments (patient_id, doctor_id, starts_at, status) VALUES (?, ?, ?, \'booked\')",\n                patientId, doctorId, startsAt);\n        return startsAt;\n    }\n\n    public static boolean cancel(String appointmentId, Instant now) {\n        Map<String, Object> appt = Db.one("SELECT id, starts_at FROM appointments WHERE id = ?", appointmentId);\n        Instant startsAt = (Instant) appt.get("starts_at");\n        if (Duration.between(now, startsAt).compareTo(CANCEL_WINDOW) <= 0) {\n            throw new TooLate("too late to cancel");\n        }\n        Db.run("UPDATE appointments SET status = \'cancelled\' WHERE id = ?", appointmentId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Booking an appointment\n\nA patient picks a slot with a doctor and this PR books it, or refuses.\n\n## Rules\n\n- A doctor's working hours are a local time range per weekday, in the clinic's\n  zone.\n- An appointment is 30 minutes, and a doctor needs 10 minutes between two of\n  them. A booking may not start within ten minutes of another one ending, and\n  may not end within ten minutes of another one starting.\n- A slot may be booked once, even when two patients press the button in the\n  same second.\n- An appointment cannot be booked in the past.\n- A patient may cancel up to 24 hours before the start. Exactly 24 hours\n  before is still allowed.\n\n## Notes for the reviewer\n\n`doctor_hours` is `(doctor_id, weekday, open_time, close_time)` with local\ntimes. `appointments` carry `starts_at` in UTC and `status`. There is no\nunique index on the table yet; the migration in this PR does not add one.\n","src/booking.py":'"""Book and cancel appointments."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\n\nLENGTH = timedelta(minutes=30)\nBUFFER = timedelta(minutes=10)\nCANCEL_WINDOW = timedelta(hours=24)\n\n\ndef within_hours(doctor, starts_at):\n    hours = db.one(\n        "SELECT open_time, close_time FROM doctor_hours WHERE doctor_id = %s AND weekday = %s",\n        (doctor["id"], starts_at.weekday()),\n    )\n    if hours is None:\n        return False\n    return hours["open_time"] <= starts_at.time() and (starts_at + LENGTH).time() <= hours["close_time"]\n\n\ndef book(patient_id, doctor_id, starts_at):\n    doctor = db.one("SELECT id, clinic_id FROM doctors WHERE id = %s", (doctor_id,))\n    if not within_hours(doctor, starts_at):\n        raise Unavailable("outside working hours")\n\n    clash = db.one(\n        "SELECT 1 FROM appointments WHERE doctor_id = %s AND status = \'booked\' "\n        "AND starts_at < %s AND starts_at + interval \'40 minutes\' > %s",\n        (doctor_id, starts_at + LENGTH, starts_at),\n    )\n    if clash:\n        raise Unavailable("slot taken")\n\n    db.run(\n        "INSERT INTO appointments (patient_id, doctor_id, starts_at, status) VALUES (%s, %s, %s, \'booked\')",\n        (patient_id, doctor_id, starts_at),\n    )\n    return {"starts_at": starts_at}\n\n\ndef cancel(appointment_id, now=None):\n    now = now or datetime.now(timezone.utc)\n    appt = db.one("SELECT id, starts_at FROM appointments WHERE id = %s", (appointment_id,))\n    if appt["starts_at"] - now <= CANCEL_WINDOW:\n        raise TooLate("too late to cancel")\n    db.run("UPDATE appointments SET status = \'cancelled\' WHERE id = %s", (appointment_id,))\n    return {"cancelled": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Booking an appointment\n\nA patient picks a slot with a doctor and this PR books it, or refuses.\n\n## Rules\n\n- A doctor's working hours are a local time range per weekday, in the clinic's\n  zone.\n- An appointment is 30 minutes, and a doctor needs 10 minutes between two of\n  them. A booking may not start within ten minutes of another one ending, and\n  may not end within ten minutes of another one starting.\n- A slot may be booked once, even when two patients press the button in the\n  same second.\n- An appointment cannot be booked in the past.\n- A patient may cancel up to 24 hours before the start. Exactly 24 hours\n  before is still allowed.\n\n## Notes for the reviewer\n\n`doctor_hours` is `(doctor_id, weekday, open_time, close_time)` with local\ntimes. `appointments` carry `starts_at` in UTC and `status`. There is no\nunique index on the table yet; the migration in this PR does not add one.\n","src/booking.ts":'// Book and cancel appointments.\nimport { db } from "./db";\n\nconst LENGTH_MIN = 30;\nconst BUFFER_MIN = 10;\nconst CANCEL_WINDOW_MS = 24 * 60 * 60 * 1000;\n\nexport async function withinHours(doctor: { id: string }, startsAt: Date) {\n  const hours = await db.one("SELECT open_time, close_time FROM doctor_hours WHERE doctor_id = $1 AND weekday = $2", [\n    doctor.id,\n    startsAt.getUTCDay(),\n  ]);\n  if (!hours) return false;\n  const start = startsAt.toISOString().slice(11, 16);\n  const end = new Date(startsAt.getTime() + LENGTH_MIN * 60_000).toISOString().slice(11, 16);\n  return hours.open_time <= start && end <= hours.close_time;\n}\n\nexport async function book(patientId: string, doctorId: string, startsAt: Date) {\n  const doctor = await db.one("SELECT id, clinic_id FROM doctors WHERE id = $1", [doctorId]);\n  if (!(await withinHours(doctor, startsAt))) throw new Unavailable("outside working hours");\n\n  const clash = await db.one(\n    "SELECT 1 FROM appointments WHERE doctor_id = $1 AND status = \'booked\' " +\n      "AND starts_at < $2 AND starts_at + interval \'40 minutes\' > $3",\n    [doctorId, new Date(startsAt.getTime() + LENGTH_MIN * 60_000), startsAt],\n  );\n  if (clash) throw new Unavailable("slot taken");\n\n  await db.run("INSERT INTO appointments (patient_id, doctor_id, starts_at, status) VALUES ($1, $2, $3, \'booked\')", [\n    patientId,\n    doctorId,\n    startsAt,\n  ]);\n  return { startsAt };\n}\n\nexport async function cancel(appointmentId: string, now = new Date()) {\n  const appt = await db.one("SELECT id, starts_at FROM appointments WHERE id = $1", [appointmentId]);\n  if (new Date(appt.starts_at).getTime() - now.getTime() <= CANCEL_WINDOW_MS) throw new TooLate("too late to cancel");\n  await db.run("UPDATE appointments SET status = \'cancelled\' WHERE id = $1", [appointmentId]);\n  return { cancelled: true };\n}\n'}}}},{slug:"fare-search-cache",title:"Fare search",difficulty:"Medium",area:"caching",domains:["travel"],minutes:25,summary:"Suppliers, a cache, then filtering, sorting and paging. Read the cache key first, then read the order the last four lines run in.",brief:["A teammate has opened this as a pull request. The five rules in the README are what the storefront promises a customer.","Search for two passengers in dirhams right after someone searched the same route for one in rupees. Then ask what page two looks like when a filter is on.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","A couple of things here look like mistakes and are deliberate. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Fare search\n\nAsk the suppliers for fares, cache what comes back, then filter, sort and page\nthe results for the storefront.\n\n## Rules\n\n- A quote is good for fifteen minutes. Older than that and the price is asked\n  for again before it is shown to anybody.\n- Two searches are the same search only when the route, the date, the number\n  of passengers and the currency all match.\n- A supplier that times out makes the result partial. A partial result is\n  never cached, and the response says which suppliers answered.\n- Filtering and sorting apply to the whole result set, before paging.\n- The total is the number of results after filtering.\n\n## Notes for the reviewer\n\n`SUPPLIERS` is a list of adapters; `quote` returns fares with `price_paise`\nand raises `SupplierTimeout`. `cache` is Redis with a per-key TTL. Prices come\nback in the currency that was asked for.\n","src/Search.java":'package travel;\n\nimport java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Random;\n\n/** Fare search across suppliers, with a cache in front. */\npublic final class Search {\n    private static final int TTL_SECONDS = 1800;\n    private static final int JITTER_SECONDS = 30;\n    private static final Random RANDOM = new Random();\n\n    public record Page(List<Map<String, Object>> results, int total, int page) {}\n\n    public static String cacheKey(String route, String date) {\n        return "fares:" + route + ":" + date;\n    }\n\n    static boolean matches(Map<String, Object> fare, Map<String, Object> filters) {\n        if (filters.get("maxStops") != null && (int) fare.get("stops") > (int) filters.get("maxStops")) {\n            return false;\n        }\n        if (filters.get("airline") != null && !filters.get("airline").equals(fare.get("airline"))) {\n            return false;\n        }\n        return true;\n    }\n\n    public static Page search(String route, String date, int passengers, String currency,\n            Map<String, Object> filters, int page, int perPage) {\n        String key = cacheKey(route, date);\n        List<Map<String, Object>> fares = Cache.get(key);\n        if (fares == null) {\n            fares = new ArrayList<>();\n            for (Supplier supplier : Suppliers.ALL) {\n                try {\n                    fares.addAll(supplier.quote(route, date, passengers, currency));\n                } catch (SupplierTimeout timeout) {\n                    continue;\n                }\n            }\n            Cache.set(key, fares, TTL_SECONDS + RANDOM.nextInt(JITTER_SECONDS));\n        }\n\n        int start = (page - 1) * perPage;\n        List<Map<String, Object>> window = fares.subList(Math.min(start, fares.size()),\n                Math.min(start + perPage, fares.size()));\n        List<Map<String, Object>> shown = new ArrayList<>();\n        for (Map<String, Object> f : window) {\n            if (matches(f, filters)) {\n                shown.add(f);\n            }\n        }\n        shown.sort(Comparator.comparingLong(f -> (long) f.get("price_paise")));\n        return new Page(shown, fares.size(), page);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Fare search\n\nAsk the suppliers for fares, cache what comes back, then filter, sort and page\nthe results for the storefront.\n\n## Rules\n\n- A quote is good for fifteen minutes. Older than that and the price is asked\n  for again before it is shown to anybody.\n- Two searches are the same search only when the route, the date, the number\n  of passengers and the currency all match.\n- A supplier that times out makes the result partial. A partial result is\n  never cached, and the response says which suppliers answered.\n- Filtering and sorting apply to the whole result set, before paging.\n- The total is the number of results after filtering.\n\n## Notes for the reviewer\n\n`SUPPLIERS` is a list of adapters; `quote` returns fares with `price_paise`\nand raises `SupplierTimeout`. `cache` is Redis with a per-key TTL. Prices come\nback in the currency that was asked for.\n","src/search.py":'"""Fare search across suppliers, with a cache in front."""\nimport random\n\nfrom cache import cache\nfrom suppliers import SUPPLIERS, SupplierTimeout\n\nTTL_SECONDS = 1800\nJITTER_SECONDS = 30\n\n\ndef cache_key(route, date):\n    return f"fares:{route}:{date}"\n\n\ndef matches(fare, filters):\n    if filters.get("max_stops") is not None and fare["stops"] > filters["max_stops"]:\n        return False\n    if filters.get("airline") and fare["airline"] != filters["airline"]:\n        return False\n    return True\n\n\ndef search(route, date, passengers, currency, filters, page, per_page):\n    key = cache_key(route, date)\n    fares = cache.get(key)\n    if fares is None:\n        fares = []\n        for supplier in SUPPLIERS:\n            try:\n                fares.extend(supplier.quote(route, date, passengers, currency))\n            except SupplierTimeout:\n                continue\n        cache.set(key, fares, TTL_SECONDS + random.randint(0, JITTER_SECONDS))\n\n    start = (page - 1) * per_page\n    window = fares[start : start + per_page]\n    shown = [f for f in window if matches(f, filters)]\n    shown.sort(key=lambda f: f["price_paise"])\n    return {"results": shown, "total": len(fares), "page": page}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Fare search\n\nAsk the suppliers for fares, cache what comes back, then filter, sort and page\nthe results for the storefront.\n\n## Rules\n\n- A quote is good for fifteen minutes. Older than that and the price is asked\n  for again before it is shown to anybody.\n- Two searches are the same search only when the route, the date, the number\n  of passengers and the currency all match.\n- A supplier that times out makes the result partial. A partial result is\n  never cached, and the response says which suppliers answered.\n- Filtering and sorting apply to the whole result set, before paging.\n- The total is the number of results after filtering.\n\n## Notes for the reviewer\n\n`SUPPLIERS` is a list of adapters; `quote` returns fares with `price_paise`\nand raises `SupplierTimeout`. `cache` is Redis with a per-key TTL. Prices come\nback in the currency that was asked for.\n","src/search.ts":'// Fare search across suppliers, with a cache in front.\nimport { cache } from "./cache";\nimport { SUPPLIERS, SupplierTimeout } from "./suppliers";\n\nconst TTL_SECONDS = 1800;\nconst JITTER_SECONDS = 30;\n\nexport function cacheKey(route: string, date: string) {\n  return `fares:${route}:${date}`;\n}\n\nexport function matches(fare: Record<string, number | string>, filters: Record<string, number | string>) {\n  if (filters.maxStops !== undefined && fare.stops > filters.maxStops) return false;\n  if (filters.airline && fare.airline !== filters.airline) return false;\n  return true;\n}\n\nexport async function search(\n  route: string,\n  date: string,\n  passengers: number,\n  currency: string,\n  filters: Record<string, number | string>,\n  page: number,\n  perPage: number,\n) {\n  const key = cacheKey(route, date);\n  let fares = await cache.get(key);\n  if (!fares) {\n    fares = [];\n    for (const supplier of SUPPLIERS) {\n      try {\n        fares.push(...(await supplier.quote(route, date, passengers, currency)));\n      } catch (err) {\n        if (err instanceof SupplierTimeout) continue;\n        throw err;\n      }\n    }\n    await cache.set(key, fares, TTL_SECONDS + Math.floor(Math.random() * JITTER_SECONDS));\n  }\n\n  const start = (page - 1) * perPage;\n  const window = fares.slice(start, start + perPage);\n  const shown = window.filter((f) => matches(f, filters));\n  shown.sort((a, b) => a.price_paise - b.price_paise);\n  return { results: shown, total: fares.length, page };\n}\n'}}}},{slug:"subscription-renewal",title:"Subscription renewals",difficulty:"Medium",area:"money",domains:["payments","saas"],minutes:25,summary:"Renew monthly, charge the difference on an upgrade, cancel. Five rules about dates and money, and the cycle here is thirty days long whatever the calendar says.",brief:["A teammate has opened this as a pull request. The README is the billing policy; the code has to match it, because customers read their statements.","Follow a subscription that started on 31 January through a year, and one whose renewal times out and is retried.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","A couple of choices here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Subscription renewals\n\nRenew a subscription every month, charge for an upgrade in the middle of a\ncycle, and cancel one. This PR is all three.\n\n## Rules\n\n- A subscription renews on the same day of the month it started on. When that\n  day does not exist in a month, it renews on the last day of that month.\n- A renewal charges the plan price once. A retry after a timeout must not\n  charge a second time.\n- An upgrade in the middle of a cycle charges the difference for the days that\n  are left, counted against the length of the cycle it is in.\n- A cancellation takes effect at the end of the period already paid for. The\n  subscription stays active until then.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`subscriptions` carry `plan_price_paise`, `renews_on` (a date), `status` and\n`last_charge_id`. `payments.charge` takes an optional idempotency key and is\nretried by the caller on a timeout.\n","src/Subscriptions.java":'package billing;\n\nimport java.time.LocalDate;\nimport java.time.temporal.ChronoUnit;\nimport java.util.Map;\n\n/** Renewals, upgrades and cancellations. */\npublic final class Subscriptions {\n    private static final int CYCLE_DAYS = 30;\n\n    public static LocalDate nextRenewal(LocalDate renewsOn) {\n        return renewsOn.plusDays(CYCLE_DAYS);\n    }\n\n    public static String renew(String subscriptionId) {\n        Map<String, Object> sub = Db.one(\n                "SELECT id, plan_price_paise, renews_on, status FROM subscriptions WHERE id = ?", subscriptionId);\n        Payments.Charge charge = Payments.charge((String) sub.get("id"), (long) sub.get("plan_price_paise"));\n        Db.run("UPDATE subscriptions SET renews_on = ?, last_charge_id = ? WHERE id = ?",\n                nextRenewal((LocalDate) sub.get("renews_on")), charge.id(), subscriptionId);\n        return charge.id();\n    }\n\n    public static long upgrade(String subscriptionId, long newPricePaise) {\n        Map<String, Object> sub =\n                Db.one("SELECT id, plan_price_paise, renews_on FROM subscriptions WHERE id = ?", subscriptionId);\n        long daysLeft = ChronoUnit.DAYS.between(LocalDate.now(), (LocalDate) sub.get("renews_on"));\n        long difference = newPricePaise - (long) sub.get("plan_price_paise");\n        double prorated = (double) (difference * daysLeft) / CYCLE_DAYS;\n        Payments.charge((String) sub.get("id"), (long) prorated);\n        Db.run("UPDATE subscriptions SET plan_price_paise = ? WHERE id = ?", newPricePaise, subscriptionId);\n        return (long) prorated;\n    }\n\n    public static boolean cancel(String subscriptionId) {\n        Db.run("UPDATE subscriptions SET status = \'cancelled\', renews_on = NULL WHERE id = ?", subscriptionId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Subscription renewals\n\nRenew a subscription every month, charge for an upgrade in the middle of a\ncycle, and cancel one. This PR is all three.\n\n## Rules\n\n- A subscription renews on the same day of the month it started on. When that\n  day does not exist in a month, it renews on the last day of that month.\n- A renewal charges the plan price once. A retry after a timeout must not\n  charge a second time.\n- An upgrade in the middle of a cycle charges the difference for the days that\n  are left, counted against the length of the cycle it is in.\n- A cancellation takes effect at the end of the period already paid for. The\n  subscription stays active until then.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`subscriptions` carry `plan_price_paise`, `renews_on` (a date), `status` and\n`last_charge_id`. `payments.charge` takes an optional idempotency key and is\nretried by the caller on a timeout.\n","src/subscriptions.py":'"""Renewals, upgrades and cancellations."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\nimport payments\n\nCYCLE_DAYS = 30\n\n\ndef next_renewal(renews_on):\n    return renews_on + timedelta(days=CYCLE_DAYS)\n\n\ndef renew(subscription_id):\n    sub = db.one(\n        "SELECT id, plan_price_paise, renews_on, status FROM subscriptions WHERE id = %s",\n        (subscription_id,),\n    )\n    charge = payments.charge(sub["id"], sub["plan_price_paise"])\n    db.run(\n        "UPDATE subscriptions SET renews_on = %s, last_charge_id = %s WHERE id = %s",\n        (next_renewal(sub["renews_on"]), charge.id, subscription_id),\n    )\n    return charge.id\n\n\ndef upgrade(subscription_id, new_price_paise):\n    sub = db.one(\n        "SELECT id, plan_price_paise, renews_on FROM subscriptions WHERE id = %s",\n        (subscription_id,),\n    )\n    days_left = (sub["renews_on"] - datetime.now(timezone.utc).date()).days\n    difference = new_price_paise - sub["plan_price_paise"]\n    prorated = difference * days_left / CYCLE_DAYS\n    payments.charge(sub["id"], int(prorated))\n    db.run(\n        "UPDATE subscriptions SET plan_price_paise = %s WHERE id = %s",\n        (new_price_paise, subscription_id),\n    )\n    return int(prorated)\n\n\ndef cancel(subscription_id):\n    db.run(\n        "UPDATE subscriptions SET status = \'cancelled\', renews_on = NULL WHERE id = %s",\n        (subscription_id,),\n    )\n    return {"cancelled": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Subscription renewals\n\nRenew a subscription every month, charge for an upgrade in the middle of a\ncycle, and cancel one. This PR is all three.\n\n## Rules\n\n- A subscription renews on the same day of the month it started on. When that\n  day does not exist in a month, it renews on the last day of that month.\n- A renewal charges the plan price once. A retry after a timeout must not\n  charge a second time.\n- An upgrade in the middle of a cycle charges the difference for the days that\n  are left, counted against the length of the cycle it is in.\n- A cancellation takes effect at the end of the period already paid for. The\n  subscription stays active until then.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`subscriptions` carry `plan_price_paise`, `renews_on` (a date), `status` and\n`last_charge_id`. `payments.charge` takes an optional idempotency key and is\nretried by the caller on a timeout.\n","src/subscriptions.ts":'// Renewals, upgrades and cancellations.\nimport { db } from "./db";\nimport * as payments from "./payments";\n\nconst CYCLE_DAYS = 30;\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport function nextRenewal(renewsOn: Date) {\n  return new Date(renewsOn.getTime() + CYCLE_DAYS * DAY_MS);\n}\n\nexport async function renew(subscriptionId: string) {\n  const sub = await db.one("SELECT id, plan_price_paise, renews_on, status FROM subscriptions WHERE id = $1", [\n    subscriptionId,\n  ]);\n  const charge = await payments.charge(sub.id, sub.plan_price_paise);\n  await db.run("UPDATE subscriptions SET renews_on = $1, last_charge_id = $2 WHERE id = $3", [\n    nextRenewal(new Date(sub.renews_on)),\n    charge.id,\n    subscriptionId,\n  ]);\n  return charge.id;\n}\n\nexport async function upgrade(subscriptionId: string, newPricePaise: number) {\n  const sub = await db.one("SELECT id, plan_price_paise, renews_on FROM subscriptions WHERE id = $1", [subscriptionId]);\n  const daysLeft = Math.floor((new Date(sub.renews_on).getTime() - Date.now()) / DAY_MS);\n  const difference = newPricePaise - sub.plan_price_paise;\n  const prorated = (difference * daysLeft) / CYCLE_DAYS;\n  await payments.charge(sub.id, Math.trunc(prorated));\n  await db.run("UPDATE subscriptions SET plan_price_paise = $1 WHERE id = $2", [newPricePaise, subscriptionId]);\n  return Math.trunc(prorated);\n}\n\nexport async function cancel(subscriptionId: string) {\n  await db.run("UPDATE subscriptions SET status = \'cancelled\', renews_on = NULL WHERE id = $1", [subscriptionId]);\n  return { cancelled: true };\n}\n'}}}},{slug:"payment-idempotency",title:"Idempotency keys on charges",difficulty:"Medium",area:"backend",domains:["payments"],minutes:25,summary:"Twenty lines that decide whether a retried charge takes money twice. The five rules in the README are all about a key, and the code keeps one of them.",brief:["A teammate has opened this as a pull request. This is the code between a merchant’s retry loop and somebody’s card.","Send the same key from two merchants. Send the same key with a different amount. Send it twice in the same millisecond. Then ask what the request_hash column is for.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One or two things here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Idempotency keys on the charge endpoint\n\nMerchants retry. This PR makes `POST /charges` safe to call twice with the\nsame `Idempotency-Key` header.\n\n## Rules\n\n- A key belongs to the merchant that sent it. Two merchants may use the same\n  key and must not see each other's result.\n- The same key with the same request body returns the first response, with the\n  same charge id, and does not charge again.\n- The same key with a different body is an error, not a second charge.\n- Two requests with one key arriving together: one charges, the other waits\n  and gets the same answer. Neither is a second charge.\n- A key is remembered for 24 hours.\n\n## Notes for the reviewer\n\n`idempotency_keys` is `(key, merchant_id, request_hash, response, created_at)`\nwith a unique index on `key` alone today; the migration in this PR does not\nchange it. `cache` is Redis.\n","src/Idempotency.java":'package billing;\n\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.util.Map;\nimport java.util.TreeMap;\n\n/** Idempotency for POST /charges. */\npublic final class Idempotency {\n    private static final int KEY_TTL_HOURS = 24;\n\n    public static String requestHash(Map<String, Object> body) {\n        try {\n            MessageDigest sha = MessageDigest.getInstance("SHA-256");\n            byte[] out = sha.digest(new TreeMap<>(body).toString().getBytes(StandardCharsets.UTF_8));\n            return java.util.HexFormat.of().formatHex(out);\n        } catch (Exception e) {\n            throw new IllegalStateException(e);\n        }\n    }\n\n    public static Map<String, Object> charge(String merchantId, String key, Map<String, Object> body) {\n        if (key == null || key.isEmpty()) {\n            return Map.of("id", Payments.charge(merchantId, (long) body.get("amount_paise")).id());\n        }\n\n        Map<String, Object> seen = Db.one("SELECT key, response FROM idempotency_keys WHERE key = ?", key);\n        if (seen != null) {\n            return (Map<String, Object>) seen.get("response");\n        }\n\n        Payments.Charge result = Payments.charge(merchantId, (long) body.get("amount_paise"));\n        Db.run("INSERT INTO idempotency_keys (key, merchant_id, request_hash, response, created_at) "\n                + "VALUES (?, ?, ?, ?, now())", key, merchantId, requestHash(body), Map.of("id", result.id()));\n        return Map.of("id", result.id());\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Idempotency keys on the charge endpoint\n\nMerchants retry. This PR makes `POST /charges` safe to call twice with the\nsame `Idempotency-Key` header.\n\n## Rules\n\n- A key belongs to the merchant that sent it. Two merchants may use the same\n  key and must not see each other's result.\n- The same key with the same request body returns the first response, with the\n  same charge id, and does not charge again.\n- The same key with a different body is an error, not a second charge.\n- Two requests with one key arriving together: one charges, the other waits\n  and gets the same answer. Neither is a second charge.\n- A key is remembered for 24 hours.\n\n## Notes for the reviewer\n\n`idempotency_keys` is `(key, merchant_id, request_hash, response, created_at)`\nwith a unique index on `key` alone today; the migration in this PR does not\nchange it. `cache` is Redis.\n","src/idempotency.py":'"""Idempotency for POST /charges."""\nimport hashlib\nimport json\n\nimport db\nimport payments\n\nKEY_TTL_HOURS = 24\n\n\ndef request_hash(body):\n    return hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()\n\n\ndef charge(merchant_id, key, body):\n    if not key:\n        return payments.charge(merchant_id, body["amount_paise"])\n\n    seen = db.one("SELECT key, response FROM idempotency_keys WHERE key = %s", (key,))\n    if seen is not None:\n        return seen["response"]\n\n    charge_result = payments.charge(merchant_id, body["amount_paise"])\n    db.run(\n        "INSERT INTO idempotency_keys (key, merchant_id, request_hash, response, created_at) "\n        "VALUES (%s, %s, %s, %s, now())",\n        (key, merchant_id, request_hash(body), json.dumps({"id": charge_result.id})),\n    )\n    return {"id": charge_result.id}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Idempotency keys on the charge endpoint\n\nMerchants retry. This PR makes `POST /charges` safe to call twice with the\nsame `Idempotency-Key` header.\n\n## Rules\n\n- A key belongs to the merchant that sent it. Two merchants may use the same\n  key and must not see each other's result.\n- The same key with the same request body returns the first response, with the\n  same charge id, and does not charge again.\n- The same key with a different body is an error, not a second charge.\n- Two requests with one key arriving together: one charges, the other waits\n  and gets the same answer. Neither is a second charge.\n- A key is remembered for 24 hours.\n\n## Notes for the reviewer\n\n`idempotency_keys` is `(key, merchant_id, request_hash, response, created_at)`\nwith a unique index on `key` alone today; the migration in this PR does not\nchange it. `cache` is Redis.\n","src/idempotency.ts":'// Idempotency for POST /charges.\nimport { createHash } from "node:crypto";\nimport { db } from "./db";\nimport * as payments from "./payments";\n\nconst KEY_TTL_HOURS = 24;\n\nexport function requestHash(body: Record<string, unknown>) {\n  return createHash("sha256").update(JSON.stringify(body, Object.keys(body).sort())).digest("hex");\n}\n\nexport async function charge(merchantId: string, key: string | undefined, body: Record<string, number>) {\n  if (!key) return payments.charge(merchantId, body.amount_paise);\n\n  const seen = await db.one("SELECT key, response FROM idempotency_keys WHERE key = $1", [key]);\n  if (seen) return seen.response;\n\n  const result = await payments.charge(merchantId, body.amount_paise);\n  await db.run(\n    "INSERT INTO idempotency_keys (key, merchant_id, request_hash, response, created_at) " +\n      "VALUES ($1, $2, $3, $4, now())",\n    [key, merchantId, requestHash(body), JSON.stringify({ id: result.id })],\n  );\n  return { id: result.id };\n}\n'}}}},{slug:"card-vault",title:"Saving a card for next time",difficulty:"Medium",area:"security",domains:["payments","identity"],minutes:25,summary:"Send the card to the vault, keep the token, show the last four. Thirty lines, and the first rule in the README is broken on the first one.",brief:["A teammate has opened this as a pull request. The rules in the README are the ones an auditor reads out; treat them that way.","Follow the card number through this file and write down every place a copy of it ends up.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One or two things here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Saving a card for next time\n\nA customer ticks "save this card". We send the card to the vault provider,\nkeep the token, and show the card on the payment screen. This PR does that.\n\n## Rules\n\n- The card number, the CVV and the expiry never touch our database, our logs\n  or our error reports. Only the provider sees them.\n- What we keep is the token, the network (visa, rupay), the last four digits\n  and the expiry month and year for the display.\n- The last four digits are what the provider returns, not something we cut off\n  the number ourselves.\n- A token belongs to one customer and is never returned to another.\n- A failed vault call tells the customer their card could not be saved, and\n  says nothing else.\n\n## Notes for the reviewer\n\n`vault.store` returns `token`, `network`, `last4`. `cards` is\n`(customer_id, token, network, last4, expiry_month, expiry_year)`.\n',"src/Vault.java":'package billing;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Saving a card and listing saved cards. */\npublic final class Vault {\n    private static final Logger log = Logger.getLogger(Vault.class.getName());\n\n    public record Card(String number, String cvv, int expiryMonth, int expiryYear) {}\n\n    public static Map<String, Object> saveCard(String customerId, Card card) {\n        log.info("saving card for " + customerId + ": " + card);\n        VaultClient.Stored stored;\n        try {\n            stored = VaultClient.store(card.number(), card.cvv(), card.expiryMonth(), card.expiryYear());\n        } catch (VaultClient.VaultError err) {\n            throw new BadRequest("could not save card: " + err.getMessage());\n        }\n\n        String last4 = card.number().substring(card.number().length() - 4);\n        Db.run("INSERT INTO cards (customer_id, token, network, last4, expiry_month, expiry_year) "\n                + "VALUES (?, ?, ?, ?, ?, ?)",\n                customerId, stored.token(), stored.network(), last4, card.expiryMonth(), card.expiryYear());\n        return Map.of("token", stored.token(), "last4", last4);\n    }\n\n    public static List<Map<String, Object>> savedCards(String customerId, String token) {\n        if (token != null) {\n            return Db.all("SELECT token, network, last4 FROM cards WHERE token = ?", token);\n        }\n        return Db.all("SELECT token, network, last4 FROM cards WHERE customer_id = ?", customerId);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Saving a card for next time\n\nA customer ticks "save this card". We send the card to the vault provider,\nkeep the token, and show the card on the payment screen. This PR does that.\n\n## Rules\n\n- The card number, the CVV and the expiry never touch our database, our logs\n  or our error reports. Only the provider sees them.\n- What we keep is the token, the network (visa, rupay), the last four digits\n  and the expiry month and year for the display.\n- The last four digits are what the provider returns, not something we cut off\n  the number ourselves.\n- A token belongs to one customer and is never returned to another.\n- A failed vault call tells the customer their card could not be saved, and\n  says nothing else.\n\n## Notes for the reviewer\n\n`vault.store` returns `token`, `network`, `last4`. `cards` is\n`(customer_id, token, network, last4, expiry_month, expiry_year)`.\n',"src/vault.py":'"""Saving a card and listing saved cards."""\nimport logging\n\nimport db\nimport vault\n\nlog = logging.getLogger(__name__)\n\n\ndef save_card(customer_id, card):\n    log.info("saving card for %s: %s", customer_id, card)\n    try:\n        stored = vault.store(card["number"], card["cvv"], card["expiry_month"], card["expiry_year"])\n    except vault.VaultError as err:\n        raise BadRequest(f"could not save card: {err}")\n\n    db.run(\n        "INSERT INTO cards (customer_id, token, network, last4, expiry_month, expiry_year) "\n        "VALUES (%s, %s, %s, %s, %s, %s)",\n        (\n            customer_id,\n            stored.token,\n            stored.network,\n            card["number"][-4:],\n            card["expiry_month"],\n            card["expiry_year"],\n        ),\n    )\n    return {"token": stored.token, "last4": card["number"][-4:]}\n\n\ndef saved_cards(customer_id, token=None):\n    if token:\n        return db.all("SELECT token, network, last4 FROM cards WHERE token = %s", (token,))\n    return db.all("SELECT token, network, last4 FROM cards WHERE customer_id = %s", (customer_id,))\n'}},typescript:{entry:"README.md",files:{"README.md":'# Saving a card for next time\n\nA customer ticks "save this card". We send the card to the vault provider,\nkeep the token, and show the card on the payment screen. This PR does that.\n\n## Rules\n\n- The card number, the CVV and the expiry never touch our database, our logs\n  or our error reports. Only the provider sees them.\n- What we keep is the token, the network (visa, rupay), the last four digits\n  and the expiry month and year for the display.\n- The last four digits are what the provider returns, not something we cut off\n  the number ourselves.\n- A token belongs to one customer and is never returned to another.\n- A failed vault call tells the customer their card could not be saved, and\n  says nothing else.\n\n## Notes for the reviewer\n\n`vault.store` returns `token`, `network`, `last4`. `cards` is\n`(customer_id, token, network, last4, expiry_month, expiry_year)`.\n',"src/vault.ts":'// Saving a card and listing saved cards.\nimport { db } from "./db";\nimport { log } from "./log";\nimport * as vault from "./vaultClient";\n\ntype Card = { number: string; cvv: string; expiry_month: number; expiry_year: number };\n\nexport async function saveCard(customerId: string, card: Card) {\n  log.info("saving card for %s: %o", customerId, card);\n  let stored;\n  try {\n    stored = await vault.store(card.number, card.cvv, card.expiry_month, card.expiry_year);\n  } catch (err) {\n    throw new BadRequest(`could not save card: ${(err as Error).message}`);\n  }\n\n  await db.run(\n    "INSERT INTO cards (customer_id, token, network, last4, expiry_month, expiry_year) " +\n      "VALUES ($1, $2, $3, $4, $5, $6)",\n    [customerId, stored.token, stored.network, card.number.slice(-4), card.expiry_month, card.expiry_year],\n  );\n  return { token: stored.token, last4: card.number.slice(-4) };\n}\n\nexport async function savedCards(customerId: string, token?: string) {\n  if (token) return db.all("SELECT token, network, last4 FROM cards WHERE token = $1", [token]);\n  return db.all("SELECT token, network, last4 FROM cards WHERE customer_id = $1", [customerId]);\n}\n'}}}},{slug:"settlement-report",title:"Daily settlement report",difficulty:"Medium",area:"data",domains:["payments","analytics"],minutes:25,summary:"Four numbers finance reads every morning. Two queries decide which day a rupee belongs to, and both of them answer with a different day than the README does.",brief:["A teammate has opened this as a pull request. Finance will reconcile against a bank statement, so a rupee in the wrong day is a morning of somebody’s life.","Take a sale at 04:00 IST and a refund three days after the sale it reverses, and follow each into a row.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of this is right. A comment on those lines costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Daily settlement report\n\nFinance opens this every morning: what we took yesterday, what we owe the\nmerchants, and what we kept. This PR builds the row.\n\n## Rules\n\n- A day runs midnight to midnight in Asia/Kolkata, which is where the business\n  banks.\n- Gross is the settled sales of that day. A refund is subtracted from the day\n  the sale it reverses settled, not the day the refund arrived.\n- Net is gross minus refunds minus commission, and the four numbers on the row\n  have to add up exactly.\n- A day that has been closed is never rebuilt. It is read.\n- Amounts are paise, as integers. Commission is 2% of gross.\n\n## Notes for the reviewer\n\n`settlements` is one row per date with a unique index on `on_date` and a\n`closed` flag finance sets. Refunds carry `transaction_id`, the sale they\nreverse.\n","src/Settlement.java":'package billing;\n\nimport java.time.LocalDate;\nimport java.util.Map;\n\n/** The daily settlement row. */\npublic final class Settlement {\n    private static final int COMMISSION_BPS = 200;\n\n    public record Row(long gross, long refunds, long commission, long net) {}\n\n    public static Row build(LocalDate onDate) {\n        long gross = (long) Db.one("SELECT coalesce(sum(amount_paise), 0) AS n FROM transactions "\n                + "WHERE status = \'settled\' AND settled_at::date = ?", onDate).get("n");\n        long refunds = (long) Db.one(\n                "SELECT coalesce(sum(amount_paise), 0) AS n FROM refunds WHERE created_at::date = ?", onDate).get("n");\n\n        double commission = (double) (gross * COMMISSION_BPS) / 10000;\n        double net = gross - refunds - commission;\n\n        Db.run("INSERT INTO settlements (on_date, gross_paise, refunds_paise, commission_paise, net_paise) "\n                + "VALUES (?, ?, ?, ?, ?) ON CONFLICT (on_date) DO UPDATE SET "\n                + "gross_paise = EXCLUDED.gross_paise, refunds_paise = EXCLUDED.refunds_paise, "\n                + "commission_paise = EXCLUDED.commission_paise, net_paise = EXCLUDED.net_paise",\n                onDate, gross, refunds, (long) commission, (long) net);\n        return new Row(gross, refunds, (long) commission, (long) net);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Daily settlement report\n\nFinance opens this every morning: what we took yesterday, what we owe the\nmerchants, and what we kept. This PR builds the row.\n\n## Rules\n\n- A day runs midnight to midnight in Asia/Kolkata, which is where the business\n  banks.\n- Gross is the settled sales of that day. A refund is subtracted from the day\n  the sale it reverses settled, not the day the refund arrived.\n- Net is gross minus refunds minus commission, and the four numbers on the row\n  have to add up exactly.\n- A day that has been closed is never rebuilt. It is read.\n- Amounts are paise, as integers. Commission is 2% of gross.\n\n## Notes for the reviewer\n\n`settlements` is one row per date with a unique index on `on_date` and a\n`closed` flag finance sets. Refunds carry `transaction_id`, the sale they\nreverse.\n","src/settlement.py":'"""The daily settlement row."""\nimport db\n\nCOMMISSION_BPS = 200\n\n\ndef build(on_date):\n    gross = db.one(\n        "SELECT coalesce(sum(amount_paise), 0) AS n FROM transactions "\n        "WHERE status = \'settled\' AND settled_at::date = %s",\n        (on_date,),\n    )["n"]\n    refunds = db.one(\n        "SELECT coalesce(sum(amount_paise), 0) AS n FROM refunds WHERE created_at::date = %s",\n        (on_date,),\n    )["n"]\n\n    commission = gross * COMMISSION_BPS / 10000\n    net = gross - refunds - commission\n\n    db.run(\n        "INSERT INTO settlements (on_date, gross_paise, refunds_paise, commission_paise, net_paise) "\n        "VALUES (%s, %s, %s, %s, %s) ON CONFLICT (on_date) DO UPDATE SET "\n        "gross_paise = EXCLUDED.gross_paise, refunds_paise = EXCLUDED.refunds_paise, "\n        "commission_paise = EXCLUDED.commission_paise, net_paise = EXCLUDED.net_paise",\n        (on_date, gross, refunds, int(commission), int(net)),\n    )\n    return {"gross": gross, "refunds": refunds, "commission": int(commission), "net": int(net)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Daily settlement report\n\nFinance opens this every morning: what we took yesterday, what we owe the\nmerchants, and what we kept. This PR builds the row.\n\n## Rules\n\n- A day runs midnight to midnight in Asia/Kolkata, which is where the business\n  banks.\n- Gross is the settled sales of that day. A refund is subtracted from the day\n  the sale it reverses settled, not the day the refund arrived.\n- Net is gross minus refunds minus commission, and the four numbers on the row\n  have to add up exactly.\n- A day that has been closed is never rebuilt. It is read.\n- Amounts are paise, as integers. Commission is 2% of gross.\n\n## Notes for the reviewer\n\n`settlements` is one row per date with a unique index on `on_date` and a\n`closed` flag finance sets. Refunds carry `transaction_id`, the sale they\nreverse.\n","src/settlement.ts":'// The daily settlement row.\nimport { db } from "./db";\n\nconst COMMISSION_BPS = 200;\n\nexport async function build(onDate: string) {\n  const gross = Number(\n    (\n      await db.one(\n        "SELECT coalesce(sum(amount_paise), 0) AS n FROM transactions " +\n          "WHERE status = \'settled\' AND settled_at::date = $1",\n        [onDate],\n      )\n    ).n,\n  );\n  const refunds = Number(\n    (await db.one("SELECT coalesce(sum(amount_paise), 0) AS n FROM refunds WHERE created_at::date = $1", [onDate])).n,\n  );\n\n  const commission = (gross * COMMISSION_BPS) / 10000;\n  const net = gross - refunds - commission;\n\n  await db.run(\n    "INSERT INTO settlements (on_date, gross_paise, refunds_paise, commission_paise, net_paise) " +\n      "VALUES ($1, $2, $3, $4, $5) ON CONFLICT (on_date) DO UPDATE SET " +\n      "gross_paise = EXCLUDED.gross_paise, refunds_paise = EXCLUDED.refunds_paise, " +\n      "commission_paise = EXCLUDED.commission_paise, net_paise = EXCLUDED.net_paise",\n    [onDate, gross, refunds, Math.trunc(commission), Math.trunc(net)],\n  );\n  return { gross, refunds, commission: Math.trunc(commission), net: Math.trunc(net) };\n}\n'}}}},{slug:"session-revocation",title:"Signing out",difficulty:"Medium",area:"security",domains:["identity"],minutes:25,summary:"Sign out, sign out everywhere, and the refresh in between. The interesting question is what a stolen refresh token can still do after all three.",brief:["A teammate has opened this as a pull request. Sign out is the button people press when they think something is wrong, so it has to be the one thing that works.","Steal a refresh token, then sign out everywhere from the real browser, and see what the thief can still do. Then use one refresh token twice.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of this is right. A comment on those lines costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Signing out\n\n"Sign out" ends this session. "Sign out everywhere" ends all of them. This PR\nadds both, on top of the refresh-token rotation that already exists.\n\n## Rules\n\n- Signing out ends the session it was called for: that refresh token stops\n  working immediately.\n- Sign out everywhere ends every session on the account, including the one\n  that asked.\n- An access token already in a browser stays valid until it expires, which is\n  at most five minutes. Nothing else keeps working.\n- A refresh token is single use. A second use of one is treated as theft, and\n  every session on that account ends.\n- Ending a session is recorded: which session, when, and why.\n\n## Notes for the reviewer\n\n`sessions` is `(id, user_id, refresh_token, revoked_at, revoked_reason,\nlast_used_at)`. `issue_access` mints the short-lived access token.\n',"src/Sessions.java":'package accounts;\n\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport java.util.Map;\n\n/** Sign out, sign out everywhere, and refresh. */\npublic final class Sessions {\n    private static final int ACCESS_TTL_MINUTES = 60;\n    private static final SecureRandom RANDOM = new SecureRandom();\n\n    public static boolean signOut(String sessionId) {\n        Db.run("DELETE FROM sessions WHERE id = ?", sessionId);\n        return true;\n    }\n\n    public static boolean signOutEverywhere(String userId, String currentSessionId) {\n        Db.run("DELETE FROM sessions WHERE user_id = ? AND id <> ?", userId, currentSessionId);\n        return true;\n    }\n\n    public static Map<String, String> refresh(String refreshToken) {\n        Map<String, Object> row =\n                Db.one("SELECT id, user_id, revoked_at FROM sessions WHERE refresh_token = ?", refreshToken);\n        if (row == null) {\n            throw new Unauthorized("bad token");\n        }\n\n        byte[] bytes = new byte[32];\n        RANDOM.nextBytes(bytes);\n        String newToken = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);\n        Db.run("UPDATE sessions SET refresh_token = ?, last_used_at = now() WHERE id = ?", newToken, row.get("id"));\n        return Map.of("access", Tokens.issueAccess((String) row.get("user_id"), ACCESS_TTL_MINUTES),\n                "refresh", newToken);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Signing out\n\n"Sign out" ends this session. "Sign out everywhere" ends all of them. This PR\nadds both, on top of the refresh-token rotation that already exists.\n\n## Rules\n\n- Signing out ends the session it was called for: that refresh token stops\n  working immediately.\n- Sign out everywhere ends every session on the account, including the one\n  that asked.\n- An access token already in a browser stays valid until it expires, which is\n  at most five minutes. Nothing else keeps working.\n- A refresh token is single use. A second use of one is treated as theft, and\n  every session on that account ends.\n- Ending a session is recorded: which session, when, and why.\n\n## Notes for the reviewer\n\n`sessions` is `(id, user_id, refresh_token, revoked_at, revoked_reason,\nlast_used_at)`. `issue_access` mints the short-lived access token.\n',"src/sessions.py":'"""Sign out, sign out everywhere, and refresh."""\nimport secrets\n\nimport db\nfrom tokens import issue_access\n\nACCESS_TTL_MINUTES = 60\n\n\ndef sign_out(session_id):\n    db.run("DELETE FROM sessions WHERE id = %s", (session_id,))\n    return {"ok": True}\n\n\ndef sign_out_everywhere(user_id, current_session_id):\n    db.run(\n        "DELETE FROM sessions WHERE user_id = %s AND id <> %s",\n        (user_id, current_session_id),\n    )\n    return {"ok": True}\n\n\ndef refresh(refresh_token):\n    row = db.one(\n        "SELECT id, user_id, revoked_at FROM sessions WHERE refresh_token = %s",\n        (refresh_token,),\n    )\n    if row is None:\n        raise Unauthorized("bad token")\n\n    new_token = secrets.token_urlsafe(32)\n    db.run(\n        "UPDATE sessions SET refresh_token = %s, last_used_at = now() WHERE id = %s",\n        (new_token, row["id"]),\n    )\n    return {"access": issue_access(row["user_id"], ACCESS_TTL_MINUTES), "refresh": new_token}\n'}},typescript:{entry:"README.md",files:{"README.md":'# Signing out\n\n"Sign out" ends this session. "Sign out everywhere" ends all of them. This PR\nadds both, on top of the refresh-token rotation that already exists.\n\n## Rules\n\n- Signing out ends the session it was called for: that refresh token stops\n  working immediately.\n- Sign out everywhere ends every session on the account, including the one\n  that asked.\n- An access token already in a browser stays valid until it expires, which is\n  at most five minutes. Nothing else keeps working.\n- A refresh token is single use. A second use of one is treated as theft, and\n  every session on that account ends.\n- Ending a session is recorded: which session, when, and why.\n\n## Notes for the reviewer\n\n`sessions` is `(id, user_id, refresh_token, revoked_at, revoked_reason,\nlast_used_at)`. `issue_access` mints the short-lived access token.\n',"src/sessions.ts":'// Sign out, sign out everywhere, and refresh.\nimport { randomBytes } from "node:crypto";\nimport { db } from "./db";\nimport { issueAccess } from "./tokens";\n\nconst ACCESS_TTL_MINUTES = 60;\n\nexport async function signOut(sessionId: string) {\n  await db.run("DELETE FROM sessions WHERE id = $1", [sessionId]);\n  return { ok: true };\n}\n\nexport async function signOutEverywhere(userId: string, currentSessionId: string) {\n  await db.run("DELETE FROM sessions WHERE user_id = $1 AND id <> $2", [userId, currentSessionId]);\n  return { ok: true };\n}\n\nexport async function refresh(refreshToken: string) {\n  const row = await db.one("SELECT id, user_id, revoked_at FROM sessions WHERE refresh_token = $1", [refreshToken]);\n  if (!row) throw new Unauthorized("bad token");\n\n  const newToken = randomBytes(32).toString("base64url");\n  await db.run("UPDATE sessions SET refresh_token = $1, last_used_at = now() WHERE id = $2", [newToken, row.id]);\n  return { access: issueAccess(row.user_id, ACCESS_TTL_MINUTES), refresh: newToken };\n}\n'}}}},{slug:"email-change",title:"Changing the email on an account",difficulty:"Medium",area:"security",domains:["identity"],minutes:25,summary:"Twenty-five lines that decide who owns an account. The login address changes on the first statement, and everything else follows from that.",brief:["A teammate has opened this as a pull request. The address on an account is the way back into it, so treat this as an account-takeover surface.","Ask what happens between the request and the confirmation, and what a stranger with somebody’s open laptop can do with these two endpoints.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","A couple of things here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Changing the email on an account\n\nThe address on an account is also how its owner signs in, so changing it is a\nsecurity operation. This PR adds the request and the confirmation.\n\n## Rules\n\n- The new address becomes the login address only after it has been verified.\n- The old address is told the moment a change is requested, and the change can\n  be undone from that mail for 72 hours.\n- A verification link is single use, expires after 24 hours, and works only for\n  the account that asked for it.\n- Confirming a change ends the account's other sessions.\n- Two accounts may never end up with the same login address.\n\n## Notes for the reviewer\n\n`users` carry `email`, `pending_email`, `email_verified`, `change_token` and\n`change_requested_at`. `mailer` has `send_verification` and `send_notice`.\nThere is a unique index on `users.email`.\n","src/EmailChange.java":'package accounts;\n\nimport java.security.SecureRandom;\nimport java.util.HexFormat;\nimport java.util.Map;\n\n/** Requesting and confirming an email change. */\npublic final class EmailChange {\n    private static final SecureRandom RANDOM = new SecureRandom();\n\n    public static boolean requestChange(String userId, String newEmail) {\n        byte[] bytes = new byte[16];\n        RANDOM.nextBytes(bytes);\n        String token = HexFormat.of().formatHex(bytes);\n        Db.run("UPDATE users SET email = ?, email_verified = false, change_token = ?, change_requested_at = now() "\n                + "WHERE id = ?", newEmail, token, userId);\n        Mailer.sendVerification(newEmail, token);\n        return true;\n    }\n\n    public static Map<String, Object> confirmChange(String token) {\n        Map<String, Object> user = Db.one("SELECT id, email FROM users WHERE change_token = ?", token);\n        if (user == null) {\n            throw new NotFound("bad link");\n        }\n\n        Db.run("UPDATE users SET email_verified = true WHERE id = ?", user.get("id"));\n        return Map.of("ok", true, "email", user.get("email"));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Changing the email on an account\n\nThe address on an account is also how its owner signs in, so changing it is a\nsecurity operation. This PR adds the request and the confirmation.\n\n## Rules\n\n- The new address becomes the login address only after it has been verified.\n- The old address is told the moment a change is requested, and the change can\n  be undone from that mail for 72 hours.\n- A verification link is single use, expires after 24 hours, and works only for\n  the account that asked for it.\n- Confirming a change ends the account's other sessions.\n- Two accounts may never end up with the same login address.\n\n## Notes for the reviewer\n\n`users` carry `email`, `pending_email`, `email_verified`, `change_token` and\n`change_requested_at`. `mailer` has `send_verification` and `send_notice`.\nThere is a unique index on `users.email`.\n","src/email_change.py":'"""Requesting and confirming an email change."""\nimport secrets\n\nimport db\nimport mailer\n\n\ndef request_change(user_id, new_email):\n    token = secrets.token_hex(16)\n    db.run(\n        "UPDATE users SET email = %s, email_verified = false, change_token = %s, change_requested_at = now() "\n        "WHERE id = %s",\n        (new_email, token, user_id),\n    )\n    mailer.send_verification(new_email, token)\n    return {"sent": True}\n\n\ndef confirm_change(token):\n    user = db.one("SELECT id, email FROM users WHERE change_token = %s", (token,))\n    if user is None:\n        raise NotFound("bad link")\n\n    db.run("UPDATE users SET email_verified = true WHERE id = %s", (user["id"],))\n    return {"ok": True, "email": user["email"]}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Changing the email on an account\n\nThe address on an account is also how its owner signs in, so changing it is a\nsecurity operation. This PR adds the request and the confirmation.\n\n## Rules\n\n- The new address becomes the login address only after it has been verified.\n- The old address is told the moment a change is requested, and the change can\n  be undone from that mail for 72 hours.\n- A verification link is single use, expires after 24 hours, and works only for\n  the account that asked for it.\n- Confirming a change ends the account's other sessions.\n- Two accounts may never end up with the same login address.\n\n## Notes for the reviewer\n\n`users` carry `email`, `pending_email`, `email_verified`, `change_token` and\n`change_requested_at`. `mailer` has `send_verification` and `send_notice`.\nThere is a unique index on `users.email`.\n","src/emailChange.ts":'// Requesting and confirming an email change.\nimport { randomBytes } from "node:crypto";\nimport { db } from "./db";\nimport * as mailer from "./mailer";\n\nexport async function requestChange(userId: string, newEmail: string) {\n  const token = randomBytes(16).toString("hex");\n  await db.run(\n    "UPDATE users SET email = $1, email_verified = false, change_token = $2, change_requested_at = now() " +\n      "WHERE id = $3",\n    [newEmail, token, userId],\n  );\n  await mailer.sendVerification(newEmail, token);\n  return { sent: true };\n}\n\nexport async function confirmChange(token: string) {\n  const user = await db.one("SELECT id, email FROM users WHERE change_token = $1", [token]);\n  if (!user) throw new NotFound("bad link");\n\n  await db.run("UPDATE users SET email_verified = true WHERE id = $1", [user.id]);\n  return { ok: true, email: user.email };\n}\n'}}}},{slug:"api-keys",title:"API keys for the public API",difficulty:"Medium",area:"security",domains:["saas","devtools"],minutes:25,summary:"Issue a key, check a key, list the keys. Read the column the key is written into, and then read the loop that checks one.",brief:["A teammate has opened this as a pull request. This is the front door of the public API, so read it the way an attacker with a stolen backup would.","Present a key from another workspace. Then ask what the verify loop costs when a customer has ten thousand keys, and what it tells an attacker about timing.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","A couple of things here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# API keys for the public API\n\nCustomers call our API with a key they create in the dashboard. This PR issues\nthem and checks them.\n\n## Rules\n\n- A key is shown to the customer once, when it is created. We store something\n  that proves a presented key is right, not the key.\n- A key carries scopes. A request outside its scopes is refused.\n- A key belongs to one workspace, and a key from one workspace can never act\n  on another.\n- A key can be revoked, and can be given an expiry. Both take effect at once.\n- The dashboard lists keys by a prefix and the last four characters, so a\n  customer can tell them apart without us keeping the key.\n\n## Notes for the reviewer\n\n`api_keys` is `(id, workspace_id, name, secret, prefix, last4, scopes,\nrevoked_at, expires_at)`. `hashing` wraps argon2. Keys look like\n`cv_live_<32 random characters>`.\n","src/ApiKeys.java":'package platform;\n\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport java.util.List;\nimport java.util.Map;\n\n/** Creating and verifying API keys. */\npublic final class ApiKeys {\n    private static final String PREFIX = "cv_live_";\n    private static final SecureRandom RANDOM = new SecureRandom();\n\n    public static String createKey(String workspaceId, String name, List<String> scopes) {\n        byte[] bytes = new byte[24];\n        RANDOM.nextBytes(bytes);\n        String key = PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);\n        Db.run("INSERT INTO api_keys (workspace_id, name, secret, prefix, last4, scopes) "\n                + "VALUES (?, ?, ?, ?, ?, ?)",\n                workspaceId, name, key, PREFIX, key.substring(key.length() - 4), scopes);\n        return key;\n    }\n\n    public static Map<String, Object> verify(String presented, String workspaceId, String action) {\n        List<Map<String, Object>> rows = Db.all("SELECT id, workspace_id, secret, scopes, revoked_at FROM api_keys");\n        for (Map<String, Object> row : rows) {\n            if (row.get("secret").equals(presented)) {\n                List<String> scopes = (List<String>) row.get("scopes");\n                if (!scopes.contains(action) && !scopes.contains("*")) {\n                    throw new Forbidden("out of scope");\n                }\n                return Map.of("keyId", row.get("id"), "workspaceId", row.get("workspace_id"));\n            }\n        }\n        throw new Unauthorized("unknown key");\n    }\n\n    public static List<Map<String, Object>> listKeys(String workspaceId) {\n        return Db.all("SELECT id, name, prefix, last4, secret, scopes, revoked_at FROM api_keys WHERE workspace_id = ?",\n                workspaceId);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# API keys for the public API\n\nCustomers call our API with a key they create in the dashboard. This PR issues\nthem and checks them.\n\n## Rules\n\n- A key is shown to the customer once, when it is created. We store something\n  that proves a presented key is right, not the key.\n- A key carries scopes. A request outside its scopes is refused.\n- A key belongs to one workspace, and a key from one workspace can never act\n  on another.\n- A key can be revoked, and can be given an expiry. Both take effect at once.\n- The dashboard lists keys by a prefix and the last four characters, so a\n  customer can tell them apart without us keeping the key.\n\n## Notes for the reviewer\n\n`api_keys` is `(id, workspace_id, name, secret, prefix, last4, scopes,\nrevoked_at, expires_at)`. `hashing` wraps argon2. Keys look like\n`cv_live_<32 random characters>`.\n","src/api_keys.py":'"""Creating and verifying API keys."""\nimport secrets\n\nimport db\n\nPREFIX = "cv_live_"\n\n\ndef create_key(workspace_id, name, scopes):\n    key = PREFIX + secrets.token_urlsafe(24)\n    db.run(\n        "INSERT INTO api_keys (workspace_id, name, secret, prefix, last4, scopes) "\n        "VALUES (%s, %s, %s, %s, %s, %s)",\n        (workspace_id, name, key, PREFIX, key[-4:], scopes),\n    )\n    return {"key": key}\n\n\ndef verify(presented, workspace_id, action):\n    rows = db.all("SELECT id, workspace_id, secret, scopes, revoked_at FROM api_keys")\n    for row in rows:\n        if row["secret"] == presented:\n            if action not in row["scopes"] and "*" not in row["scopes"]:\n                raise Forbidden("out of scope")\n            return {"key_id": row["id"], "workspace_id": row["workspace_id"]}\n    raise Unauthorized("unknown key")\n\n\ndef list_keys(workspace_id):\n    return db.all(\n        "SELECT id, name, prefix, last4, secret, scopes, revoked_at FROM api_keys WHERE workspace_id = %s",\n        (workspace_id,),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":"# API keys for the public API\n\nCustomers call our API with a key they create in the dashboard. This PR issues\nthem and checks them.\n\n## Rules\n\n- A key is shown to the customer once, when it is created. We store something\n  that proves a presented key is right, not the key.\n- A key carries scopes. A request outside its scopes is refused.\n- A key belongs to one workspace, and a key from one workspace can never act\n  on another.\n- A key can be revoked, and can be given an expiry. Both take effect at once.\n- The dashboard lists keys by a prefix and the last four characters, so a\n  customer can tell them apart without us keeping the key.\n\n## Notes for the reviewer\n\n`api_keys` is `(id, workspace_id, name, secret, prefix, last4, scopes,\nrevoked_at, expires_at)`. `hashing` wraps argon2. Keys look like\n`cv_live_<32 random characters>`.\n","src/apiKeys.ts":'// Creating and verifying API keys.\nimport { randomBytes } from "node:crypto";\nimport { db } from "./db";\n\nconst PREFIX = "cv_live_";\n\nexport async function createKey(workspaceId: string, name: string, scopes: string[]) {\n  const key = PREFIX + randomBytes(24).toString("base64url");\n  await db.run(\n    "INSERT INTO api_keys (workspace_id, name, secret, prefix, last4, scopes) VALUES ($1, $2, $3, $4, $5, $6)",\n    [workspaceId, name, key, PREFIX, key.slice(-4), scopes],\n  );\n  return { key };\n}\n\nexport async function verify(presented: string, workspaceId: string, action: string) {\n  const rows = await db.all("SELECT id, workspace_id, secret, scopes, revoked_at FROM api_keys");\n  for (const row of rows) {\n    if (row.secret === presented) {\n      if (!row.scopes.includes(action) && !row.scopes.includes("*")) throw new Forbidden("out of scope");\n      return { keyId: row.id, workspaceId: row.workspace_id };\n    }\n  }\n  throw new Unauthorized("unknown key");\n}\n\nexport async function listKeys(workspaceId: string) {\n  return db.all("SELECT id, name, prefix, last4, secret, scopes, revoked_at FROM api_keys WHERE workspace_id = $1", [\n    workspaceId,\n  ]);\n}\n'}}}},{slug:"feature-flags",title:"Feature flags",difficulty:"Medium",area:"backend",domains:["saas","devtools"],minutes:25,summary:"Twenty-five lines on the request path of every page. Five rules, and the first one is broken by a single return.",brief:["A teammate has opened this as a pull request. Every request in the product goes through this helper, including the ones that decide whether somebody sees a half-built feature.","Ask a flag that does not exist. Then reload the page twenty times on a 10% rollout. Then kill a flag and see how long it takes.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One or two things here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Feature flags\n\nFlags decide who sees what. This PR adds the evaluation helper every request\ngoes through.\n\n## Rules\n\n- A flag that does not exist is off. Unknown means off, never on.\n- A percentage rollout is sticky: the same user is on the same side of a 10%\n  rollout on every request, and moving from 10% to 20% never takes anyone off.\n- A flag can be killed. A kill takes effect everywhere within a minute.\n- Evaluating a flag does not touch the database on the request path.\n- Which flags a user saw is worth recording, once per user per day, not per\n  request.\n\n## Notes for the reviewer\n\n`flags` is `(key, enabled, percent, killed)`. `cache` is a process-local\ndictionary. `analytics.track` is a network call.\n","src/Flags.java":'package platform;\n\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.Random;\n\n/** Flag evaluation. */\npublic final class Flags {\n    private static final Map<String, Map<String, Object>> CACHE = new HashMap<>();\n    private static final Random RANDOM = new Random();\n\n    public static Map<String, Object> loadFlag(String key) {\n        if (CACHE.containsKey(key)) {\n            return CACHE.get(key);\n        }\n        Map<String, Object> flag = Db.one("SELECT key, enabled, percent, killed FROM flags WHERE key = ?", key);\n        CACHE.put(key, flag);\n        return flag;\n    }\n\n    public static boolean isOn(String key, String userId) {\n        Map<String, Object> flag = loadFlag(key);\n        if (flag == null) {\n            return true;\n        }\n\n        Analytics.track(userId, "flag_evaluated", Map.of("flag", key));\n\n        if (!(boolean) flag.get("enabled")) {\n            return false;\n        }\n        if ((int) flag.get("percent") >= 100) {\n            return true;\n        }\n        return RANDOM.nextInt(100) + 1 <= (int) flag.get("percent");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Feature flags\n\nFlags decide who sees what. This PR adds the evaluation helper every request\ngoes through.\n\n## Rules\n\n- A flag that does not exist is off. Unknown means off, never on.\n- A percentage rollout is sticky: the same user is on the same side of a 10%\n  rollout on every request, and moving from 10% to 20% never takes anyone off.\n- A flag can be killed. A kill takes effect everywhere within a minute.\n- Evaluating a flag does not touch the database on the request path.\n- Which flags a user saw is worth recording, once per user per day, not per\n  request.\n\n## Notes for the reviewer\n\n`flags` is `(key, enabled, percent, killed)`. `cache` is a process-local\ndictionary. `analytics.track` is a network call.\n","src/flags.py":'"""Flag evaluation."""\nimport random\n\nimport analytics\nimport db\n\ncache = {}\n\n\ndef load_flag(key):\n    if key in cache:\n        return cache[key]\n    flag = db.one("SELECT key, enabled, percent, killed FROM flags WHERE key = %s", (key,))\n    cache[key] = flag\n    return flag\n\n\ndef is_on(key, user_id):\n    flag = load_flag(key)\n    if flag is None:\n        return True\n\n    analytics.track(user_id, "flag_evaluated", {"flag": key})\n\n    if not flag["enabled"]:\n        return False\n    if flag["percent"] >= 100:\n        return True\n    return random.randint(1, 100) <= flag["percent"]\n'}},typescript:{entry:"README.md",files:{"README.md":"# Feature flags\n\nFlags decide who sees what. This PR adds the evaluation helper every request\ngoes through.\n\n## Rules\n\n- A flag that does not exist is off. Unknown means off, never on.\n- A percentage rollout is sticky: the same user is on the same side of a 10%\n  rollout on every request, and moving from 10% to 20% never takes anyone off.\n- A flag can be killed. A kill takes effect everywhere within a minute.\n- Evaluating a flag does not touch the database on the request path.\n- Which flags a user saw is worth recording, once per user per day, not per\n  request.\n\n## Notes for the reviewer\n\n`flags` is `(key, enabled, percent, killed)`. `cache` is a process-local\ndictionary. `analytics.track` is a network call.\n","src/flags.ts":'// Flag evaluation.\nimport * as analytics from "./analytics";\nimport { db } from "./db";\n\nconst cache = new Map<string, Flag | null>();\n\ntype Flag = { key: string; enabled: boolean; percent: number; killed: boolean };\n\nexport async function loadFlag(key: string) {\n  if (cache.has(key)) return cache.get(key) ?? null;\n  const flag = await db.one("SELECT key, enabled, percent, killed FROM flags WHERE key = $1", [key]);\n  cache.set(key, flag);\n  return flag;\n}\n\nexport async function isOn(key: string, userId: string) {\n  const flag = await loadFlag(key);\n  if (!flag) return true;\n\n  await analytics.track(userId, "flag_evaluated", { flag: key });\n\n  if (!flag.enabled) return false;\n  if (flag.percent >= 100) return true;\n  return Math.floor(Math.random() * 100) + 1 <= flag.percent;\n}\n'}}}},{slug:"cron-runner",title:"The job runner",difficulty:"Medium",area:"concurrency",domains:["devtools","scheduling"],minutes:25,summary:"Twenty lines that every instance runs at the same second. Count how many machines are in the fleet, then read the loop again.",brief:["A teammate has opened this as a pull request. Every instance wakes on the same minute boundary, so read this as several copies running at once.","Run it on four instances. Then make one job take nine minutes. Then take the fleet down for a day and bring it back.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something in here looks wrong and is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The job runner\n\nJobs are declared with a schedule and run by this loop, which every instance\nruns. This PR is the loop.\n\n## Rules\n\n- A job runs once per due time, however many instances are awake.\n- A run that is still going when the next one is due does not start a second\n  run of that job.\n- Schedules are wall-clock times in Asia/Kolkata. A job at 02:30 runs once on\n  the day the clocks move, not twice and not never.\n- A job that fails is recorded and retried at its next due time. One failing\n  job does not stop the others.\n- If the fleet was down over a due time, the run is caught up once, not once\n  per missed slot.\n\n## Notes for the reviewer\n\n`jobs` is `(name, schedule, last_run_at, running, last_error)`. `due_at`\nparses the schedule. The loop wakes every minute on every instance.\n","src/Runner.java":'package platform;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n/** The one-minute job loop. */\npublic final class Runner {\n\n    public static int tick(Instant now) {\n        int ran = 0;\n        List<Map<String, Object>> jobs = Db.all("SELECT name, schedule, last_run_at, running FROM jobs");\n        for (Map<String, Object> job : jobs) {\n            Instant due = Schedule.dueAt((String) job.get("schedule"), now);\n            Instant lastRun = (Instant) job.get("last_run_at");\n            if (lastRun != null && !lastRun.isBefore(due)) {\n                continue;\n            }\n\n            Db.run("UPDATE jobs SET running = true WHERE name = ?", job.get("name"));\n            Registry.JOBS.get(job.get("name")).run();\n            Db.run("UPDATE jobs SET running = false, last_run_at = ? WHERE name = ?", now, job.get("name"));\n            ran++;\n        }\n        return ran;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The job runner\n\nJobs are declared with a schedule and run by this loop, which every instance\nruns. This PR is the loop.\n\n## Rules\n\n- A job runs once per due time, however many instances are awake.\n- A run that is still going when the next one is due does not start a second\n  run of that job.\n- Schedules are wall-clock times in Asia/Kolkata. A job at 02:30 runs once on\n  the day the clocks move, not twice and not never.\n- A job that fails is recorded and retried at its next due time. One failing\n  job does not stop the others.\n- If the fleet was down over a due time, the run is caught up once, not once\n  per missed slot.\n\n## Notes for the reviewer\n\n`jobs` is `(name, schedule, last_run_at, running, last_error)`. `due_at`\nparses the schedule. The loop wakes every minute on every instance.\n","src/runner.py":'"""The one-minute job loop."""\nfrom datetime import datetime, timezone\n\nimport db\nfrom registry import JOBS\nfrom schedule import due_at\n\n\ndef tick(now=None):\n    now = now or datetime.now(timezone.utc)\n    ran = 0\n    jobs = db.all("SELECT name, schedule, last_run_at, running FROM jobs")\n    for job in jobs:\n        due = due_at(job["schedule"], now)\n        if job["last_run_at"] is not None and job["last_run_at"] >= due:\n            continue\n\n        db.run("UPDATE jobs SET running = true WHERE name = %s", (job["name"],))\n        JOBS[job["name"]]()\n        db.run(\n            "UPDATE jobs SET running = false, last_run_at = %s WHERE name = %s",\n            (now, job["name"]),\n        )\n        ran += 1\n    return {"ran": ran}\n'}},typescript:{entry:"README.md",files:{"README.md":"# The job runner\n\nJobs are declared with a schedule and run by this loop, which every instance\nruns. This PR is the loop.\n\n## Rules\n\n- A job runs once per due time, however many instances are awake.\n- A run that is still going when the next one is due does not start a second\n  run of that job.\n- Schedules are wall-clock times in Asia/Kolkata. A job at 02:30 runs once on\n  the day the clocks move, not twice and not never.\n- A job that fails is recorded and retried at its next due time. One failing\n  job does not stop the others.\n- If the fleet was down over a due time, the run is caught up once, not once\n  per missed slot.\n\n## Notes for the reviewer\n\n`jobs` is `(name, schedule, last_run_at, running, last_error)`. `due_at`\nparses the schedule. The loop wakes every minute on every instance.\n","src/runner.ts":'// The one-minute job loop.\nimport { db } from "./db";\nimport { JOBS } from "./registry";\nimport { dueAt } from "./schedule";\n\nexport async function tick(now = new Date()) {\n  let ran = 0;\n  const jobs = await db.all("SELECT name, schedule, last_run_at, running FROM jobs");\n  for (const job of jobs) {\n    const due = dueAt(job.schedule, now);\n    if (job.last_run_at !== null && new Date(job.last_run_at) >= due) continue;\n\n    await db.run("UPDATE jobs SET running = true WHERE name = $1", [job.name]);\n    await JOBS[job.name]();\n    await db.run("UPDATE jobs SET running = false, last_run_at = $1 WHERE name = $2", [now, job.name]);\n    ran += 1;\n  }\n  return { ran };\n}\n'}}}},{slug:"event-pipeline",title:"Event ingestion",difficulty:"Medium",area:"data",domains:["analytics"],minutes:25,summary:"The endpoint every app in the company writes to. Fifteen lines, five rules, and the number it returns is not the number it wrote.",brief:["A teammate has opened this as a pull request. Everything downstream, every dashboard and every rollup, is built on what this writes.","Retry a batch. Then send one from a phone whose clock says 2043. Then let the fifth insert in a batch of ten fail.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Event ingestion\n\nThe apps send batches of product events to `POST /events`. This PR takes them\nand writes them down.\n\n## Rules\n\n- A batch is accepted whole or not at all. A client that retries a batch it\n  already sent does not create the events twice.\n- The time an event happened comes from the client; the time we received it\n  comes from us, and both are stored.\n- A clock on a phone can be wrong. An event dated far in the future or long\n  before the app existed is clamped and marked, not stored as sent.\n- Events carry properties the product teams choose. Nothing that identifies a\n  person goes in them, and the endpoint rejects the known keys.\n- The response is the count accepted. A partial write is never reported as\n  accepted.\n\n## Notes for the reviewer\n\n`events` is `(id, name, user_id, at, received_at, props)`. `event_id` is a\nclient-generated uuid, unique per event. There is no unique index on it yet.\n","src/Ingest.java":'package analytics;\n\nimport java.time.Instant;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\n/** POST /events */\npublic final class Ingest {\n    private static final Set<String> BANNED_PROPS = Set.of("email", "phone", "password", "address");\n\n    public record Event(String eventId, String name, String at, Map<String, Object> props) {}\n\n    public static int ingest(String userId, List<Event> batch) {\n        int accepted = 0;\n        for (Event event : batch) {\n            Instant at = LocalDateTime.parse(event.at(), DateTimeFormatter.ISO_DATE_TIME).toInstant(ZoneOffset.UTC);\n            Db.run("INSERT INTO events (id, name, user_id, at, received_at, props) VALUES (?, ?, ?, ?, ?, ?)",\n                    event.eventId(), event.name(), userId, at, Instant.now(), event.props());\n            accepted++;\n        }\n        return batch.size();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Event ingestion\n\nThe apps send batches of product events to `POST /events`. This PR takes them\nand writes them down.\n\n## Rules\n\n- A batch is accepted whole or not at all. A client that retries a batch it\n  already sent does not create the events twice.\n- The time an event happened comes from the client; the time we received it\n  comes from us, and both are stored.\n- A clock on a phone can be wrong. An event dated far in the future or long\n  before the app existed is clamped and marked, not stored as sent.\n- Events carry properties the product teams choose. Nothing that identifies a\n  person goes in them, and the endpoint rejects the known keys.\n- The response is the count accepted. A partial write is never reported as\n  accepted.\n\n## Notes for the reviewer\n\n`events` is `(id, name, user_id, at, received_at, props)`. `event_id` is a\nclient-generated uuid, unique per event. There is no unique index on it yet.\n","src/ingest.py":'"""POST /events"""\nimport json\nfrom datetime import datetime, timezone\n\nimport db\n\nBANNED_PROPS = {"email", "phone", "password", "address"}\n\n\ndef ingest(user_id, batch):\n    accepted = 0\n    for event in batch:\n        at = datetime.fromisoformat(event["at"])\n        db.run(\n            "INSERT INTO events (id, name, user_id, at, received_at, props) VALUES (%s, %s, %s, %s, %s, %s)",\n            (\n                event["event_id"],\n                event["name"],\n                user_id,\n                at,\n                datetime.now(timezone.utc),\n                json.dumps(event.get("props", {})),\n            ),\n        )\n        accepted += 1\n    return {"accepted": len(batch)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Event ingestion\n\nThe apps send batches of product events to `POST /events`. This PR takes them\nand writes them down.\n\n## Rules\n\n- A batch is accepted whole or not at all. A client that retries a batch it\n  already sent does not create the events twice.\n- The time an event happened comes from the client; the time we received it\n  comes from us, and both are stored.\n- A clock on a phone can be wrong. An event dated far in the future or long\n  before the app existed is clamped and marked, not stored as sent.\n- Events carry properties the product teams choose. Nothing that identifies a\n  person goes in them, and the endpoint rejects the known keys.\n- The response is the count accepted. A partial write is never reported as\n  accepted.\n\n## Notes for the reviewer\n\n`events` is `(id, name, user_id, at, received_at, props)`. `event_id` is a\nclient-generated uuid, unique per event. There is no unique index on it yet.\n","src/ingest.ts":'// POST /events\nimport { db } from "./db";\n\nconst BANNED_PROPS = new Set(["email", "phone", "password", "address"]);\n\ntype Event = { event_id: string; name: string; at: string; props?: Record<string, unknown> };\n\nexport async function ingest(userId: string, batch: Event[]) {\n  let accepted = 0;\n  for (const event of batch) {\n    const at = new Date(event.at);\n    await db.run(\n      "INSERT INTO events (id, name, user_id, at, received_at, props) VALUES ($1, $2, $3, $4, $5, $6)",\n      [event.event_id, event.name, userId, at, new Date(), JSON.stringify(event.props ?? {})],\n    );\n    accepted += 1;\n  }\n  return { accepted: batch.length };\n}\n'}}}},{slug:"funnel-report",title:"The signup funnel",difficulty:"Medium",area:"data",domains:["analytics"],minutes:25,summary:"Twenty lines that produce the number in next week’s board deck. The first rule says it counts people, and the query counts something else.",brief:["A teammate has opened this as a pull request. Somebody will make a decision on this number, so check what it is actually counting.","Take a visitor who reloaded the pricing page four times, and a customer who bought in March and signed up in April.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The signup funnel\n\nProduct asks the same question every week: of the people who landed, how many\nsigned up, and how many bought. This PR answers it.\n\n## Rules\n\n- A funnel counts people, not events. Somebody who views the pricing page four\n  times is one person at that step.\n- A step counts only for people who completed the step before it, and only\n  after they completed it. Buying on Monday and signing up on Tuesday is not a\n  conversion.\n- A day is a day in Asia/Kolkata.\n- The rate at each step is against the step before it, and the first step is\n  100%. A funnel with nobody in it is reported as empty, not as an error.\n- The window is inclusive of both dates the caller gives.\n\n## Notes for the reviewer\n\n`events` is `(user_id, name, at)` and is large. The steps come in as a list of\nevent names, in order.\n","src/Funnel.java":'package analytics;\n\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** The signup funnel. */\npublic final class Funnel {\n\n    public record Step(String step, long people, double rate) {}\n\n    public static List<Step> funnel(List<String> steps, LocalDate startDate, LocalDate endDate) {\n        List<Long> counts = new ArrayList<>();\n        for (String name : steps) {\n            Map<String, Object> row = Db.one("SELECT count(*) AS n FROM events "\n                    + "WHERE name = ? AND at >= ? AND at < ?", name, startDate, endDate);\n            counts.add((long) row.get("n"));\n        }\n\n        List<Step> out = new ArrayList<>();\n        for (int i = 0; i < steps.size(); i++) {\n            double rate = i > 0 ? (double) counts.get(i) / counts.get(i - 1) * 100 : 100;\n            out.add(new Step(steps.get(i), counts.get(i), Math.round(rate * 10) / 10.0));\n        }\n        return out;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The signup funnel\n\nProduct asks the same question every week: of the people who landed, how many\nsigned up, and how many bought. This PR answers it.\n\n## Rules\n\n- A funnel counts people, not events. Somebody who views the pricing page four\n  times is one person at that step.\n- A step counts only for people who completed the step before it, and only\n  after they completed it. Buying on Monday and signing up on Tuesday is not a\n  conversion.\n- A day is a day in Asia/Kolkata.\n- The rate at each step is against the step before it, and the first step is\n  100%. A funnel with nobody in it is reported as empty, not as an error.\n- The window is inclusive of both dates the caller gives.\n\n## Notes for the reviewer\n\n`events` is `(user_id, name, at)` and is large. The steps come in as a list of\nevent names, in order.\n","src/funnel.py":'"""The signup funnel."""\nimport db\n\n\ndef funnel(steps, start_date, end_date):\n    counts = []\n    for name in steps:\n        row = db.one(\n            "SELECT count(*) AS n FROM events "\n            "WHERE name = %s AND at >= %s AND at < %s",\n            (name, start_date, end_date),\n        )\n        counts.append(row["n"])\n\n    out = []\n    for i, name in enumerate(steps):\n        rate = counts[i] / counts[i - 1] * 100 if i > 0 else 100\n        out.append({"step": name, "people": counts[i], "rate": round(rate, 1)})\n    return {"steps": out, "total": counts[0]}\n'}},typescript:{entry:"README.md",files:{"README.md":"# The signup funnel\n\nProduct asks the same question every week: of the people who landed, how many\nsigned up, and how many bought. This PR answers it.\n\n## Rules\n\n- A funnel counts people, not events. Somebody who views the pricing page four\n  times is one person at that step.\n- A step counts only for people who completed the step before it, and only\n  after they completed it. Buying on Monday and signing up on Tuesday is not a\n  conversion.\n- A day is a day in Asia/Kolkata.\n- The rate at each step is against the step before it, and the first step is\n  100%. A funnel with nobody in it is reported as empty, not as an error.\n- The window is inclusive of both dates the caller gives.\n\n## Notes for the reviewer\n\n`events` is `(user_id, name, at)` and is large. The steps come in as a list of\nevent names, in order.\n","src/funnel.ts":'// The signup funnel.\nimport { db } from "./db";\n\nexport async function funnel(steps: string[], startDate: string, endDate: string) {\n  const counts: number[] = [];\n  for (const name of steps) {\n    const row = await db.one("SELECT count(*) AS n FROM events WHERE name = $1 AND at >= $2 AND at < $3", [\n      name,\n      startDate,\n      endDate,\n    ]);\n    counts.push(Number(row.n));\n  }\n\n  const out = steps.map((name, i) => {\n    const rate = i > 0 ? (counts[i] / counts[i - 1]) * 100 : 100;\n    return { step: name, people: counts[i], rate: Math.round(rate * 10) / 10 };\n  });\n  return { steps: out, total: counts[0] };\n}\n'}}}},{slug:"notification-prefs",title:"Notification preferences",difficulty:"Medium",area:"backend",domains:["messaging","saas"],minutes:25,summary:"Twenty lines every sender calls before it sends. Two of them decide whether an unsubscribe means anything and whether a password reset arrives.",brief:["A teammate has opened this as a pull request. Getting this wrong means either spamming people who asked you to stop, or swallowing the mail somebody needs to get back into their account.","Ask for a type that does not exist. Then unsubscribe from marketing and try to reset your password. Then turn off SMS entirely.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One or two things here are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Notification preferences\n\nPeople choose what we send them and where. This PR is the check every sender\ncalls before it sends anything.\n\n## Rules\n\n- A preference that has never been set falls back to the default for that\n  type. A type nobody knows is not sent.\n- Transactional mail (a receipt, a password reset, a security alert) is always\n  sent. Preferences and unsubscribes apply to the rest.\n- Unsubscribing from a marketing mail unsubscribes from marketing, not from\n  every type we have.\n- A person can turn off a channel entirely. That beats any per-type setting.\n- The check is called on the send path for every recipient, so it does not go\n  to the database per recipient.\n\n## Notes for the reviewer\n\n`prefs` is `(user_id, type, channel, enabled)` with a row only for the choices\nsomeone actually made. `TYPES` is the catalogue, each with `transactional` and\na default per channel.\n","src/Prefs.java":'package messaging;\n\nimport java.util.Map;\n\n/** May we send this? */\npublic final class Prefs {\n\n    public static boolean shouldSend(String userId, String typeName, String channel) {\n        Catalogue.Type kind = Catalogue.TYPES.get(typeName);\n        if (kind == null) {\n            return true;\n        }\n\n        Map<String, Object> user =\n                Db.one("SELECT id, unsubscribed_all, channels_off FROM users WHERE id = ?", userId);\n        if ((boolean) user.get("unsubscribed_all")) {\n            return false;\n        }\n\n        Map<String, Object> row = Db.one("SELECT enabled FROM prefs WHERE user_id = ? AND type = ? AND channel = ?",\n                userId, typeName, channel);\n        if (row != null) {\n            return (boolean) row.get("enabled");\n        }\n        return kind.defaults().getOrDefault(channel, true);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Notification preferences\n\nPeople choose what we send them and where. This PR is the check every sender\ncalls before it sends anything.\n\n## Rules\n\n- A preference that has never been set falls back to the default for that\n  type. A type nobody knows is not sent.\n- Transactional mail (a receipt, a password reset, a security alert) is always\n  sent. Preferences and unsubscribes apply to the rest.\n- Unsubscribing from a marketing mail unsubscribes from marketing, not from\n  every type we have.\n- A person can turn off a channel entirely. That beats any per-type setting.\n- The check is called on the send path for every recipient, so it does not go\n  to the database per recipient.\n\n## Notes for the reviewer\n\n`prefs` is `(user_id, type, channel, enabled)` with a row only for the choices\nsomeone actually made. `TYPES` is the catalogue, each with `transactional` and\na default per channel.\n","src/prefs.py":'"""May we send this?"""\nimport db\nfrom catalogue import TYPES\n\n\ndef should_send(user_id, type_name, channel):\n    kind = TYPES.get(type_name)\n    if kind is None:\n        return True\n\n    user = db.one("SELECT id, unsubscribed_all, channels_off FROM users WHERE id = %s", (user_id,))\n    if user["unsubscribed_all"]:\n        return False\n\n    row = db.one(\n        "SELECT enabled FROM prefs WHERE user_id = %s AND type = %s AND channel = %s",\n        (user_id, type_name, channel),\n    )\n    if row is not None:\n        return row["enabled"]\n    return kind.defaults.get(channel, True)\n'}},typescript:{entry:"README.md",files:{"README.md":"# Notification preferences\n\nPeople choose what we send them and where. This PR is the check every sender\ncalls before it sends anything.\n\n## Rules\n\n- A preference that has never been set falls back to the default for that\n  type. A type nobody knows is not sent.\n- Transactional mail (a receipt, a password reset, a security alert) is always\n  sent. Preferences and unsubscribes apply to the rest.\n- Unsubscribing from a marketing mail unsubscribes from marketing, not from\n  every type we have.\n- A person can turn off a channel entirely. That beats any per-type setting.\n- The check is called on the send path for every recipient, so it does not go\n  to the database per recipient.\n\n## Notes for the reviewer\n\n`prefs` is `(user_id, type, channel, enabled)` with a row only for the choices\nsomeone actually made. `TYPES` is the catalogue, each with `transactional` and\na default per channel.\n","src/prefs.ts":'// May we send this?\nimport { TYPES } from "./catalogue";\nimport { db } from "./db";\n\nexport async function shouldSend(userId: string, typeName: string, channel: string) {\n  const kind = TYPES[typeName];\n  if (!kind) return true;\n\n  const user = await db.one("SELECT id, unsubscribed_all, channels_off FROM users WHERE id = $1", [userId]);\n  if (user.unsubscribed_all) return false;\n\n  const row = await db.one("SELECT enabled FROM prefs WHERE user_id = $1 AND type = $2 AND channel = $3", [\n    userId,\n    typeName,\n    channel,\n  ]);\n  if (row) return row.enabled;\n  return kind.defaults[channel] ?? true;\n}\n'}}}},{slug:"email-template",title:"Rendering an email",difficulty:"Medium",area:"security",domains:["messaging"],minutes:25,summary:"A template, some values a user typed, and a string substitution between them. Ask what a display name is allowed to contain.",brief:["A teammate has opened this as a pull request. The values here come from things people type, and the output goes into somebody else’s inbox.","Set your display name to a piece of HTML. Then to a line with a newline and a Bcc header in it. Then send a template whose value nobody supplied.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","One thing here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Rendering an email\n\nTemplates are written by the marketing team in the admin, and filled with\nvalues from the application. This PR renders one and hands it to the sender.\n\n## Rules\n\n- Anything that came from a person is escaped before it goes into the HTML.\n- A template asking for a value nobody supplied is an error, not an email with\n  a blank in it.\n- The subject is one line. A value with a newline in it may not add headers.\n- The plain-text part is built from the same values, so it never says\n  something different from the HTML.\n- An unsubscribe link goes in every non-transactional email.\n\n## Notes for the reviewer\n\n`templates` rows carry `subject`, `html` and `text`, with `{{name}}` style\nplaceholders. `values` comes from the caller and can hold anything a user\ntyped: a display name, an order note, a workspace name.\n","src/Render.java":'package messaging;\n\nimport java.util.Map;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\n/** Rendering an email from a template. */\npublic final class Render {\n    private static final Pattern PLACEHOLDER = Pattern.compile("\\\\{\\\\{(\\\\w+)\\\\}\\\\}");\n\n    public record Email(String subject, String html, String text) {}\n\n    public static String fill(String text, Map<String, String> values) {\n        Matcher m = PLACEHOLDER.matcher(text);\n        StringBuilder out = new StringBuilder();\n        while (m.find()) {\n            m.appendReplacement(out, Matcher.quoteReplacement(values.getOrDefault(m.group(1), "")));\n        }\n        m.appendTail(out);\n        return out.toString();\n    }\n\n    public static Email render(String templateName, Map<String, String> values, boolean transactional) {\n        Map<String, Object> template =\n                Db.one("SELECT subject, html, text FROM templates WHERE name = ?", templateName);\n        String subject = fill((String) template.get("subject"), values);\n        String html = fill((String) template.get("html"), values);\n        String text = fill((String) template.get("text"), values);\n\n        if (!transactional) {\n            html = html + "<p><a href=\\"" + values.get("unsubscribe_url") + "\\">Unsubscribe</a></p>";\n        }\n\n        return new Email(subject, html, text);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Rendering an email\n\nTemplates are written by the marketing team in the admin, and filled with\nvalues from the application. This PR renders one and hands it to the sender.\n\n## Rules\n\n- Anything that came from a person is escaped before it goes into the HTML.\n- A template asking for a value nobody supplied is an error, not an email with\n  a blank in it.\n- The subject is one line. A value with a newline in it may not add headers.\n- The plain-text part is built from the same values, so it never says\n  something different from the HTML.\n- An unsubscribe link goes in every non-transactional email.\n\n## Notes for the reviewer\n\n`templates` rows carry `subject`, `html` and `text`, with `{{name}}` style\nplaceholders. `values` comes from the caller and can hold anything a user\ntyped: a display name, an order note, a workspace name.\n","src/render.py":'"""Rendering an email from a template."""\nimport re\n\nimport db\n\nPLACEHOLDER = re.compile(r"\\{\\{(\\w+)\\}\\}")\n\n\ndef fill(text, values):\n    return PLACEHOLDER.sub(lambda m: str(values.get(m.group(1), "")), text)\n\n\ndef render(template_name, values, transactional=False):\n    template = db.one("SELECT subject, html, text FROM templates WHERE name = %s", (template_name,))\n    subject = fill(template["subject"], values)\n    html = fill(template["html"], values)\n    text = fill(template["text"], values)\n\n    if not transactional:\n        html = html + f\'<p><a href="{values["unsubscribe_url"]}">Unsubscribe</a></p>\'\n\n    return {"subject": subject, "html": html, "text": text}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Rendering an email\n\nTemplates are written by the marketing team in the admin, and filled with\nvalues from the application. This PR renders one and hands it to the sender.\n\n## Rules\n\n- Anything that came from a person is escaped before it goes into the HTML.\n- A template asking for a value nobody supplied is an error, not an email with\n  a blank in it.\n- The subject is one line. A value with a newline in it may not add headers.\n- The plain-text part is built from the same values, so it never says\n  something different from the HTML.\n- An unsubscribe link goes in every non-transactional email.\n\n## Notes for the reviewer\n\n`templates` rows carry `subject`, `html` and `text`, with `{{name}}` style\nplaceholders. `values` comes from the caller and can hold anything a user\ntyped: a display name, an order note, a workspace name.\n","src/render.ts":'// Rendering an email from a template.\nimport { db } from "./db";\n\nconst PLACEHOLDER = /\\{\\{(\\w+)\\}\\}/g;\n\nexport function fill(text: string, values: Record<string, string>) {\n  return text.replace(PLACEHOLDER, (_, key) => String(values[key] ?? ""));\n}\n\nexport async function render(templateName: string, values: Record<string, string>, transactional = false) {\n  const template = await db.one("SELECT subject, html, text FROM templates WHERE name = $1", [templateName]);\n  const subject = fill(template.subject, values);\n  let html = fill(template.html, values);\n  const text = fill(template.text, values);\n\n  if (!transactional) {\n    html = html + `<p><a href="${values.unsubscribe_url}">Unsubscribe</a></p>`;\n  }\n\n  return { subject, html, text };\n}\n'}}}},{slug:"outgoing-webhooks",title:"Webhooks out to customers",difficulty:"Medium",area:"integrations",domains:["messaging","saas"],minutes:25,summary:"We call a URL the customer chose, from our network, on the request path, five times if it fails. Each half of that sentence is worth a comment.",brief:["A teammate has opened this as a pull request. The URL in this code is typed by a customer, and the request is made by our servers.","Register an endpoint pointing at 169.254.169.254, or at localhost. Then register one that takes thirty seconds to answer.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Webhooks out to customers\n\nCustomers register a URL and we call it when something happens in their\nworkspace. This PR is the delivery path.\n\n## Rules\n\n- A delivery is signed, so the customer can tell it came from us and has not\n  been changed.\n- Delivering a webhook never makes the request that caused it wait.\n- A customer URL is somewhere on the internet, not somewhere inside our\n  network. Private and loopback addresses are refused.\n- A failed delivery is retried with a growing gap, up to a day, and then the\n  endpoint is disabled and the customer told.\n- Every delivery carries an id, and the same event delivered twice carries the\n  same one.\n\n## Notes for the reviewer\n\n`endpoints` is `(workspace_id, url, secret, disabled_at)`. `deliveries` is the\nlog. `http.post` follows redirects by default.\n","src/Webhooks.java":'package messaging;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Delivering webhooks to customer endpoints. */\npublic final class Webhooks {\n    private static final int MAX_ATTEMPTS = 5;\n\n    public static int deliver(String workspaceId, Map<String, Object> event) throws InterruptedException {\n        List<Map<String, Object>> endpoints =\n                Db.all("SELECT url, secret FROM endpoints WHERE workspace_id = ?", workspaceId);\n        for (Map<String, Object> endpoint : endpoints) {\n            String payload = Json.encode(event);\n            for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n                Http.Response response = Http.post((String) endpoint.get("url"), payload,\n                        Map.of("Content-Type", "application/json"));\n                Db.run("INSERT INTO deliveries (workspace_id, url, status, at) VALUES (?, ?, ?, now())",\n                        workspaceId, endpoint.get("url"), response.status());\n                if (response.status() < 300) {\n                    break;\n                }\n                Thread.sleep(1000);\n            }\n        }\n        return endpoints.size();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Webhooks out to customers\n\nCustomers register a URL and we call it when something happens in their\nworkspace. This PR is the delivery path.\n\n## Rules\n\n- A delivery is signed, so the customer can tell it came from us and has not\n  been changed.\n- Delivering a webhook never makes the request that caused it wait.\n- A customer URL is somewhere on the internet, not somewhere inside our\n  network. Private and loopback addresses are refused.\n- A failed delivery is retried with a growing gap, up to a day, and then the\n  endpoint is disabled and the customer told.\n- Every delivery carries an id, and the same event delivered twice carries the\n  same one.\n\n## Notes for the reviewer\n\n`endpoints` is `(workspace_id, url, secret, disabled_at)`. `deliveries` is the\nlog. `http.post` follows redirects by default.\n","src/webhooks.py":'"""Delivering webhooks to customer endpoints."""\nimport json\nimport time\n\nimport db\nimport http\n\nMAX_ATTEMPTS = 5\n\n\ndef deliver(workspace_id, event):\n    endpoints = db.all("SELECT url, secret FROM endpoints WHERE workspace_id = %s", (workspace_id,))\n    for endpoint in endpoints:\n        payload = json.dumps(event)\n        for attempt in range(MAX_ATTEMPTS):\n            response = http.post(endpoint["url"], payload, headers={"Content-Type": "application/json"})\n            db.run(\n                "INSERT INTO deliveries (workspace_id, url, status, at) VALUES (%s, %s, %s, now())",\n                (workspace_id, endpoint["url"], response.status),\n            )\n            if response.status < 300:\n                break\n            time.sleep(1)\n    return {"delivered": len(endpoints)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Webhooks out to customers\n\nCustomers register a URL and we call it when something happens in their\nworkspace. This PR is the delivery path.\n\n## Rules\n\n- A delivery is signed, so the customer can tell it came from us and has not\n  been changed.\n- Delivering a webhook never makes the request that caused it wait.\n- A customer URL is somewhere on the internet, not somewhere inside our\n  network. Private and loopback addresses are refused.\n- A failed delivery is retried with a growing gap, up to a day, and then the\n  endpoint is disabled and the customer told.\n- Every delivery carries an id, and the same event delivered twice carries the\n  same one.\n\n## Notes for the reviewer\n\n`endpoints` is `(workspace_id, url, secret, disabled_at)`. `deliveries` is the\nlog. `http.post` follows redirects by default.\n","src/webhooks.ts":'// Delivering webhooks to customer endpoints.\nimport { db } from "./db";\nimport { http } from "./http";\n\nconst MAX_ATTEMPTS = 5;\n\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\nexport async function deliver(workspaceId: string, event: Record<string, unknown>) {\n  const endpoints = await db.all("SELECT url, secret FROM endpoints WHERE workspace_id = $1", [workspaceId]);\n  for (const endpoint of endpoints) {\n    const payload = JSON.stringify(event);\n    for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n      const response = await http.post(endpoint.url, payload, { "Content-Type": "application/json" });\n      await db.run("INSERT INTO deliveries (workspace_id, url, status, at) VALUES ($1, $2, $3, now())", [\n        workspaceId,\n        endpoint.url,\n        response.status,\n      ]);\n      if (response.status < 300) break;\n      await sleep(1000);\n    }\n  }\n  return { delivered: endpoints.length };\n}\n'}}}},{slug:"digest-mailer",title:"The weekly digest",difficulty:"Medium",area:"backend",domains:["messaging","analytics"],minutes:25,summary:"One loop, one query per user, one email per user. Five rules, and the loop keeps the ones about sending rather than the ones about not sending.",brief:["A teammate has opened this as a pull request. It runs once a week against every active user, and every mistake in it arrives in somebody’s inbox.","Run it for a workspace where nothing happened. Then let it crash halfway and run it again. Then run it for a user in Auckland.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The weekly digest\n\nOnce a week everyone gets a summary of what happened in their workspace. This\nPR is the job that sends it.\n\n## Rules\n\n- The digest is sent at 08:00 on Monday in the recipient’s own zone.\n- It covers the seven days before that, and an item appears in exactly one\n  digest.\n- Somebody with nothing to report is not sent an empty digest.\n- The job can be re-run after a failure. Nobody receives two digests for the\n  same week.\n- It reports how many were sent, and that number is what the mailer accepted.\n\n## Notes for the reviewer\n\n`users` carry `timezone`. `items` are the events of a workspace, with `at` in\nUTC. `mailer.send` raises on a permanent failure and returns an id otherwise.\n","src/Digest.java":'package messaging;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n/** The weekly digest job. */\npublic final class Digest {\n\n    public static int run(Instant now) {\n        Instant since = now.minus(Duration.ofDays(7));\n        List<Map<String, Object>> users =\n                Db.all("SELECT id, email, timezone, workspace_id FROM users WHERE active = true");\n        int sent = 0;\n        for (Map<String, Object> user : users) {\n            List<Map<String, Object>> items = Db.all(\n                    "SELECT id, kind, title, at FROM items WHERE workspace_id = ? AND at > ? ORDER BY at DESC",\n                    user.get("workspace_id"), since);\n            String body = Render.digest(user, items);\n            Mailer.send((String) user.get("email"), "Your week", body);\n            sent++;\n        }\n        return sent;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The weekly digest\n\nOnce a week everyone gets a summary of what happened in their workspace. This\nPR is the job that sends it.\n\n## Rules\n\n- The digest is sent at 08:00 on Monday in the recipient’s own zone.\n- It covers the seven days before that, and an item appears in exactly one\n  digest.\n- Somebody with nothing to report is not sent an empty digest.\n- The job can be re-run after a failure. Nobody receives two digests for the\n  same week.\n- It reports how many were sent, and that number is what the mailer accepted.\n\n## Notes for the reviewer\n\n`users` carry `timezone`. `items` are the events of a workspace, with `at` in\nUTC. `mailer.send` raises on a permanent failure and returns an id otherwise.\n","src/digest.py":'"""The weekly digest job."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\nimport mailer\nfrom render import render_digest\n\n\ndef run(now=None):\n    now = now or datetime.now(timezone.utc)\n    since = now - timedelta(days=7)\n    users = db.all("SELECT id, email, timezone, workspace_id FROM users WHERE active = true")\n    sent = 0\n    for user in users:\n        items = db.all(\n            "SELECT id, kind, title, at FROM items WHERE workspace_id = %s AND at > %s ORDER BY at DESC",\n            (user["workspace_id"], since),\n        )\n        body = render_digest(user, items)\n        mailer.send(user["email"], "Your week", body)\n        sent += 1\n    return {"sent": sent}\n'}},typescript:{entry:"README.md",files:{"README.md":"# The weekly digest\n\nOnce a week everyone gets a summary of what happened in their workspace. This\nPR is the job that sends it.\n\n## Rules\n\n- The digest is sent at 08:00 on Monday in the recipient’s own zone.\n- It covers the seven days before that, and an item appears in exactly one\n  digest.\n- Somebody with nothing to report is not sent an empty digest.\n- The job can be re-run after a failure. Nobody receives two digests for the\n  same week.\n- It reports how many were sent, and that number is what the mailer accepted.\n\n## Notes for the reviewer\n\n`users` carry `timezone`. `items` are the events of a workspace, with `at` in\nUTC. `mailer.send` raises on a permanent failure and returns an id otherwise.\n","src/digest.ts":'// The weekly digest job.\nimport { db } from "./db";\nimport * as mailer from "./mailer";\nimport { renderDigest } from "./render";\n\nconst WEEK_MS = 7 * 24 * 60 * 60 * 1000;\n\nexport async function run(now = new Date()) {\n  const since = new Date(now.getTime() - WEEK_MS);\n  const users = await db.all("SELECT id, email, timezone, workspace_id FROM users WHERE active = true");\n  let sent = 0;\n  for (const user of users) {\n    const items = await db.all(\n      "SELECT id, kind, title, at FROM items WHERE workspace_id = $1 AND at > $2 ORDER BY at DESC",\n      [user.workspace_id, since],\n    );\n    const body = renderDigest(user, items);\n    await mailer.send(user.email, "Your week", body);\n    sent += 1;\n  }\n  return { sent };\n}\n'}}}},{slug:"sla-timer",title:"Support SLA timers",difficulty:"Medium",area:"time",domains:["scheduling","saas"],minutes:25,summary:"Four working hours, a clock that stops, and a number that decides whether a customer gets money back. The helper at the top is where to start.",brief:["A teammate has opened this as a pull request. This number goes in a report a customer reads and sometimes claims against.","Open a ticket at 17:30 on Friday and answer it at 09:30 on Monday. Then open one on a public holiday. Then look at one nobody has answered yet.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Support SLA timers\n\nEvery ticket has a promise attached: first reply within four working hours.\nThis PR works out whether we kept it.\n\n## Rules\n\n- The clock runs during business hours only, 09:00 to 18:00 Monday to Friday\n  in the customer’s zone, and not on a holiday.\n- The clock stops while we are waiting for the customer, and starts again when\n  they reply.\n- A ticket answered exactly on the deadline is within the SLA.\n- Reopening a ticket does not reset the first-reply clock. It was either met\n  or it was not.\n- A ticket with no reply yet reports the time used so far, not a breach, until\n  the deadline passes.\n\n## Notes for the reviewer\n\n`tickets` carry `opened_at`, `first_reply_at`, `zone` and `status`.\n`pauses` is `(ticket_id, from_at, to_at)`, one row per wait on the customer.\n`holidays` is a table of dates per region.\n","src/Sla.java":'package scheduling;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n/** Working out whether the first-reply SLA was met. */\npublic final class Sla {\n    private static final long TARGET_SECONDS = 4 * 3600;\n    private static final int WORK_HOURS_PER_DAY = 9;\n\n    public record Result(long usedSeconds, boolean breached) {}\n\n    public static long workingSeconds(Instant start, Instant end) {\n        Duration elapsed = Duration.between(start, end);\n        long days = elapsed.toDays();\n        long remainder = elapsed.minusDays(days).getSeconds();\n        return days * WORK_HOURS_PER_DAY * 3600 + remainder;\n    }\n\n    public static Result firstReplySla(String ticketId) {\n        Map<String, Object> ticket =\n                Db.one("SELECT id, opened_at, first_reply_at, zone, status FROM tickets WHERE id = ?", ticketId);\n        List<Map<String, Object>> pauses = Db.all("SELECT from_at, to_at FROM pauses WHERE ticket_id = ?", ticketId);\n\n        long used = workingSeconds((Instant) ticket.get("opened_at"), (Instant) ticket.get("first_reply_at"));\n        for (Map<String, Object> pause : pauses) {\n            used -= Duration.between((Instant) pause.get("from_at"), (Instant) pause.get("to_at")).getSeconds();\n        }\n\n        return new Result(used, used > TARGET_SECONDS);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Support SLA timers\n\nEvery ticket has a promise attached: first reply within four working hours.\nThis PR works out whether we kept it.\n\n## Rules\n\n- The clock runs during business hours only, 09:00 to 18:00 Monday to Friday\n  in the customer’s zone, and not on a holiday.\n- The clock stops while we are waiting for the customer, and starts again when\n  they reply.\n- A ticket answered exactly on the deadline is within the SLA.\n- Reopening a ticket does not reset the first-reply clock. It was either met\n  or it was not.\n- A ticket with no reply yet reports the time used so far, not a breach, until\n  the deadline passes.\n\n## Notes for the reviewer\n\n`tickets` carry `opened_at`, `first_reply_at`, `zone` and `status`.\n`pauses` is `(ticket_id, from_at, to_at)`, one row per wait on the customer.\n`holidays` is a table of dates per region.\n","src/sla.py":'"""Working out whether the first-reply SLA was met."""\nfrom datetime import timedelta\n\nimport db\n\nTARGET = timedelta(hours=4)\nWORK_HOURS_PER_DAY = 9\n\n\ndef working_seconds(start, end):\n    days = (end - start).days\n    remainder = (end - start).seconds\n    return days * WORK_HOURS_PER_DAY * 3600 + remainder\n\n\ndef first_reply_sla(ticket_id):\n    ticket = db.one(\n        "SELECT id, opened_at, first_reply_at, zone, status FROM tickets WHERE id = %s",\n        (ticket_id,),\n    )\n    pauses = db.all("SELECT from_at, to_at FROM pauses WHERE ticket_id = %s", (ticket_id,))\n\n    used = working_seconds(ticket["opened_at"], ticket["first_reply_at"])\n    for pause in pauses:\n        used -= (pause["to_at"] - pause["from_at"]).total_seconds()\n\n    return {"used_seconds": used, "breached": used > TARGET.total_seconds()}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Support SLA timers\n\nEvery ticket has a promise attached: first reply within four working hours.\nThis PR works out whether we kept it.\n\n## Rules\n\n- The clock runs during business hours only, 09:00 to 18:00 Monday to Friday\n  in the customer’s zone, and not on a holiday.\n- The clock stops while we are waiting for the customer, and starts again when\n  they reply.\n- A ticket answered exactly on the deadline is within the SLA.\n- Reopening a ticket does not reset the first-reply clock. It was either met\n  or it was not.\n- A ticket with no reply yet reports the time used so far, not a breach, until\n  the deadline passes.\n\n## Notes for the reviewer\n\n`tickets` carry `opened_at`, `first_reply_at`, `zone` and `status`.\n`pauses` is `(ticket_id, from_at, to_at)`, one row per wait on the customer.\n`holidays` is a table of dates per region.\n","src/sla.ts":'// Working out whether the first-reply SLA was met.\nimport { db } from "./db";\n\nconst TARGET_SECONDS = 4 * 3600;\nconst WORK_HOURS_PER_DAY = 9;\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport function workingSeconds(start: Date, end: Date) {\n  const elapsed = end.getTime() - start.getTime();\n  const days = Math.floor(elapsed / DAY_MS);\n  const remainder = (elapsed % DAY_MS) / 1000;\n  return days * WORK_HOURS_PER_DAY * 3600 + remainder;\n}\n\nexport async function firstReplySla(ticketId: string) {\n  const ticket = await db.one("SELECT id, opened_at, first_reply_at, zone, status FROM tickets WHERE id = $1", [\n    ticketId,\n  ]);\n  const pauses = await db.all("SELECT from_at, to_at FROM pauses WHERE ticket_id = $1", [ticketId]);\n\n  let used = workingSeconds(new Date(ticket.opened_at), new Date(ticket.first_reply_at));\n  for (const pause of pauses) {\n    used -= (new Date(pause.to_at).getTime() - new Date(pause.from_at).getTime()) / 1000;\n  }\n\n  return { usedSeconds: used, breached: used > TARGET_SECONDS };\n}\n'}}}},{slug:"oncall-rotation",title:"Who is on call",difficulty:"Medium",area:"time",domains:["scheduling","devtools"],minutes:25,summary:"Twenty lines that decide whose phone rings at 3am. The handover time is in the table and not in the arithmetic.",brief:["A teammate has opened this as a pull request. When this is wrong nobody answers the page, and the person who finds out is a customer.","Ask who is on call at 09:00 and at 11:00 on a handover day. Then put two overrides on the same afternoon. Then empty the members list.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Who is on call\n\nAn alert has to reach a person. This PR answers who that is right now.\n\n## Rules\n\n- A rotation is a list of people and a handover time. The handover is a\n  wall-clock time in the rotation’s zone, usually 10:00.\n- Somebody is always on call. A gap in the schedule falls back to the\n  rotation’s owner, and that is recorded.\n- An override beats the rotation for the window it covers.\n- Two overrides that touch the same window are a mistake, and the later one\n  wins, not both.\n- Being on call is a fact about a moment. Asking twice for the same moment\n  gives the same answer.\n\n## Notes for the reviewer\n\n`rotations` is `(id, zone, handover_at, owner_id, members)`, members in order.\n`overrides` is `(rotation_id, user_id, from_at, to_at)`.\n","src/OnCall.java":'package scheduling;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n/** Who is on call. */\npublic final class OnCall {\n    private static final int SHIFT_DAYS = 7;\n\n    public static String whoIsOnCall(String rotationId, Instant at) {\n        Map<String, Object> rotation = Db.one(\n                "SELECT id, zone, handover_at, owner_id, members, starts_at FROM rotations WHERE id = ?", rotationId);\n\n        Map<String, Object> override = Db.one(\n                "SELECT user_id FROM overrides WHERE rotation_id = ? AND from_at <= ? AND to_at >= ?",\n                rotationId, at, at);\n        if (override != null) {\n            return (String) override.get("user_id");\n        }\n\n        long elapsedDays = Duration.between((Instant) rotation.get("starts_at"), at).toDays();\n        List<String> members = (List<String>) rotation.get("members");\n        int index = (int) ((elapsedDays / SHIFT_DAYS) % members.size());\n        return members.get(index);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Who is on call\n\nAn alert has to reach a person. This PR answers who that is right now.\n\n## Rules\n\n- A rotation is a list of people and a handover time. The handover is a\n  wall-clock time in the rotation’s zone, usually 10:00.\n- Somebody is always on call. A gap in the schedule falls back to the\n  rotation’s owner, and that is recorded.\n- An override beats the rotation for the window it covers.\n- Two overrides that touch the same window are a mistake, and the later one\n  wins, not both.\n- Being on call is a fact about a moment. Asking twice for the same moment\n  gives the same answer.\n\n## Notes for the reviewer\n\n`rotations` is `(id, zone, handover_at, owner_id, members)`, members in order.\n`overrides` is `(rotation_id, user_id, from_at, to_at)`.\n","src/oncall.py":'"""Who is on call."""\nfrom datetime import datetime, timezone\n\nimport db\n\nSHIFT_DAYS = 7\n\n\ndef who_is_on_call(rotation_id, at=None):\n    at = at or datetime.now(timezone.utc)\n    rotation = db.one(\n        "SELECT id, zone, handover_at, owner_id, members, starts_at FROM rotations WHERE id = %s",\n        (rotation_id,),\n    )\n\n    override = db.one(\n        "SELECT user_id FROM overrides WHERE rotation_id = %s AND from_at <= %s AND to_at >= %s",\n        (rotation_id, at, at),\n    )\n    if override:\n        return override["user_id"]\n\n    elapsed_days = (at - rotation["starts_at"]).days\n    index = (elapsed_days // SHIFT_DAYS) % len(rotation["members"])\n    return rotation["members"][index]\n'}},typescript:{entry:"README.md",files:{"README.md":"# Who is on call\n\nAn alert has to reach a person. This PR answers who that is right now.\n\n## Rules\n\n- A rotation is a list of people and a handover time. The handover is a\n  wall-clock time in the rotation’s zone, usually 10:00.\n- Somebody is always on call. A gap in the schedule falls back to the\n  rotation’s owner, and that is recorded.\n- An override beats the rotation for the window it covers.\n- Two overrides that touch the same window are a mistake, and the later one\n  wins, not both.\n- Being on call is a fact about a moment. Asking twice for the same moment\n  gives the same answer.\n\n## Notes for the reviewer\n\n`rotations` is `(id, zone, handover_at, owner_id, members)`, members in order.\n`overrides` is `(rotation_id, user_id, from_at, to_at)`.\n","src/oncall.ts":'// Who is on call.\nimport { db } from "./db";\n\nconst SHIFT_DAYS = 7;\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport async function whoIsOnCall(rotationId: string, at = new Date()) {\n  const rotation = await db.one(\n    "SELECT id, zone, handover_at, owner_id, members, starts_at FROM rotations WHERE id = $1",\n    [rotationId],\n  );\n\n  const override = await db.one(\n    "SELECT user_id FROM overrides WHERE rotation_id = $1 AND from_at <= $2 AND to_at >= $3",\n    [rotationId, at, at],\n  );\n  if (override) return override.user_id;\n\n  const elapsedDays = Math.floor((at.getTime() - new Date(rotation.starts_at).getTime()) / DAY_MS);\n  const index = Math.floor(elapsedDays / SHIFT_DAYS) % rotation.members.length;\n  return rotation.members[index];\n}\n'}}}},{slug:"shift-roster",title:"Assigning shifts",difficulty:"Medium",area:"time",domains:["scheduling"],minutes:25,summary:"Three checks and an update. One of the rules in the README has no code at all, and the week in the query is not the week in the rule.",brief:["A teammate has opened this as a pull request. These rules come from a labour agreement, so a wrong answer is a legal problem, not a support ticket.","Assign somebody a 22:00 to 06:00 shift and then the 08:00 one the next morning. Then count a week from Wednesday.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Assigning shifts\n\nA manager drops a person into a shift. This PR decides whether that is\nallowed.\n\n## Rules\n\n- Nobody works two shifts at once. Shifts that touch at the ends are fine.\n- Eleven hours of rest between the end of one shift and the start of the next.\n- At most 48 hours in a week, where a week is Monday to Sunday in the site’s\n  zone.\n- A shift that crosses midnight belongs to the day it starts on.\n- The check and the assignment are one step: two managers assigning at the\n  same moment cannot both win.\n\n## Notes for the reviewer\n\n`shifts` is `(id, site_id, user_id, starts_at, ends_at)` in UTC. Sites carry\n`zone`. A shift is at most twelve hours long.\n","src/Roster.java":'package scheduling;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Assigning a person to a shift. */\npublic final class Roster {\n    private static final int REST_HOURS = 11;\n    private static final int MAX_WEEK_HOURS = 48;\n\n    public static boolean assign(String shiftId, String userId) {\n        Map<String, Object> shift =\n                Db.one("SELECT id, site_id, starts_at, ends_at FROM shifts WHERE id = ?", shiftId);\n\n        Map<String, Object> clash = Db.one("SELECT 1 FROM shifts WHERE user_id = ? AND starts_at <= ? AND ends_at >= ?",\n                userId, shift.get("ends_at"), shift.get("starts_at"));\n        if (clash != null) {\n            throw new Refused("already working");\n        }\n\n        Instant weekStart = ((Instant) shift.get("starts_at")).minus(Duration.ofDays(7));\n        double weekHours = (double) Db.one(\n                "SELECT coalesce(sum(extract(epoch from (ends_at - starts_at))) / 3600, 0) AS h FROM shifts "\n                        + "WHERE user_id = ? AND starts_at > ?", userId, weekStart).get("h");\n        if (weekHours + 8 > MAX_WEEK_HOURS) {\n            throw new Refused("too many hours");\n        }\n\n        Db.run("UPDATE shifts SET user_id = ? WHERE id = ?", userId, shiftId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Assigning shifts\n\nA manager drops a person into a shift. This PR decides whether that is\nallowed.\n\n## Rules\n\n- Nobody works two shifts at once. Shifts that touch at the ends are fine.\n- Eleven hours of rest between the end of one shift and the start of the next.\n- At most 48 hours in a week, where a week is Monday to Sunday in the site’s\n  zone.\n- A shift that crosses midnight belongs to the day it starts on.\n- The check and the assignment are one step: two managers assigning at the\n  same moment cannot both win.\n\n## Notes for the reviewer\n\n`shifts` is `(id, site_id, user_id, starts_at, ends_at)` in UTC. Sites carry\n`zone`. A shift is at most twelve hours long.\n","src/roster.py":'"""Assigning a person to a shift."""\nfrom datetime import timedelta\n\nimport db\n\nREST = timedelta(hours=11)\nMAX_WEEK_HOURS = 48\n\n\ndef assign(shift_id, user_id):\n    shift = db.one("SELECT id, site_id, starts_at, ends_at FROM shifts WHERE id = %s", (shift_id,))\n\n    clash = db.one(\n        "SELECT 1 FROM shifts WHERE user_id = %s AND starts_at <= %s AND ends_at >= %s",\n        (user_id, shift["ends_at"], shift["starts_at"]),\n    )\n    if clash:\n        raise Refused("already working")\n\n    week_hours = db.one(\n        "SELECT coalesce(sum(extract(epoch from (ends_at - starts_at))) / 3600, 0) AS h FROM shifts "\n        "WHERE user_id = %s AND starts_at > %s",\n        (user_id, shift["starts_at"] - timedelta(days=7)),\n    )["h"]\n    if week_hours + 8 > MAX_WEEK_HOURS:\n        raise Refused("too many hours")\n\n    db.run("UPDATE shifts SET user_id = %s WHERE id = %s", (user_id, shift_id))\n    return {"assigned": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Assigning shifts\n\nA manager drops a person into a shift. This PR decides whether that is\nallowed.\n\n## Rules\n\n- Nobody works two shifts at once. Shifts that touch at the ends are fine.\n- Eleven hours of rest between the end of one shift and the start of the next.\n- At most 48 hours in a week, where a week is Monday to Sunday in the site’s\n  zone.\n- A shift that crosses midnight belongs to the day it starts on.\n- The check and the assignment are one step: two managers assigning at the\n  same moment cannot both win.\n\n## Notes for the reviewer\n\n`shifts` is `(id, site_id, user_id, starts_at, ends_at)` in UTC. Sites carry\n`zone`. A shift is at most twelve hours long.\n","src/roster.ts":'// Assigning a person to a shift.\nimport { db } from "./db";\n\nconst REST_HOURS = 11;\nconst MAX_WEEK_HOURS = 48;\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport async function assign(shiftId: string, userId: string) {\n  const shift = await db.one("SELECT id, site_id, starts_at, ends_at FROM shifts WHERE id = $1", [shiftId]);\n\n  const clash = await db.one("SELECT 1 FROM shifts WHERE user_id = $1 AND starts_at <= $2 AND ends_at >= $3", [\n    userId,\n    shift.ends_at,\n    shift.starts_at,\n  ]);\n  if (clash) throw new Refused("already working");\n\n  const weekStart = new Date(new Date(shift.starts_at).getTime() - 7 * DAY_MS);\n  const weekHours = Number(\n    (\n      await db.one(\n        "SELECT coalesce(sum(extract(epoch from (ends_at - starts_at))) / 3600, 0) AS h FROM shifts " +\n          "WHERE user_id = $1 AND starts_at > $2",\n        [userId, weekStart],\n      )\n    ).h,\n  );\n  if (weekHours + 8 > MAX_WEEK_HOURS) throw new Refused("too many hours");\n\n  await db.run("UPDATE shifts SET user_id = $1 WHERE id = $2", [userId, shiftId]);\n  return { assigned: true };\n}\n'}}}},{slug:"ab-test-results",title:"Reading an experiment",difficulty:"Medium",area:"data",domains:["analytics"],minutes:25,summary:"One query and six lines of arithmetic that decide which checkout ships. The README says a person is counted once, and the query says otherwise.",brief:["A teammate has opened this as a pull request. Somebody will ship a change on this number and believe it.","Take a user assigned three times because they cleared their cookies, and one who bought last week and was put in the experiment today.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Reading an experiment\n\nProduct wants to know whether the new checkout beat the old one. This PR\ncomputes the result the dashboard shows.\n\n## Rules\n\n- A person is counted once per experiment, in the variant they were first\n  assigned.\n- Conversions count only after assignment. Somebody who converted before they\n  were put in the experiment is not a conversion for it.\n- A result is only shown once both variants have at least the minimum sample,\n  which is 1,000 people.\n- The uplift is relative: the difference between the variants over the control\n  rate.\n- A variant with nobody in it reports nothing, not an error and not a zero\n  that looks like a result.\n\n## Notes for the reviewer\n\n`assignments` is `(experiment_id, user_id, variant, at)`, one row per\nassignment attempt, not per person. `conversions` is `(user_id, at)`.\n","src/Experiment.java":'package analytics;\n\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** Reading an experiment. */\npublic final class Experiment {\n    private static final long MIN_SAMPLE = 1000;\n\n    public record Variant(long people, double rate) {}\n\n    public record Result(Variant control, Variant treatment, double uplift, boolean ready) {}\n\n    public static Result results(String experimentId) {\n        List<Map<String, Object>> rows = Db.all("SELECT a.variant, count(*) AS people, "\n                + "count(c.user_id) AS conversions "\n                + "FROM assignments a LEFT JOIN conversions c ON c.user_id = a.user_id "\n                + "WHERE a.experiment_id = ? GROUP BY a.variant", experimentId);\n        Map<String, Map<String, Object>> byVariant = new HashMap<>();\n        for (Map<String, Object> r : rows) {\n            byVariant.put((String) r.get("variant"), r);\n        }\n\n        Map<String, Object> control = byVariant.get("control");\n        Map<String, Object> treatment = byVariant.get("treatment");\n        double controlRate = (double) (long) control.get("conversions") / (long) control.get("people");\n        double treatmentRate = (double) (long) treatment.get("conversions") / (long) treatment.get("people");\n\n        return new Result(new Variant((long) control.get("people"), controlRate),\n                new Variant((long) treatment.get("people"), treatmentRate),\n                (treatmentRate - controlRate) / controlRate * 100,\n                (long) control.get("people") > MIN_SAMPLE);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Reading an experiment\n\nProduct wants to know whether the new checkout beat the old one. This PR\ncomputes the result the dashboard shows.\n\n## Rules\n\n- A person is counted once per experiment, in the variant they were first\n  assigned.\n- Conversions count only after assignment. Somebody who converted before they\n  were put in the experiment is not a conversion for it.\n- A result is only shown once both variants have at least the minimum sample,\n  which is 1,000 people.\n- The uplift is relative: the difference between the variants over the control\n  rate.\n- A variant with nobody in it reports nothing, not an error and not a zero\n  that looks like a result.\n\n## Notes for the reviewer\n\n`assignments` is `(experiment_id, user_id, variant, at)`, one row per\nassignment attempt, not per person. `conversions` is `(user_id, at)`.\n","src/experiment.py":'"""Reading an experiment."""\nimport db\n\nMIN_SAMPLE = 1000\n\n\ndef results(experiment_id):\n    rows = db.all(\n        "SELECT a.variant, count(*) AS people, "\n        "count(c.user_id) AS conversions "\n        "FROM assignments a LEFT JOIN conversions c ON c.user_id = a.user_id "\n        "WHERE a.experiment_id = %s GROUP BY a.variant",\n        (experiment_id,),\n    )\n    by_variant = {r["variant"]: r for r in rows}\n\n    control = by_variant["control"]\n    treatment = by_variant["treatment"]\n    control_rate = control["conversions"] / control["people"]\n    treatment_rate = treatment["conversions"] / treatment["people"]\n\n    return {\n        "control": {"people": control["people"], "rate": control_rate},\n        "treatment": {"people": treatment["people"], "rate": treatment_rate},\n        "uplift": (treatment_rate - control_rate) / control_rate * 100,\n        "ready": control["people"] > MIN_SAMPLE,\n    }\n'}},typescript:{entry:"README.md",files:{"README.md":"# Reading an experiment\n\nProduct wants to know whether the new checkout beat the old one. This PR\ncomputes the result the dashboard shows.\n\n## Rules\n\n- A person is counted once per experiment, in the variant they were first\n  assigned.\n- Conversions count only after assignment. Somebody who converted before they\n  were put in the experiment is not a conversion for it.\n- A result is only shown once both variants have at least the minimum sample,\n  which is 1,000 people.\n- The uplift is relative: the difference between the variants over the control\n  rate.\n- A variant with nobody in it reports nothing, not an error and not a zero\n  that looks like a result.\n\n## Notes for the reviewer\n\n`assignments` is `(experiment_id, user_id, variant, at)`, one row per\nassignment attempt, not per person. `conversions` is `(user_id, at)`.\n","src/experiment.ts":'// Reading an experiment.\nimport { db } from "./db";\n\nconst MIN_SAMPLE = 1000;\n\nexport async function results(experimentId: string) {\n  const rows = await db.all(\n    "SELECT a.variant, count(*) AS people, count(c.user_id) AS conversions " +\n      "FROM assignments a LEFT JOIN conversions c ON c.user_id = a.user_id " +\n      "WHERE a.experiment_id = $1 GROUP BY a.variant",\n    [experimentId],\n  );\n  const byVariant = Object.fromEntries(rows.map((r) => [r.variant, r]));\n\n  const control = byVariant.control;\n  const treatment = byVariant.treatment;\n  const controlRate = Number(control.conversions) / Number(control.people);\n  const treatmentRate = Number(treatment.conversions) / Number(treatment.people);\n\n  return {\n    control: { people: Number(control.people), rate: controlRate },\n    treatment: { people: Number(treatment.people), rate: treatmentRate },\n    uplift: ((treatmentRate - controlRate) / controlRate) * 100,\n    ready: Number(control.people) > MIN_SAMPLE,\n  };\n}\n'}}}},{slug:"photo-upload",title:"Uploading a photo",difficulty:"Medium",area:"security",domains:["social","media"],minutes:25,summary:"Twenty lines between a phone and a public bucket. Read the order of the checks, and ask what the file still carries when it lands.",brief:["A teammate has opened this as a pull request. The bytes here come from a stranger and the URL it returns is on the internet.","Upload a 2 GB file. Then a PHP script called image.jpg. Then a holiday photo with the location still in it, on a private post.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Uploading a photo\n\nSomebody adds a photo to a post. This PR takes the file, stores it and points\nthe post at it.\n\n## Rules\n\n- What the browser says a file is proves nothing. The type is decided from the\n  bytes, and only JPEG, PNG and WebP are accepted.\n- Location and camera metadata is stripped before the file is stored.\n- A file is at most 10 MB, and that limit is enforced before the bytes are in\n  memory.\n- The stored name never comes from the name the user sent.\n- A photo on a private post is only readable by somebody who may read the post.\n\n## Notes for the reviewer\n\n`storage.put` takes a key and bytes and returns a public URL under the bucket.\n`images.strip_metadata` exists and is not called anywhere yet.\n","src/Upload.java":'package social;\n\nimport java.nio.file.Paths;\nimport java.util.Map;\nimport java.util.Set;\n\n/** Photo upload. */\npublic final class Upload {\n    private static final int MAX_BYTES = 10 * 1024 * 1024;\n    private static final Set<String> ALLOWED = Set.of("image/jpeg", "image/png", "image/webp");\n\n    public record Incoming(byte[] bytes, String contentType, String filename) {}\n\n    public static String uploadPhoto(String userId, String postId, Incoming upload) {\n        byte[] data = upload.bytes();\n        if (data.length > MAX_BYTES) {\n            throw new TooLarge("file too large");\n        }\n        if (!ALLOWED.contains(upload.contentType())) {\n            throw new BadRequest("not an image");\n        }\n\n        String key = "photos/" + postId + "/" + Paths.get(upload.filename()).getFileName();\n        String url = Storage.put(key, data);\n\n        Db.run("INSERT INTO photos (post_id, user_id, url, bytes) VALUES (?, ?, ?, ?)",\n                postId, userId, url, data.length);\n        return url;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Uploading a photo\n\nSomebody adds a photo to a post. This PR takes the file, stores it and points\nthe post at it.\n\n## Rules\n\n- What the browser says a file is proves nothing. The type is decided from the\n  bytes, and only JPEG, PNG and WebP are accepted.\n- Location and camera metadata is stripped before the file is stored.\n- A file is at most 10 MB, and that limit is enforced before the bytes are in\n  memory.\n- The stored name never comes from the name the user sent.\n- A photo on a private post is only readable by somebody who may read the post.\n\n## Notes for the reviewer\n\n`storage.put` takes a key and bytes and returns a public URL under the bucket.\n`images.strip_metadata` exists and is not called anywhere yet.\n","src/upload.py":'"""Photo upload."""\nimport os\n\nimport db\nimport storage\n\nMAX_BYTES = 10 * 1024 * 1024\nALLOWED = {"image/jpeg", "image/png", "image/webp"}\n\n\ndef upload_photo(user_id, post_id, upload):\n    data = upload.read()\n    if len(data) > MAX_BYTES:\n        raise TooLarge("file too large")\n    if upload.content_type not in ALLOWED:\n        raise BadRequest("not an image")\n\n    key = f"photos/{post_id}/{os.path.basename(upload.filename)}"\n    url = storage.put(key, data)\n\n    db.run(\n        "INSERT INTO photos (post_id, user_id, url, bytes) VALUES (%s, %s, %s, %s)",\n        (post_id, user_id, url, len(data)),\n    )\n    return {"url": url}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Uploading a photo\n\nSomebody adds a photo to a post. This PR takes the file, stores it and points\nthe post at it.\n\n## Rules\n\n- What the browser says a file is proves nothing. The type is decided from the\n  bytes, and only JPEG, PNG and WebP are accepted.\n- Location and camera metadata is stripped before the file is stored.\n- A file is at most 10 MB, and that limit is enforced before the bytes are in\n  memory.\n- The stored name never comes from the name the user sent.\n- A photo on a private post is only readable by somebody who may read the post.\n\n## Notes for the reviewer\n\n`storage.put` takes a key and bytes and returns a public URL under the bucket.\n`images.strip_metadata` exists and is not called anywhere yet.\n","src/upload.ts":'// Photo upload.\nimport { basename } from "node:path";\nimport { db } from "./db";\nimport * as storage from "./storage";\n\nconst MAX_BYTES = 10 * 1024 * 1024;\nconst ALLOWED = new Set(["image/jpeg", "image/png", "image/webp"]);\n\ntype Upload = { read(): Promise<Buffer>; contentType: string; filename: string };\n\nexport async function uploadPhoto(userId: string, postId: string, upload: Upload) {\n  const data = await upload.read();\n  if (data.length > MAX_BYTES) throw new TooLarge("file too large");\n  if (!ALLOWED.has(upload.contentType)) throw new BadRequest("not an image");\n\n  const key = `photos/${postId}/${basename(upload.filename)}`;\n  const url = await storage.put(key, data);\n\n  await db.run("INSERT INTO photos (post_id, user_id, url, bytes) VALUES ($1, $2, $3, $4)", [\n    postId,\n    userId,\n    url,\n    data.length,\n  ]);\n  return { url };\n}\n'}}}},{slug:"follow-graph",title:"Following and unfollowing",difficulty:"Medium",area:"backend",domains:["social"],minutes:25,summary:"The follow button, in twenty lines. The insert is careful about duplicates and the two counts next to it are not.",brief:["A teammate has opened this as a pull request. Read the insert, then read the two statements after it, then ask whether they agree.","Tap follow twice. Then unfollow somebody you never followed. Then follow a private account, and follow somebody who blocked you.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Following and unfollowing\n\nThis PR is the follow button.\n\n## Rules\n\n- Following is idempotent. Two taps leave one follow.\n- A private account gets a request, not a follower, until it accepts.\n- Blocking removes any follow in both directions, and a blocked person cannot\n  follow again.\n- The follower and following counts on a profile match the rows.\n- Nobody follows themselves.\n\n## Notes for the reviewer\n\n`follows` is `(follower_id, author_id, accepted, at)` with a unique index on\nthe pair. `users` carries denormalised `follower_count` and `following_count`\nand a `private` flag. `blocks` is `(user_id, blocked_id)`.\n","src/Follow.java":'package social;\n\nimport java.util.Map;\n\n/** Follow and unfollow. */\npublic final class Follow {\n\n    public static boolean follow(String followerId, String authorId) {\n        Map<String, Object> author = Db.one("SELECT id, private FROM users WHERE id = ?", authorId);\n\n        Db.run("INSERT INTO follows (follower_id, author_id, accepted, at) VALUES (?, ?, true, now()) "\n                + "ON CONFLICT (follower_id, author_id) DO NOTHING", followerId, authorId);\n        Db.run("UPDATE users SET follower_count = follower_count + 1 WHERE id = ?", authorId);\n        Db.run("UPDATE users SET following_count = following_count + 1 WHERE id = ?", followerId);\n        return true;\n    }\n\n    public static boolean unfollow(String followerId, String authorId) {\n        Db.run("DELETE FROM follows WHERE follower_id = ? AND author_id = ?", followerId, authorId);\n        Db.run("UPDATE users SET follower_count = follower_count - 1 WHERE id = ?", authorId);\n        Db.run("UPDATE users SET following_count = following_count - 1 WHERE id = ?", followerId);\n        return false;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Following and unfollowing\n\nThis PR is the follow button.\n\n## Rules\n\n- Following is idempotent. Two taps leave one follow.\n- A private account gets a request, not a follower, until it accepts.\n- Blocking removes any follow in both directions, and a blocked person cannot\n  follow again.\n- The follower and following counts on a profile match the rows.\n- Nobody follows themselves.\n\n## Notes for the reviewer\n\n`follows` is `(follower_id, author_id, accepted, at)` with a unique index on\nthe pair. `users` carries denormalised `follower_count` and `following_count`\nand a `private` flag. `blocks` is `(user_id, blocked_id)`.\n","src/follow.py":'"""Follow and unfollow."""\nimport db\n\n\ndef follow(follower_id, author_id):\n    author = db.one("SELECT id, private FROM users WHERE id = %s", (author_id,))\n\n    db.run(\n        "INSERT INTO follows (follower_id, author_id, accepted, at) VALUES (%s, %s, true, now()) "\n        "ON CONFLICT (follower_id, author_id) DO NOTHING",\n        (follower_id, author_id),\n    )\n    db.run("UPDATE users SET follower_count = follower_count + 1 WHERE id = %s", (author_id,))\n    db.run("UPDATE users SET following_count = following_count + 1 WHERE id = %s", (follower_id,))\n    return {"following": True}\n\n\ndef unfollow(follower_id, author_id):\n    db.run("DELETE FROM follows WHERE follower_id = %s AND author_id = %s", (follower_id, author_id))\n    db.run("UPDATE users SET follower_count = follower_count - 1 WHERE id = %s", (author_id,))\n    db.run("UPDATE users SET following_count = following_count - 1 WHERE id = %s", (follower_id,))\n    return {"following": False}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Following and unfollowing\n\nThis PR is the follow button.\n\n## Rules\n\n- Following is idempotent. Two taps leave one follow.\n- A private account gets a request, not a follower, until it accepts.\n- Blocking removes any follow in both directions, and a blocked person cannot\n  follow again.\n- The follower and following counts on a profile match the rows.\n- Nobody follows themselves.\n\n## Notes for the reviewer\n\n`follows` is `(follower_id, author_id, accepted, at)` with a unique index on\nthe pair. `users` carries denormalised `follower_count` and `following_count`\nand a `private` flag. `blocks` is `(user_id, blocked_id)`.\n","src/follow.ts":'// Follow and unfollow.\nimport { db } from "./db";\n\nexport async function follow(followerId: string, authorId: string) {\n  const author = await db.one("SELECT id, private FROM users WHERE id = $1", [authorId]);\n\n  await db.run(\n    "INSERT INTO follows (follower_id, author_id, accepted, at) VALUES ($1, $2, true, now()) " +\n      "ON CONFLICT (follower_id, author_id) DO NOTHING",\n    [followerId, authorId],\n  );\n  await db.run("UPDATE users SET follower_count = follower_count + 1 WHERE id = $1", [authorId]);\n  await db.run("UPDATE users SET following_count = following_count + 1 WHERE id = $1", [followerId]);\n  return { following: true };\n}\n\nexport async function unfollow(followerId: string, authorId: string) {\n  await db.run("DELETE FROM follows WHERE follower_id = $1 AND author_id = $2", [followerId, authorId]);\n  await db.run("UPDATE users SET follower_count = follower_count - 1 WHERE id = $1", [authorId]);\n  await db.run("UPDATE users SET following_count = following_count - 1 WHERE id = $1", [followerId]);\n  return { following: false };\n}\n'}}}},{slug:"comment-moderation",title:"Reporting and hiding comments",difficulty:"Medium",area:"backend",domains:["social"],minutes:25,summary:"Reports on one side, a moderator on the other. One of these two functions hides a comment without a moderator, and the other tells the author who reported them.",brief:["A teammate has opened this as a pull request. Moderation code is read by lawyers and by the people it is used against, so read it as both.","Report the same comment five times from one account. Then read the message the author gets.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Reporting and hiding comments\n\nReaders report comments, moderators hide them. This PR is both ends.\n\n## Rules\n\n- A person reports a comment once. Reporting again changes nothing.\n- A comment reaches review at five reports from five different accounts. It is\n  never hidden by reports alone.\n- Hiding is a moderator decision, and every decision is recorded with who made\n  it and why.\n- A hidden comment is gone from the thread and from the counts, and its author\n  is told without being told who reported it.\n- A moderator may not act on their own comment.\n\n## Notes for the reviewer\n\n`reports` is `(comment_id, reporter_id, reason, at)`. `comments` carries\n`hidden_at` and a denormalised `reply_count` on the parent post.\n","src/Moderation.java":'package social;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.stream.Collectors;\n\n/** Reports and moderator decisions. */\npublic final class Moderation {\n    private static final int REVIEW_THRESHOLD = 5;\n\n    public static long report(String commentId, String reporterId, String reason) {\n        Db.run("INSERT INTO reports (comment_id, reporter_id, reason, at) VALUES (?, ?, ?, now())",\n                commentId, reporterId, reason);\n        long count = (long) Db.one("SELECT count(*) AS n FROM reports WHERE comment_id = ?", commentId).get("n");\n        if (count >= REVIEW_THRESHOLD) {\n            Db.run("UPDATE comments SET hidden_at = now() WHERE id = ?", commentId);\n        }\n        return count;\n    }\n\n    public static boolean hide(String commentId, String moderatorId, String reason) {\n        Map<String, Object> comment = Db.one("SELECT id, author_id, post_id FROM comments WHERE id = ?", commentId);\n        Db.run("UPDATE comments SET hidden_at = now() WHERE id = ?", commentId);\n        List<Map<String, Object>> reporters =\n                Db.all("SELECT reporter_id FROM reports WHERE comment_id = ?", commentId);\n        Notify.send((String) comment.get("author_id"),\n                "Your comment was hidden: " + reason + ". Reported by " + reporters.size() + " people: "\n                        + reporters.stream().map(r -> String.valueOf(r.get("reporter_id")))\n                                .collect(Collectors.joining(", ")));\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Reporting and hiding comments\n\nReaders report comments, moderators hide them. This PR is both ends.\n\n## Rules\n\n- A person reports a comment once. Reporting again changes nothing.\n- A comment reaches review at five reports from five different accounts. It is\n  never hidden by reports alone.\n- Hiding is a moderator decision, and every decision is recorded with who made\n  it and why.\n- A hidden comment is gone from the thread and from the counts, and its author\n  is told without being told who reported it.\n- A moderator may not act on their own comment.\n\n## Notes for the reviewer\n\n`reports` is `(comment_id, reporter_id, reason, at)`. `comments` carries\n`hidden_at` and a denormalised `reply_count` on the parent post.\n","src/moderation.py":'"""Reports and moderator decisions."""\nimport db\nimport notify\n\nREVIEW_THRESHOLD = 5\n\n\ndef report(comment_id, reporter_id, reason):\n    db.run(\n        "INSERT INTO reports (comment_id, reporter_id, reason, at) VALUES (%s, %s, %s, now())",\n        (comment_id, reporter_id, reason),\n    )\n    count = db.one("SELECT count(*) AS n FROM reports WHERE comment_id = %s", (comment_id,))["n"]\n    if count >= REVIEW_THRESHOLD:\n        db.run("UPDATE comments SET hidden_at = now() WHERE id = %s", (comment_id,))\n    return {"reports": count}\n\n\ndef hide(comment_id, moderator_id, reason):\n    comment = db.one("SELECT id, author_id, post_id FROM comments WHERE id = %s", (comment_id,))\n    db.run("UPDATE comments SET hidden_at = now() WHERE id = %s", (comment_id,))\n    reporters = db.all("SELECT reporter_id FROM reports WHERE comment_id = %s", (comment_id,))\n    notify.send(\n        comment["author_id"],\n        f"Your comment was hidden: {reason}. Reported by {len(reporters)} people: "\n        + ", ".join(str(r["reporter_id"]) for r in reporters),\n    )\n    return {"hidden": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Reporting and hiding comments\n\nReaders report comments, moderators hide them. This PR is both ends.\n\n## Rules\n\n- A person reports a comment once. Reporting again changes nothing.\n- A comment reaches review at five reports from five different accounts. It is\n  never hidden by reports alone.\n- Hiding is a moderator decision, and every decision is recorded with who made\n  it and why.\n- A hidden comment is gone from the thread and from the counts, and its author\n  is told without being told who reported it.\n- A moderator may not act on their own comment.\n\n## Notes for the reviewer\n\n`reports` is `(comment_id, reporter_id, reason, at)`. `comments` carries\n`hidden_at` and a denormalised `reply_count` on the parent post.\n","src/moderation.ts":'// Reports and moderator decisions.\nimport { db } from "./db";\nimport * as notify from "./notify";\n\nconst REVIEW_THRESHOLD = 5;\n\nexport async function report(commentId: string, reporterId: string, reason: string) {\n  await db.run("INSERT INTO reports (comment_id, reporter_id, reason, at) VALUES ($1, $2, $3, now())", [\n    commentId,\n    reporterId,\n    reason,\n  ]);\n  const count = Number(\n    (await db.one("SELECT count(*) AS n FROM reports WHERE comment_id = $1", [commentId])).n,\n  );\n  if (count >= REVIEW_THRESHOLD) {\n    await db.run("UPDATE comments SET hidden_at = now() WHERE id = $1", [commentId]);\n  }\n  return { reports: count };\n}\n\nexport async function hide(commentId: string, moderatorId: string, reason: string) {\n  const comment = await db.one("SELECT id, author_id, post_id FROM comments WHERE id = $1", [commentId]);\n  await db.run("UPDATE comments SET hidden_at = now() WHERE id = $1", [commentId]);\n  const reporters = await db.all("SELECT reporter_id FROM reports WHERE comment_id = $1", [commentId]);\n  await notify.send(\n    comment.author_id,\n    `Your comment was hidden: ${reason}. Reported by ${reporters.length} people: ` +\n      reporters.map((r) => r.reporter_id).join(", "),\n  );\n  return { hidden: true };\n}\n'}}}},{slug:"mentions",title:"Mentions",difficulty:"Medium",area:"backend",domains:["social","messaging"],minutes:25,summary:"A regular expression and a loop. Four of the five rules are about who should not be notified, and the loop notifies everybody it finds.",brief:["A teammate has opened this as a pull request. Notifications are the easiest thing in a product to turn into harassment, so read the rules about who is left out.","Write a post containing an email address, then one that mentions the same person three times, then edit it and save again.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Mentions\n\nWriting @someone in a post notifies them. This PR finds the mentions and sends\nthe notifications.\n\n## Rules\n\n- A mention is an @ followed by a handle, at a word boundary. An email address\n  is not a mention, and neither is an @ inside a code block.\n- Somebody is notified once per post, however many times they are mentioned in\n  it.\n- Editing a post notifies only the people who were not mentioned before.\n- Nobody is notified of their own mention.\n- A mention of somebody who blocked the author notifies nobody.\n\n## Notes for the reviewer\n\n`users` are looked up by handle, which is unique. `mentions` is\n`(post_id, user_id)` and records who has already been notified for a post.\n","src/Mentions.java":'package social;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\n/** Finding and notifying mentions. */\npublic final class Mentions {\n    private static final Pattern MENTION = Pattern.compile("@(\\\\w+)");\n\n    public static List<String> handlesIn(String body) {\n        List<String> out = new ArrayList<>();\n        Matcher m = MENTION.matcher(body);\n        while (m.find()) {\n            out.add(m.group(1));\n        }\n        return out;\n    }\n\n    public static int notifyMentions(String postId, String authorId, String body) {\n        int sent = 0;\n        for (String handle : handlesIn(body)) {\n            Map<String, Object> user = Db.one("SELECT id, handle FROM users WHERE handle = ?", handle);\n            if (user == null) {\n                continue;\n            }\n            Db.run("INSERT INTO mentions (post_id, user_id) VALUES (?, ?)", postId, user.get("id"));\n            Notify.send((String) user.get("id"),\n                    "You were mentioned in a post: " + body.substring(0, Math.min(200, body.length())));\n            sent++;\n        }\n        return sent;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Mentions\n\nWriting @someone in a post notifies them. This PR finds the mentions and sends\nthe notifications.\n\n## Rules\n\n- A mention is an @ followed by a handle, at a word boundary. An email address\n  is not a mention, and neither is an @ inside a code block.\n- Somebody is notified once per post, however many times they are mentioned in\n  it.\n- Editing a post notifies only the people who were not mentioned before.\n- Nobody is notified of their own mention.\n- A mention of somebody who blocked the author notifies nobody.\n\n## Notes for the reviewer\n\n`users` are looked up by handle, which is unique. `mentions` is\n`(post_id, user_id)` and records who has already been notified for a post.\n","src/mentions.py":'"""Finding and notifying mentions."""\nimport re\n\nimport db\nimport notify\n\nMENTION = re.compile(r"@(\\w+)")\n\n\ndef handles_in(body):\n    return MENTION.findall(body)\n\n\ndef notify_mentions(post_id, author_id, body):\n    handles = handles_in(body)\n    sent = 0\n    for handle in handles:\n        user = db.one("SELECT id, handle FROM users WHERE handle = %s", (handle,))\n        if user is None:\n            continue\n        db.run("INSERT INTO mentions (post_id, user_id) VALUES (%s, %s)", (post_id, user["id"]))\n        notify.send(user["id"], f"You were mentioned in a post: {body[:200]}")\n        sent += 1\n    return {"notified": sent}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Mentions\n\nWriting @someone in a post notifies them. This PR finds the mentions and sends\nthe notifications.\n\n## Rules\n\n- A mention is an @ followed by a handle, at a word boundary. An email address\n  is not a mention, and neither is an @ inside a code block.\n- Somebody is notified once per post, however many times they are mentioned in\n  it.\n- Editing a post notifies only the people who were not mentioned before.\n- Nobody is notified of their own mention.\n- A mention of somebody who blocked the author notifies nobody.\n\n## Notes for the reviewer\n\n`users` are looked up by handle, which is unique. `mentions` is\n`(post_id, user_id)` and records who has already been notified for a post.\n","src/mentions.ts":'// Finding and notifying mentions.\nimport { db } from "./db";\nimport * as notify from "./notify";\n\nconst MENTION = /@(\\w+)/g;\n\nexport function handlesIn(body: string) {\n  return [...body.matchAll(MENTION)].map((m) => m[1]);\n}\n\nexport async function notifyMentions(postId: string, authorId: string, body: string) {\n  const handles = handlesIn(body);\n  let sent = 0;\n  for (const handle of handles) {\n    const user = await db.one("SELECT id, handle FROM users WHERE handle = $1", [handle]);\n    if (!user) continue;\n    await db.run("INSERT INTO mentions (post_id, user_id) VALUES ($1, $2)", [postId, user.id]);\n    await notify.send(user.id, `You were mentioned in a post: ${body.slice(0, 200)}`);\n    sent += 1;\n  }\n  return { notified: sent };\n}\n'}}}},{slug:"profile-privacy",title:"A private profile",difficulty:"Medium",area:"security",domains:["social","identity"],minutes:25,summary:"One endpoint, one privacy flag, and a cache in front of it. The flag is read, and the cache does not know it exists.",brief:["A teammate has opened this as a pull request. Private accounts are used by people who have a reason, so read it as though somebody’s safety rests on it, because it does.","Ask for a private profile as a stranger, then as somebody who requested a follow and was never accepted, then as somebody who was blocked. Then ask twice in a minute.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# A private profile\n\nSomebody makes their account private. This PR is the profile endpoint that\nhas to respect it.\n\n## Rules\n\n- A private profile shows the handle, the display name and the avatar to\n  anybody, and nothing else.\n- Posts, follower and following lists and the counts are for accepted\n  followers and the owner.\n- Whether an account exists is not a secret. Whether its posts exist is.\n- Blocking is invisible: a blocked viewer sees what a stranger sees, not an\n  error that tells them they were blocked.\n- Going private hides what was already posted, including anything cached.\n\n## Notes for the reviewer\n\n`users` carries `private`. `follows` carries `accepted`. The response is\nrendered by the app and also cached at the edge for a minute.\n","src/Profile.java":'package social;\n\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** GET /users/:handle */\npublic final class Profile {\n    private static final int CACHE_TTL = 60;\n\n    public static Map<String, Object> profile(String viewerId, String handle) {\n        Object cached = Cache.get("profile:" + handle);\n        if (cached != null) {\n            return (Map<String, Object>) cached;\n        }\n\n        Map<String, Object> user = Db.one("SELECT id, handle, name, avatar_url, private, follower_count, "\n                + "following_count FROM users WHERE handle = ?", handle);\n        if (user == null) {\n            throw new NotFound("no such profile");\n        }\n\n        Map<String, Object> blocked =\n                Db.one("SELECT 1 FROM blocks WHERE user_id = ? AND blocked_id = ?", user.get("id"), viewerId);\n        if (blocked != null) {\n            throw new Forbidden("you are blocked by this user");\n        }\n\n        Map<String, Object> follow = Db.one("SELECT accepted FROM follows WHERE follower_id = ? AND author_id = ?",\n                viewerId, user.get("id"));\n        boolean maySee = !(boolean) user.get("private") || follow != null || viewerId.equals(user.get("id"));\n\n        Map<String, Object> body = new HashMap<>();\n        body.put("handle", user.get("handle"));\n        body.put("name", user.get("name"));\n        body.put("avatarUrl", user.get("avatar_url"));\n        body.put("followers", user.get("follower_count"));\n        body.put("following", user.get("following_count"));\n        List<Map<String, Object>> posts = maySee\n                ? Db.all("SELECT id, body, created_at FROM posts WHERE author_id = ?", user.get("id"))\n                : List.of();\n        body.put("posts", posts);\n        Cache.set("profile:" + handle, body, CACHE_TTL);\n        return body;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# A private profile\n\nSomebody makes their account private. This PR is the profile endpoint that\nhas to respect it.\n\n## Rules\n\n- A private profile shows the handle, the display name and the avatar to\n  anybody, and nothing else.\n- Posts, follower and following lists and the counts are for accepted\n  followers and the owner.\n- Whether an account exists is not a secret. Whether its posts exist is.\n- Blocking is invisible: a blocked viewer sees what a stranger sees, not an\n  error that tells them they were blocked.\n- Going private hides what was already posted, including anything cached.\n\n## Notes for the reviewer\n\n`users` carries `private`. `follows` carries `accepted`. The response is\nrendered by the app and also cached at the edge for a minute.\n","src/profile.py":'"""GET /users/:handle"""\nimport db\nfrom cache import cache\n\nCACHE_TTL = 60\n\n\ndef profile(viewer_id, handle):\n    cached = cache.get(f"profile:{handle}")\n    if cached is not None:\n        return cached\n\n    user = db.one(\n        "SELECT id, handle, name, avatar_url, private, follower_count, following_count FROM users WHERE handle = %s",\n        (handle,),\n    )\n    if user is None:\n        raise NotFound("no such profile")\n\n    blocked = db.one("SELECT 1 FROM blocks WHERE user_id = %s AND blocked_id = %s", (user["id"], viewer_id))\n    if blocked:\n        raise Forbidden("you are blocked by this user")\n\n    follow = db.one(\n        "SELECT accepted FROM follows WHERE follower_id = %s AND author_id = %s",\n        (viewer_id, user["id"]),\n    )\n    may_see = not user["private"] or follow is not None or viewer_id == user["id"]\n\n    body = {\n        "handle": user["handle"],\n        "name": user["name"],\n        "avatar_url": user["avatar_url"],\n        "followers": user["follower_count"],\n        "following": user["following_count"],\n        "posts": db.all("SELECT id, body, created_at FROM posts WHERE author_id = %s", (user["id"],)) if may_see else [],\n    }\n    cache.set(f"profile:{handle}", body, CACHE_TTL)\n    return body\n'}},typescript:{entry:"README.md",files:{"README.md":"# A private profile\n\nSomebody makes their account private. This PR is the profile endpoint that\nhas to respect it.\n\n## Rules\n\n- A private profile shows the handle, the display name and the avatar to\n  anybody, and nothing else.\n- Posts, follower and following lists and the counts are for accepted\n  followers and the owner.\n- Whether an account exists is not a secret. Whether its posts exist is.\n- Blocking is invisible: a blocked viewer sees what a stranger sees, not an\n  error that tells them they were blocked.\n- Going private hides what was already posted, including anything cached.\n\n## Notes for the reviewer\n\n`users` carries `private`. `follows` carries `accepted`. The response is\nrendered by the app and also cached at the edge for a minute.\n","src/profile.ts":'// GET /users/:handle\nimport { cache } from "./cache";\nimport { db } from "./db";\n\nconst CACHE_TTL = 60;\n\nexport async function profile(viewerId: string, handle: string) {\n  const cached = cache.get(`profile:${handle}`);\n  if (cached !== undefined) return cached;\n\n  const user = await db.one(\n    "SELECT id, handle, name, avatar_url, private, follower_count, following_count FROM users WHERE handle = $1",\n    [handle],\n  );\n  if (!user) throw new NotFound("no such profile");\n\n  const blocked = await db.one("SELECT 1 FROM blocks WHERE user_id = $1 AND blocked_id = $2", [user.id, viewerId]);\n  if (blocked) throw new Forbidden("you are blocked by this user");\n\n  const follow = await db.one("SELECT accepted FROM follows WHERE follower_id = $1 AND author_id = $2", [\n    viewerId,\n    user.id,\n  ]);\n  const maySee = !user.private || follow !== null || viewerId === user.id;\n\n  const body = {\n    handle: user.handle,\n    name: user.name,\n    avatarUrl: user.avatar_url,\n    followers: user.follower_count,\n    following: user.following_count,\n    posts: maySee ? await db.all("SELECT id, body, created_at FROM posts WHERE author_id = $1", [user.id]) : [],\n  };\n  cache.set(`profile:${handle}`, body, CACHE_TTL);\n  return body;\n}\n'}}}},{slug:"playback-urls",title:"Playback links",difficulty:"Medium",area:"security",domains:["media"],minutes:25,summary:"Fifteen lines that decide who can watch a paid video and how many views it has. Read what goes into the signature, and what does not.",brief:["A teammate has opened this as a pull request. The link it returns ends up in browser history, in referrer headers and sometimes in a group chat.","Ask for a link to a paid video without buying it. Then paste the link somewhere public. Then seek twenty times in one sitting.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Playback links\n\nA viewer presses play and the app asks for a link to the video file. This PR\nmints it and counts the view.\n\n## Rules\n\n- A link is good for fifteen minutes and for the person it was issued to.\n- A link to a paid video is only issued to somebody whose purchase or\n  subscription is live.\n- A view counts once per person per video per day, however many times the\n  player asks for a link.\n- The signature covers everything that decides what is served: the object, the\n  person and the expiry.\n- The link is not a secret that can be reused. Sharing it does not share the\n  video.\n\n## Notes for the reviewer\n\n`sign(path, secret)` returns a hex digest. The CDN checks the signature and\nthe expiry from the query string. The player asks for a new link on every\nseek.\n","src/Playback.java":'package media;\n\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Minting a playback link. */\npublic final class Playback {\n    private static final long TTL_SECONDS = 900;\n    private static final String SECRET = System.getenv("CDN_SECRET");\n\n    public record Link(String url, long expires) {}\n\n    public static Link playbackUrl(String userId, String videoId) {\n        Map<String, Object> video = Db.one("SELECT id, path, paid FROM videos WHERE id = ?", videoId);\n\n        String signature = Signing.sign((String) video.get("path"), SECRET);\n        long expires = Instant.now().getEpochSecond() + TTL_SECONDS;\n        String url = "https://cdn.example.com/" + video.get("path") + "?sig=" + signature + "&expires=" + expires;\n\n        Db.run("INSERT INTO views (video_id, user_id, at) VALUES (?, ?, now())", videoId, userId);\n        return new Link(url, expires);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Playback links\n\nA viewer presses play and the app asks for a link to the video file. This PR\nmints it and counts the view.\n\n## Rules\n\n- A link is good for fifteen minutes and for the person it was issued to.\n- A link to a paid video is only issued to somebody whose purchase or\n  subscription is live.\n- A view counts once per person per video per day, however many times the\n  player asks for a link.\n- The signature covers everything that decides what is served: the object, the\n  person and the expiry.\n- The link is not a secret that can be reused. Sharing it does not share the\n  video.\n\n## Notes for the reviewer\n\n`sign(path, secret)` returns a hex digest. The CDN checks the signature and\nthe expiry from the query string. The player asks for a new link on every\nseek.\n","src/playback.py":'"""Minting a playback link."""\nimport os\nimport time\n\nimport db\nfrom signing import sign\n\nTTL_SECONDS = 900\nSECRET = os.environ["CDN_SECRET"]\n\n\ndef playback_url(user_id, video_id):\n    video = db.one("SELECT id, path, paid FROM videos WHERE id = %s", (video_id,))\n\n    signature = sign(video["path"], SECRET)\n    expires = int(time.time()) + TTL_SECONDS\n    url = f"https://cdn.example.com/{video[\'path\']}?sig={signature}&expires={expires}"\n\n    db.run(\n        "INSERT INTO views (video_id, user_id, at) VALUES (%s, %s, now())",\n        (video_id, user_id),\n    )\n    return {"url": url, "expires": expires}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Playback links\n\nA viewer presses play and the app asks for a link to the video file. This PR\nmints it and counts the view.\n\n## Rules\n\n- A link is good for fifteen minutes and for the person it was issued to.\n- A link to a paid video is only issued to somebody whose purchase or\n  subscription is live.\n- A view counts once per person per video per day, however many times the\n  player asks for a link.\n- The signature covers everything that decides what is served: the object, the\n  person and the expiry.\n- The link is not a secret that can be reused. Sharing it does not share the\n  video.\n\n## Notes for the reviewer\n\n`sign(path, secret)` returns a hex digest. The CDN checks the signature and\nthe expiry from the query string. The player asks for a new link on every\nseek.\n","src/playback.ts":'// Minting a playback link.\nimport { db } from "./db";\nimport { sign } from "./signing";\n\nconst TTL_SECONDS = 900;\nconst SECRET = process.env.CDN_SECRET as string;\n\nexport async function playbackUrl(userId: string, videoId: string) {\n  const video = await db.one("SELECT id, path, paid FROM videos WHERE id = $1", [videoId]);\n\n  const signature = sign(video.path, SECRET);\n  const expires = Math.floor(Date.now() / 1000) + TTL_SECONDS;\n  const url = `https://cdn.example.com/${video.path}?sig=${signature}&expires=${expires}`;\n\n  await db.run("INSERT INTO views (video_id, user_id, at) VALUES ($1, $2, now())", [videoId, userId]);\n  return { url, expires };\n}\n'}}}},{slug:"thumbnail-cache",title:"Thumbnails on demand",difficulty:"Medium",area:"caching",domains:["media"],minutes:25,summary:"Ten lines, a public endpoint and a shared cache. Look at the key it writes, then at what the query string is allowed to be.",brief:["A teammate has opened this as a pull request. Anybody on the internet can call this and choose part of the input.","Ask for w=399, then w=398, then a thousand more. Then ask for the same image at two sizes. Then replace the source.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Thumbnails on demand\n\n`GET /img/:key?w=400` resizes an image and caches the result. This PR adds it.\n\n## Rules\n\n- Only the sizes in the list are served. Anything else is refused, not\n  resized.\n- A cached thumbnail belongs to one source image and one size.\n- Replacing the source image replaces every thumbnail of it.\n- The response carries cache headers so browsers and the CDN can hold it.\n- The endpoint is public, so the work it can be asked to do is bounded.\n\n## Notes for the reviewer\n\n`cache` is a shared Redis. `images.resize` decodes the source and is the\nexpensive part. `SIZES` is the list the product uses.\n","src/Thumbs.java":'package media;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** GET /img/:key */\npublic final class Thumbs {\n    private static final List<Integer> SIZES = List.of(80, 200, 400, 1200);\n    private static final int CACHE_TTL = 86400;\n\n    public record Image(byte[] bytes, Map<String, String> headers) {}\n\n    public static Image thumbnail(String key, String width) {\n        byte[] cached = Cache.get("thumb:" + key);\n        if (cached != null) {\n            return new Image(cached, Map.of());\n        }\n\n        byte[] source = Storage.get(key);\n        byte[] out = Images.resize(source, Integer.parseInt(width));\n        Cache.set("thumb:" + key, out, CACHE_TTL);\n        return new Image(out, Map.of());\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Thumbnails on demand\n\n`GET /img/:key?w=400` resizes an image and caches the result. This PR adds it.\n\n## Rules\n\n- Only the sizes in the list are served. Anything else is refused, not\n  resized.\n- A cached thumbnail belongs to one source image and one size.\n- Replacing the source image replaces every thumbnail of it.\n- The response carries cache headers so browsers and the CDN can hold it.\n- The endpoint is public, so the work it can be asked to do is bounded.\n\n## Notes for the reviewer\n\n`cache` is a shared Redis. `images.resize` decodes the source and is the\nexpensive part. `SIZES` is the list the product uses.\n","src/thumbs.py":'"""GET /img/:key"""\nimport db\nimport images\nimport storage\nfrom cache import cache\n\nSIZES = [80, 200, 400, 1200]\nCACHE_TTL = 86400\n\n\ndef thumbnail(key, width):\n    cached = cache.get(f"thumb:{key}")\n    if cached is not None:\n        return {"bytes": cached, "headers": {}}\n\n    source = storage.get(key)\n    out = images.resize(source, int(width))\n    cache.set(f"thumb:{key}", out, CACHE_TTL)\n    return {"bytes": out, "headers": {}}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Thumbnails on demand\n\n`GET /img/:key?w=400` resizes an image and caches the result. This PR adds it.\n\n## Rules\n\n- Only the sizes in the list are served. Anything else is refused, not\n  resized.\n- A cached thumbnail belongs to one source image and one size.\n- Replacing the source image replaces every thumbnail of it.\n- The response carries cache headers so browsers and the CDN can hold it.\n- The endpoint is public, so the work it can be asked to do is bounded.\n\n## Notes for the reviewer\n\n`cache` is a shared Redis. `images.resize` decodes the source and is the\nexpensive part. `SIZES` is the list the product uses.\n","src/thumbs.ts":'// GET /img/:key\nimport { cache } from "./cache";\nimport * as images from "./images";\nimport * as storage from "./storage";\n\nconst SIZES = [80, 200, 400, 1200];\nconst CACHE_TTL = 86400;\n\nexport async function thumbnail(key: string, width: string) {\n  const cached = await cache.get(`thumb:${key}`);\n  if (cached) return { bytes: cached, headers: {} };\n\n  const source = await storage.get(key);\n  const out = await images.resize(source, Number(width));\n  await cache.set(`thumb:${key}`, out, CACHE_TTL);\n  return { bytes: out, headers: {} };\n}\n'}}}},{slug:"playlist-order",title:"Reordering a playlist",difficulty:"Medium",area:"backend",domains:["media"],minutes:25,summary:"Drag a track, save the order. Count the writes this does for a playlist of ten thousand, then ask what happens when two people drag at once.",brief:["A teammate has opened this as a pull request. Reordering is a thing people do repeatedly and impatiently, often on a phone.","Move a track to position 1 in a playlist of ten thousand. Then have two people move different tracks at the same time. Then send a position of 0, and of 99999.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Reordering a playlist\n\nDragging a track to a new place. This PR saves the new order.\n\n## Rules\n\n- A move changes one track’s place. The others keep theirs.\n- Two people reordering the same playlist do not end up with tracks sharing a\n  position or an order nobody asked for.\n- Removing a track leaves the rest in order, with no gap anybody can see.\n- The position is ours. A client says where a track was dropped, not what its\n  stored position should be.\n- A playlist can hold ten thousand tracks and reordering is a common action.\n\n## Notes for the reviewer\n\n`playlist_tracks` is `(playlist_id, track_id, position)`, an integer position\nstarting at 1. The client sends the index it dropped the track at.\n","src/Playlist.java":'package media;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** Reordering a playlist. */\npublic final class Playlist {\n\n    public static int move(String playlistId, String trackId, int newPosition) {\n        List<Map<String, Object>> tracks = Db.all(\n                "SELECT track_id, position FROM playlist_tracks WHERE playlist_id = ? ORDER BY position", playlistId);\n        Map<String, Object> moving = null;\n        List<Map<String, Object>> rest = new ArrayList<>();\n        for (Map<String, Object> t : tracks) {\n            if (t.get("track_id").equals(trackId)) {\n                moving = t;\n            } else {\n                rest.add(t);\n            }\n        }\n        rest.add(newPosition - 1, moving);\n\n        for (int index = 0; index < rest.size(); index++) {\n            Db.run("UPDATE playlist_tracks SET position = ? WHERE playlist_id = ? AND track_id = ?",\n                    index + 1, playlistId, rest.get(index).get("track_id"));\n        }\n        return newPosition;\n    }\n\n    public static boolean remove(String playlistId, String trackId) {\n        Db.run("DELETE FROM playlist_tracks WHERE playlist_id = ? AND track_id = ?", playlistId, trackId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Reordering a playlist\n\nDragging a track to a new place. This PR saves the new order.\n\n## Rules\n\n- A move changes one track’s place. The others keep theirs.\n- Two people reordering the same playlist do not end up with tracks sharing a\n  position or an order nobody asked for.\n- Removing a track leaves the rest in order, with no gap anybody can see.\n- The position is ours. A client says where a track was dropped, not what its\n  stored position should be.\n- A playlist can hold ten thousand tracks and reordering is a common action.\n\n## Notes for the reviewer\n\n`playlist_tracks` is `(playlist_id, track_id, position)`, an integer position\nstarting at 1. The client sends the index it dropped the track at.\n","src/playlist.py":'"""Reordering a playlist."""\nimport db\n\n\ndef move(playlist_id, track_id, new_position):\n    tracks = db.all(\n        "SELECT track_id, position FROM playlist_tracks WHERE playlist_id = %s ORDER BY position",\n        (playlist_id,),\n    )\n    moving = [t for t in tracks if t["track_id"] == track_id][0]\n    rest = [t for t in tracks if t["track_id"] != track_id]\n    rest.insert(new_position - 1, moving)\n\n    for index, track in enumerate(rest, start=1):\n        db.run(\n            "UPDATE playlist_tracks SET position = %s WHERE playlist_id = %s AND track_id = %s",\n            (index, playlist_id, track["track_id"]),\n        )\n    return {"moved": track_id, "position": new_position}\n\n\ndef remove(playlist_id, track_id):\n    db.run(\n        "DELETE FROM playlist_tracks WHERE playlist_id = %s AND track_id = %s",\n        (playlist_id, track_id),\n    )\n    return {"removed": track_id}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Reordering a playlist\n\nDragging a track to a new place. This PR saves the new order.\n\n## Rules\n\n- A move changes one track’s place. The others keep theirs.\n- Two people reordering the same playlist do not end up with tracks sharing a\n  position or an order nobody asked for.\n- Removing a track leaves the rest in order, with no gap anybody can see.\n- The position is ours. A client says where a track was dropped, not what its\n  stored position should be.\n- A playlist can hold ten thousand tracks and reordering is a common action.\n\n## Notes for the reviewer\n\n`playlist_tracks` is `(playlist_id, track_id, position)`, an integer position\nstarting at 1. The client sends the index it dropped the track at.\n","src/playlist.ts":'// Reordering a playlist.\nimport { db } from "./db";\n\nexport async function move(playlistId: string, trackId: string, newPosition: number) {\n  const tracks = await db.all(\n    "SELECT track_id, position FROM playlist_tracks WHERE playlist_id = $1 ORDER BY position",\n    [playlistId],\n  );\n  const moving = tracks.find((t) => t.track_id === trackId);\n  const rest = tracks.filter((t) => t.track_id !== trackId);\n  rest.splice(newPosition - 1, 0, moving);\n\n  for (let index = 0; index < rest.length; index++) {\n    await db.run("UPDATE playlist_tracks SET position = $1 WHERE playlist_id = $2 AND track_id = $3", [\n      index + 1,\n      playlistId,\n      rest[index].track_id,\n    ]);\n  }\n  return { moved: trackId, position: newPosition };\n}\n\nexport async function remove(playlistId: string, trackId: string) {\n  await db.run("DELETE FROM playlist_tracks WHERE playlist_id = $1 AND track_id = $2", [playlistId, trackId]);\n  return { removed: trackId };\n}\n'}}}},{slug:"lesson-video",title:"Lesson video progress",difficulty:"Medium",area:"backend",domains:["edtech","media"],minutes:25,summary:"The player says where the student is, and the course believes it. Read the five rules, then read which of the two numbers the completion check uses.",brief:["A teammate has opened this as a pull request. Completion here feeds a certificate, so somebody has a reason to lie to it.","Drag the scrubber to the end. Then rewatch a lesson from the start. Then ask for the video of a course you never bought.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Lesson video progress\n\nA student watches a lesson. The player reports where they are, and the course\nmarks the lesson complete. This PR handles both.\n\n## Rules\n\n- Progress only moves forward. Rewatching does not take a lesson back to 40%.\n- A lesson is complete at 90% of its duration watched, counted as seconds\n  actually watched, not the furthest point reached.\n- Progress comes from the player, so it is checked against the lesson’s real\n  duration before it is stored.\n- A lesson video is only served to a student enrolled in that course.\n- The player reports every ten seconds, so the write path is cheap.\n\n## Notes for the reviewer\n\n`lesson_progress` is `(student_id, lesson_id, seconds_watched, position,\ncompleted_at)`. `lessons` carry `duration_seconds` and `course_id`.\n","src/Progress.java":'package learn;\n\nimport java.util.Map;\n\n/** Lesson video progress. */\npublic final class Progress {\n    private static final double COMPLETE_AT = 0.9;\n\n    public static long reportProgress(String studentId, String lessonId, long position, long secondsWatched) {\n        Map<String, Object> lesson =\n                Db.one("SELECT id, course_id, duration_seconds FROM lessons WHERE id = ?", lessonId);\n\n        Db.run("INSERT INTO lesson_progress (student_id, lesson_id, seconds_watched, position) VALUES (?, ?, ?, ?) "\n                + "ON CONFLICT (student_id, lesson_id) DO UPDATE SET seconds_watched = EXCLUDED.seconds_watched, "\n                + "position = EXCLUDED.position", studentId, lessonId, secondsWatched, position);\n\n        if (position >= (long) lesson.get("duration_seconds") * COMPLETE_AT) {\n            Db.run("UPDATE lesson_progress SET completed_at = now() WHERE student_id = ? AND lesson_id = ?",\n                    studentId, lessonId);\n        }\n        return position;\n    }\n\n    public static String videoUrl(String studentId, String lessonId) {\n        Map<String, Object> lesson = Db.one("SELECT id, video_key FROM lessons WHERE id = ?", lessonId);\n        return Storage.publicUrl((String) lesson.get("video_key"));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Lesson video progress\n\nA student watches a lesson. The player reports where they are, and the course\nmarks the lesson complete. This PR handles both.\n\n## Rules\n\n- Progress only moves forward. Rewatching does not take a lesson back to 40%.\n- A lesson is complete at 90% of its duration watched, counted as seconds\n  actually watched, not the furthest point reached.\n- Progress comes from the player, so it is checked against the lesson’s real\n  duration before it is stored.\n- A lesson video is only served to a student enrolled in that course.\n- The player reports every ten seconds, so the write path is cheap.\n\n## Notes for the reviewer\n\n`lesson_progress` is `(student_id, lesson_id, seconds_watched, position,\ncompleted_at)`. `lessons` carry `duration_seconds` and `course_id`.\n","src/progress.py":'"""Lesson video progress."""\nimport db\nimport storage\n\nCOMPLETE_AT = 0.9\n\n\ndef report_progress(student_id, lesson_id, position, seconds_watched):\n    lesson = db.one("SELECT id, course_id, duration_seconds FROM lessons WHERE id = %s", (lesson_id,))\n\n    db.run(\n        "INSERT INTO lesson_progress (student_id, lesson_id, seconds_watched, position) VALUES (%s, %s, %s, %s) "\n        "ON CONFLICT (student_id, lesson_id) DO UPDATE SET seconds_watched = EXCLUDED.seconds_watched, "\n        "position = EXCLUDED.position",\n        (student_id, lesson_id, seconds_watched, position),\n    )\n\n    if position >= lesson["duration_seconds"] * COMPLETE_AT:\n        db.run(\n            "UPDATE lesson_progress SET completed_at = now() WHERE student_id = %s AND lesson_id = %s",\n            (student_id, lesson_id),\n        )\n    return {"position": position}\n\n\ndef video_url(student_id, lesson_id):\n    lesson = db.one("SELECT id, video_key FROM lessons WHERE id = %s", (lesson_id,))\n    return {"url": storage.public_url(lesson["video_key"])}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Lesson video progress\n\nA student watches a lesson. The player reports where they are, and the course\nmarks the lesson complete. This PR handles both.\n\n## Rules\n\n- Progress only moves forward. Rewatching does not take a lesson back to 40%.\n- A lesson is complete at 90% of its duration watched, counted as seconds\n  actually watched, not the furthest point reached.\n- Progress comes from the player, so it is checked against the lesson’s real\n  duration before it is stored.\n- A lesson video is only served to a student enrolled in that course.\n- The player reports every ten seconds, so the write path is cheap.\n\n## Notes for the reviewer\n\n`lesson_progress` is `(student_id, lesson_id, seconds_watched, position,\ncompleted_at)`. `lessons` carry `duration_seconds` and `course_id`.\n","src/progress.ts":'// Lesson video progress.\nimport { db } from "./db";\nimport * as storage from "./storage";\n\nconst COMPLETE_AT = 0.9;\n\nexport async function reportProgress(\n  studentId: string,\n  lessonId: string,\n  position: number,\n  secondsWatched: number,\n) {\n  const lesson = await db.one("SELECT id, course_id, duration_seconds FROM lessons WHERE id = $1", [lessonId]);\n\n  await db.run(\n    "INSERT INTO lesson_progress (student_id, lesson_id, seconds_watched, position) VALUES ($1, $2, $3, $4) " +\n      "ON CONFLICT (student_id, lesson_id) DO UPDATE SET seconds_watched = EXCLUDED.seconds_watched, " +\n      "position = EXCLUDED.position",\n    [studentId, lessonId, secondsWatched, position],\n  );\n\n  if (position >= lesson.duration_seconds * COMPLETE_AT) {\n    await db.run("UPDATE lesson_progress SET completed_at = now() WHERE student_id = $1 AND lesson_id = $2", [\n      studentId,\n      lessonId,\n    ]);\n  }\n  return { position };\n}\n\nexport async function videoUrl(studentId: string, lessonId: string) {\n  const lesson = await db.one("SELECT id, video_key FROM lessons WHERE id = $1", [lessonId]);\n  return { url: storage.publicUrl(lesson.video_key) };\n}\n'}}}},{slug:"stream-keys",title:"Live stream keys",difficulty:"Medium",area:"security",domains:["media"],minutes:25,summary:"Twenty lines between an encoder and a live channel. Two columns are selected and never read, and the key is in the log on the first line.",brief:["A teammate has opened this as a pull request. Somebody who gets a stream key can broadcast as that creator, to their audience.","Revoke a key and connect again. Then find a key in the application logs. Then connect ten thousand times a minute.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Live stream keys\n\nA creator goes live by pointing their encoder at our ingest server with a\nstream key. This PR issues the key and lets the ingest server check one.\n\n## Rules\n\n- A stream key is a secret. It is shown to its creator, stored so that a leak\n  of the table does not hand somebody the ability to stream as them, and never\n  written to a log.\n- A key belongs to one creator and can be revoked and reissued at any time.\n  Revoking takes effect on the next connection.\n- A key that has not been used for ninety days stops working.\n- The ingest server checks a key on every connection, thousands of times a\n  minute, and a wrong key must not be distinguishable by how long the check\n  takes.\n- A live stream is tied to the key that started it, so a revoked key ends the\n  stream it started.\n\n## Notes for the reviewer\n\n`stream_keys` is `(creator_id, key, created_at, last_used_at, revoked_at)`.\n`hashing` wraps argon2. The ingest server calls `check_key` directly.\n","src/Streams.java":'package media;\n\nimport java.security.SecureRandom;\nimport java.util.HexFormat;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Issuing and checking stream keys. */\npublic final class Streams {\n    private static final Logger log = Logger.getLogger(Streams.class.getName());\n    private static final SecureRandom RANDOM = new SecureRandom();\n\n    public static String issueKey(String creatorId) {\n        byte[] bytes = new byte[16];\n        RANDOM.nextBytes(bytes);\n        String key = HexFormat.of().formatHex(bytes);\n        Db.run("INSERT INTO stream_keys (creator_id, key, created_at) VALUES (?, ?, now())", creatorId, key);\n        log.info("issued stream key " + key + " for creator " + creatorId);\n        return key;\n    }\n\n    public static String checkKey(String key) {\n        Map<String, Object> row =\n                Db.one("SELECT creator_id, revoked_at, last_used_at FROM stream_keys WHERE key = ?", key);\n        if (row == null) {\n            return null;\n        }\n\n        Db.run("UPDATE stream_keys SET last_used_at = now() WHERE key = ?", key);\n        return (String) row.get("creator_id");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Live stream keys\n\nA creator goes live by pointing their encoder at our ingest server with a\nstream key. This PR issues the key and lets the ingest server check one.\n\n## Rules\n\n- A stream key is a secret. It is shown to its creator, stored so that a leak\n  of the table does not hand somebody the ability to stream as them, and never\n  written to a log.\n- A key belongs to one creator and can be revoked and reissued at any time.\n  Revoking takes effect on the next connection.\n- A key that has not been used for ninety days stops working.\n- The ingest server checks a key on every connection, thousands of times a\n  minute, and a wrong key must not be distinguishable by how long the check\n  takes.\n- A live stream is tied to the key that started it, so a revoked key ends the\n  stream it started.\n\n## Notes for the reviewer\n\n`stream_keys` is `(creator_id, key, created_at, last_used_at, revoked_at)`.\n`hashing` wraps argon2. The ingest server calls `check_key` directly.\n","src/streams.py":'"""Issuing and checking stream keys."""\nimport logging\nimport secrets\n\nimport db\n\nlog = logging.getLogger(__name__)\n\n\ndef issue_key(creator_id):\n    key = secrets.token_hex(16)\n    db.run(\n        "INSERT INTO stream_keys (creator_id, key, created_at) VALUES (%s, %s, now())",\n        (creator_id, key),\n    )\n    log.info("issued stream key %s for creator %s", key, creator_id)\n    return {"key": key}\n\n\ndef check_key(key):\n    row = db.one("SELECT creator_id, revoked_at, last_used_at FROM stream_keys WHERE key = %s", (key,))\n    if row is None:\n        return None\n\n    db.run("UPDATE stream_keys SET last_used_at = now() WHERE key = %s", (key,))\n    return {"creator_id": row["creator_id"]}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Live stream keys\n\nA creator goes live by pointing their encoder at our ingest server with a\nstream key. This PR issues the key and lets the ingest server check one.\n\n## Rules\n\n- A stream key is a secret. It is shown to its creator, stored so that a leak\n  of the table does not hand somebody the ability to stream as them, and never\n  written to a log.\n- A key belongs to one creator and can be revoked and reissued at any time.\n  Revoking takes effect on the next connection.\n- A key that has not been used for ninety days stops working.\n- The ingest server checks a key on every connection, thousands of times a\n  minute, and a wrong key must not be distinguishable by how long the check\n  takes.\n- A live stream is tied to the key that started it, so a revoked key ends the\n  stream it started.\n\n## Notes for the reviewer\n\n`stream_keys` is `(creator_id, key, created_at, last_used_at, revoked_at)`.\n`hashing` wraps argon2. The ingest server calls `check_key` directly.\n","src/streams.ts":'// Issuing and checking stream keys.\nimport { randomBytes } from "node:crypto";\nimport { db } from "./db";\nimport { log } from "./log";\n\nexport async function issueKey(creatorId: string) {\n  const key = randomBytes(16).toString("hex");\n  await db.run("INSERT INTO stream_keys (creator_id, key, created_at) VALUES ($1, $2, now())", [creatorId, key]);\n  log.info("issued stream key %s for creator %s", key, creatorId);\n  return { key };\n}\n\nexport async function checkKey(key: string) {\n  const row = await db.one("SELECT creator_id, revoked_at, last_used_at FROM stream_keys WHERE key = $1", [key]);\n  if (!row) return null;\n\n  await db.run("UPDATE stream_keys SET last_used_at = now() WHERE key = $1", [key]);\n  return { creatorId: row.creator_id };\n}\n'}}}},{slug:"certificate-verify",title:"Verifying a certificate",difficulty:"Medium",area:"security",domains:["edtech"],minutes:25,summary:"A public page an employer opens, and the serial that addresses it. Read how the serial is made, then read what the page selects.",brief:["A teammate has opened this as a pull request. This page is public, unauthenticated, and linked from CVs.","Work out what you need to construct somebody else’s serial. Then revoke a certificate and open the link from the CV.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Verifying a certificate\n\nA certificate has a public page at `/verify/:serial` that an employer can\nopen. This PR issues the serial and serves that page.\n\n## Rules\n\n- A serial cannot be guessed from another one, and knowing a student’s name\n  does not let somebody construct theirs.\n- The public page shows the course, the date and the holder’s name, and\n  nothing else about the student.\n- A revoked certificate says so. It does not disappear, because a link in a\n  CV has to resolve to something.\n- A serial that does not exist and a revoked one are different answers.\n- The page is public and cacheable, but a revocation shows within an hour.\n\n## Notes for the reviewer\n\n`certificates` is `(serial, student_id, course_id, issued_on, revoked_at)`.\nThe verify page is served to anybody, with no session.\n","src/Verify.java":'package learn;\n\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.util.HexFormat;\nimport java.util.Map;\n\n/** Issuing and verifying certificates. */\npublic final class Verify {\n    private static final int CACHE_SECONDS = 86400;\n\n    public static String makeSerial(String studentId, String courseId) {\n        try {\n            byte[] digest = MessageDigest.getInstance("MD5")\n                    .digest((studentId + ":" + courseId).getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest).substring(0, 10).toUpperCase();\n        } catch (Exception e) {\n            throw new IllegalStateException(e);\n        }\n    }\n\n    public static String issue(String studentId, String courseId) {\n        String serial = makeSerial(studentId, courseId);\n        Db.run("INSERT INTO certificates (serial, student_id, course_id, issued_on) VALUES (?, ?, ?, now())",\n                serial, studentId, courseId);\n        return serial;\n    }\n\n    public static Map<String, Object> verifyPage(String serial) {\n        Map<String, Object> row = Db.one(\n                "SELECT c.serial, c.issued_on, c.revoked_at, s.name, s.email, s.phone, co.title "\n                        + "FROM certificates c JOIN students s ON s.id = c.student_id "\n                        + "JOIN courses co ON co.id = c.course_id "\n                        + "WHERE c.serial = ? AND c.revoked_at IS NULL", serial);\n        if (row == null) {\n            throw new NotFound("no such certificate");\n        }\n        return row;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Verifying a certificate\n\nA certificate has a public page at `/verify/:serial` that an employer can\nopen. This PR issues the serial and serves that page.\n\n## Rules\n\n- A serial cannot be guessed from another one, and knowing a student’s name\n  does not let somebody construct theirs.\n- The public page shows the course, the date and the holder’s name, and\n  nothing else about the student.\n- A revoked certificate says so. It does not disappear, because a link in a\n  CV has to resolve to something.\n- A serial that does not exist and a revoked one are different answers.\n- The page is public and cacheable, but a revocation shows within an hour.\n\n## Notes for the reviewer\n\n`certificates` is `(serial, student_id, course_id, issued_on, revoked_at)`.\nThe verify page is served to anybody, with no session.\n","src/verify.py":'"""Issuing and verifying certificates."""\nimport hashlib\n\nimport db\n\nCACHE_SECONDS = 86400\n\n\ndef make_serial(student_id, course_id):\n    seed = f"{student_id}:{course_id}"\n    return hashlib.md5(seed.encode()).hexdigest()[:10].upper()\n\n\ndef issue(student_id, course_id):\n    serial = make_serial(student_id, course_id)\n    db.run(\n        "INSERT INTO certificates (serial, student_id, course_id, issued_on) VALUES (%s, %s, %s, now())",\n        (serial, student_id, course_id),\n    )\n    return {"serial": serial}\n\n\ndef verify_page(serial):\n    row = db.one(\n        "SELECT c.serial, c.issued_on, c.revoked_at, s.name, s.email, s.phone, co.title "\n        "FROM certificates c JOIN students s ON s.id = c.student_id JOIN courses co ON co.id = c.course_id "\n        "WHERE c.serial = %s AND c.revoked_at IS NULL",\n        (serial,),\n    )\n    if row is None:\n        raise NotFound("no such certificate")\n    return {"certificate": row, "cache_seconds": CACHE_SECONDS}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Verifying a certificate\n\nA certificate has a public page at `/verify/:serial` that an employer can\nopen. This PR issues the serial and serves that page.\n\n## Rules\n\n- A serial cannot be guessed from another one, and knowing a student’s name\n  does not let somebody construct theirs.\n- The public page shows the course, the date and the holder’s name, and\n  nothing else about the student.\n- A revoked certificate says so. It does not disappear, because a link in a\n  CV has to resolve to something.\n- A serial that does not exist and a revoked one are different answers.\n- The page is public and cacheable, but a revocation shows within an hour.\n\n## Notes for the reviewer\n\n`certificates` is `(serial, student_id, course_id, issued_on, revoked_at)`.\nThe verify page is served to anybody, with no session.\n","src/verify.ts":'// Issuing and verifying certificates.\nimport { createHash } from "node:crypto";\nimport { db } from "./db";\n\nconst CACHE_SECONDS = 86400;\n\nexport function makeSerial(studentId: string, courseId: string) {\n  const seed = `${studentId}:${courseId}`;\n  return createHash("md5").update(seed).digest("hex").slice(0, 10).toUpperCase();\n}\n\nexport async function issue(studentId: string, courseId: string) {\n  const serial = makeSerial(studentId, courseId);\n  await db.run("INSERT INTO certificates (serial, student_id, course_id, issued_on) VALUES ($1, $2, $3, now())", [\n    serial,\n    studentId,\n    courseId,\n  ]);\n  return { serial };\n}\n\nexport async function verifyPage(serial: string) {\n  const row = await db.one(\n    "SELECT c.serial, c.issued_on, c.revoked_at, s.name, s.email, s.phone, co.title " +\n      "FROM certificates c JOIN students s ON s.id = c.student_id JOIN courses co ON co.id = c.course_id " +\n      "WHERE c.serial = $1 AND c.revoked_at IS NULL",\n    [serial],\n  );\n  if (!row) throw new NotFound("no such certificate");\n  return { certificate: row, cacheSeconds: CACHE_SECONDS };\n}\n'}}}},{slug:"attendance-marking",title:"Marking attendance",difficulty:"Medium",area:"backend",domains:["edtech"],minutes:25,summary:"A register of sixty students and the percentage it feeds. Mark the same class twice and then read the percentage.",brief:["A teammate has opened this as a pull request. Attendance decides exam eligibility in a lot of places, so the number at the end matters.","Save the register twice. Then cancel a class. Then have a teacher mark a class from another teacher’s course.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Marking attendance\n\nA teacher marks a class register. This PR saves it.\n\n## Rules\n\n- A student has one mark per class, and marking again corrects it rather than\n  adding a second.\n- A correction after the register is locked is recorded as a correction, with\n  who made it and when, and the original is kept.\n- A register is for one class on one date. A teacher may only mark classes\n  they teach.\n- The attendance percentage on a student’s record counts classes held, not\n  classes scheduled: a cancelled class is in neither number.\n- Marking a register of sixty students is one action, not sixty.\n\n## Notes for the reviewer\n\n`attendance` is `(class_id, student_id, status, marked_by, marked_at)` where\nstatus is `present`, `absent` or `late`. `classes` carry `teacher_id`,\n`held_on` and `cancelled`.\n","src/Attendance.java":'package learn;\n\nimport java.util.Map;\n\n/** Marking a register. */\npublic final class Attendance {\n\n    public static int mark(String classId, String teacherId, Map<String, String> marks) {\n        for (Map.Entry<String, String> entry : marks.entrySet()) {\n            Db.run("INSERT INTO attendance (class_id, student_id, status, marked_by, marked_at) "\n                    + "VALUES (?, ?, ?, ?, now())", classId, entry.getKey(), entry.getValue(), teacherId);\n        }\n        return marks.size();\n    }\n\n    public static int percentage(String studentId, String courseId) {\n        long held = (long) Db.one("SELECT count(*) AS n FROM classes WHERE course_id = ?", courseId).get("n");\n        long present = (long) Db.one("SELECT count(*) AS n FROM attendance a JOIN classes c ON c.id = a.class_id "\n                + "WHERE a.student_id = ? AND c.course_id = ? AND a.status = \'present\'",\n                studentId, courseId).get("n");\n        return Math.round((float) present / held * 100);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Marking attendance\n\nA teacher marks a class register. This PR saves it.\n\n## Rules\n\n- A student has one mark per class, and marking again corrects it rather than\n  adding a second.\n- A correction after the register is locked is recorded as a correction, with\n  who made it and when, and the original is kept.\n- A register is for one class on one date. A teacher may only mark classes\n  they teach.\n- The attendance percentage on a student’s record counts classes held, not\n  classes scheduled: a cancelled class is in neither number.\n- Marking a register of sixty students is one action, not sixty.\n\n## Notes for the reviewer\n\n`attendance` is `(class_id, student_id, status, marked_by, marked_at)` where\nstatus is `present`, `absent` or `late`. `classes` carry `teacher_id`,\n`held_on` and `cancelled`.\n","src/attendance.py":'"""Marking a register."""\nimport db\n\n\ndef mark(class_id, teacher_id, marks):\n    for student_id, status in marks.items():\n        db.run(\n            "INSERT INTO attendance (class_id, student_id, status, marked_by, marked_at) "\n            "VALUES (%s, %s, %s, %s, now())",\n            (class_id, student_id, status, teacher_id),\n        )\n    return {"marked": len(marks)}\n\n\ndef percentage(student_id, course_id):\n    held = db.one(\n        "SELECT count(*) AS n FROM classes WHERE course_id = %s",\n        (course_id,),\n    )["n"]\n    present = db.one(\n        "SELECT count(*) AS n FROM attendance a JOIN classes c ON c.id = a.class_id "\n        "WHERE a.student_id = %s AND c.course_id = %s AND a.status = \'present\'",\n        (student_id, course_id),\n    )["n"]\n    return {"percent": round(present / held * 100)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Marking attendance\n\nA teacher marks a class register. This PR saves it.\n\n## Rules\n\n- A student has one mark per class, and marking again corrects it rather than\n  adding a second.\n- A correction after the register is locked is recorded as a correction, with\n  who made it and when, and the original is kept.\n- A register is for one class on one date. A teacher may only mark classes\n  they teach.\n- The attendance percentage on a student’s record counts classes held, not\n  classes scheduled: a cancelled class is in neither number.\n- Marking a register of sixty students is one action, not sixty.\n\n## Notes for the reviewer\n\n`attendance` is `(class_id, student_id, status, marked_by, marked_at)` where\nstatus is `present`, `absent` or `late`. `classes` carry `teacher_id`,\n`held_on` and `cancelled`.\n","src/attendance.ts":'// Marking a register.\nimport { db } from "./db";\n\nexport async function mark(classId: string, teacherId: string, marks: Record<string, string>) {\n  for (const [studentId, status] of Object.entries(marks)) {\n    await db.run(\n      "INSERT INTO attendance (class_id, student_id, status, marked_by, marked_at) VALUES ($1, $2, $3, $4, now())",\n      [classId, studentId, status, teacherId],\n    );\n  }\n  return { marked: Object.keys(marks).length };\n}\n\nexport async function percentage(studentId: string, courseId: string) {\n  const held = Number((await db.one("SELECT count(*) AS n FROM classes WHERE course_id = $1", [courseId])).n);\n  const present = Number(\n    (\n      await db.one(\n        "SELECT count(*) AS n FROM attendance a JOIN classes c ON c.id = a.class_id " +\n          "WHERE a.student_id = $1 AND c.course_id = $2 AND a.status = \'present\'",\n        [studentId, courseId],\n      )\n    ).n,\n  );\n  return { percent: Math.round((present / held) * 100) };\n}\n'}}}},{slug:"parent-access",title:"Parent access to a student",difficulty:"Medium",area:"security",domains:["edtech","identity"],minutes:25,summary:"One guardian link and one query. Four columns are selected to decide access and two of them are never read.",brief:["A teammate has opened this as a pull request. Read it as the school’s lawyer would, and then as a student who has just turned eighteen.","Withdraw a guardian link and load the page. Then read the column list on the report query out loud.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Parent access to a student\n\nA parent logs in and sees their child. This PR is the endpoint behind that.\n\n## Rules\n\n- A parent sees a student only through a link a school administrator made.\n- A parent sees marks, attendance and fees. Not the teacher’s private notes,\n  not other students, not the disciplinary file.\n- A student over eighteen controls their own record: the link stops granting\n  access until the student re-approves it.\n- A link can be withdrawn, and that takes effect at once.\n- Every parent read is auditable, because a family dispute eventually asks who\n  saw what.\n\n## Notes for the reviewer\n\n`guardians` is `(parent_id, student_id, approved_at, withdrawn_at)`.\n`students` carry `dob`. `reports` holds marks, attendance, fees, private notes\nand the disciplinary record.\n","src/Parents.java":'package learn;\n\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** What a parent may see. */\npublic final class Parents {\n\n    public static Map<String, Object> studentView(String parentId, String studentId) {\n        Map<String, Object> link = Db.one("SELECT parent_id, student_id, approved_at, withdrawn_at FROM guardians "\n                + "WHERE parent_id = ? AND student_id = ?", parentId, studentId);\n        if (link == null) {\n            throw new Forbidden("not a guardian of this student");\n        }\n\n        Map<String, Object> student = Db.one("SELECT id, name, dob FROM students WHERE id = ?", studentId);\n        Map<String, Object> report = Db.one(\n                "SELECT marks, attendance, fees, private_notes, disciplinary FROM reports WHERE student_id = ?",\n                studentId);\n        Map<String, Object> out = new HashMap<>();\n        out.put("student", student);\n        out.put("report", report);\n        return out;\n    }\n\n    public static List<Map<String, Object>> children(String parentId) {\n        return Db.all("SELECT s.id, s.name, s.class_name FROM guardians g JOIN students s ON s.id = g.student_id "\n                + "WHERE g.parent_id = ?", parentId);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Parent access to a student\n\nA parent logs in and sees their child. This PR is the endpoint behind that.\n\n## Rules\n\n- A parent sees a student only through a link a school administrator made.\n- A parent sees marks, attendance and fees. Not the teacher’s private notes,\n  not other students, not the disciplinary file.\n- A student over eighteen controls their own record: the link stops granting\n  access until the student re-approves it.\n- A link can be withdrawn, and that takes effect at once.\n- Every parent read is auditable, because a family dispute eventually asks who\n  saw what.\n\n## Notes for the reviewer\n\n`guardians` is `(parent_id, student_id, approved_at, withdrawn_at)`.\n`students` carry `dob`. `reports` holds marks, attendance, fees, private notes\nand the disciplinary record.\n","src/parents.py":'"""What a parent may see."""\nimport db\n\n\ndef student_view(parent_id, student_id):\n    link = db.one(\n        "SELECT parent_id, student_id, approved_at, withdrawn_at FROM guardians "\n        "WHERE parent_id = %s AND student_id = %s",\n        (parent_id, student_id),\n    )\n    if link is None:\n        raise Forbidden("not a guardian of this student")\n\n    student = db.one("SELECT id, name, dob FROM students WHERE id = %s", (student_id,))\n    report = db.one(\n        "SELECT marks, attendance, fees, private_notes, disciplinary FROM reports WHERE student_id = %s",\n        (student_id,),\n    )\n    return {"student": student, "report": report}\n\n\ndef children(parent_id):\n    return db.all(\n        "SELECT s.id, s.name, s.class_name FROM guardians g JOIN students s ON s.id = g.student_id "\n        "WHERE g.parent_id = %s",\n        (parent_id,),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":"# Parent access to a student\n\nA parent logs in and sees their child. This PR is the endpoint behind that.\n\n## Rules\n\n- A parent sees a student only through a link a school administrator made.\n- A parent sees marks, attendance and fees. Not the teacher’s private notes,\n  not other students, not the disciplinary file.\n- A student over eighteen controls their own record: the link stops granting\n  access until the student re-approves it.\n- A link can be withdrawn, and that takes effect at once.\n- Every parent read is auditable, because a family dispute eventually asks who\n  saw what.\n\n## Notes for the reviewer\n\n`guardians` is `(parent_id, student_id, approved_at, withdrawn_at)`.\n`students` carry `dob`. `reports` holds marks, attendance, fees, private notes\nand the disciplinary record.\n","src/parents.ts":'// What a parent may see.\nimport { db } from "./db";\n\nexport async function studentView(parentId: string, studentId: string) {\n  const link = await db.one(\n    "SELECT parent_id, student_id, approved_at, withdrawn_at FROM guardians " +\n      "WHERE parent_id = $1 AND student_id = $2",\n    [parentId, studentId],\n  );\n  if (!link) throw new Forbidden("not a guardian of this student");\n\n  const student = await db.one("SELECT id, name, dob FROM students WHERE id = $1", [studentId]);\n  const report = await db.one(\n    "SELECT marks, attendance, fees, private_notes, disciplinary FROM reports WHERE student_id = $1",\n    [studentId],\n  );\n  return { student, report };\n}\n\nexport async function children(parentId: string) {\n  return db.all(\n    "SELECT s.id, s.name, s.class_name FROM guardians g JOIN students s ON s.id = g.student_id " +\n      "WHERE g.parent_id = $1",\n    [parentId],\n  );\n}\n'}}}},{slug:"question-bank-import",title:"Importing a question bank",difficulty:"Medium",area:"data",domains:["edtech"],minutes:25,summary:"A spreadsheet of questions, straight into the bank. The second rule in the README is about how the answer is stored, and the insert stores the other thing.",brief:["A teammate has opened this as a pull request. What this writes becomes the quiz a hundred students sit.","Import a file with a blank stem, one with a letter E in the answer column, and one with a comma inside an option. Then import the same file twice.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Importing a question bank\n\nA teacher uploads a spreadsheet of questions. This PR imports it.\n\n## Rules\n\n- A row is imported whole or not at all, and the import tells the teacher\n  which rows failed and why.\n- The correct answer is stored as the option text, not as the letter the\n  spreadsheet used, because the options are shuffled when the quiz is served.\n- A question needs between two and six options, exactly one of them correct,\n  and a non-empty stem.\n- Importing the same file twice does not double the bank. A row is the same\n  row when its stem and its options match.\n- The file is a teacher’s, not a stranger’s, but it is still a file: the\n  import does not trust its size or its contents.\n\n## Notes for the reviewer\n\n`questions` is `(quiz_id, stem, options, answer, imported_hash)`. The\nspreadsheet columns are stem, four option columns, and a letter A to D.\n","src/ImportBank.java":'package learn;\n\nimport java.util.Arrays;\nimport java.util.List;\n\n/** Importing a question bank. */\npublic final class ImportBank {\n    private static final List<String> LETTERS = List.of("A", "B", "C", "D");\n\n    public static int importQuestions(String quizId, String text) {\n        List<String[]> rows = Csv.parse(text);\n        int imported = 0;\n        for (String[] row : rows.subList(1, rows.size())) {\n            String stem = row[0];\n            List<String> options = Arrays.asList(row[1], row[2], row[3], row[4]);\n            int answerIndex = LETTERS.indexOf(row[5]);\n\n            Db.run("INSERT INTO questions (quiz_id, stem, options, answer) VALUES (?, ?, ?, ?)",\n                    quizId, stem, options, answerIndex);\n            imported++;\n        }\n        return imported;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Importing a question bank\n\nA teacher uploads a spreadsheet of questions. This PR imports it.\n\n## Rules\n\n- A row is imported whole or not at all, and the import tells the teacher\n  which rows failed and why.\n- The correct answer is stored as the option text, not as the letter the\n  spreadsheet used, because the options are shuffled when the quiz is served.\n- A question needs between two and six options, exactly one of them correct,\n  and a non-empty stem.\n- Importing the same file twice does not double the bank. A row is the same\n  row when its stem and its options match.\n- The file is a teacher’s, not a stranger’s, but it is still a file: the\n  import does not trust its size or its contents.\n\n## Notes for the reviewer\n\n`questions` is `(quiz_id, stem, options, answer, imported_hash)`. The\nspreadsheet columns are stem, four option columns, and a letter A to D.\n","src/import_bank.py":'"""Importing a question bank."""\nimport csv\nimport io\n\nimport db\n\nLETTERS = ["A", "B", "C", "D"]\n\n\ndef import_questions(quiz_id, upload):\n    rows = list(csv.reader(io.StringIO(upload.read().decode("utf-8"))))\n    imported = 0\n    for row in rows[1:]:\n        stem = row[0]\n        options = [row[1], row[2], row[3], row[4]]\n        answer_index = LETTERS.index(row[5])\n\n        db.run(\n            "INSERT INTO questions (quiz_id, stem, options, answer) VALUES (%s, %s, %s, %s)",\n            (quiz_id, stem, options, answer_index),\n        )\n        imported += 1\n    return {"imported": imported}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Importing a question bank\n\nA teacher uploads a spreadsheet of questions. This PR imports it.\n\n## Rules\n\n- A row is imported whole or not at all, and the import tells the teacher\n  which rows failed and why.\n- The correct answer is stored as the option text, not as the letter the\n  spreadsheet used, because the options are shuffled when the quiz is served.\n- A question needs between two and six options, exactly one of them correct,\n  and a non-empty stem.\n- Importing the same file twice does not double the bank. A row is the same\n  row when its stem and its options match.\n- The file is a teacher’s, not a stranger’s, but it is still a file: the\n  import does not trust its size or its contents.\n\n## Notes for the reviewer\n\n`questions` is `(quiz_id, stem, options, answer, imported_hash)`. The\nspreadsheet columns are stem, four option columns, and a letter A to D.\n","src/importBank.ts":'// Importing a question bank.\nimport { db } from "./db";\nimport { parseCsv } from "./csv";\n\nconst LETTERS = ["A", "B", "C", "D"];\n\nexport async function importQuestions(quizId: string, text: string) {\n  const rows = parseCsv(text);\n  let imported = 0;\n  for (const row of rows.slice(1)) {\n    const stem = row[0];\n    const options = [row[1], row[2], row[3], row[4]];\n    const answerIndex = LETTERS.indexOf(row[5]);\n\n    await db.run("INSERT INTO questions (quiz_id, stem, options, answer) VALUES ($1, $2, $3, $4)", [\n      quizId,\n      stem,\n      options,\n      answerIndex,\n    ]);\n    imported += 1;\n  }\n  return { imported };\n}\n'}}}},{slug:"course-pricing",title:"What a course costs",difficulty:"Medium",area:"money",domains:["edtech","payments"],minutes:25,summary:"A list price, a sale, a student discount and a coupon, applied one after another. Read the order they are applied in against the five rules.",brief:["A teammate has opened this as a pull request. The number it returns is what a card is charged.","Take a course whose sale ended last week. Then a student with a 20% discount and a 50% coupon. Then a flat coupon bigger than the price.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# What a course costs\n\nCourses have a list price, a sale price, coupons and a student discount. This\nPR works out what one student pays.\n\n## Rules\n\n- Amounts are paise, as integers. The final amount is what the gateway is\n  charged.\n- The sale price replaces the list price while the sale is on. A coupon then\n  applies to whatever price is in force.\n- One coupon per order. A percentage coupon never takes more than its stated\n  cap.\n- The student discount and a coupon do not stack: the student pays the better\n  of the two, not both.\n- A price is never below zero, and a free course is free without going near\n  the gateway.\n\n## Notes for the reviewer\n\n`courses` carry `list_paise`, `sale_paise`, `sale_until`. Coupons carry\n`kind` (`percent` or `flat`), `value` and `cap_paise`. The student discount is\na percentage on the profile.\n","src/Pricing.java":'package learn;\n\nimport java.util.Map;\n\n/** What a student pays. */\npublic final class Pricing {\n\n    public static long priceFor(String courseId, String studentId, String couponCode) {\n        Map<String, Object> course =\n                Db.one("SELECT id, list_paise, sale_paise, sale_until FROM courses WHERE id = ?", courseId);\n        Map<String, Object> student = Db.one("SELECT id, discount_percent FROM students WHERE id = ?", studentId);\n\n        double price = (long) course.get("list_paise");\n        if (course.get("sale_paise") != null) {\n            price = (long) course.get("sale_paise");\n        }\n\n        int discount = (int) student.get("discount_percent");\n        if (discount > 0) {\n            price = price - price * discount / 100;\n        }\n\n        if (couponCode != null) {\n            Map<String, Object> coupon = Db.one("SELECT kind, value, cap_paise FROM coupons WHERE code = ?", couponCode);\n            if ("percent".equals(coupon.get("kind"))) {\n                price = price - price * (int) coupon.get("value") / 100;\n            } else {\n                price = price - (long) coupon.get("value");\n            }\n        }\n\n        return (long) price;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# What a course costs\n\nCourses have a list price, a sale price, coupons and a student discount. This\nPR works out what one student pays.\n\n## Rules\n\n- Amounts are paise, as integers. The final amount is what the gateway is\n  charged.\n- The sale price replaces the list price while the sale is on. A coupon then\n  applies to whatever price is in force.\n- One coupon per order. A percentage coupon never takes more than its stated\n  cap.\n- The student discount and a coupon do not stack: the student pays the better\n  of the two, not both.\n- A price is never below zero, and a free course is free without going near\n  the gateway.\n\n## Notes for the reviewer\n\n`courses` carry `list_paise`, `sale_paise`, `sale_until`. Coupons carry\n`kind` (`percent` or `flat`), `value` and `cap_paise`. The student discount is\na percentage on the profile.\n","src/pricing.py":'"""What a student pays."""\nfrom datetime import datetime, timezone\n\nimport db\n\n\ndef price_for(course_id, student_id, coupon_code=None):\n    course = db.one("SELECT id, list_paise, sale_paise, sale_until FROM courses WHERE id = %s", (course_id,))\n    student = db.one("SELECT id, discount_percent FROM students WHERE id = %s", (student_id,))\n\n    price = course["list_paise"]\n    if course["sale_paise"] is not None:\n        price = course["sale_paise"]\n\n    if student["discount_percent"]:\n        price = price - price * student["discount_percent"] / 100\n\n    if coupon_code:\n        coupon = db.one("SELECT kind, value, cap_paise FROM coupons WHERE code = %s", (coupon_code,))\n        if coupon["kind"] == "percent":\n            price = price - price * coupon["value"] / 100\n        else:\n            price = price - coupon["value"]\n\n    return {"paise": int(price)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# What a course costs\n\nCourses have a list price, a sale price, coupons and a student discount. This\nPR works out what one student pays.\n\n## Rules\n\n- Amounts are paise, as integers. The final amount is what the gateway is\n  charged.\n- The sale price replaces the list price while the sale is on. A coupon then\n  applies to whatever price is in force.\n- One coupon per order. A percentage coupon never takes more than its stated\n  cap.\n- The student discount and a coupon do not stack: the student pays the better\n  of the two, not both.\n- A price is never below zero, and a free course is free without going near\n  the gateway.\n\n## Notes for the reviewer\n\n`courses` carry `list_paise`, `sale_paise`, `sale_until`. Coupons carry\n`kind` (`percent` or `flat`), `value` and `cap_paise`. The student discount is\na percentage on the profile.\n","src/pricing.ts":'// What a student pays.\nimport { db } from "./db";\n\nexport async function priceFor(courseId: string, studentId: string, couponCode?: string) {\n  const course = await db.one("SELECT id, list_paise, sale_paise, sale_until FROM courses WHERE id = $1", [courseId]);\n  const student = await db.one("SELECT id, discount_percent FROM students WHERE id = $1", [studentId]);\n\n  let price = course.list_paise;\n  if (course.sale_paise !== null) {\n    price = course.sale_paise;\n  }\n\n  if (student.discount_percent) {\n    price = price - (price * student.discount_percent) / 100;\n  }\n\n  if (couponCode) {\n    const coupon = await db.one("SELECT kind, value, cap_paise FROM coupons WHERE code = $1", [couponCode]);\n    if (coupon.kind === "percent") {\n      price = price - (price * coupon.value) / 100;\n    } else {\n      price = price - coupon.value;\n    }\n  }\n\n  return { paise: Math.trunc(price) };\n}\n'}}}},{slug:"bank-statement",title:"The monthly statement",difficulty:"Medium",area:"money",domains:["fintech","analytics"],minutes:25,summary:"Twenty-five lines a customer reads once a month and sometimes takes to a bank. Read the cache key first.",brief:["A teammate has opened this as a pull request. A statement is a document people rely on, and this one is derived rather than stored.","Open last month’s statement, then open it again next week. Then open it as a different customer. Then look at a transaction at 04:00 IST on the first.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The monthly statement\n\nA customer opens their statement for a month. This PR builds it and caches the\nrendered copy.\n\n## Rules\n\n- A month runs from the first to the last day in the customer’s zone, which is\n  Asia/Kolkata.\n- The opening balance is the balance at the first instant of the month, and\n  closing is opening plus the movements in it. The three always agree.\n- Only settled transactions are on a statement. A pending authorisation is\n  shown separately and is not in the balances.\n- A statement for a month that has ended never changes.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`transactions` carry `amount_paise` (negative for debits), `status` and\n`settled_at`. `accounts` carry the current `balance_paise`. `cache` is Redis.\n","src/Statement.java":'package bank;\n\nimport java.time.LocalDate;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** Building a monthly statement. */\npublic final class Statement {\n    private static final int CACHE_TTL = 3600;\n\n    public static Map<String, Object> statement(String accountId, int year, int month) {\n        Object cached = Cache.get("statement:" + year + "-" + month);\n        if (cached != null) {\n            return (Map<String, Object>) cached;\n        }\n\n        LocalDate first = LocalDate.of(year, month, 1);\n        LocalDate last = first.plusMonths(1);\n\n        List<Map<String, Object>> rows = Db.all("SELECT id, amount_paise, status, settled_at FROM transactions "\n                + "WHERE account_id = ? AND settled_at >= ? AND settled_at < ? ORDER BY settled_at",\n                accountId, first, last);\n\n        Map<String, Object> account = Db.one("SELECT balance_paise FROM accounts WHERE id = ?", accountId);\n        long movements = 0;\n        for (Map<String, Object> r : rows) {\n            movements += (long) r.get("amount_paise");\n        }\n        long closing = (long) account.get("balance_paise");\n        long opening = closing - movements;\n\n        Map<String, Object> body = new HashMap<>();\n        body.put("opening", opening);\n        body.put("closing", closing);\n        body.put("rows", rows);\n        Cache.set("statement:" + year + "-" + month, body, CACHE_TTL);\n        return body;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The monthly statement\n\nA customer opens their statement for a month. This PR builds it and caches the\nrendered copy.\n\n## Rules\n\n- A month runs from the first to the last day in the customer’s zone, which is\n  Asia/Kolkata.\n- The opening balance is the balance at the first instant of the month, and\n  closing is opening plus the movements in it. The three always agree.\n- Only settled transactions are on a statement. A pending authorisation is\n  shown separately and is not in the balances.\n- A statement for a month that has ended never changes.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`transactions` carry `amount_paise` (negative for debits), `status` and\n`settled_at`. `accounts` carry the current `balance_paise`. `cache` is Redis.\n","src/statement.py":'"""Building a monthly statement."""\nfrom datetime import date\n\nimport db\nfrom cache import cache\n\nCACHE_TTL = 3600\n\n\ndef statement(account_id, year, month):\n    cached = cache.get(f"statement:{year}-{month}")\n    if cached is not None:\n        return cached\n\n    first = date(year, month, 1)\n    last = date(year + (month // 12), (month % 12) + 1, 1)\n\n    rows = db.all(\n        "SELECT id, amount_paise, status, settled_at FROM transactions "\n        "WHERE account_id = %s AND settled_at >= %s AND settled_at < %s ORDER BY settled_at",\n        (account_id, first, last),\n    )\n\n    account = db.one("SELECT balance_paise FROM accounts WHERE id = %s", (account_id,))\n    movements = sum(r["amount_paise"] for r in rows)\n    closing = account["balance_paise"]\n    opening = closing - movements\n\n    body = {"opening": opening, "closing": closing, "rows": rows}\n    cache.set(f"statement:{year}-{month}", body, CACHE_TTL)\n    return body\n'}},typescript:{entry:"README.md",files:{"README.md":"# The monthly statement\n\nA customer opens their statement for a month. This PR builds it and caches the\nrendered copy.\n\n## Rules\n\n- A month runs from the first to the last day in the customer’s zone, which is\n  Asia/Kolkata.\n- The opening balance is the balance at the first instant of the month, and\n  closing is opening plus the movements in it. The three always agree.\n- Only settled transactions are on a statement. A pending authorisation is\n  shown separately and is not in the balances.\n- A statement for a month that has ended never changes.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`transactions` carry `amount_paise` (negative for debits), `status` and\n`settled_at`. `accounts` carry the current `balance_paise`. `cache` is Redis.\n","src/statement.ts":'// Building a monthly statement.\nimport { cache } from "./cache";\nimport { db } from "./db";\n\nconst CACHE_TTL = 3600;\n\nexport async function statement(accountId: string, year: number, month: number) {\n  const cached = await cache.get(`statement:${year}-${month}`);\n  if (cached) return cached;\n\n  const first = `${year}-${String(month).padStart(2, "0")}-01`;\n  const last = month === 12 ? `${year + 1}-01-01` : `${year}-${String(month + 1).padStart(2, "0")}-01`;\n\n  const rows = await db.all(\n    "SELECT id, amount_paise, status, settled_at FROM transactions " +\n      "WHERE account_id = $1 AND settled_at >= $2 AND settled_at < $3 ORDER BY settled_at",\n    [accountId, first, last],\n  );\n\n  const account = await db.one("SELECT balance_paise FROM accounts WHERE id = $1", [accountId]);\n  const movements = rows.reduce((sum, r) => sum + Number(r.amount_paise), 0);\n  const closing = Number(account.balance_paise);\n  const opening = closing - movements;\n\n  const body = { opening, closing, rows };\n  await cache.set(`statement:${year}-${month}`, body, CACHE_TTL);\n  return body;\n}\n'}}}},{slug:"kyc-status",title:"KYC status",difficulty:"Medium",area:"security",domains:["fintech","identity"],minutes:25,summary:"A callback from the verification provider, twenty lines, and the signature header arrives as a parameter and is never opened.",brief:["A teammate has opened this as a pull request. Whoever can post to this endpoint decides who is verified at a bank.","Post to it yourself with a customer id you chose. Then let the provider retry an old callback after a newer one. Then read the log line.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# KYC status\n\nIdentity documents go to a verification provider, and a callback tells us what\nthey decided. This PR is our side.\n\n## Rules\n\n- The status moves forward only: unverified, pending, verified or rejected. A\n  verified customer is never moved back by a late or repeated callback.\n- The callback is signed. An unsigned or wrongly signed call is refused and\n  recorded.\n- The provider’s reference decides which customer a callback is about. A\n  customer id in the body is not trusted.\n- Nothing from a document reaches the logs: no number, no name, no image URL.\n- A verification expires after two years and the customer is asked again.\n\n## Notes for the reviewer\n\n`kyc` is `(customer_id, status, provider_ref, verified_at, updated_at)`.\n`verify_signature(body, header)` exists. The provider retries a callback until\nit gets a 2xx.\n","src/Kyc.java":'package bank;\n\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** The KYC provider callback. */\npublic final class Kyc {\n    private static final Logger log = Logger.getLogger(Kyc.class.getName());\n\n    public static boolean handleCallback(Map<String, String> body, String signatureHeader) {\n        log.info("kyc callback: " + body);\n\n        String customerId = body.get("customer_id");\n        String status = body.get("status");\n\n        Db.run("UPDATE kyc SET status = ?, verified_at = now(), updated_at = now() WHERE customer_id = ?",\n                status, customerId);\n        return true;\n    }\n\n    public static boolean isVerified(String customerId) {\n        Map<String, Object> row = Db.one("SELECT status, verified_at FROM kyc WHERE customer_id = ?", customerId);\n        return row != null && "verified".equals(row.get("status"));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# KYC status\n\nIdentity documents go to a verification provider, and a callback tells us what\nthey decided. This PR is our side.\n\n## Rules\n\n- The status moves forward only: unverified, pending, verified or rejected. A\n  verified customer is never moved back by a late or repeated callback.\n- The callback is signed. An unsigned or wrongly signed call is refused and\n  recorded.\n- The provider’s reference decides which customer a callback is about. A\n  customer id in the body is not trusted.\n- Nothing from a document reaches the logs: no number, no name, no image URL.\n- A verification expires after two years and the customer is asked again.\n\n## Notes for the reviewer\n\n`kyc` is `(customer_id, status, provider_ref, verified_at, updated_at)`.\n`verify_signature(body, header)` exists. The provider retries a callback until\nit gets a 2xx.\n","src/kyc.py":'"""The KYC provider callback."""\nimport logging\n\nimport db\n\nlog = logging.getLogger(__name__)\n\n\ndef handle_callback(body, signature_header):\n    log.info("kyc callback: %s", body)\n\n    customer_id = body["customer_id"]\n    status = body["status"]\n\n    db.run(\n        "UPDATE kyc SET status = %s, verified_at = now(), updated_at = now() WHERE customer_id = %s",\n        (status, customer_id),\n    )\n    return {"ok": True}\n\n\ndef is_verified(customer_id):\n    row = db.one("SELECT status, verified_at FROM kyc WHERE customer_id = %s", (customer_id,))\n    return row is not None and row["status"] == "verified"\n'}},typescript:{entry:"README.md",files:{"README.md":"# KYC status\n\nIdentity documents go to a verification provider, and a callback tells us what\nthey decided. This PR is our side.\n\n## Rules\n\n- The status moves forward only: unverified, pending, verified or rejected. A\n  verified customer is never moved back by a late or repeated callback.\n- The callback is signed. An unsigned or wrongly signed call is refused and\n  recorded.\n- The provider’s reference decides which customer a callback is about. A\n  customer id in the body is not trusted.\n- Nothing from a document reaches the logs: no number, no name, no image URL.\n- A verification expires after two years and the customer is asked again.\n\n## Notes for the reviewer\n\n`kyc` is `(customer_id, status, provider_ref, verified_at, updated_at)`.\n`verify_signature(body, header)` exists. The provider retries a callback until\nit gets a 2xx.\n","src/kyc.ts":'// The KYC provider callback.\nimport { db } from "./db";\nimport { log } from "./log";\n\nexport async function handleCallback(body: Record<string, string>, signatureHeader: string) {\n  log.info("kyc callback: %o", body);\n\n  const customerId = body.customer_id;\n  const status = body.status;\n\n  await db.run("UPDATE kyc SET status = $1, verified_at = now(), updated_at = now() WHERE customer_id = $2", [\n    status,\n    customerId,\n  ]);\n  return { ok: true };\n}\n\nexport async function isVerified(customerId: string) {\n  const row = await db.one("SELECT status, verified_at FROM kyc WHERE customer_id = $1", [customerId]);\n  return row !== null && row.status === "verified";\n}\n'}}}},{slug:"dispute-flow",title:"Disputes and chargebacks",difficulty:"Medium",area:"money",domains:["fintech","payments"],minutes:25,summary:"Three notices, three branches, and money moving in each. Follow one charge through open, then through won, and count what happened to the balance.",brief:["A teammate has opened this as a pull request. Every branch moves real money between a customer and a merchant.","Send the open notice twice, which networks do. Then send won. Then ask whether the merchant may still send evidence at 23:00 on the deadline.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Disputes and chargebacks\n\nA customer disputes a charge. The network gives us a window to send evidence,\nand then decides. This PR handles both ends.\n\n## Rules\n\n- Opening a dispute credits the customer provisionally and freezes the amount\n  on the merchant.\n- If we win, the provisional credit is reversed and the merchant is released.\n  If we lose, the credit stands and the freeze becomes a debit.\n- A dispute is opened once per charge. A second notice for the same charge\n  updates the one that exists.\n- The evidence deadline comes from the network as an instant. It is shown to\n  the merchant in their zone and enforced against the instant.\n- Every state change is recorded, and money only moves inside a transaction.\n\n## Notes for the reviewer\n\n`disputes` is `(charge_id, status, amount_paise, evidence_due_at)`. `ledger`\nholds the movements. The network posts a notice for open, won and lost.\n","src/Disputes.java":'package bank;\n\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.Map;\n\n/** Dispute notices from the network. */\npublic final class Disputes {\n\n    public static String onNotice(Map<String, Object> notice) {\n        Map<String, Object> charge = Db.one(\n                "SELECT id, merchant_id, customer_id, amount_paise FROM charges WHERE id = ?",\n                notice.get("charge_id"));\n\n        if ("open".equals(notice.get("type"))) {\n            Db.run("INSERT INTO disputes (charge_id, status, amount_paise, evidence_due_at) VALUES (?, \'open\', ?, ?)",\n                    charge.get("id"), charge.get("amount_paise"), notice.get("evidence_due_at"));\n            Ledger.credit((String) charge.get("customer_id"), (long) charge.get("amount_paise"));\n            return "open";\n        }\n\n        if ("won".equals(notice.get("type"))) {\n            Db.run("UPDATE disputes SET status = \'won\' WHERE charge_id = ?", charge.get("id"));\n            Ledger.debit((String) charge.get("customer_id"), (long) charge.get("amount_paise"));\n            return "won";\n        }\n\n        Db.run("UPDATE disputes SET status = \'lost\' WHERE charge_id = ?", charge.get("id"));\n        Ledger.debit((String) charge.get("merchant_id"), (long) charge.get("amount_paise"));\n        return "lost";\n    }\n\n    public static boolean maySubmitEvidence(String chargeId, Instant now) {\n        Map<String, Object> dispute =\n                Db.one("SELECT status, evidence_due_at FROM disputes WHERE charge_id = ?", chargeId);\n        Instant due = (Instant) dispute.get("evidence_due_at");\n        return !due.atZone(ZoneOffset.UTC).toLocalDate().isBefore(now.atZone(ZoneOffset.UTC).toLocalDate());\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Disputes and chargebacks\n\nA customer disputes a charge. The network gives us a window to send evidence,\nand then decides. This PR handles both ends.\n\n## Rules\n\n- Opening a dispute credits the customer provisionally and freezes the amount\n  on the merchant.\n- If we win, the provisional credit is reversed and the merchant is released.\n  If we lose, the credit stands and the freeze becomes a debit.\n- A dispute is opened once per charge. A second notice for the same charge\n  updates the one that exists.\n- The evidence deadline comes from the network as an instant. It is shown to\n  the merchant in their zone and enforced against the instant.\n- Every state change is recorded, and money only moves inside a transaction.\n\n## Notes for the reviewer\n\n`disputes` is `(charge_id, status, amount_paise, evidence_due_at)`. `ledger`\nholds the movements. The network posts a notice for open, won and lost.\n","src/disputes.py":'"""Dispute notices from the network."""\nimport db\nimport ledger\n\n\ndef on_notice(notice):\n    charge = db.one("SELECT id, merchant_id, customer_id, amount_paise FROM charges WHERE id = %s", (notice["charge_id"],))\n\n    if notice["type"] == "open":\n        db.run(\n            "INSERT INTO disputes (charge_id, status, amount_paise, evidence_due_at) VALUES (%s, \'open\', %s, %s)",\n            (charge["id"], charge["amount_paise"], notice["evidence_due_at"]),\n        )\n        ledger.credit(charge["customer_id"], charge["amount_paise"])\n        return {"status": "open"}\n\n    if notice["type"] == "won":\n        db.run("UPDATE disputes SET status = \'won\' WHERE charge_id = %s", (charge["id"],))\n        ledger.debit(charge["customer_id"], charge["amount_paise"])\n        return {"status": "won"}\n\n    db.run("UPDATE disputes SET status = \'lost\' WHERE charge_id = %s", (charge["id"],))\n    ledger.debit(charge["merchant_id"], charge["amount_paise"])\n    return {"status": "lost"}\n\n\ndef may_submit_evidence(charge_id, now):\n    dispute = db.one("SELECT status, evidence_due_at FROM disputes WHERE charge_id = %s", (charge_id,))\n    return dispute["evidence_due_at"].date() >= now.date()\n'}},typescript:{entry:"README.md",files:{"README.md":"# Disputes and chargebacks\n\nA customer disputes a charge. The network gives us a window to send evidence,\nand then decides. This PR handles both ends.\n\n## Rules\n\n- Opening a dispute credits the customer provisionally and freezes the amount\n  on the merchant.\n- If we win, the provisional credit is reversed and the merchant is released.\n  If we lose, the credit stands and the freeze becomes a debit.\n- A dispute is opened once per charge. A second notice for the same charge\n  updates the one that exists.\n- The evidence deadline comes from the network as an instant. It is shown to\n  the merchant in their zone and enforced against the instant.\n- Every state change is recorded, and money only moves inside a transaction.\n\n## Notes for the reviewer\n\n`disputes` is `(charge_id, status, amount_paise, evidence_due_at)`. `ledger`\nholds the movements. The network posts a notice for open, won and lost.\n","src/disputes.ts":'// Dispute notices from the network.\nimport { db } from "./db";\nimport * as ledger from "./ledger";\n\ntype Notice = { charge_id: string; type: string; evidence_due_at?: string };\n\nexport async function onNotice(notice: Notice) {\n  const charge = await db.one("SELECT id, merchant_id, customer_id, amount_paise FROM charges WHERE id = $1", [\n    notice.charge_id,\n  ]);\n\n  if (notice.type === "open") {\n    await db.run(\n      "INSERT INTO disputes (charge_id, status, amount_paise, evidence_due_at) VALUES ($1, \'open\', $2, $3)",\n      [charge.id, charge.amount_paise, notice.evidence_due_at],\n    );\n    await ledger.credit(charge.customer_id, charge.amount_paise);\n    return { status: "open" };\n  }\n\n  if (notice.type === "won") {\n    await db.run("UPDATE disputes SET status = \'won\' WHERE charge_id = $1", [charge.id]);\n    await ledger.debit(charge.customer_id, charge.amount_paise);\n    return { status: "won" };\n  }\n\n  await db.run("UPDATE disputes SET status = \'lost\' WHERE charge_id = $1", [charge.id]);\n  await ledger.debit(charge.merchant_id, charge.amount_paise);\n  return { status: "lost" };\n}\n\nexport async function maySubmitEvidence(chargeId: string, now: Date) {\n  const dispute = await db.one("SELECT status, evidence_due_at FROM disputes WHERE charge_id = $1", [chargeId]);\n  return new Date(dispute.evidence_due_at).toDateString() >= now.toDateString();\n}\n'}}}},{slug:"emi-schedule",title:"The loan schedule",difficulty:"Medium",area:"money",domains:["fintech"],minutes:25,summary:"The table a customer signs. Thirty lines of arithmetic, every number of which ends up on a legal document.",brief:["A teammate has opened this as a pull request. The customer signs this schedule, so a paisa that does not add up is a dispute.","Add the instalments up and compare with the principal plus interest. Then look at the balance after the last one. Then follow the due dates across a year.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The loan schedule\n\nA customer takes a loan and gets a table of instalments. This PR builds it.\n\n## Rules\n\n- Amounts are paise, as integers. The instalments add up to the principal plus\n  the interest, exactly.\n- The last instalment absorbs the rounding, so the balance after it is zero.\n- Interest for a period is on the balance outstanding at the start of that\n  period.\n- Instalments fall on the same day of the month as the disbursal, and on the\n  last day of the month when that day does not exist.\n- A schedule is built once and stored. Rebuilding it for an existing loan is\n  not allowed, because the customer has signed it.\n\n## Notes for the reviewer\n\n`loans` carry `principal_paise`, `annual_rate_bps`, `months` and\n`disbursed_on`. The instalment is the usual amortising formula.\n","src/Emi.java":'package bank;\n\nimport java.time.LocalDate;\nimport java.util.Map;\n\n/** Building a loan schedule. */\npublic final class Emi {\n\n    public static double instalment(double principal, double monthlyRate, int months) {\n        double factor = Math.pow(1 + monthlyRate, months);\n        return principal * monthlyRate * factor / (factor - 1);\n    }\n\n    public static long buildSchedule(String loanId) {\n        Map<String, Object> loan = Db.one(\n                "SELECT id, principal_paise, annual_rate_bps, months, disbursed_on FROM loans WHERE id = ?", loanId);\n        double monthlyRate = (int) loan.get("annual_rate_bps") / 10000.0 / 12;\n        int months = (int) loan.get("months");\n        double emi = instalment((long) loan.get("principal_paise"), monthlyRate, months);\n\n        double balance = (long) loan.get("principal_paise");\n        LocalDate dueOn = (LocalDate) loan.get("disbursed_on");\n        for (int n = 0; n < months; n++) {\n            double interest = balance * monthlyRate;\n            double principalPart = emi - interest;\n            balance = balance - principalPart;\n            dueOn = dueOn.plusDays(30);\n\n            Db.run("INSERT INTO instalments (loan_id, n, due_on, amount_paise, interest_paise, balance_paise) "\n                    + "VALUES (?, ?, ?, ?, ?, ?)",\n                    loanId, n + 1, dueOn, (long) emi, (long) interest, (long) balance);\n        }\n        return (long) emi;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The loan schedule\n\nA customer takes a loan and gets a table of instalments. This PR builds it.\n\n## Rules\n\n- Amounts are paise, as integers. The instalments add up to the principal plus\n  the interest, exactly.\n- The last instalment absorbs the rounding, so the balance after it is zero.\n- Interest for a period is on the balance outstanding at the start of that\n  period.\n- Instalments fall on the same day of the month as the disbursal, and on the\n  last day of the month when that day does not exist.\n- A schedule is built once and stored. Rebuilding it for an existing loan is\n  not allowed, because the customer has signed it.\n\n## Notes for the reviewer\n\n`loans` carry `principal_paise`, `annual_rate_bps`, `months` and\n`disbursed_on`. The instalment is the usual amortising formula.\n","src/emi.py":'"""Building a loan schedule."""\nfrom datetime import timedelta\n\nimport db\n\n\ndef instalment(principal, monthly_rate, months):\n    factor = (1 + monthly_rate) ** months\n    return principal * monthly_rate * factor / (factor - 1)\n\n\ndef build_schedule(loan_id):\n    loan = db.one(\n        "SELECT id, principal_paise, annual_rate_bps, months, disbursed_on FROM loans WHERE id = %s",\n        (loan_id,),\n    )\n    monthly_rate = loan["annual_rate_bps"] / 10000 / 12\n    emi = instalment(loan["principal_paise"], monthly_rate, loan["months"])\n\n    balance = loan["principal_paise"]\n    due_on = loan["disbursed_on"]\n    for n in range(loan["months"]):\n        interest = balance * monthly_rate\n        principal_part = emi - interest\n        balance = balance - principal_part\n        due_on = due_on + timedelta(days=30)\n\n        db.run(\n            "INSERT INTO instalments (loan_id, n, due_on, amount_paise, interest_paise, balance_paise) "\n            "VALUES (%s, %s, %s, %s, %s, %s)",\n            (loan_id, n + 1, due_on, int(emi), int(interest), int(balance)),\n        )\n    return {"instalments": loan["months"], "emi_paise": int(emi)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# The loan schedule\n\nA customer takes a loan and gets a table of instalments. This PR builds it.\n\n## Rules\n\n- Amounts are paise, as integers. The instalments add up to the principal plus\n  the interest, exactly.\n- The last instalment absorbs the rounding, so the balance after it is zero.\n- Interest for a period is on the balance outstanding at the start of that\n  period.\n- Instalments fall on the same day of the month as the disbursal, and on the\n  last day of the month when that day does not exist.\n- A schedule is built once and stored. Rebuilding it for an existing loan is\n  not allowed, because the customer has signed it.\n\n## Notes for the reviewer\n\n`loans` carry `principal_paise`, `annual_rate_bps`, `months` and\n`disbursed_on`. The instalment is the usual amortising formula.\n","src/emi.ts":'// Building a loan schedule.\nimport { db } from "./db";\n\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport function instalment(principal: number, monthlyRate: number, months: number) {\n  const factor = (1 + monthlyRate) ** months;\n  return (principal * monthlyRate * factor) / (factor - 1);\n}\n\nexport async function buildSchedule(loanId: string) {\n  const loan = await db.one(\n    "SELECT id, principal_paise, annual_rate_bps, months, disbursed_on FROM loans WHERE id = $1",\n    [loanId],\n  );\n  const monthlyRate = loan.annual_rate_bps / 10000 / 12;\n  const emi = instalment(loan.principal_paise, monthlyRate, loan.months);\n\n  let balance = loan.principal_paise;\n  let dueOn = new Date(loan.disbursed_on);\n  for (let n = 0; n < loan.months; n++) {\n    const interest = balance * monthlyRate;\n    const principalPart = emi - interest;\n    balance = balance - principalPart;\n    dueOn = new Date(dueOn.getTime() + 30 * DAY_MS);\n\n    await db.run(\n      "INSERT INTO instalments (loan_id, n, due_on, amount_paise, interest_paise, balance_paise) " +\n        "VALUES ($1, $2, $3, $4, $5, $6)",\n      [loanId, n + 1, dueOn, Math.trunc(emi), Math.trunc(interest), Math.trunc(balance)],\n    );\n  }\n  return { instalments: loan.months, emiPaise: Math.trunc(emi) };\n}\n'}}}},{slug:"beneficiary-limits",title:"Adding a payee",difficulty:"Medium",area:"security",domains:["fintech","identity"],minutes:25,summary:"The cooling period and the new-payee cap exist because of one specific fraud. Read what this checks, and what it looks up but never reads.",brief:["A teammate has opened this as a pull request. Every rule in the README is there because somebody lost their savings to the case it describes.","Add a payee and send money a minute later. Then confirm payee B with the OTP that was sent for payee A. Then send ₹49,000 twice, a week apart.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Adding a payee\n\nBefore money can be sent to a new account, the payee is added and sits in a\ncooling period. This PR adds one and checks a transfer against the limits.\n\n## Rules\n\n- A newly added payee has a cooling period of thirty minutes. Nothing goes to\n  them before it ends.\n- In the first twenty-four hours after the cooling period, at most ₹50,000 may\n  go to a new payee.\n- The OTP that confirms a payee is for that payee. It cannot be used to\n  confirm a different one.\n- A payee belongs to one customer, and the same account number may be a payee\n  of many customers.\n- Deleting and re-adding the same account starts the cooling period again.\n\n## Notes for the reviewer\n\n`payees` is `(id, customer_id, account_number, added_at, confirmed_at)`.\n`otps` is `(customer_id, code, expires_at, used_at)`.\n","src/Payees.java":'package bank;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Adding a payee and checking a transfer. */\npublic final class Payees {\n    private static final Duration COOLING = Duration.ofMinutes(30);\n    private static final long NEW_PAYEE_CAP_PAISE = 5000000;\n\n    public static boolean confirmPayee(String customerId, String payeeId, String code) {\n        Map<String, Object> otp = Db.one(\n                "SELECT customer_id, code, expires_at, used_at FROM otps WHERE customer_id = ? AND code = ?",\n                customerId, code);\n        if (otp == null) {\n            throw new BadRequest("wrong code");\n        }\n\n        Db.run("UPDATE payees SET confirmed_at = now() WHERE id = ?", payeeId);\n        Db.run("UPDATE otps SET used_at = now() WHERE customer_id = ? AND code = ?", customerId, code);\n        return true;\n    }\n\n    public static boolean maySend(String customerId, String payeeId, long amountPaise, Instant now) {\n        Map<String, Object> payee =\n                Db.one("SELECT id, customer_id, added_at, confirmed_at FROM payees WHERE id = ?", payeeId);\n\n        long sent = (long) Db.one("SELECT coalesce(sum(amount_paise), 0) AS total FROM transfers WHERE payee_id = ?",\n                payeeId).get("total");\n\n        return sent + amountPaise <= NEW_PAYEE_CAP_PAISE;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Adding a payee\n\nBefore money can be sent to a new account, the payee is added and sits in a\ncooling period. This PR adds one and checks a transfer against the limits.\n\n## Rules\n\n- A newly added payee has a cooling period of thirty minutes. Nothing goes to\n  them before it ends.\n- In the first twenty-four hours after the cooling period, at most ₹50,000 may\n  go to a new payee.\n- The OTP that confirms a payee is for that payee. It cannot be used to\n  confirm a different one.\n- A payee belongs to one customer, and the same account number may be a payee\n  of many customers.\n- Deleting and re-adding the same account starts the cooling period again.\n\n## Notes for the reviewer\n\n`payees` is `(id, customer_id, account_number, added_at, confirmed_at)`.\n`otps` is `(customer_id, code, expires_at, used_at)`.\n","src/payees.py":'"""Adding a payee and checking a transfer."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\n\nCOOLING = timedelta(minutes=30)\nNEW_PAYEE_CAP_PAISE = 5000000\n\n\ndef confirm_payee(customer_id, payee_id, code):\n    otp = db.one(\n        "SELECT customer_id, code, expires_at, used_at FROM otps WHERE customer_id = %s AND code = %s",\n        (customer_id, code),\n    )\n    if otp is None:\n        raise BadRequest("wrong code")\n\n    db.run("UPDATE payees SET confirmed_at = now() WHERE id = %s", (payee_id,))\n    db.run("UPDATE otps SET used_at = now() WHERE customer_id = %s AND code = %s", (customer_id, code))\n    return {"confirmed": True}\n\n\ndef may_send(customer_id, payee_id, amount_paise, now=None):\n    now = now or datetime.now(timezone.utc)\n    payee = db.one("SELECT id, customer_id, added_at, confirmed_at FROM payees WHERE id = %s", (payee_id,))\n\n    sent = db.one(\n        "SELECT coalesce(sum(amount_paise), 0) AS total FROM transfers WHERE payee_id = %s",\n        (payee_id,),\n    )["total"]\n\n    if sent + amount_paise > NEW_PAYEE_CAP_PAISE:\n        return False\n    return True\n'}},typescript:{entry:"README.md",files:{"README.md":"# Adding a payee\n\nBefore money can be sent to a new account, the payee is added and sits in a\ncooling period. This PR adds one and checks a transfer against the limits.\n\n## Rules\n\n- A newly added payee has a cooling period of thirty minutes. Nothing goes to\n  them before it ends.\n- In the first twenty-four hours after the cooling period, at most ₹50,000 may\n  go to a new payee.\n- The OTP that confirms a payee is for that payee. It cannot be used to\n  confirm a different one.\n- A payee belongs to one customer, and the same account number may be a payee\n  of many customers.\n- Deleting and re-adding the same account starts the cooling period again.\n\n## Notes for the reviewer\n\n`payees` is `(id, customer_id, account_number, added_at, confirmed_at)`.\n`otps` is `(customer_id, code, expires_at, used_at)`.\n","src/payees.ts":'// Adding a payee and checking a transfer.\nimport { db } from "./db";\n\nconst COOLING_MS = 30 * 60 * 1000;\nconst NEW_PAYEE_CAP_PAISE = 5000000;\n\nexport async function confirmPayee(customerId: string, payeeId: string, code: string) {\n  const otp = await db.one(\n    "SELECT customer_id, code, expires_at, used_at FROM otps WHERE customer_id = $1 AND code = $2",\n    [customerId, code],\n  );\n  if (!otp) throw new BadRequest("wrong code");\n\n  await db.run("UPDATE payees SET confirmed_at = now() WHERE id = $1", [payeeId]);\n  await db.run("UPDATE otps SET used_at = now() WHERE customer_id = $1 AND code = $2", [customerId, code]);\n  return { confirmed: true };\n}\n\nexport async function maySend(customerId: string, payeeId: string, amountPaise: number, now = new Date()) {\n  const payee = await db.one("SELECT id, customer_id, added_at, confirmed_at FROM payees WHERE id = $1", [payeeId]);\n\n  const sent = Number(\n    (await db.one("SELECT coalesce(sum(amount_paise), 0) AS total FROM transfers WHERE payee_id = $1", [payeeId]))\n      .total,\n  );\n\n  if (sent + amountPaise > NEW_PAYEE_CAP_PAISE) return false;\n  return true;\n}\n'}}}},{slug:"wearable-sync",title:"Syncing a fitness band",difficulty:"Medium",area:"data",domains:["health","analytics"],minutes:25,summary:"Samples from a device with its own clock and its own idea of units, straight into a daily total. The unit column is stored and never looked at.",brief:["A teammate has opened this as a pull request. Everything here comes from a device we do not control, over a connection that drops.","Resend a sync that half succeeded. Then send a sample in kilometres. Then set the band’s clock to 2043.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Syncing a fitness band\n\nA band uploads samples when the phone next has a connection. This PR takes\nthem and rolls them into daily totals.\n\n## Rules\n\n- A sample is counted once. The band resends what it is unsure about, so the\n  same sample can arrive many times.\n- Times come from the device, which can be wrong. A sample dated in the future\n  or before the account existed is rejected.\n- A day total is the user’s calendar day in their own zone.\n- Steps are whole numbers; distance is metres. The band sometimes sends\n  kilometres, which the payload says.\n- A sync is one upload of up to ten thousand samples.\n\n## Notes for the reviewer\n\n`samples` is `(user_id, device_id, sample_id, taken_at, steps, distance,\nunit)`. `daily` is the rolled-up total per user per day.\n","src/Sync.java":'package health;\n\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.List;\nimport java.util.Map;\n\n/** Taking samples from a band. */\npublic final class Sync {\n\n    public record Sample(String id, String takenAt, int steps, double distance, String unit) {}\n\n    public static int sync(String userId, String deviceId, List<Sample> samples) {\n        int stored = 0;\n        for (Sample sample : samples) {\n            Instant takenAt = Instant.parse(sample.takenAt());\n\n            Db.run("INSERT INTO samples (user_id, device_id, sample_id, taken_at, steps, distance, unit) "\n                    + "VALUES (?, ?, ?, ?, ?, ?, ?)",\n                    userId, deviceId, sample.id(), takenAt, sample.steps(), sample.distance(), sample.unit());\n\n            Db.run("INSERT INTO daily (user_id, on_date, steps, distance_m) VALUES (?, ?, ?, ?) "\n                    + "ON CONFLICT (user_id, on_date) DO UPDATE SET steps = daily.steps + EXCLUDED.steps, "\n                    + "distance_m = daily.distance_m + EXCLUDED.distance_m",\n                    userId, takenAt.atZone(ZoneOffset.UTC).toLocalDate(), sample.steps(), sample.distance());\n            stored++;\n        }\n        return stored;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Syncing a fitness band\n\nA band uploads samples when the phone next has a connection. This PR takes\nthem and rolls them into daily totals.\n\n## Rules\n\n- A sample is counted once. The band resends what it is unsure about, so the\n  same sample can arrive many times.\n- Times come from the device, which can be wrong. A sample dated in the future\n  or before the account existed is rejected.\n- A day total is the user’s calendar day in their own zone.\n- Steps are whole numbers; distance is metres. The band sometimes sends\n  kilometres, which the payload says.\n- A sync is one upload of up to ten thousand samples.\n\n## Notes for the reviewer\n\n`samples` is `(user_id, device_id, sample_id, taken_at, steps, distance,\nunit)`. `daily` is the rolled-up total per user per day.\n","src/sync.py":'"""Taking samples from a band."""\nfrom datetime import datetime, timezone\n\nimport db\n\n\ndef sync(user_id, device_id, samples):\n    stored = 0\n    for sample in samples:\n        taken_at = datetime.fromisoformat(sample["taken_at"])\n\n        db.run(\n            "INSERT INTO samples (user_id, device_id, sample_id, taken_at, steps, distance, unit) "\n            "VALUES (%s, %s, %s, %s, %s, %s, %s)",\n            (user_id, device_id, sample["id"], taken_at, sample["steps"], sample["distance"], sample["unit"]),\n        )\n\n        db.run(\n            "INSERT INTO daily (user_id, on_date, steps, distance_m) VALUES (%s, %s, %s, %s) "\n            "ON CONFLICT (user_id, on_date) DO UPDATE SET steps = daily.steps + EXCLUDED.steps, "\n            "distance_m = daily.distance_m + EXCLUDED.distance_m",\n            (user_id, taken_at.date(), sample["steps"], sample["distance"]),\n        )\n        stored += 1\n    return {"stored": stored}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Syncing a fitness band\n\nA band uploads samples when the phone next has a connection. This PR takes\nthem and rolls them into daily totals.\n\n## Rules\n\n- A sample is counted once. The band resends what it is unsure about, so the\n  same sample can arrive many times.\n- Times come from the device, which can be wrong. A sample dated in the future\n  or before the account existed is rejected.\n- A day total is the user’s calendar day in their own zone.\n- Steps are whole numbers; distance is metres. The band sometimes sends\n  kilometres, which the payload says.\n- A sync is one upload of up to ten thousand samples.\n\n## Notes for the reviewer\n\n`samples` is `(user_id, device_id, sample_id, taken_at, steps, distance,\nunit)`. `daily` is the rolled-up total per user per day.\n","src/sync.ts":'// Taking samples from a band.\nimport { db } from "./db";\n\ntype Sample = { id: string; taken_at: string; steps: number; distance: number; unit: string };\n\nexport async function sync(userId: string, deviceId: string, samples: Sample[]) {\n  let stored = 0;\n  for (const sample of samples) {\n    const takenAt = new Date(sample.taken_at);\n\n    await db.run(\n      "INSERT INTO samples (user_id, device_id, sample_id, taken_at, steps, distance, unit) " +\n        "VALUES ($1, $2, $3, $4, $5, $6, $7)",\n      [userId, deviceId, sample.id, takenAt, sample.steps, sample.distance, sample.unit],\n    );\n\n    await db.run(\n      "INSERT INTO daily (user_id, on_date, steps, distance_m) VALUES ($1, $2, $3, $4) " +\n        "ON CONFLICT (user_id, on_date) DO UPDATE SET steps = daily.steps + EXCLUDED.steps, " +\n        "distance_m = daily.distance_m + EXCLUDED.distance_m",\n      [userId, takenAt.toISOString().slice(0, 10), sample.steps, sample.distance],\n    );\n    stored += 1;\n  }\n  return { stored };\n}\n'}}}},{slug:"consent-sharing",title:"Sharing a record with another clinic",difficulty:"Medium",area:"security",domains:["health","identity"],minutes:25,summary:"A consent row with seven columns, four of which decide what may be shared. Count how many of them this code reads.",brief:["A teammate has opened this as a pull request. Consent is the only thing standing between a specialist and somebody’s whole medical history.","Use a consent that expired last year. Then use one meant for a different specialist. Then withdraw one and ask what the record now says about it.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Sharing a record with another clinic\n\nA patient consents to their record being sent to a specialist. This PR records\nthe consent and serves the share.\n\n## Rules\n\n- Consent is for a purpose, a recipient and a period. It is not a general\n  permission.\n- A patient can withdraw consent at any time, and a withdrawal stops future\n  access immediately. What was already sent cannot be recalled, and the record\n  says so.\n- A share carries only the categories the patient agreed to.\n- Every access under a consent is logged with which consent allowed it.\n- Consent is not a login: the recipient still authenticates as themselves.\n\n## Notes for the reviewer\n\n`consents` is `(id, patient_id, recipient_id, purpose, categories, granted_at,\nexpires_at, withdrawn_at)`. `record_sections` holds the categories.\n","src/Consent.java":'package health;\n\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** Consented sharing. */\npublic final class Consent {\n\n    public static Map<String, Object> share(String consentId, String recipientId) {\n        Map<String, Object> consent = Db.one(\n                "SELECT id, patient_id, recipient_id, purpose, categories, expires_at, withdrawn_at "\n                        + "FROM consents WHERE id = ?", consentId);\n        if (consent == null) {\n            throw new NotFound("no such consent");\n        }\n\n        List<Map<String, Object>> sections =\n                Db.all("SELECT category, body FROM record_sections WHERE patient_id = ?", consent.get("patient_id"));\n        Map<String, Object> out = new HashMap<>();\n        out.put("patientId", consent.get("patient_id"));\n        out.put("sections", sections);\n        return out;\n    }\n\n    public static boolean withdraw(String consentId, String patientId) {\n        Db.run("DELETE FROM consents WHERE id = ? AND patient_id = ?", consentId, patientId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Sharing a record with another clinic\n\nA patient consents to their record being sent to a specialist. This PR records\nthe consent and serves the share.\n\n## Rules\n\n- Consent is for a purpose, a recipient and a period. It is not a general\n  permission.\n- A patient can withdraw consent at any time, and a withdrawal stops future\n  access immediately. What was already sent cannot be recalled, and the record\n  says so.\n- A share carries only the categories the patient agreed to.\n- Every access under a consent is logged with which consent allowed it.\n- Consent is not a login: the recipient still authenticates as themselves.\n\n## Notes for the reviewer\n\n`consents` is `(id, patient_id, recipient_id, purpose, categories, granted_at,\nexpires_at, withdrawn_at)`. `record_sections` holds the categories.\n","src/consent.py":'"""Consented sharing."""\nimport db\n\n\ndef share(consent_id, recipient_id):\n    consent = db.one(\n        "SELECT id, patient_id, recipient_id, purpose, categories, expires_at, withdrawn_at "\n        "FROM consents WHERE id = %s",\n        (consent_id,),\n    )\n    if consent is None:\n        raise NotFound("no such consent")\n\n    sections = db.all(\n        "SELECT category, body FROM record_sections WHERE patient_id = %s",\n        (consent["patient_id"],),\n    )\n    return {"patient_id": consent["patient_id"], "sections": sections}\n\n\ndef withdraw(consent_id, patient_id):\n    db.run("DELETE FROM consents WHERE id = %s AND patient_id = %s", (consent_id, patient_id))\n    return {"withdrawn": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Sharing a record with another clinic\n\nA patient consents to their record being sent to a specialist. This PR records\nthe consent and serves the share.\n\n## Rules\n\n- Consent is for a purpose, a recipient and a period. It is not a general\n  permission.\n- A patient can withdraw consent at any time, and a withdrawal stops future\n  access immediately. What was already sent cannot be recalled, and the record\n  says so.\n- A share carries only the categories the patient agreed to.\n- Every access under a consent is logged with which consent allowed it.\n- Consent is not a login: the recipient still authenticates as themselves.\n\n## Notes for the reviewer\n\n`consents` is `(id, patient_id, recipient_id, purpose, categories, granted_at,\nexpires_at, withdrawn_at)`. `record_sections` holds the categories.\n","src/consent.ts":'// Consented sharing.\nimport { db } from "./db";\n\nexport async function share(consentId: string, recipientId: string) {\n  const consent = await db.one(\n    "SELECT id, patient_id, recipient_id, purpose, categories, expires_at, withdrawn_at " +\n      "FROM consents WHERE id = $1",\n    [consentId],\n  );\n  if (!consent) throw new NotFound("no such consent");\n\n  const sections = await db.all("SELECT category, body FROM record_sections WHERE patient_id = $1", [\n    consent.patient_id,\n  ]);\n  return { patientId: consent.patient_id, sections };\n}\n\nexport async function withdraw(consentId: string, patientId: string) {\n  await db.run("DELETE FROM consents WHERE id = $1 AND patient_id = $2", [consentId, patientId]);\n  return { withdrawn: true };\n}\n'}}}},{slug:"triage-queue",title:"The triage queue",difficulty:"Medium",area:"concurrency",domains:["health","scheduling"],minutes:25,summary:"Who the next clinician sees. The second rule in the README is the one that keeps people safe, and the ORDER BY does not know about it.",brief:["A teammate has opened this as a pull request. The order this produces decides who waits, in a place where waiting matters.","Have two clinicians press next at the same moment. Then leave a standard case waiting three hours while urgent cases keep arriving.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The triage queue\n\nPatients arrive and are seen in an order that is not the order they arrived\nin. This PR decides who is next.\n\n## Rules\n\n- Priority beats arrival time. Within a priority, whoever has waited longest\n  goes next.\n- Nobody waits past the maximum for their priority: an urgent case must be\n  seen within 15 minutes, standard within 2 hours, low within 4. A case past\n  its maximum jumps ahead of lower priorities.\n- Calling a patient claims them. Two clinicians calling at the same moment do\n  not get the same patient.\n- A patient who leaves is removed from the queue and their wait is recorded.\n- The board on the wall is a snapshot, not a promise: it may lag by up to a\n  minute.\n\n## Notes for the reviewer\n\n`queue` is `(id, patient_id, priority, arrived_at, called_at, left_at)`,\npriority 1 urgent, 2 standard, 3 low.\n","src/Triage.java":'package health;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Who is next. */\npublic final class Triage {\n    private static final Map<Integer, Duration> MAX_WAIT =\n            Map.of(1, Duration.ofMinutes(15), 2, Duration.ofHours(2), 3, Duration.ofHours(4));\n\n    public record Called(String patientId, long waitedSeconds) {}\n\n    public static Called nextPatient(String clinicianId, Instant now) {\n        Map<String, Object> row = Db.one("SELECT id, patient_id, priority, arrived_at FROM queue "\n                + "WHERE called_at IS NULL ORDER BY priority, arrived_at LIMIT 1");\n        if (row == null) {\n            return null;\n        }\n\n        Db.run("UPDATE queue SET called_at = now(), called_by = ? WHERE id = ?", clinicianId, row.get("id"));\n        return new Called((String) row.get("patient_id"),\n                Duration.between((Instant) row.get("arrived_at"), now).getSeconds());\n    }\n\n    public static boolean leave(String queueId) {\n        Db.run("DELETE FROM queue WHERE id = ?", queueId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The triage queue\n\nPatients arrive and are seen in an order that is not the order they arrived\nin. This PR decides who is next.\n\n## Rules\n\n- Priority beats arrival time. Within a priority, whoever has waited longest\n  goes next.\n- Nobody waits past the maximum for their priority: an urgent case must be\n  seen within 15 minutes, standard within 2 hours, low within 4. A case past\n  its maximum jumps ahead of lower priorities.\n- Calling a patient claims them. Two clinicians calling at the same moment do\n  not get the same patient.\n- A patient who leaves is removed from the queue and their wait is recorded.\n- The board on the wall is a snapshot, not a promise: it may lag by up to a\n  minute.\n\n## Notes for the reviewer\n\n`queue` is `(id, patient_id, priority, arrived_at, called_at, left_at)`,\npriority 1 urgent, 2 standard, 3 low.\n","src/triage.py":'"""Who is next."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\n\nMAX_WAIT = {1: timedelta(minutes=15), 2: timedelta(hours=2), 3: timedelta(hours=4)}\n\n\ndef next_patient(clinician_id, now=None):\n    now = now or datetime.now(timezone.utc)\n\n    row = db.one(\n        "SELECT id, patient_id, priority, arrived_at FROM queue "\n        "WHERE called_at IS NULL ORDER BY priority, arrived_at LIMIT 1",\n    )\n    if row is None:\n        return None\n\n    db.run(\n        "UPDATE queue SET called_at = now(), called_by = %s WHERE id = %s",\n        (clinician_id, row["id"]),\n    )\n    return {"patient_id": row["patient_id"], "waited": (now - row["arrived_at"]).total_seconds()}\n\n\ndef leave(queue_id):\n    db.run("DELETE FROM queue WHERE id = %s", (queue_id,))\n    return {"left": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# The triage queue\n\nPatients arrive and are seen in an order that is not the order they arrived\nin. This PR decides who is next.\n\n## Rules\n\n- Priority beats arrival time. Within a priority, whoever has waited longest\n  goes next.\n- Nobody waits past the maximum for their priority: an urgent case must be\n  seen within 15 minutes, standard within 2 hours, low within 4. A case past\n  its maximum jumps ahead of lower priorities.\n- Calling a patient claims them. Two clinicians calling at the same moment do\n  not get the same patient.\n- A patient who leaves is removed from the queue and their wait is recorded.\n- The board on the wall is a snapshot, not a promise: it may lag by up to a\n  minute.\n\n## Notes for the reviewer\n\n`queue` is `(id, patient_id, priority, arrived_at, called_at, left_at)`,\npriority 1 urgent, 2 standard, 3 low.\n","src/triage.ts":'// Who is next.\nimport { db } from "./db";\n\nconst MAX_WAIT_MINUTES: Record<number, number> = { 1: 15, 2: 120, 3: 240 };\n\nexport async function nextPatient(clinicianId: string, now = new Date()) {\n  const row = await db.one(\n    "SELECT id, patient_id, priority, arrived_at FROM queue " +\n      "WHERE called_at IS NULL ORDER BY priority, arrived_at LIMIT 1",\n  );\n  if (!row) return null;\n\n  await db.run("UPDATE queue SET called_at = now(), called_by = $1 WHERE id = $2", [clinicianId, row.id]);\n  return {\n    patientId: row.patient_id,\n    waited: (now.getTime() - new Date(row.arrived_at).getTime()) / 1000,\n  };\n}\n\nexport async function leave(queueId: string) {\n  await db.run("DELETE FROM queue WHERE id = $1", [queueId]);\n  return { left: true };\n}\n'}}}},{slug:"lab-results",title:"Releasing lab results",difficulty:"Medium",area:"backend",domains:["health","messaging"],minutes:25,summary:"A message from the lab, a row, and two notifications. Read the second rule in the README, then read when released_at is set.",brief:["A teammate has opened this as a pull request. Somebody finds out something about their health from what this sends.","Send a critical result. Then send a corrected one for an order that already has a result. Then send a message whose patient_id is not the patient on the order.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Releasing lab results\n\nResults arrive from the lab and are released to the patient and the ordering\nclinician. This PR handles the release.\n\n## Rules\n\n- A result goes to the clinician who ordered it and to the patient.\n- A result flagged critical is not released to the patient until a clinician\n  has seen it. Everything else is released after a 48-hour hold, or at once if\n  the clinician releases it early.\n- A result belongs to the patient it was ordered for. The lab sends a\n  reference; the patient is looked up from the order, not from the message.\n- A corrected result replaces the earlier one for everybody who saw it, and\n  says that it is a correction.\n- Values keep the units the lab sent.\n\n## Notes for the reviewer\n\n`orders` is `(id, patient_id, clinician_id, lab_ref)`. `results` is\n`(order_id, value, unit, critical, released_at, corrected_of)`.\n","src/Results.java":'package health;\n\nimport java.time.Duration;\nimport java.util.List;\nimport java.util.Map;\n\n/** Taking a result from the lab and releasing it. */\npublic final class Results {\n    private static final Duration HOLD = Duration.ofHours(48);\n\n    public static boolean receive(Map<String, Object> message) {\n        Map<String, Object> order =\n                Db.one("SELECT id, patient_id, clinician_id FROM orders WHERE lab_ref = ?", message.get("lab_ref"));\n\n        Db.run("INSERT INTO results (order_id, value, unit, critical, released_at) VALUES (?, ?, ?, ?, now())",\n                order.get("id"), message.get("value"), message.get("unit"), message.get("critical"));\n\n        Notify.send((String) message.get("patient_id"),\n                "Your result is ready: " + message.get("value") + " " + message.get("unit"));\n        Notify.send((String) order.get("clinician_id"), "A result is ready");\n        return true;\n    }\n\n    public static List<Map<String, Object>> patientResults(String patientId) {\n        return Db.all("SELECT r.value, r.unit, r.critical, r.released_at FROM results r "\n                + "JOIN orders o ON o.id = r.order_id "\n                + "WHERE o.patient_id = ? ORDER BY r.released_at DESC", patientId);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Releasing lab results\n\nResults arrive from the lab and are released to the patient and the ordering\nclinician. This PR handles the release.\n\n## Rules\n\n- A result goes to the clinician who ordered it and to the patient.\n- A result flagged critical is not released to the patient until a clinician\n  has seen it. Everything else is released after a 48-hour hold, or at once if\n  the clinician releases it early.\n- A result belongs to the patient it was ordered for. The lab sends a\n  reference; the patient is looked up from the order, not from the message.\n- A corrected result replaces the earlier one for everybody who saw it, and\n  says that it is a correction.\n- Values keep the units the lab sent.\n\n## Notes for the reviewer\n\n`orders` is `(id, patient_id, clinician_id, lab_ref)`. `results` is\n`(order_id, value, unit, critical, released_at, corrected_of)`.\n","src/results.py":'"""Taking a result from the lab and releasing it."""\nfrom datetime import timedelta\n\nimport db\nimport notify\n\nHOLD = timedelta(hours=48)\n\n\ndef receive(message):\n    order = db.one("SELECT id, patient_id, clinician_id FROM orders WHERE lab_ref = %s", (message["lab_ref"],))\n\n    db.run(\n        "INSERT INTO results (order_id, value, unit, critical, released_at) VALUES (%s, %s, %s, %s, now())",\n        (order["id"], message["value"], message["unit"], message["critical"]),\n    )\n\n    notify.send(message["patient_id"], f"Your result is ready: {message[\'value\']} {message[\'unit\']}")\n    notify.send(order["clinician_id"], "A result is ready")\n    return {"received": True}\n\n\ndef patient_results(patient_id):\n    return db.all(\n        "SELECT r.value, r.unit, r.critical, r.released_at FROM results r JOIN orders o ON o.id = r.order_id "\n        "WHERE o.patient_id = %s ORDER BY r.released_at DESC",\n        (patient_id,),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":"# Releasing lab results\n\nResults arrive from the lab and are released to the patient and the ordering\nclinician. This PR handles the release.\n\n## Rules\n\n- A result goes to the clinician who ordered it and to the patient.\n- A result flagged critical is not released to the patient until a clinician\n  has seen it. Everything else is released after a 48-hour hold, or at once if\n  the clinician releases it early.\n- A result belongs to the patient it was ordered for. The lab sends a\n  reference; the patient is looked up from the order, not from the message.\n- A corrected result replaces the earlier one for everybody who saw it, and\n  says that it is a correction.\n- Values keep the units the lab sent.\n\n## Notes for the reviewer\n\n`orders` is `(id, patient_id, clinician_id, lab_ref)`. `results` is\n`(order_id, value, unit, critical, released_at, corrected_of)`.\n","src/results.ts":'// Taking a result from the lab and releasing it.\nimport { db } from "./db";\nimport * as notify from "./notify";\n\nconst HOLD_HOURS = 48;\n\ntype Message = { lab_ref: string; patient_id: string; value: string; unit: string; critical: boolean };\n\nexport async function receive(message: Message) {\n  const order = await db.one("SELECT id, patient_id, clinician_id FROM orders WHERE lab_ref = $1", [message.lab_ref]);\n\n  await db.run("INSERT INTO results (order_id, value, unit, critical, released_at) VALUES ($1, $2, $3, $4, now())", [\n    order.id,\n    message.value,\n    message.unit,\n    message.critical,\n  ]);\n\n  await notify.send(message.patient_id, `Your result is ready: ${message.value} ${message.unit}`);\n  await notify.send(order.clinician_id, "A result is ready");\n  return { received: true };\n}\n\nexport async function patientResults(patientId: string) {\n  return db.all(\n    "SELECT r.value, r.unit, r.critical, r.released_at FROM results r JOIN orders o ON o.id = r.order_id " +\n      "WHERE o.patient_id = $1 ORDER BY r.released_at DESC",\n    [patientId],\n  );\n}\n'}}}},{slug:"insurance-claim",title:"Submitting an insurance claim",difficulty:"Medium",area:"money",domains:["health","payments"],minutes:25,summary:"Work out what can be claimed and send it. The insurer charges for duplicates, and the README says the call can time out after they accepted it.",brief:["A teammate has opened this as a pull request. The insurer is a third party that charges us for our mistakes.","Let the submit call time out, then retry it. Then claim for a visit from last year. Then claim for a visit the patient paid in full.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Submitting an insurance claim\n\nAfter a visit, a claim goes to the insurer. This PR builds and submits it.\n\n## Rules\n\n- A claim is submitted once per visit. The insurer rejects duplicates and\n  charges us for them.\n- The claimable amount is the billed amount less what the patient already paid\n  and less anything the policy excludes.\n- A claim is submitted within ninety days of the visit, in the insurer’s\n  calendar, or it is refused.\n- A submission that fails is retried, and the retry is the same claim, not a\n  new one.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`visits` carry `billed_paise`, `paid_paise`, `visited_on`, `policy_id`.\n`claims` is `(visit_id, external_ref, amount_paise, status)`. `insurer.submit`\nreturns a reference and can time out after the insurer has accepted.\n","src/Claims.java":'package health;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Building and submitting a claim. */\npublic final class Claims {\n    private static final int WINDOW_DAYS = 90;\n\n    public static long claimable(Map<String, Object> visit, List<Map<String, Object>> exclusions) {\n        long amount = (long) visit.get("billed_paise") - (long) visit.get("paid_paise");\n        for (Map<String, Object> line : exclusions) {\n            amount = amount - (long) line.get("amount_paise");\n        }\n        return amount;\n    }\n\n    public static String submit(String visitId) {\n        Map<String, Object> visit = Db.one(\n                "SELECT id, billed_paise, paid_paise, visited_on, policy_id FROM visits WHERE id = ?", visitId);\n        List<Map<String, Object>> exclusions =\n                Db.all("SELECT amount_paise FROM exclusions WHERE policy_id = ?", visit.get("policy_id"));\n\n        long amount = claimable(visit, exclusions);\n        Insurer.Response response = Insurer.submit(visitId, amount);\n\n        Db.run("INSERT INTO claims (visit_id, external_ref, amount_paise, status) VALUES (?, ?, ?, \'submitted\')",\n                visitId, response.reference(), amount);\n        return response.reference();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Submitting an insurance claim\n\nAfter a visit, a claim goes to the insurer. This PR builds and submits it.\n\n## Rules\n\n- A claim is submitted once per visit. The insurer rejects duplicates and\n  charges us for them.\n- The claimable amount is the billed amount less what the patient already paid\n  and less anything the policy excludes.\n- A claim is submitted within ninety days of the visit, in the insurer’s\n  calendar, or it is refused.\n- A submission that fails is retried, and the retry is the same claim, not a\n  new one.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`visits` carry `billed_paise`, `paid_paise`, `visited_on`, `policy_id`.\n`claims` is `(visit_id, external_ref, amount_paise, status)`. `insurer.submit`\nreturns a reference and can time out after the insurer has accepted.\n","src/claims.py":'"""Building and submitting a claim."""\nfrom datetime import date, timedelta\n\nimport db\nimport insurer\n\nWINDOW_DAYS = 90\n\n\ndef claimable(visit, exclusions):\n    amount = visit["billed_paise"] - visit["paid_paise"]\n    for line in exclusions:\n        amount = amount - line["amount_paise"]\n    return amount\n\n\ndef submit(visit_id):\n    visit = db.one(\n        "SELECT id, billed_paise, paid_paise, visited_on, policy_id FROM visits WHERE id = %s",\n        (visit_id,),\n    )\n    exclusions = db.all("SELECT amount_paise FROM exclusions WHERE policy_id = %s", (visit["policy_id"],))\n\n    amount = claimable(visit, exclusions)\n    response = insurer.submit(visit_id, amount)\n\n    db.run(\n        "INSERT INTO claims (visit_id, external_ref, amount_paise, status) VALUES (%s, %s, %s, \'submitted\')",\n        (visit_id, response.reference, amount),\n    )\n    return {"reference": response.reference, "amount_paise": amount}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Submitting an insurance claim\n\nAfter a visit, a claim goes to the insurer. This PR builds and submits it.\n\n## Rules\n\n- A claim is submitted once per visit. The insurer rejects duplicates and\n  charges us for them.\n- The claimable amount is the billed amount less what the patient already paid\n  and less anything the policy excludes.\n- A claim is submitted within ninety days of the visit, in the insurer’s\n  calendar, or it is refused.\n- A submission that fails is retried, and the retry is the same claim, not a\n  new one.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`visits` carry `billed_paise`, `paid_paise`, `visited_on`, `policy_id`.\n`claims` is `(visit_id, external_ref, amount_paise, status)`. `insurer.submit`\nreturns a reference and can time out after the insurer has accepted.\n","src/claims.ts":'// Building and submitting a claim.\nimport { db } from "./db";\nimport * as insurer from "./insurer";\n\nconst WINDOW_DAYS = 90;\n\nexport function claimable(visit: { billed_paise: number; paid_paise: number }, exclusions: { amount_paise: number }[]) {\n  let amount = visit.billed_paise - visit.paid_paise;\n  for (const line of exclusions) {\n    amount = amount - line.amount_paise;\n  }\n  return amount;\n}\n\nexport async function submit(visitId: string) {\n  const visit = await db.one(\n    "SELECT id, billed_paise, paid_paise, visited_on, policy_id FROM visits WHERE id = $1",\n    [visitId],\n  );\n  const exclusions = await db.all("SELECT amount_paise FROM exclusions WHERE policy_id = $1", [visit.policy_id]);\n\n  const amount = claimable(visit, exclusions);\n  const response = await insurer.submit(visitId, amount);\n\n  await db.run("INSERT INTO claims (visit_id, external_ref, amount_paise, status) VALUES ($1, $2, $3, \'submitted\')", [\n    visitId,\n    response.reference,\n    amount,\n  ]);\n  return { reference: response.reference, amountPaise: amount };\n}\n'}}}},{slug:"clinic-roster",title:"The clinic roster",difficulty:"Medium",area:"time",domains:["health","scheduling"],minutes:25,summary:"Publishing a week and answering who is on. The first statement in publish deletes more than it should.",brief:["A teammate has opened this as a pull request. The front desk trusts this to know which room to send a patient to.","Publish next week and then look at this week. Then put two doctors in one room. Then ask who is on at the exact minute a session ends.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The clinic roster\n\nWhich doctor is in which room, on which day. This PR publishes the roster and\nanswers who is on.\n\n## Rules\n\n- A doctor is in one room at a time, and a room holds one doctor at a time.\n- A roster is published for a week. Publishing again replaces that week and\n  nothing else.\n- A locum covering a session replaces the named doctor for that session only.\n- The roster is read constantly by the front desk, and published once a week.\n- Sessions are local clinic times.\n\n## Notes for the reviewer\n\n`roster` is `(clinic_id, doctor_id, room_id, session_start, session_end)`.\n`locums` is `(roster_id, locum_id)`. The clinic carries a zone.\n","src/Roster.java":'package health;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n/** Publishing and reading the roster. */\npublic final class Roster {\n\n    public record Session(String doctorId, String roomId, Instant start, Instant end) {}\n\n    public static int publish(String clinicId, String weekStart, List<Session> sessions) {\n        Db.run("DELETE FROM roster WHERE clinic_id = ?", clinicId);\n\n        for (Session session : sessions) {\n            Db.run("INSERT INTO roster (clinic_id, doctor_id, room_id, session_start, session_end) "\n                    + "VALUES (?, ?, ?, ?, ?)",\n                    clinicId, session.doctorId(), session.roomId(), session.start(), session.end());\n        }\n        return sessions.size();\n    }\n\n    public static List<Map<String, Object>> whoIsOn(String clinicId, Instant at) {\n        return Db.all("SELECT doctor_id, room_id, session_start, session_end FROM roster "\n                + "WHERE clinic_id = ? AND session_start <= ? AND session_end >= ?", clinicId, at, at);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The clinic roster\n\nWhich doctor is in which room, on which day. This PR publishes the roster and\nanswers who is on.\n\n## Rules\n\n- A doctor is in one room at a time, and a room holds one doctor at a time.\n- A roster is published for a week. Publishing again replaces that week and\n  nothing else.\n- A locum covering a session replaces the named doctor for that session only.\n- The roster is read constantly by the front desk, and published once a week.\n- Sessions are local clinic times.\n\n## Notes for the reviewer\n\n`roster` is `(clinic_id, doctor_id, room_id, session_start, session_end)`.\n`locums` is `(roster_id, locum_id)`. The clinic carries a zone.\n","src/roster.py":'"""Publishing and reading the roster."""\nfrom datetime import datetime, timezone\n\nimport db\n\n\ndef publish(clinic_id, week_start, sessions):\n    db.run("DELETE FROM roster WHERE clinic_id = %s", (clinic_id,))\n\n    for session in sessions:\n        db.run(\n            "INSERT INTO roster (clinic_id, doctor_id, room_id, session_start, session_end) "\n            "VALUES (%s, %s, %s, %s, %s)",\n            (clinic_id, session["doctor_id"], session["room_id"], session["start"], session["end"]),\n        )\n    return {"sessions": len(sessions)}\n\n\ndef who_is_on(clinic_id, at=None):\n    at = at or datetime.now(timezone.utc)\n    return db.all(\n        "SELECT doctor_id, room_id, session_start, session_end FROM roster "\n        "WHERE clinic_id = %s AND session_start <= %s AND session_end >= %s",\n        (clinic_id, at, at),\n    )\n'}},typescript:{entry:"README.md",files:{"README.md":"# The clinic roster\n\nWhich doctor is in which room, on which day. This PR publishes the roster and\nanswers who is on.\n\n## Rules\n\n- A doctor is in one room at a time, and a room holds one doctor at a time.\n- A roster is published for a week. Publishing again replaces that week and\n  nothing else.\n- A locum covering a session replaces the named doctor for that session only.\n- The roster is read constantly by the front desk, and published once a week.\n- Sessions are local clinic times.\n\n## Notes for the reviewer\n\n`roster` is `(clinic_id, doctor_id, room_id, session_start, session_end)`.\n`locums` is `(roster_id, locum_id)`. The clinic carries a zone.\n","src/roster.ts":'// Publishing and reading the roster.\nimport { db } from "./db";\n\ntype Session = { doctor_id: string; room_id: string; start: string; end: string };\n\nexport async function publish(clinicId: string, weekStart: string, sessions: Session[]) {\n  await db.run("DELETE FROM roster WHERE clinic_id = $1", [clinicId]);\n\n  for (const session of sessions) {\n    await db.run(\n      "INSERT INTO roster (clinic_id, doctor_id, room_id, session_start, session_end) VALUES ($1, $2, $3, $4, $5)",\n      [clinicId, session.doctor_id, session.room_id, session.start, session.end],\n    );\n  }\n  return { sessions: sessions.length };\n}\n\nexport async function whoIsOn(clinicId: string, at = new Date()) {\n  return db.all(\n    "SELECT doctor_id, room_id, session_start, session_end FROM roster " +\n      "WHERE clinic_id = $1 AND session_start <= $2 AND session_end >= $3",\n    [clinicId, at, at],\n  );\n}\n'}}}},{slug:"cancellation-tiers",title:"Cancelling a booking",difficulty:"Medium",area:"money",domains:["travel","payments"],minutes:25,summary:"Three refund bands and a call that moves money. Read the boundaries against the second rule, then read the order of the last two statements.",brief:["A teammate has opened this as a pull request. The refund policy is published, so a traveller can and will check the arithmetic.","Cancel exactly 24 hours before departure. Then cancel twice because the first response timed out. Then cancel a booking that already departed.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Cancelling a booking\n\nWhat comes back when a traveller cancels depends on how long before departure\nthey do it. This PR works it out and refunds.\n\n## Rules\n\n- The bands are counted from departure in the airline’s zone: more than 7 days\n  back 100% of the fare, 24 hours to 7 days 50%, under 24 hours nothing.\n- A band boundary is inclusive of the longer window: exactly 24 hours before\n  departure is the 50% band.\n- Taxes come back whatever the band. Fees do not.\n- One cancellation per booking. A retry returns the first result.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`bookings` carry `fare_paise`, `tax_paise`, `fee_paise`, `departs_at` and the\nairline’s `zone`. `payments.refund` is not reversible.\n","src/Cancel.java":'package travel;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Cancelling and refunding. */\npublic final class Cancel {\n    private static final Duration WEEK = Duration.ofDays(7);\n    private static final Duration DAY = Duration.ofHours(24);\n\n    public static double refundShare(Instant departsAt, Instant now) {\n        Duration left = Duration.between(now, departsAt);\n        if (left.compareTo(WEEK) > 0) {\n            return 1.0;\n        }\n        if (left.compareTo(DAY) > 0) {\n            return 0.5;\n        }\n        return 0.0;\n    }\n\n    public static long cancel(String bookingId, Instant now) {\n        Map<String, Object> booking = Db.one(\n                "SELECT id, fare_paise, tax_paise, fee_paise, departs_at, status FROM bookings WHERE id = ?",\n                bookingId);\n\n        double share = refundShare((Instant) booking.get("departs_at"), now);\n        double amount = (long) booking.get("fare_paise") * share + (long) booking.get("tax_paise");\n\n        Payments.refund(bookingId, (long) amount);\n        Db.run("UPDATE bookings SET status = \'cancelled\' WHERE id = ?", bookingId);\n        return (long) amount;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Cancelling a booking\n\nWhat comes back when a traveller cancels depends on how long before departure\nthey do it. This PR works it out and refunds.\n\n## Rules\n\n- The bands are counted from departure in the airline’s zone: more than 7 days\n  back 100% of the fare, 24 hours to 7 days 50%, under 24 hours nothing.\n- A band boundary is inclusive of the longer window: exactly 24 hours before\n  departure is the 50% band.\n- Taxes come back whatever the band. Fees do not.\n- One cancellation per booking. A retry returns the first result.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`bookings` carry `fare_paise`, `tax_paise`, `fee_paise`, `departs_at` and the\nairline’s `zone`. `payments.refund` is not reversible.\n","src/cancel.py":'"""Cancelling and refunding."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\nimport payments\n\nWEEK = timedelta(days=7)\nDAY = timedelta(hours=24)\n\n\ndef refund_share(departs_at, now):\n    left = departs_at - now\n    if left > WEEK:\n        return 1.0\n    if left > DAY:\n        return 0.5\n    return 0.0\n\n\ndef cancel(booking_id, now=None):\n    now = now or datetime.now(timezone.utc)\n    booking = db.one(\n        "SELECT id, fare_paise, tax_paise, fee_paise, departs_at, status FROM bookings WHERE id = %s",\n        (booking_id,),\n    )\n\n    share = refund_share(booking["departs_at"], now)\n    amount = booking["fare_paise"] * share + booking["tax_paise"]\n\n    payments.refund(booking_id, int(amount))\n    db.run("UPDATE bookings SET status = \'cancelled\' WHERE id = %s", (booking_id,))\n    return {"refunded_paise": int(amount)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Cancelling a booking\n\nWhat comes back when a traveller cancels depends on how long before departure\nthey do it. This PR works it out and refunds.\n\n## Rules\n\n- The bands are counted from departure in the airline’s zone: more than 7 days\n  back 100% of the fare, 24 hours to 7 days 50%, under 24 hours nothing.\n- A band boundary is inclusive of the longer window: exactly 24 hours before\n  departure is the 50% band.\n- Taxes come back whatever the band. Fees do not.\n- One cancellation per booking. A retry returns the first result.\n- Amounts are paise, as integers.\n\n## Notes for the reviewer\n\n`bookings` carry `fare_paise`, `tax_paise`, `fee_paise`, `departs_at` and the\nairline’s `zone`. `payments.refund` is not reversible.\n","src/cancel.ts":'// Cancelling and refunding.\nimport { db } from "./db";\nimport * as payments from "./payments";\n\nconst WEEK_MS = 7 * 24 * 60 * 60 * 1000;\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport function refundShare(departsAt: Date, now: Date) {\n  const left = departsAt.getTime() - now.getTime();\n  if (left > WEEK_MS) return 1;\n  if (left > DAY_MS) return 0.5;\n  return 0;\n}\n\nexport async function cancel(bookingId: string, now = new Date()) {\n  const booking = await db.one(\n    "SELECT id, fare_paise, tax_paise, fee_paise, departs_at, status FROM bookings WHERE id = $1",\n    [bookingId],\n  );\n\n  const share = refundShare(new Date(booking.departs_at), now);\n  const amount = booking.fare_paise * share + booking.tax_paise;\n\n  await payments.refund(bookingId, Math.trunc(amount));\n  await db.run("UPDATE bookings SET status = \'cancelled\' WHERE id = $1", [bookingId]);\n  return { refundedPaise: Math.trunc(amount) };\n}\n'}}}},{slug:"seat-map",title:"Choosing a seat",difficulty:"Medium",area:"concurrency",domains:["travel"],minutes:25,summary:"Twenty lines behind the seat map. The exit row rule has three parts and the code checks one of them.",brief:["A teammate has opened this as a pull request. Two people on the same flight are looking at the same map right now.","Have two passengers tap 12A at the same moment. Then move a passenger from 30C to 30D. Then put an adult travelling with an infant in the exit row.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Choosing a seat\n\nThe seat map on the booking page, and the call that takes one. This PR is\nboth.\n\n## Rules\n\n- A seat is held by one passenger. Two people choosing at once do not both get\n  it.\n- An exit row needs a passenger who may sit there: an adult, no infant, no\n  assistance booked.\n- Changing your seat frees the old one in the same step.\n- The map shown to a passenger reflects the aircraft actually assigned, which\n  can change up to departure.\n- The map is read constantly and written rarely.\n\n## Notes for the reviewer\n\n`seats` is `(flight_id, seat_no, passenger_id, exit_row)`. `passengers` carry\n`age`, `infant` and `assistance`.\n","src/Seats.java":'package travel;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** The seat map. */\npublic final class Seats {\n\n    public static List<Map<String, Object>> mapFor(String flightId) {\n        return Db.all("SELECT seat_no, passenger_id, exit_row FROM seats WHERE flight_id = ? ORDER BY seat_no",\n                flightId);\n    }\n\n    public static String choose(String flightId, String passengerId, String seatNo) {\n        Map<String, Object> seat = Db.one(\n                "SELECT seat_no, passenger_id, exit_row FROM seats WHERE flight_id = ? AND seat_no = ?",\n                flightId, seatNo);\n        if (seat.get("passenger_id") != null) {\n            throw new Taken("seat is taken");\n        }\n\n        Map<String, Object> passenger =\n                Db.one("SELECT id, age, infant, assistance FROM passengers WHERE id = ?", passengerId);\n        if ((boolean) seat.get("exit_row") && (int) passenger.get("age") < 18) {\n            throw new Refused("not eligible for an exit row");\n        }\n\n        Db.run("UPDATE seats SET passenger_id = ? WHERE flight_id = ? AND seat_no = ?",\n                passengerId, flightId, seatNo);\n        return seatNo;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Choosing a seat\n\nThe seat map on the booking page, and the call that takes one. This PR is\nboth.\n\n## Rules\n\n- A seat is held by one passenger. Two people choosing at once do not both get\n  it.\n- An exit row needs a passenger who may sit there: an adult, no infant, no\n  assistance booked.\n- Changing your seat frees the old one in the same step.\n- The map shown to a passenger reflects the aircraft actually assigned, which\n  can change up to departure.\n- The map is read constantly and written rarely.\n\n## Notes for the reviewer\n\n`seats` is `(flight_id, seat_no, passenger_id, exit_row)`. `passengers` carry\n`age`, `infant` and `assistance`.\n","src/seats.py":'"""The seat map."""\nimport db\n\n\ndef map_for(flight_id):\n    return db.all(\n        "SELECT seat_no, passenger_id, exit_row FROM seats WHERE flight_id = %s ORDER BY seat_no",\n        (flight_id,),\n    )\n\n\ndef choose(flight_id, passenger_id, seat_no):\n    seat = db.one(\n        "SELECT seat_no, passenger_id, exit_row FROM seats WHERE flight_id = %s AND seat_no = %s",\n        (flight_id, seat_no),\n    )\n    if seat["passenger_id"] is not None:\n        raise Taken("seat is taken")\n\n    passenger = db.one("SELECT id, age, infant, assistance FROM passengers WHERE id = %s", (passenger_id,))\n    if seat["exit_row"] and passenger["age"] < 18:\n        raise Refused("not eligible for an exit row")\n\n    db.run(\n        "UPDATE seats SET passenger_id = %s WHERE flight_id = %s AND seat_no = %s",\n        (passenger_id, flight_id, seat_no),\n    )\n    return {"seat_no": seat_no}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Choosing a seat\n\nThe seat map on the booking page, and the call that takes one. This PR is\nboth.\n\n## Rules\n\n- A seat is held by one passenger. Two people choosing at once do not both get\n  it.\n- An exit row needs a passenger who may sit there: an adult, no infant, no\n  assistance booked.\n- Changing your seat frees the old one in the same step.\n- The map shown to a passenger reflects the aircraft actually assigned, which\n  can change up to departure.\n- The map is read constantly and written rarely.\n\n## Notes for the reviewer\n\n`seats` is `(flight_id, seat_no, passenger_id, exit_row)`. `passengers` carry\n`age`, `infant` and `assistance`.\n","src/seats.ts":'// The seat map.\nimport { db } from "./db";\n\nexport async function mapFor(flightId: string) {\n  return db.all("SELECT seat_no, passenger_id, exit_row FROM seats WHERE flight_id = $1 ORDER BY seat_no", [flightId]);\n}\n\nexport async function choose(flightId: string, passengerId: string, seatNo: string) {\n  const seat = await db.one("SELECT seat_no, passenger_id, exit_row FROM seats WHERE flight_id = $1 AND seat_no = $2", [\n    flightId,\n    seatNo,\n  ]);\n  if (seat.passenger_id !== null) throw new Taken("seat is taken");\n\n  const passenger = await db.one("SELECT id, age, infant, assistance FROM passengers WHERE id = $1", [passengerId]);\n  if (seat.exit_row && passenger.age < 18) throw new Refused("not eligible for an exit row");\n\n  await db.run("UPDATE seats SET passenger_id = $1 WHERE flight_id = $2 AND seat_no = $3", [\n    passengerId,\n    flightId,\n    seatNo,\n  ]);\n  return { seatNo };\n}\n'}}}},{slug:"loyalty-points",title:"Loyalty points",difficulty:"Medium",area:"money",domains:["travel","payments"],minutes:25,summary:"Points in, points out, oldest first. The lot walk looks careful and the thing it does not do is the one that matters.",brief:["A teammate has opened this as a pull request. Points are a currency: members count them, and the airline owes them.","Redeem from two browsers at once. Then redeem when half the lots expired last year. Then look at how many points a fare earns.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Loyalty points\n\nPoints are earned on a flight and spent on a booking. This PR is the earn and\nthe redeem.\n\n## Rules\n\n- Points are earned when a flight is flown, not when it is booked, and once\n  per flight.\n- Points expire two years after they are earned, oldest spent first.\n- A balance is never negative, and two redemptions at once cannot take it\n  below zero.\n- Cancelling a flight takes back the points it earned, even if some have been\n  spent: the balance may then be short, and the member is told.\n- Points are whole numbers.\n\n## Notes for the reviewer\n\n`point_lots` is `(member_id, flight_id, points, earned_on, expires_on,\nspent)`. Spending walks the lots. Rates come from `tiers`.\n","src/Loyalty.java":'package travel;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Earning and spending points. */\npublic final class Loyalty {\n\n    public static double earn(String memberId, String flightId, long farePaise, double tierRate) {\n        double points = farePaise / 100.0 * tierRate;\n\n        Db.run("INSERT INTO point_lots (member_id, flight_id, points, earned_on, expires_on, spent) "\n                + "VALUES (?, ?, ?, now(), now() + interval \'730 days\', 0)", memberId, flightId, points);\n        return points;\n    }\n\n    public static double redeem(String memberId, double points) {\n        List<Map<String, Object>> lots =\n                Db.all("SELECT id, points, spent FROM point_lots WHERE member_id = ? ORDER BY earned_on", memberId);\n\n        double left = points;\n        for (Map<String, Object> lot : lots) {\n            double available = (double) lot.get("points") - (double) lot.get("spent");\n            double take = Math.min(available, left);\n            Db.run("UPDATE point_lots SET spent = spent + ? WHERE id = ?", take, lot.get("id"));\n            left = left - take;\n            if (left == 0) {\n                break;\n            }\n        }\n\n        return points - left;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Loyalty points\n\nPoints are earned on a flight and spent on a booking. This PR is the earn and\nthe redeem.\n\n## Rules\n\n- Points are earned when a flight is flown, not when it is booked, and once\n  per flight.\n- Points expire two years after they are earned, oldest spent first.\n- A balance is never negative, and two redemptions at once cannot take it\n  below zero.\n- Cancelling a flight takes back the points it earned, even if some have been\n  spent: the balance may then be short, and the member is told.\n- Points are whole numbers.\n\n## Notes for the reviewer\n\n`point_lots` is `(member_id, flight_id, points, earned_on, expires_on,\nspent)`. Spending walks the lots. Rates come from `tiers`.\n","src/loyalty.py":'"""Earning and spending points."""\nfrom datetime import timedelta\n\nimport db\n\nTWO_YEARS = timedelta(days=730)\n\n\ndef earn(member_id, flight_id, fare_paise, tier_rate):\n    points = fare_paise / 100 * tier_rate\n\n    db.run(\n        "INSERT INTO point_lots (member_id, flight_id, points, earned_on, expires_on, spent) "\n        "VALUES (%s, %s, %s, now(), now() + interval \'730 days\', 0)",\n        (member_id, flight_id, points),\n    )\n    return {"points": points}\n\n\ndef redeem(member_id, points):\n    lots = db.all(\n        "SELECT id, points, spent FROM point_lots WHERE member_id = %s ORDER BY earned_on",\n        (member_id,),\n    )\n\n    left = points\n    for lot in lots:\n        available = lot["points"] - lot["spent"]\n        take = min(available, left)\n        db.run("UPDATE point_lots SET spent = spent + %s WHERE id = %s", (take, lot["id"]))\n        left = left - take\n        if left == 0:\n            break\n\n    return {"redeemed": points - left}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Loyalty points\n\nPoints are earned on a flight and spent on a booking. This PR is the earn and\nthe redeem.\n\n## Rules\n\n- Points are earned when a flight is flown, not when it is booked, and once\n  per flight.\n- Points expire two years after they are earned, oldest spent first.\n- A balance is never negative, and two redemptions at once cannot take it\n  below zero.\n- Cancelling a flight takes back the points it earned, even if some have been\n  spent: the balance may then be short, and the member is told.\n- Points are whole numbers.\n\n## Notes for the reviewer\n\n`point_lots` is `(member_id, flight_id, points, earned_on, expires_on,\nspent)`. Spending walks the lots. Rates come from `tiers`.\n","src/loyalty.ts":'// Earning and spending points.\nimport { db } from "./db";\n\nexport async function earn(memberId: string, flightId: string, farePaise: number, tierRate: number) {\n  const points = (farePaise / 100) * tierRate;\n\n  await db.run(\n    "INSERT INTO point_lots (member_id, flight_id, points, earned_on, expires_on, spent) " +\n      "VALUES ($1, $2, $3, now(), now() + interval \'730 days\', 0)",\n    [memberId, flightId, points],\n  );\n  return { points };\n}\n\nexport async function redeem(memberId: string, points: number) {\n  const lots = await db.all("SELECT id, points, spent FROM point_lots WHERE member_id = $1 ORDER BY earned_on", [\n    memberId,\n  ]);\n\n  let left = points;\n  for (const lot of lots) {\n    const available = lot.points - lot.spent;\n    const take = Math.min(available, left);\n    await db.run("UPDATE point_lots SET spent = spent + $1 WHERE id = $2", [take, lot.id]);\n    left = left - take;\n    if (left === 0) break;\n  }\n\n  return { redeemed: points - left };\n}\n'}}}},{slug:"price-alerts",title:"Price alerts",difficulty:"Medium",area:"backend",domains:["travel","messaging"],minutes:25,summary:"A job that emails travellers every fifteen minutes when a fare is low. Work out how many emails one fare drop sends.",brief:["A teammate has opened this as a pull request. It runs four times an hour against every alert in the product and sends email.","Drop a fare below a target and leave it there for a day. Then count the supplier calls for ten thousand alerts. Then read the price in the message.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Price alerts\n\nA traveller watches a route and is told when the fare drops. This PR is the\njob that checks and sends.\n\n## Rules\n\n- An alert fires when the fare is below the target, and then not again for\n  that alert until the fare has gone back above it.\n- An alert is for a route, dates, passengers and a currency. Comparing a fare\n  for one passenger against a target for two is not a comparison.\n- A traveller gets at most three alert emails a day across all their alerts.\n- An alert older than ninety days with no activity is retired, and the\n  traveller is told once.\n- The job runs every fifteen minutes over every live alert.\n\n## Notes for the reviewer\n\n`alerts` is `(id, user_id, route, depart_on, passengers, currency,\ntarget_paise, last_fired_at, created_at)`. `fares.cheapest` calls the supplier.\n","src/Alerts.java":'package travel;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** The price alert job. */\npublic final class Alerts {\n    private static final int DAILY_CAP = 3;\n\n    public static int run() {\n        List<Map<String, Object>> alerts = Db.all(\n                "SELECT id, user_id, route, depart_on, passengers, currency, target_paise, last_fired_at FROM alerts");\n\n        int fired = 0;\n        for (Map<String, Object> alert : alerts) {\n            Fares.Quote cheapest = Fares.cheapest((String) alert.get("route"), alert.get("depart_on"));\n\n            if (cheapest.pricePaise() < (long) alert.get("target_paise")) {\n                Mailer.send((String) alert.get("user_id"),\n                        alert.get("route") + " is down to " + cheapest.pricePaise() / 100);\n                Db.run("UPDATE alerts SET last_fired_at = now() WHERE id = ?", alert.get("id"));\n                fired++;\n            }\n        }\n        return fired;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Price alerts\n\nA traveller watches a route and is told when the fare drops. This PR is the\njob that checks and sends.\n\n## Rules\n\n- An alert fires when the fare is below the target, and then not again for\n  that alert until the fare has gone back above it.\n- An alert is for a route, dates, passengers and a currency. Comparing a fare\n  for one passenger against a target for two is not a comparison.\n- A traveller gets at most three alert emails a day across all their alerts.\n- An alert older than ninety days with no activity is retired, and the\n  traveller is told once.\n- The job runs every fifteen minutes over every live alert.\n\n## Notes for the reviewer\n\n`alerts` is `(id, user_id, route, depart_on, passengers, currency,\ntarget_paise, last_fired_at, created_at)`. `fares.cheapest` calls the supplier.\n","src/alerts.py":'"""The price alert job."""\nimport db\nimport fares\nimport mailer\n\nDAILY_CAP = 3\n\n\ndef run():\n    alerts = db.all(\n        "SELECT id, user_id, route, depart_on, passengers, currency, target_paise, last_fired_at FROM alerts"\n    )\n\n    fired = 0\n    for alert in alerts:\n        cheapest = fares.cheapest(alert["route"], alert["depart_on"])\n\n        if cheapest["price_paise"] < alert["target_paise"]:\n            mailer.send(\n                alert["user_id"],\n                f"{alert[\'route\']} is down to {cheapest[\'price_paise\'] / 100}",\n            )\n            db.run("UPDATE alerts SET last_fired_at = now() WHERE id = %s", (alert["id"],))\n            fired += 1\n    return {"fired": fired}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Price alerts\n\nA traveller watches a route and is told when the fare drops. This PR is the\njob that checks and sends.\n\n## Rules\n\n- An alert fires when the fare is below the target, and then not again for\n  that alert until the fare has gone back above it.\n- An alert is for a route, dates, passengers and a currency. Comparing a fare\n  for one passenger against a target for two is not a comparison.\n- A traveller gets at most three alert emails a day across all their alerts.\n- An alert older than ninety days with no activity is retired, and the\n  traveller is told once.\n- The job runs every fifteen minutes over every live alert.\n\n## Notes for the reviewer\n\n`alerts` is `(id, user_id, route, depart_on, passengers, currency,\ntarget_paise, last_fired_at, created_at)`. `fares.cheapest` calls the supplier.\n","src/alerts.ts":'// The price alert job.\nimport { db } from "./db";\nimport * as fares from "./fares";\nimport * as mailer from "./mailer";\n\nconst DAILY_CAP = 3;\n\nexport async function run() {\n  const alerts = await db.all(\n    "SELECT id, user_id, route, depart_on, passengers, currency, target_paise, last_fired_at FROM alerts",\n  );\n\n  let fired = 0;\n  for (const alert of alerts) {\n    const cheapest = await fares.cheapest(alert.route, alert.depart_on);\n\n    if (cheapest.price_paise < alert.target_paise) {\n      await mailer.send(alert.user_id, `${alert.route} is down to ${cheapest.price_paise / 100}`);\n      await db.run("UPDATE alerts SET last_fired_at = now() WHERE id = $1", [alert.id]);\n      fired += 1;\n    }\n  }\n  return { fired };\n}\n'}}}},{slug:"travel-documents",title:"Checking travel documents",difficulty:"Medium",area:"security",domains:["travel","identity"],minutes:25,summary:"A passport, a visa and a destination’s rules. Read the first line of output before you read the logic.",brief:["A teammate has opened this as a pull request. A wrong yes here puts somebody on a plane they will be turned back from.","Check a passport that expires a month after arrival for a country that wants six. Then check a traveller holding a transit visa. Then read the log line and the refusal message.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Checking travel documents\n\nBefore check-in, a traveller’s passport and visa are checked against the\nroute. This PR does the check and stores what was seen.\n\n## Rules\n\n- A passport must be valid for the whole trip, and for six months beyond the\n  arrival date where the destination requires it.\n- A visa is checked against the destination and the purpose. A transit visa is\n  not a visitor visa.\n- Document numbers are stored encrypted and are never in a log, an error\n  message or an analytics event.\n- A check is recorded with its outcome and the rule that failed, so an agent\n  can explain a refusal.\n- A failed check does not stop the traveller from checking in for a domestic\n  leg of the same booking.\n\n## Notes for the reviewer\n\n`documents` is `(traveller_id, kind, number, expires_on, country)`.\n`requirements` holds per-destination rules. `crypto.encrypt` exists.\n","src/Documents.java":'package travel;\n\nimport java.time.LocalDate;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Checking documents before check-in. */\npublic final class Documents {\n    private static final Logger log = Logger.getLogger(Documents.class.getName());\n\n    public record Outcome(boolean ok, String reason) {}\n\n    public static Outcome check(String travellerId, String destination, LocalDate arrivalOn) {\n        Map<String, Object> passport = Db.one(\n                "SELECT number, expires_on, country FROM documents WHERE traveller_id = ? AND kind = \'passport\'",\n                travellerId);\n        Map<String, Object> requirement =\n                Db.one("SELECT months_beyond, needs_visa FROM requirements WHERE country = ?", destination);\n\n        log.info("checking passport " + passport.get("number") + " for " + destination);\n\n        if (((LocalDate) passport.get("expires_on")).isBefore(arrivalOn)) {\n            return new Outcome(false, "passport " + passport.get("number") + " expires before arrival");\n        }\n\n        if ((boolean) requirement.get("needs_visa")) {\n            Map<String, Object> visa = Db.one(\n                    "SELECT number, expires_on FROM documents WHERE traveller_id = ? AND kind = \'visa\'", travellerId);\n            if (visa == null) {\n                return new Outcome(false, "no visa");\n            }\n        }\n\n        return new Outcome(true, null);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Checking travel documents\n\nBefore check-in, a traveller’s passport and visa are checked against the\nroute. This PR does the check and stores what was seen.\n\n## Rules\n\n- A passport must be valid for the whole trip, and for six months beyond the\n  arrival date where the destination requires it.\n- A visa is checked against the destination and the purpose. A transit visa is\n  not a visitor visa.\n- Document numbers are stored encrypted and are never in a log, an error\n  message or an analytics event.\n- A check is recorded with its outcome and the rule that failed, so an agent\n  can explain a refusal.\n- A failed check does not stop the traveller from checking in for a domestic\n  leg of the same booking.\n\n## Notes for the reviewer\n\n`documents` is `(traveller_id, kind, number, expires_on, country)`.\n`requirements` holds per-destination rules. `crypto.encrypt` exists.\n","src/documents.py":'"""Checking documents before check-in."""\nimport logging\nfrom datetime import date\n\nimport db\n\nlog = logging.getLogger(__name__)\n\n\ndef check(traveller_id, destination, arrival_on):\n    passport = db.one(\n        "SELECT number, expires_on, country FROM documents WHERE traveller_id = %s AND kind = \'passport\'",\n        (traveller_id,),\n    )\n    requirement = db.one("SELECT months_beyond, needs_visa FROM requirements WHERE country = %s", (destination,))\n\n    log.info("checking passport %s for %s", passport["number"], destination)\n\n    if passport["expires_on"] < arrival_on:\n        return {"ok": False, "reason": f"passport {passport[\'number\']} expires before arrival"}\n\n    if requirement["needs_visa"]:\n        visa = db.one(\n            "SELECT number, expires_on FROM documents WHERE traveller_id = %s AND kind = \'visa\'",\n            (traveller_id,),\n        )\n        if visa is None:\n            return {"ok": False, "reason": "no visa"}\n\n    return {"ok": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Checking travel documents\n\nBefore check-in, a traveller’s passport and visa are checked against the\nroute. This PR does the check and stores what was seen.\n\n## Rules\n\n- A passport must be valid for the whole trip, and for six months beyond the\n  arrival date where the destination requires it.\n- A visa is checked against the destination and the purpose. A transit visa is\n  not a visitor visa.\n- Document numbers are stored encrypted and are never in a log, an error\n  message or an analytics event.\n- A check is recorded with its outcome and the rule that failed, so an agent\n  can explain a refusal.\n- A failed check does not stop the traveller from checking in for a domestic\n  leg of the same booking.\n\n## Notes for the reviewer\n\n`documents` is `(traveller_id, kind, number, expires_on, country)`.\n`requirements` holds per-destination rules. `crypto.encrypt` exists.\n","src/documents.ts":'// Checking documents before check-in.\nimport { db } from "./db";\nimport { log } from "./log";\n\nexport async function check(travellerId: string, destination: string, arrivalOn: string) {\n  const passport = await db.one(\n    "SELECT number, expires_on, country FROM documents WHERE traveller_id = $1 AND kind = \'passport\'",\n    [travellerId],\n  );\n  const requirement = await db.one("SELECT months_beyond, needs_visa FROM requirements WHERE country = $1", [\n    destination,\n  ]);\n\n  log.info("checking passport %s for %s", passport.number, destination);\n\n  if (passport.expires_on < arrivalOn) {\n    return { ok: false, reason: `passport ${passport.number} expires before arrival` };\n  }\n\n  if (requirement.needs_visa) {\n    const visa = await db.one("SELECT number, expires_on FROM documents WHERE traveller_id = $1 AND kind = \'visa\'", [\n      travellerId,\n    ]);\n    if (!visa) return { ok: false, reason: "no visa" };\n  }\n\n  return { ok: true };\n}\n'}}}},{slug:"jwt-auth",title:"JWT authentication middleware",difficulty:"Hard",area:"security",domains:["identity"],minutes:25,summary:"Bearer-token verification for every route, and the login handler that issues the token.",brief:["A teammate has opened this as a pull request. It decides who is logged in on every request, so review it the way a security-minded senior would.","Read the README for the token contract (algorithm, secret, claims, expiry), then read auth and login together: what one issues, the other must check.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of it is right. Roles in tokens, hashed passwords and a generic login error are all fine."],variants:{java:{entry:"README.md",files:{"README.md":"# JWT authentication filter\n\nEvery API request carries a bearer token issued at login. The filter\nverifies it and attaches `request.user`.\n\n## Token\n\nHS256, signed with `JWT_SECRET` from the environment, claims `sub` (user id),\n`role`, `iat` and `exp` (15 minutes after `iat`). Refresh is handled elsewhere.\n\n## Behaviour\n\n- Missing or invalid token: `401` with a generic message.\n- Valid token: `request.user = {id: sub, role: role}` and the handler runs.\n\n## Notes for the reviewer\n\n`Jose` is our JWT library: `Jose.decode(token, key, algorithms)` verifies the\nsignature and returns the claims; `Jose.header(token)` reads the unverified\nheader. Both throw `JoseException` on any failure.\n","src/Auth.java":'package auth;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Bearer-token authentication for every route. */\npublic final class Auth implements Filter {\n    static final String SECRET = System.getenv().getOrDefault("JWT_SECRET", "dev-secret");\n\n    static String tokenFrom(Request request) {\n        String header = request.headerOr("authorization", "");\n        if (header.toLowerCase().startsWith("bearer ")) {\n            return header.substring(7).trim();\n        }\n        return request.query("token");\n    }\n\n    static Map<String, Object> verify(String token) throws JoseException {\n        Map<String, Object> header = Jose.header(token);\n        return Jose.decode(token, SECRET, List.of((String) header.get("alg")));\n    }\n\n    @Override\n    public Response filter(Request request, Chain chain) {\n        String token = tokenFrom(request);\n        if (token == null || token.isEmpty()) {\n            return Response.of(401, "missing token");\n        }\n        Map<String, Object> claims;\n        try {\n            claims = verify(token);\n        } catch (JoseException exc) {\n            return Response.of(401, "invalid token: " + exc.getMessage());\n        }\n        request.setUser(Map.of("id", claims.get("sub"), "role", claims.getOrDefault("role", "user")));\n        return chain.next(request);\n    }\n}\n',"src/Login.java":'package auth;\n\nimport java.util.Map;\n\n/** POST /login: issue the token. */\npublic final class Login {\n    static final long TTL_SECONDS = 15 * 60;\n\n    public static Response login(String email, String password) {\n        Store.User user = Store.findUser(email);\n        if (user == null || !Security.verifyPassword(password, user.passwordHash())) {\n            return Response.json(401, Map.of("error", "invalid credentials"));\n        }\n        long now = System.currentTimeMillis() / 1000;\n        String token = Jose.encode(Map.of("sub", user.id(), "role", user.role(), "iat", now), Auth.SECRET, "HS256");\n        return Response.json(200, Map.of("token", token))\n                .header("Set-Cookie", "token=" + token + "; Path=/; Secure; SameSite=Lax");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# JWT authentication middleware\n\nEvery API request carries a bearer token issued at login. The middleware\nverifies it and attaches `request.user`.\n\n## Token\n\nHS256, signed with `JWT_SECRET` from the environment, claims `sub` (user id),\n`role`, `iat` and `exp` (15 minutes after `iat`). Refresh is handled elsewhere.\n\n## Behaviour\n\n- Missing or invalid token: `401` with a generic message.\n- Valid token: `request.user = {"id": sub, "role": role}` and the handler runs.\n\n## Notes for the reviewer\n\n`jose` is our JWT library: `jose.decode(token, key, algorithms=[...])`\nverifies the signature and returns the claims; `jose.header(token)` reads the\nunverified header.\n',"src/auth.py":'"""Bearer-token authentication for every route."""\nimport os\n\nimport jose\n\nSECRET = os.environ.get("JWT_SECRET", "dev-secret")\n\n\ndef token_from(request):\n    header = request.headers.get("authorization", "")\n    if header.lower().startswith("bearer "):\n        return header[7:].strip()\n    return request.query.get("token")\n\n\ndef verify(token):\n    header = jose.header(token)\n    claims = jose.decode(token, SECRET, algorithms=[header["alg"]])\n    return claims\n\n\nasync def authenticate(request, handler):\n    token = token_from(request)\n    if not token:\n        return Response(401, "missing token")\n    try:\n        claims = verify(token)\n    except jose.JoseError as exc:\n        return Response(401, "invalid token: %s" % exc)\n    request.user = {"id": claims["sub"], "role": claims.get("role", "user")}\n    return await handler(request)\n\n\nclass Response:\n    def __init__(self, status, body=""):\n        self.status = status\n        self.body = body\n',"src/login.py":'"""POST /login: issue the token."""\nimport time\n\nimport jose\nimport store\nfrom auth import SECRET\nfrom security import verify_password\n\nTTL_SECONDS = 15 * 60\n\n\ndef login(email, password):\n    user = store.find_user(email)\n    if user is None or not verify_password(password, user.password_hash):\n        return 401, {"error": "invalid credentials"}\n    now = int(time.time())\n    token = jose.encode({"sub": user.id, "role": user.role, "iat": now}, SECRET, algorithm="HS256")\n    return 200, {"token": token}, {"Set-Cookie": "token=%s; Path=/; Secure; SameSite=Lax" % token}\n'}},typescript:{entry:"README.md",files:{"README.md":"# JWT authentication middleware\n\nEvery API request carries a bearer token issued at login. The middleware\nverifies it and attaches `req.user`.\n\n## Token\n\nHS256, signed with `JWT_SECRET` from the environment, claims `sub` (user id),\n`role`, `iat` and `exp` (15 minutes after `iat`). Refresh is handled elsewhere.\n\n## Behaviour\n\n- Missing or invalid token: `401` with a generic message.\n- Valid token: `req.user = { id: sub, role }` and the handler runs.\n\n## Notes for the reviewer\n\n`jose` is our JWT library: `jose.verify(token, key, { algorithms })` checks\nthe signature and returns the claims; `jose.decodeHeader(token)` reads the\nunverified header.\n","src/auth.ts":'// Bearer-token authentication for every route.\nimport * as jose from "./jose";\nimport type { Request, Response, NextFunction } from "./framework";\n\nexport const SECRET = process.env.JWT_SECRET ?? "dev-secret";\n\nexport function tokenFrom(req: Request): string | undefined {\n  const header = req.headers.authorization ?? "";\n  if (header.toLowerCase().startsWith("bearer ")) return header.slice(7).trim();\n  return req.query.token;\n}\n\nexport function verify(token: string): jose.Claims {\n  const header = jose.decodeHeader(token);\n  return jose.verify(token, SECRET, { algorithms: [header.alg] });\n}\n\nexport function authenticate(req: Request, res: Response, next: NextFunction): void {\n  const token = tokenFrom(req);\n  if (!token) {\n    res.status(401).send("missing token");\n    return;\n  }\n  let claims: jose.Claims;\n  try {\n    claims = verify(token);\n  } catch (err) {\n    res.status(401).send(`invalid token: ${(err as Error).message}`);\n    return;\n  }\n  req.user = { id: claims.sub, role: claims.role ?? "user" };\n  next();\n}\n',"src/login.ts":'// POST /login: issue the token.\nimport * as jose from "./jose";\nimport * as store from "./store";\nimport { SECRET } from "./auth";\nimport { verifyPassword } from "./security";\nimport type { Request, Response } from "./framework";\n\nconst TTL_SECONDS = 15 * 60;\n\nexport async function login(req: Request, res: Response): Promise<void> {\n  const { email, password } = req.body as { email: string; password: string };\n  const user = await store.findUser(email);\n  if (!user || !(await verifyPassword(password, user.passwordHash))) {\n    res.status(401).json({ error: "invalid credentials" });\n    return;\n  }\n  const now = Math.floor(Date.now() / 1000);\n  const token = jose.sign({ sub: user.id, role: user.role, iat: now }, SECRET, { algorithm: "HS256" });\n  res.setHeader("Set-Cookie", `token=${token}; Path=/; Secure; SameSite=Lax`);\n  res.json({ token });\n}\n'}}}},{slug:"inventory-reservation",title:"Stock reservation",difficulty:"Hard",area:"backend",domains:["ecommerce"],minutes:25,summary:"Hold stock for an order at checkout so two people cannot buy the last unit, and give it back when payment fails.",brief:["A teammate has opened this as a pull request. Money and stock are involved; think about two customers clicking Buy at the same second.","Read the README for the promised behaviour (all-or-nothing, 15-minute release), then trace reserve, release and the checkout hooks together.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","release is written the right way. Use it as the standard the rest should meet."],variants:{java:{entry:"README.md",files:{"README.md":"# Stock reservation\n\nWhen a customer starts checkout we reserve their items so two people cannot\nbuy the last unit. A reservation is released if the order is not paid within\n15 minutes.\n\n## API\n\n- `Reserve.reserve(orderId, items)`: items is a list of `(sku, qty)`. Reserves\n  all of them or none. Returns `true` on success, `false` if any item is short.\n- `Reserve.release(orderId)`: gives the stock back.\n\n## Notes for the reviewer\n\n`Db.transaction(Runnable)` commits when the block returns and rolls back on\nexception. The `stock` table has `sku, available`; `reservations` has\n`order_id, sku, qty, created_at`.\n","src/Checkout.java":'package stock;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Where reserve is called from. */\npublic final class Checkout {\n    public static Response startCheckout(Order order) {\n        List<Reserve.Line> items = order.lines().stream().map(l -> new Reserve.Line(l.sku(), l.qty())).toList();\n        if (!Reserve.reserve(order.id(), items)) {\n            return Response.of(409, "some items are out of stock");\n        }\n        return Response.of(200, Map.of("order_id", order.id()));\n    }\n\n    public static void onPaymentFailed(String orderId) {\n        Reserve.release(orderId);\n    }\n\n    public static void onPaid(String orderId) {\n        Payments.confirm(orderId);\n    }\n}\n',"src/Reserve.java":'package stock;\n\nimport java.util.List;\nimport java.util.Map;\n\n/** Hold stock for an order. */\npublic final class Reserve {\n    public record Line(String sku, int qty) {}\n\n    public static boolean reserve(String orderId, List<Line> items) {\n        for (Line line : items) {\n            Map<String, Object> row = Db.one("SELECT available FROM stock WHERE sku = ?", line.sku());\n            if (row == null || ((Number) row.get("available")).intValue() < line.qty()) {\n                return false;\n            }\n        }\n        for (Line line : items) {\n            Db.run("UPDATE stock SET available = available - ? WHERE sku = ?", line.qty(), line.sku());\n            Db.run("INSERT INTO reservations (order_id, sku, qty, created_at) VALUES (?, ?, ?, now())",\n                    orderId, line.sku(), line.qty());\n        }\n        return true;\n    }\n\n    public static void release(String orderId) {\n        Db.transaction(() -> {\n            List<Map<String, Object>> rows = Db.all("SELECT sku, qty FROM reservations WHERE order_id = ?", orderId);\n            for (Map<String, Object> r : rows) {\n                Db.run("UPDATE stock SET available = available + ? WHERE sku = ?", r.get("qty"), r.get("sku"));\n            }\n            Db.run("DELETE FROM reservations WHERE order_id = ?", orderId);\n        });\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Stock reservation\n\nWhen a customer starts checkout we reserve their items so two people cannot\nbuy the last unit. A reservation is released if the order is not paid within\n15 minutes.\n\n## API\n\n- `reserve(order_id, items)`: items is a list of `(sku, qty)`. Reserves all of\n  them or none. Returns `True` on success, `False` if any item is short.\n- `release(order_id)`: gives the stock back.\n\n## Notes for the reviewer\n\n`db.transaction()` is a context manager that commits on exit and rolls back on\nexception. The `stock` table has `sku, available`; `reservations` has\n`order_id, sku, qty, created_at`.\n","src/checkout.py":'"""Where reserve is called from."""\nfrom reserve import reserve, release\n\nimport payments\n\n\ndef start_checkout(order):\n    items = [(line.sku, line.qty) for line in order.lines]\n    if not reserve(order.id, items):\n        return 409, "some items are out of stock"\n    return 200, {"order_id": order.id}\n\n\ndef on_payment_failed(order_id):\n    release(order_id)\n\n\ndef on_paid(order_id):\n    payments.confirm(order_id)\n',"src/reserve.py":'"""Hold stock for an order."""\nimport db\n\n\ndef reserve(order_id, items):\n    for sku, qty in items:\n        row = db.one("SELECT available FROM stock WHERE sku = %s", (sku,))\n        if row is None or row["available"] < qty:\n            return False\n    for sku, qty in items:\n        db.run("UPDATE stock SET available = available - %s WHERE sku = %s", (qty, sku))\n        db.run(\n            "INSERT INTO reservations (order_id, sku, qty, created_at) VALUES (%s, %s, %s, now())",\n            (order_id, sku, qty),\n        )\n    return True\n\n\ndef release(order_id):\n    with db.transaction():\n        rows = db.all("SELECT sku, qty FROM reservations WHERE order_id = %s", (order_id,))\n        for r in rows:\n            db.run("UPDATE stock SET available = available + %s WHERE sku = %s", (r["qty"], r["sku"]))\n        db.run("DELETE FROM reservations WHERE order_id = %s", (order_id,))\n'}},typescript:{entry:"README.md",files:{"README.md":"# Stock reservation\n\nWhen a customer starts checkout we reserve their items so two people cannot\nbuy the last unit. A reservation is released if the order is not paid within\n15 minutes.\n\n## API\n\n- `reserve(orderId, items)`: items is an array of `{ sku, qty }`. Reserves all\n  of them or none. Resolves `true` on success, `false` if any item is short.\n- `release(orderId)`: gives the stock back.\n\n## Notes for the reviewer\n\n`db.transaction(fn)` runs `fn` with a client, commits when it resolves and\nrolls back when it throws. The `stock` table has `sku, available`;\n`reservations` has `order_id, sku, qty, created_at`.\n","src/checkout.ts":'// Where reserve is called from.\nimport * as payments from "./payments";\nimport { release, reserve } from "./reserve";\n\ntype Order = { id: string; lines: { sku: string; qty: number }[] };\n\nexport async function startCheckout(order: Order): Promise<[number, unknown]> {\n  const items = order.lines.map((l) => ({ sku: l.sku, qty: l.qty }));\n  if (!(await reserve(order.id, items))) return [409, "some items are out of stock"];\n  return [200, { order_id: order.id }];\n}\n\nexport async function onPaymentFailed(orderId: string): Promise<void> {\n  await release(orderId);\n}\n\nexport async function onPaid(orderId: string): Promise<void> {\n  await payments.confirm(orderId);\n}\n',"src/reserve.ts":'// Hold stock for an order.\nimport { db } from "./db";\n\nexport type Item = { sku: string; qty: number };\n\nexport async function reserve(orderId: string, items: Item[]): Promise<boolean> {\n  for (const { sku, qty } of items) {\n    const row = await db.one<{ available: number }>("SELECT available FROM stock WHERE sku = $1", [sku]);\n    if (!row || row.available < qty) return false;\n  }\n  for (const { sku, qty } of items) {\n    await db.run("UPDATE stock SET available = available - $1 WHERE sku = $2", [qty, sku]);\n    await db.run("INSERT INTO reservations (order_id, sku, qty, created_at) VALUES ($1, $2, $3, now())", [orderId, sku, qty]);\n  }\n  return true;\n}\n\nexport async function release(orderId: string): Promise<void> {\n  await db.transaction(async (tx) => {\n    const rows = await tx.all<{ sku: string; qty: number }>("SELECT sku, qty FROM reservations WHERE order_id = $1", [orderId]);\n    for (const r of rows) {\n      await tx.run("UPDATE stock SET available = available + $1 WHERE sku = $2", [r.qty, r.sku]);\n    }\n    await tx.run("DELETE FROM reservations WHERE order_id = $1", [orderId]);\n  });\n}\n'}}}},{slug:"schema-migration",title:"Orders: add a status column",difficulty:"Hard",area:"data",domains:["ecommerce"],minutes:30,summary:"A migration that adds orders.status to a 40-million-row table, a one-shot backfill script, and a rollback. Everything here runs against production while it takes writes.",brief:["A teammate has opened this as a pull request: one SQL migration the runner applies, and a script run by hand afterwards. Read the README for the deploy order and the row counts.","Reason about locks and time: for each statement, what does it hold, for how long, and what is blocked meanwhile? Then check the data rule against the CASE.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are fine on Postgres 14 and are explained in the README; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Orders: add a status column\n\nOrders have no explicit status today; the app infers it from `paid_at`,\n`refunded_at` and `cancelled_at`. This change adds `orders.status` with\nvalues `pending`, `paid`, `refunded`, `cancelled`, backfills existing rows,\nand adds an index for the admin dashboard\'s "orders by status" query.\n\n## Facts\n\n- Postgres 14. `orders` has about 40 million rows and takes writes all day.\n- The rule: `cancelled_at` set means cancelled, else `refunded_at` set means\n  refunded, else `paid_at` set means paid, else pending.\n- We deploy the migration first, then the application code that writes\n  `status`, in that order, with a few hours between them.\n- Migrations run through our runner with a 30-second statement timeout.\n\n## Notes for the reviewer\n\nThe SQL file is applied by the runner; the backfill script is run by hand\nfrom a maintenance box after the migration. `Db.run` is the shared pool.\n',"migrations/0042_add_status.sql":"-- Add orders.status, backfill, index.\nSET statement_timeout = 0;\n\nBEGIN;\n\nALTER TABLE orders ADD COLUMN status text NOT NULL DEFAULT 'pending';\n\nALTER TABLE orders ADD CONSTRAINT orders_status_check\n  CHECK (status IN ('pending', 'paid', 'refunded', 'cancelled'));\n\nCREATE INDEX orders_status_idx ON orders (status);\n\nCOMMIT;\n","scripts/BackfillStatus.java":'package scripts;\n\n/** Backfill orders.status from the timestamp columns. Run once after 0042. */\npublic final class BackfillStatus {\n    public static void backfill() {\n        Db.transaction(() -> Db.run("""\n            UPDATE orders\n               SET status = CASE\n                     WHEN cancelled_at IS NOT NULL THEN \'cancelled\'\n                     WHEN paid_at IS NOT NULL THEN \'paid\'\n                     WHEN refunded_at IS NOT NULL THEN \'refunded\'\n                     ELSE \'pending\'\n                   END\n            """));\n        System.out.println("backfill done");\n    }\n\n    /** Undo 0042 if the deploy is aborted. */\n    public static void rollback() {\n        Db.run("DROP INDEX IF EXISTS orders_status_idx");\n        Db.run("ALTER TABLE orders DROP COLUMN status");\n    }\n\n    public static void main(String[] args) {\n        backfill();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Orders: add a status column\n\nOrders have no explicit status today; the app infers it from `paid_at`,\n`refunded_at` and `cancelled_at`. This change adds `orders.status` with\nvalues `pending`, `paid`, `refunded`, `cancelled`, backfills existing rows,\nand adds an index for the admin dashboard\'s "orders by status" query.\n\n## Facts\n\n- Postgres 14. `orders` has about 40 million rows and takes writes all day.\n- The rule: `cancelled_at` set means cancelled, else `refunded_at` set means\n  refunded, else `paid_at` set means paid, else pending.\n- We deploy the migration first, then the application code that writes\n  `status`, in that order, with a few hours between them.\n- Migrations run through our runner with a 30-second statement timeout.\n\n## Notes for the reviewer\n\nThe SQL file is applied by the runner; the backfill script is run by hand\nfrom a maintenance box after the migration. `db.run` is the shared pool.\n',"migrations/0042_add_status.sql":"-- Add orders.status, backfill, index.\nSET statement_timeout = 0;\n\nBEGIN;\n\nALTER TABLE orders ADD COLUMN status text NOT NULL DEFAULT 'pending';\n\nALTER TABLE orders ADD CONSTRAINT orders_status_check\n  CHECK (status IN ('pending', 'paid', 'refunded', 'cancelled'));\n\nCREATE INDEX orders_status_idx ON orders (status);\n\nCOMMIT;\n","scripts/backfill_status.py":'"""Backfill orders.status from the timestamp columns. Run once after 0042."""\nimport logging\n\nimport db\n\nlog = logging.getLogger(__name__)\n\n\ndef backfill():\n    with db.transaction():\n        db.run(\n            """\n            UPDATE orders\n               SET status = CASE\n                     WHEN cancelled_at IS NOT NULL THEN \'cancelled\'\n                     WHEN paid_at IS NOT NULL THEN \'paid\'\n                     WHEN refunded_at IS NOT NULL THEN \'refunded\'\n                     ELSE \'pending\'\n                   END\n            """\n        )\n    log.info("backfill done")\n\n\ndef rollback():\n    """Undo 0042 if the deploy is aborted."""\n    db.run("DROP INDEX IF EXISTS orders_status_idx")\n    db.run("ALTER TABLE orders DROP COLUMN status")\n\n\nif __name__ == "__main__":\n    backfill()\n'}},typescript:{entry:"README.md",files:{"README.md":'# Orders: add a status column\n\nOrders have no explicit status today; the app infers it from `paid_at`,\n`refunded_at` and `cancelled_at`. This change adds `orders.status` with\nvalues `pending`, `paid`, `refunded`, `cancelled`, backfills existing rows,\nand adds an index for the admin dashboard\'s "orders by status" query.\n\n## Facts\n\n- Postgres 14. `orders` has about 40 million rows and takes writes all day.\n- The rule: `cancelled_at` set means cancelled, else `refunded_at` set means\n  refunded, else `paid_at` set means paid, else pending.\n- We deploy the migration first, then the application code that writes\n  `status`, in that order, with a few hours between them.\n- Migrations run through our runner with a 30-second statement timeout.\n\n## Notes for the reviewer\n\nThe SQL file is applied by the runner; the backfill script is run by hand\nfrom a maintenance box after the migration. `db.run` is the shared pool.\n',"migrations/0042_add_status.sql":"-- Add orders.status, backfill, index.\nSET statement_timeout = 0;\n\nBEGIN;\n\nALTER TABLE orders ADD COLUMN status text NOT NULL DEFAULT 'pending';\n\nALTER TABLE orders ADD CONSTRAINT orders_status_check\n  CHECK (status IN ('pending', 'paid', 'refunded', 'cancelled'));\n\nCREATE INDEX orders_status_idx ON orders (status);\n\nCOMMIT;\n","scripts/backfillStatus.ts":"// Backfill orders.status from the timestamp columns. Run once after 0042.\nimport { db } from \"../lib/db\";\n\nexport async function backfill(): Promise<void> {\n  await db.transaction(async (tx) => {\n    await tx.run(`\n      UPDATE orders\n         SET status = CASE\n               WHEN cancelled_at IS NOT NULL THEN 'cancelled'\n               WHEN paid_at IS NOT NULL THEN 'paid'\n               WHEN refunded_at IS NOT NULL THEN 'refunded'\n               ELSE 'pending'\n             END\n    `);\n  });\n  console.log(\"backfill done\");\n}\n\n/** Undo 0042 if the deploy is aborted. */\nexport async function rollback(): Promise<void> {\n  await db.run(\"DROP INDEX IF EXISTS orders_status_idx\");\n  await db.run(\"ALTER TABLE orders DROP COLUMN status\");\n}\n\nif (require.main === module) void backfill();\n"}}}},{slug:"async-worker",title:"Thumbnail worker",difficulty:"Hard",area:"concurrency",domains:["media"],minutes:30,summary:"A queue consumer that resizes uploaded images ten at a time. At-least-once delivery, a 30-second visibility timeout, and CPU-bound work in an async loop.",brief:["A teammate has opened this as a pull request. Read the queue semantics in the README first; most of what matters here follows from them.","Trace one message from receive to ack, then imagine the same message arriving twice, a resize throwing, and a deploy in the middle of a batch.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are deliberate and explained in the README; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Thumbnail worker\n\nPulls `image.uploaded` messages from the queue, downloads the original,\nwrites a 320px thumbnail to object storage, and records it in `thumbnails`.\nRuns several messages at once.\n\n## Queue semantics\n\n- `queue.receive(n)` returns up to `n` messages and hides them from other\n  workers for the visibility timeout, which is 30 seconds.\n- A message that is not acknowledged before the timeout is delivered again,\n  possibly to another worker. `queue.extend(msg, seconds)` pushes the\n  timeout out.\n- Delivery is at-least-once: the same message can arrive twice even when\n  everything went well.\n\n## Facts\n\n- Originals are 5 to 40 MB; a resize takes 2 to 20 seconds.\n- `thumbnails` has a unique index on `image_id`.\n- The service gets SIGTERM on deploy and has 60 seconds to finish.\n\n## Notes for the reviewer\n\n`Images.resize(bytes, width)` is CPU-bound. `Storage.get` and `Storage.put`\nreturn CompletableFutures over HTTP; the loop runs on a small executor.\n","src/Worker.java":'package thumbs;\n\nimport java.io.File;\nimport java.nio.file.Files;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.concurrent.CompletableFuture;\nimport java.util.concurrent.ConcurrentHashMap;\n\n/** The thumbnail worker loop. */\npublic final class Worker {\n    static final int CONCURRENCY = 10;\n    static final int WIDTH = 320;\n\n    private static final Set<String> inFlight = ConcurrentHashMap.newKeySet();\n\n    public static void runForever() throws Exception {\n        while (true) {\n            List<Message> messages = Queue.receive(CONCURRENCY);\n            if (messages.isEmpty()) {\n                Thread.sleep(1000);\n                continue;\n            }\n            List<CompletableFuture<Void>> tasks = new ArrayList<>();\n            for (Message m : messages) tasks.add(process(m).exceptionally(e -> null));\n            CompletableFuture.allOf(tasks.toArray(new CompletableFuture[0])).join();\n            for (Message m : messages) {\n                Queue.ack(m);\n            }\n        }\n    }\n\n    static CompletableFuture<Void> process(Message msg) {\n        String imageId = msg.body().get("image_id");\n        if (inFlight.contains(imageId)) return CompletableFuture.completedFuture(null);\n        return Storage.get("originals/" + imageId).thenCompose(original -> {\n            inFlight.add(imageId);\n            try {\n                File tmp = File.createTempFile(imageId, ".jpg");\n                byte[] thumb = Images.resize(original, WIDTH);\n                Files.write(tmp.toPath(), thumb);\n                return Storage.put("thumbs/" + imageId + ".jpg", thumb).thenRun(() ->\n                    Db.run("INSERT INTO thumbnails (image_id, width, bytes) VALUES (?, ?, ?)", imageId, WIDTH, thumb.length));\n            } catch (Exception e) {\n                throw new RuntimeException(e);\n            } finally {\n                inFlight.remove(imageId);\n            }\n        });\n    }\n\n    public static void main(String[] args) throws Exception {\n        runForever();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Thumbnail worker\n\nPulls `image.uploaded` messages from the queue, downloads the original,\nwrites a 320px thumbnail to object storage, and records it in `thumbnails`.\nRuns several messages at once.\n\n## Queue semantics\n\n- `queue.receive(n)` returns up to `n` messages and hides them from other\n  workers for the visibility timeout, which is 30 seconds.\n- A message that is not acknowledged before the timeout is delivered again,\n  possibly to another worker. `queue.extend(msg, seconds)` pushes the\n  timeout out.\n- Delivery is at-least-once: the same message can arrive twice even when\n  everything went well.\n\n## Facts\n\n- Originals are 5 to 40 MB; a resize takes 2 to 20 seconds.\n- `thumbnails` has a unique index on `image_id`.\n- The service gets SIGTERM on deploy and has 60 seconds to finish.\n\n## Notes for the reviewer\n\n`images.resize(bytes, width)` is CPU-bound and synchronous.\n`storage.get` and `storage.put` are async HTTP calls.\n","src/worker.py":'"""The thumbnail worker loop."""\nimport asyncio\nimport logging\nimport tempfile\n\nimport db\nimport images\nimport queue\nimport storage\n\nlog = logging.getLogger(__name__)\n\nCONCURRENCY = 10\nWIDTH = 320\n\nin_flight = set()\n\n\nasync def run_forever():\n    while True:\n        messages = await queue.receive(CONCURRENCY)\n        if not messages:\n            await asyncio.sleep(1)\n            continue\n        await asyncio.gather(*(process(m) for m in messages), return_exceptions=True)\n        for m in messages:\n            await queue.ack(m)\n\n\nasync def process(msg):\n    image_id = msg.body["image_id"]\n    if image_id in in_flight:\n        return\n    original = await storage.get(f"originals/{image_id}")\n    in_flight.add(image_id)\n    try:\n        tmp = tempfile.NamedTemporaryFile(delete=False, suffix=".jpg")\n        thumb = images.resize(original, WIDTH)\n        tmp.write(thumb)\n        tmp.close()\n        await storage.put(f"thumbs/{image_id}.jpg", thumb)\n        db.run(\n            "INSERT INTO thumbnails (image_id, width, bytes) VALUES (%s, %s, %s)",\n            (image_id, WIDTH, len(thumb)),\n        )\n    finally:\n        in_flight.discard(image_id)\n\n\nif __name__ == "__main__":\n    asyncio.run(run_forever())\n'}},typescript:{entry:"README.md",files:{"README.md":"# Thumbnail worker\n\nPulls `image.uploaded` messages from the queue, downloads the original,\nwrites a 320px thumbnail to object storage, and records it in `thumbnails`.\nRuns several messages at once.\n\n## Queue semantics\n\n- `queue.receive(n)` returns up to `n` messages and hides them from other\n  workers for the visibility timeout, which is 30 seconds.\n- A message that is not acknowledged before the timeout is delivered again,\n  possibly to another worker. `queue.extend(msg, seconds)` pushes the\n  timeout out.\n- Delivery is at-least-once: the same message can arrive twice even when\n  everything went well.\n\n## Facts\n\n- Originals are 5 to 40 MB; a resize takes 2 to 20 seconds.\n- `thumbnails` has a unique index on `image_id`.\n- The service gets SIGTERM on deploy and has 60 seconds to finish.\n\n## Notes for the reviewer\n\n`images.resize(bytes, width)` is CPU-bound and synchronous.\n`storage.get` and `storage.put` are async HTTP calls.\n","src/worker.ts":'// The thumbnail worker loop.\nimport { tmpdir } from "node:os";\nimport { join } from "node:path";\nimport { writeFileSync } from "node:fs";\nimport { db } from "./db";\nimport * as images from "./images";\nimport * as queue from "./queue";\nimport * as storage from "./storage";\n\nconst CONCURRENCY = 10;\nconst WIDTH = 320;\n\nconst inFlight = new Set<string>();\n\nexport async function runForever(): Promise<void> {\n  while (true) {\n    const messages = await queue.receive(CONCURRENCY);\n    if (messages.length === 0) {\n      await new Promise((r) => setTimeout(r, 1000));\n      continue;\n    }\n    await Promise.allSettled(messages.map((m) => process(m)));\n    for (const m of messages) {\n      await queue.ack(m);\n    }\n  }\n}\n\nasync function process(msg: queue.Message): Promise<void> {\n  const imageId = msg.body.image_id as string;\n  if (inFlight.has(imageId)) return;\n  const original = await storage.get(`originals/${imageId}`);\n  inFlight.add(imageId);\n  try {\n    const tmp = join(tmpdir(), `${imageId}.jpg`);\n    const thumb = images.resize(original, WIDTH);\n    writeFileSync(tmp, thumb);\n    await storage.put(`thumbs/${imageId}.jpg`, thumb);\n    await db.run("INSERT INTO thumbnails (image_id, width, bytes) VALUES ($1, $2, $3)", [imageId, WIDTH, thumb.length]);\n  } finally {\n    inFlight.delete(imageId);\n  }\n}\n\nif (require.main === module) void runForever();\n'}}}},{slug:"redis-sessions",title:"Move sessions to Redis",difficulty:"Hard",area:"security",domains:["identity"],minutes:25,summary:"Sessions move from Postgres to Redis. Clean, short and almost entirely correct; one requirement is not met, and the rest is bait for reviewers who flag good code.",brief:["A teammate has opened this as a pull request. Read the four requirements in the README, then the two files, and decide for each requirement whether the code meets it.","Approving is a valid outcome. Every comment on correct code costs accuracy; the one real gap is worth finding.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","The cookie is handled elsewhere, as the README says; do not review what is not here."],variants:{java:{entry:"README.md",files:{"README.md":"# Move sessions to Redis\n\nSessions were rows in Postgres; this PR moves them to Redis so the\n`GET /me` path stops hitting the primary. Nothing about the cookie\nchanges.\n\n## Requirements\n\n- A session lives 30 days from the last request, not from login\n  (sliding expiry).\n- Logout destroys the session immediately.\n- Session ids are unguessable.\n- The session stores only the user id and the login time.\n\n## Notes for the reviewer\n\n`Redis` is the shared client (`get`, `set(key, value, exSeconds)`,\n`delete`, `expire`). The cookie is set elsewhere with HttpOnly, Secure\nand SameSite=Lax, as before.\n","src/Authenticate.java":'package auth;\n\nimport java.util.Map;\n\n/** Attach request.user from the session cookie. */\npublic final class Authenticate implements Filter {\n    @Override\n    public Response filter(Request request, Chain chain) {\n        Map<String, Object> session = Sessions.load(request.cookie("sid"));\n        request.setUser(null);\n        if (session != null) {\n            request.setUser(Map.of("id", session.get("user_id")));\n        }\n        return chain.next(request);\n    }\n}\n',"src/Sessions.java":'package auth;\n\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport java.util.Map;\n\n/** Sessions in Redis. */\npublic final class Sessions {\n    static final int TTL = 30 * 24 * 3600;\n    private static final SecureRandom random = new SecureRandom();\n\n    private static String key(String sid) {\n        return "session:" + sid;\n    }\n\n    public static String create(String userId) {\n        byte[] bytes = new byte[32];\n        random.nextBytes(bytes);\n        String sid = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);\n        Redis.set(key(sid), Json.stringify(Map.of("user_id", userId, "logged_in_at", System.currentTimeMillis() / 1000)), TTL);\n        return sid;\n    }\n\n    public static Map<String, Object> load(String sid) {\n        if (sid == null || sid.isEmpty()) return null;\n        String raw = Redis.get(key(sid));\n        if (raw == null) return null;\n        return Json.parse(raw);\n    }\n\n    public static void destroy(String sid) {\n        Redis.delete(key(sid));\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Move sessions to Redis\n\nSessions were rows in Postgres; this PR moves them to Redis so the\n`GET /me` path stops hitting the primary. Nothing about the cookie\nchanges.\n\n## Requirements\n\n- A session lives 30 days from the last request, not from login\n  (sliding expiry).\n- Logout destroys the session immediately.\n- Session ids are unguessable.\n- The session stores only the user id and the login time.\n\n## Notes for the reviewer\n\n`redis` is the shared client (`get`, `set(key, value, ex=seconds)`,\n`delete`, `expire`). The cookie is set elsewhere with HttpOnly, Secure\nand SameSite=Lax, as before.\n","src/middleware.py":'"""Attach request.user from the session cookie."""\nimport sessions\n\n\nasync def authenticate(request, handler):\n    sid = request.cookies.get("sid")\n    session = sessions.load(sid)\n    request.user = None\n    if session is not None:\n        request.user = {"id": session["user_id"]}\n    return await handler(request)\n',"src/sessions.py":'"""Sessions in Redis."""\nimport json\nimport secrets\nimport time\n\nimport redis\n\nTTL = 30 * 24 * 3600\n\n\ndef _key(sid):\n    return f"session:{sid}"\n\n\ndef create(user_id):\n    sid = secrets.token_urlsafe(32)\n    redis.set(_key(sid), json.dumps({"user_id": user_id, "logged_in_at": int(time.time())}), ex=TTL)\n    return sid\n\n\ndef load(sid):\n    if not sid:\n        return None\n    raw = redis.get(_key(sid))\n    if raw is None:\n        return None\n    return json.loads(raw)\n\n\ndef destroy(sid):\n    redis.delete(_key(sid))\n'}},typescript:{entry:"README.md",files:{"README.md":"# Move sessions to Redis\n\nSessions were rows in Postgres; this PR moves them to Redis so the\n`GET /me` path stops hitting the primary. Nothing about the cookie\nchanges.\n\n## Requirements\n\n- A session lives 30 days from the last request, not from login\n  (sliding expiry).\n- Logout destroys the session immediately.\n- Session ids are unguessable.\n- The session stores only the user id and the login time.\n\n## Notes for the reviewer\n\n`redis` is the shared client (`get`, `set(key, value, ex=seconds)`,\n`delete`, `expire`). The cookie is set elsewhere with HttpOnly, Secure\nand SameSite=Lax, as before.\n","src/middleware.ts":'// Attach req.user from the session cookie.\nimport type { Request, Response, NextFunction } from "./http";\nimport * as sessions from "./sessions";\n\nexport async function authenticate(req: Request, _res: Response, next: NextFunction): Promise<void> {\n  const session = await sessions.load(req.cookies.sid);\n  req.user = session ? { id: session.userId } : null;\n  next();\n}\n',"src/sessions.ts":'// Sessions in Redis.\nimport { randomBytes } from "node:crypto";\nimport { redis } from "./redis";\n\nconst TTL = 30 * 24 * 3600;\n\nconst key = (sid: string) => `session:${sid}`;\n\nexport async function create(userId: string): Promise<string> {\n  const sid = randomBytes(32).toString("base64url");\n  await redis.set(key(sid), JSON.stringify({ userId, loggedInAt: Math.floor(Date.now() / 1000) }), { EX: TTL });\n  return sid;\n}\n\nexport async function load(sid: string | undefined): Promise<{ userId: string; loggedInAt: number } | null> {\n  if (!sid) return null;\n  const raw = await redis.get(key(sid));\n  if (raw === null) return null;\n  return JSON.parse(raw);\n}\n\nexport async function destroy(sid: string): Promise<void> {\n  await redis.delete(key(sid));\n}\n'}}}},{slug:"redis-lock",title:"Redis lock around report generation",difficulty:"Hard",area:"concurrency",domains:["analytics"],minutes:25,summary:"Eighteen lines of mutex and the endpoint that uses it. Distributed locks fail in specific, well-known ways; find which of them this one has.",brief:["A teammate has opened this as a pull request. Hold it against the three requirements in the README, especially the one about a dead server.","Play out a crash mid-build, a build that takes longer than expected, two servers racing, and a caller who can choose the key.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Redis lock around report generation\n\nGenerating a customer's monthly report takes 20 to 60 seconds and must not\nrun twice for the same customer at once (it writes files by name). This PR\nadds a Redis lock around it.\n\n## Requirements\n\n- One report per customer at a time, across all app servers.\n- If a server dies mid-report, another must be able to generate within a\n  minute or two, not never.\n- A server must never release a lock that another server holds.\n\n## Notes for the reviewer\n\n`Redis` is the shared client (`setNx(key, value)`, `setNxEx(key, value, seconds)`,\n`get`, `delete`, `eval`). `Reports.build(customerId)` is the slow part;\n`customerId` comes from the URL.\n","src/Lock.java":'package reports;\n\n/** A Redis mutex. */\npublic final class Lock {\n    public static boolean acquire(String name) throws InterruptedException {\n        while (true) {\n            if (Redis.setNx(name, "1")) {\n                return true;\n            }\n            Thread.sleep(10);\n        }\n    }\n\n    public static void release(String name) {\n        Redis.delete(name);\n    }\n}\n',"src/Report.java":'package reports;\n\nimport java.util.Map;\n\n/** POST /customers/{id}/report */\npublic final class Report {\n    public static Response generate(String customerId) throws InterruptedException {\n        String key = "lock:" + customerId;\n        Lock.acquire(key);\n        try {\n            String path = Reports.build(customerId);\n            return Response.of(200, Map.of("path", path));\n        } finally {\n            Lock.release(key);\n        }\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Redis lock around report generation\n\nGenerating a customer's monthly report takes 20 to 60 seconds and must not\nrun twice for the same customer at once (it writes files by name). This PR\nadds a Redis lock around it.\n\n## Requirements\n\n- One report per customer at a time, across all app servers.\n- If a server dies mid-report, another must be able to generate within a\n  minute or two, not never.\n- A server must never release a lock that another server holds.\n\n## Notes for the reviewer\n\n`redis` is the shared client (`set(key, value, nx=..., ex=...)`, `get`,\n`delete`, `eval`). `reports.build(customer_id)` is the slow part;\n`customer_id` comes from the URL.\n","src/lock.py":'"""A Redis mutex."""\nimport time\n\nimport redis\n\n\ndef acquire(name):\n    while True:\n        if redis.set(name, "1", nx=True):\n            return True\n        time.sleep(0.01)\n\n\ndef release(name):\n    redis.delete(name)\n',"src/report.py":'"""POST /customers/{id}/report"""\nimport lock\nimport reports\n\n\ndef generate(customer_id):\n    key = "lock:" + customer_id\n    lock.acquire(key)\n    try:\n        path = reports.build(customer_id)\n    finally:\n        lock.release(key)\n    return 200, {"path": path}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Redis lock around report generation\n\nGenerating a customer's monthly report takes 20 to 60 seconds and must not\nrun twice for the same customer at once (it writes files by name). This PR\nadds a Redis lock around it.\n\n## Requirements\n\n- One report per customer at a time, across all app servers.\n- If a server dies mid-report, another must be able to generate within a\n  minute or two, not never.\n- A server must never release a lock that another server holds.\n\n## Notes for the reviewer\n\n`redis` is the shared client (`set(key, value, nx=..., ex=...)`, `get`,\n`delete`, `eval`). `reports.build(customer_id)` is the slow part;\n`customer_id` comes from the URL.\n","src/lock.ts":'// A Redis mutex.\nimport { redis } from "./redis";\n\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\nexport async function acquire(name: string): Promise<true> {\n  while (true) {\n    if (await redis.set(name, "1", { NX: true })) return true;\n    await sleep(10);\n  }\n}\n\nexport async function release(name: string): Promise<void> {\n  await redis.delete(name);\n}\n',"src/report.ts":'// POST /customers/:id/report\nimport * as lock from "./lock";\nimport * as reports from "./reports";\n\nexport async function generate(customerId: string) {\n  const key = "lock:" + customerId;\n  await lock.acquire(key);\n  try {\n    const path = await reports.build(customerId);\n    return { status: 200, body: { path } };\n  } finally {\n    await lock.release(key);\n  }\n}\n'}}}},{slug:"oauth-callback",title:"Login with Google",difficulty:"Hard",area:"security",domains:["identity"],minutes:25,summary:"An OAuth 2.0 / OpenID Connect sign-in in two functions. Every line of the callback is a known attack if it is missing.",brief:["A teammate has opened this as a pull request. The README note on jwt.decode versus jwt.verify is the hint; the rest is knowing the OAuth checklist.","Walk the callback as an attacker: what if you send your own code, your own id_token, an email you do not own, or a next you chose?","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some choices are correct; a comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":'# Login with Google\n\nAdds "Continue with Google" using OAuth 2.0 / OpenID Connect. The browser\nis sent to Google with a `state`; Google redirects back to\n`/auth/google/callback?code=&state=`; we exchange the code for tokens,\nread the id_token, and sign the user in (creating the account on first\nlogin by email).\n\n## Notes for the reviewer\n\n`OAuth.exchange(code)` posts to Google\'s token endpoint and returns\n`{"id_token": ..., "access_token": ...}`. `Jwt.decode(token)` decodes\nWITHOUT verifying; `Jwt.verify(token, keys, audience, issuer)` verifies.\n`GOOGLE_KEYS` are Google\'s public keys. `Sessions.create(userId)` sets\nthe cookie. The login page passes `?next=` so users land where they were.\n',"src/GoogleAuth.java":'package auth;\n\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Google sign-in: start and callback. */\npublic final class GoogleAuth {\n    private static final Logger log = Logger.getLogger(GoogleAuth.class.getName());\n    static final String CLIENT_ID = "1234-abcd.apps.googleusercontent.com";\n    private static final SecureRandom random = new SecureRandom();\n\n    public static Response start(Request request) {\n        byte[] bytes = new byte[16];\n        random.nextBytes(bytes);\n        String state = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);\n        request.session().put("oauth_state", state);\n        request.session().put("next", request.queryOr("next", "/"));\n        return Response.redirect(302, OAuth.authorizeUrl(CLIENT_ID, state, "openid email profile"));\n    }\n\n    public static Response callback(Request request) {\n        String code = request.query("code");\n        Map<String, String> tokens = OAuth.exchange(code);\n        log.info("google tokens for " + request.remoteAddr() + ": " + tokens);\n\n        Map<String, Object> claims = Jwt.decode(tokens.get("id_token"));\n        String email = (String) claims.get("email");\n        User user = Store.findUserByEmail(email);\n        if (user == null) {\n            user = Store.createUser(email, (String) claims.get("name"), (String) claims.get("sub"));\n        }\n\n        Sessions.create(user.id());\n        String next = (String) request.session().remove("next");\n        return Response.redirect(302, next == null ? "/" : next);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":'# Login with Google\n\nAdds "Continue with Google" using OAuth 2.0 / OpenID Connect. The browser\nis sent to Google with a `state`; Google redirects back to\n`/auth/google/callback?code=&state=`; we exchange the code for tokens,\nread the id_token, and sign the user in (creating the account on first\nlogin by email).\n\n## Notes for the reviewer\n\n`oauth.exchange(code)` posts to Google\'s token endpoint and returns\n`{"id_token": ..., "access_token": ...}`. `jwt.decode(token)` decodes\nWITHOUT verifying; `jwt.verify(token, keys, audience, issuer)` verifies.\n`GOOGLE_KEYS` are Google\'s public keys. `sessions.create(user_id)` sets\nthe cookie. The login page passes `?next=` so users land where they were.\n',"src/google_auth.py":'"""Google sign-in: start and callback."""\nimport logging\nimport secrets\n\nimport jwt\nimport oauth\nimport sessions\nimport store\n\nlog = logging.getLogger(__name__)\n\nCLIENT_ID = "1234-abcd.apps.googleusercontent.com"\n\n\ndef start(request):\n    state = secrets.token_urlsafe(16)\n    request.session["oauth_state"] = state\n    request.session["next"] = request.query.get("next", "/")\n    return 302, oauth.authorize_url(client_id=CLIENT_ID, state=state, scope="openid email profile")\n\n\ndef callback(request):\n    code = request.query["code"]\n    tokens = oauth.exchange(code)\n    log.info("google tokens for %s: %s", request.remote_addr, tokens)\n\n    claims = jwt.decode(tokens["id_token"])\n    email = claims["email"]\n    user = store.find_user_by_email(email)\n    if user is None:\n        user = store.create_user(email=email, name=claims.get("name"), google_sub=claims["sub"])\n\n    sessions.create(user.id)\n    return 302, request.session.pop("next", "/")\n'}},typescript:{entry:"README.md",files:{"README.md":'# Login with Google\n\nAdds "Continue with Google" using OAuth 2.0 / OpenID Connect. The browser\nis sent to Google with a `state`; Google redirects back to\n`/auth/google/callback?code=&state=`; we exchange the code for tokens,\nread the id_token, and sign the user in (creating the account on first\nlogin by email).\n\n## Notes for the reviewer\n\n`oauth.exchange(code)` posts to Google\'s token endpoint and returns\n`{"id_token": ..., "access_token": ...}`. `jwt.decode(token)` decodes\nWITHOUT verifying; `jwt.verify(token, keys, audience, issuer)` verifies.\n`GOOGLE_KEYS` are Google\'s public keys. `sessions.create(user_id)` sets\nthe cookie. The login page passes `?next=` so users land where they were.\n',"src/googleAuth.ts":'// Google sign-in: start and callback.\nimport { randomBytes } from "node:crypto";\nimport * as jwt from "./jwt";\nimport * as oauth from "./oauth";\nimport * as sessions from "./sessions";\nimport * as store from "./store";\nimport type { Request } from "./http";\n\nconst CLIENT_ID = "1234-abcd.apps.googleusercontent.com";\n\nexport function start(req: Request) {\n  const state = randomBytes(16).toString("base64url");\n  req.session.oauthState = state;\n  req.session.next = (req.query.next as string) ?? "/";\n  return { status: 302, location: oauth.authorizeUrl({ clientId: CLIENT_ID, state, scope: "openid email profile" }) };\n}\n\nexport async function callback(req: Request) {\n  const code = req.query.code as string;\n  const tokens = await oauth.exchange(code);\n  console.log(`google tokens for ${req.ip}: ${JSON.stringify(tokens)}`);\n\n  const claims = jwt.decode(tokens.id_token) as { email: string; sub: string; name?: string; email_verified?: boolean };\n  const email = claims.email;\n  let user = await store.findUserByEmail(email);\n  if (!user) {\n    user = await store.createUser({ email, name: claims.name, googleSub: claims.sub });\n  }\n\n  await sessions.create(user.id);\n  const next = req.session.next ?? "/";\n  delete req.session.next;\n  return { status: 302, location: next };\n}\n'}}}},{slug:"log-redaction",title:"Redact secrets in request logs",difficulty:"Hard",area:"security",domains:["devtools"],minutes:20,summary:"A recursive redaction pass before request logging. Well built; the question is what still gets through.",brief:["A teammate has opened this as a pull request. The README gives three rules; the code meets most of them well.","Think like the data: a card number as people actually type it, a header that is not on the list but should be. Approving with one or two comments is a fine outcome.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Several things here are deliberate and correct."],variants:{java:{entry:"README.md",files:{"README.md":"# Redact secrets in request logs\n\nEvery request is logged with its headers and JSON body for debugging.\nThis PR adds a redaction pass so that passwords, tokens and card numbers\nnever reach the log store.\n\n## Rules\n\n- Redact the values of any key named `password`, `token`, `secret`,\n  `authorization`, `card_number`, `cvv`, at any depth, case-insensitively.\n- Redact anything that looks like a card number (13 to 19 digits) in\n  any string value.\n- Logging must never fail a request.\n\n## Notes for the reviewer\n\n`Log.info` takes a map and serialises it. Bodies are parsed JSON; they\ncan nest and contain lists. Requests are up to 1 MB.\n","src/Redact.java":'package logging;\n\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.regex.Pattern;\n\n/** Redact secrets before logging. */\npublic final class Redact {\n    static final Set<String> SENSITIVE = Set.of("password", "token", "secret", "authorization", "card_number", "cvv");\n    static final Pattern CARD = Pattern.compile("\\\\b\\\\d{13,19}\\\\b");\n\n    @SuppressWarnings("unchecked")\n    public static Object redact(Object value) {\n        if (value instanceof Map<?, ?> map) {\n            Map<String, Object> out = new LinkedHashMap<>();\n            for (Map.Entry<?, ?> e : map.entrySet()) {\n                String k = String.valueOf(e.getKey());\n                out.put(k, SENSITIVE.contains(k.toLowerCase()) ? "[redacted]" : redact(e.getValue()));\n            }\n            return out;\n        }\n        if (value instanceof List<?> list) {\n            List<Object> out = new ArrayList<>();\n            for (Object v : list) out.add(redact(v));\n            return out;\n        }\n        if (value instanceof String s) {\n            return CARD.matcher(s).replaceAll("[card]");\n        }\n        return value;\n    }\n\n    public static void logRequest(Request request) {\n        try {\n            Map<String, String> headers = new LinkedHashMap<>();\n            request.headers().forEach((k, v) -> headers.put(k.toLowerCase(), v));\n            Log.info(Map.of("method", request.method(), "path", request.path(), "headers", redact(headers), "body", redact(request.json())));\n        } catch (Exception e) {\n            Log.warn("could not log request");\n        }\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Redact secrets in request logs\n\nEvery request is logged with its headers and JSON body for debugging.\nThis PR adds a redaction pass so that passwords, tokens and card numbers\nnever reach the log store.\n\n## Rules\n\n- Redact the values of any key named `password`, `token`, `secret`,\n  `authorization`, `card_number`, `cvv`, at any depth, case-insensitively.\n- Redact anything that looks like a card number (13 to 19 digits) in\n  any string value.\n- Logging must never fail a request.\n\n## Notes for the reviewer\n\n`log.info` takes a dict and serialises it. Bodies are parsed JSON; they\ncan nest and contain lists. Requests are up to 1 MB.\n","src/redact.py":'"""Redact secrets before logging."""\nimport logging\nimport re\n\nlog = logging.getLogger("requests")\n\nSENSITIVE = {"password", "token", "secret", "authorization", "card_number", "cvv"}\nCARD = re.compile(r"\\b\\d{13,19}\\b")\n\n\ndef redact(value):\n    if isinstance(value, dict):\n        return {k: "[redacted]" if k.lower() in SENSITIVE else redact(v) for k, v in value.items()}\n    if isinstance(value, list):\n        return [redact(v) for v in value]\n    if isinstance(value, str):\n        return CARD.sub("[card]", value)\n    return value\n\n\ndef log_request(request):\n    try:\n        headers = {k.lower(): v for k, v in request.headers.items()}\n        log.info({"method": request.method, "path": request.path, "headers": redact(headers), "body": redact(request.json)})\n    except Exception:\n        log.warning("could not log request")\n'}},typescript:{entry:"README.md",files:{"README.md":"# Redact secrets in request logs\n\nEvery request is logged with its headers and JSON body for debugging.\nThis PR adds a redaction pass so that passwords, tokens and card numbers\nnever reach the log store.\n\n## Rules\n\n- Redact the values of any key named `password`, `token`, `secret`,\n  `authorization`, `card_number`, `cvv`, at any depth, case-insensitively.\n- Redact anything that looks like a card number (13 to 19 digits) in\n  any string value.\n- Logging must never fail a request.\n\n## Notes for the reviewer\n\n`log.info` takes a dict and serialises it. Bodies are parsed JSON; they\ncan nest and contain lists. Requests are up to 1 MB.\n","src/redact.ts":'// Redact secrets before logging.\nimport { log } from "./log";\nimport type { Request } from "./http";\n\nconst SENSITIVE = new Set(["password", "token", "secret", "authorization", "card_number", "cvv"]);\nconst CARD = /\\b\\d{13,19}\\b/g;\n\nexport function redact(value: unknown): unknown {\n  if (Array.isArray(value)) return value.map(redact);\n  if (value && typeof value === "object") {\n    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, SENSITIVE.has(k.toLowerCase()) ? "[redacted]" : redact(v)]));\n  }\n  if (typeof value === "string") return value.replace(CARD, "[card]");\n  return value;\n}\n\nexport function logRequest(req: Request): void {\n  try {\n    const headers = Object.fromEntries(Object.entries(req.headers).map(([k, v]) => [k.toLowerCase(), v]));\n    log.info({ method: req.method, path: req.path, headers: redact(headers), body: redact(req.body) });\n  } catch {\n    log.warn("could not log request");\n  }\n}\n'}}}},{slug:"assignment-regrade",title:"Late penalties and re-grading",difficulty:"Hard",area:"time",domains:["edtech"],minutes:30,summary:"A late submission, a penalty per day, a teacher re-grading afterwards, and the best mark on the transcript. Five rules, and the arithmetic disagrees with most of them.",brief:["A teammate has opened this as a pull request. The five rules in the README are the spec; read the code against them one at a time.","Trace a student in Kolkata who submits at 00:30 the night after the due date, gets 60, and is re-graded to 80 a week later. Then trace one who is eleven days late.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Two of the choices here look wrong and are exactly what the rules ask for. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Late submissions and re-grading\n\nA student submits an assignment, sometimes late. A penalty is applied, and a\nteacher can re-grade the submission afterwards. This PR adds both paths and\nthe mark that ends up on the transcript.\n\n## Rules\n\n- An assignment is due at 23:59 on `due_on`, in the student's own time zone.\n- A submission after that moment is late. Any part of a day late counts as a\n  whole day.\n- The penalty is 10% of the mark for each day late. It never takes more than\n  50%, and a mark never goes below zero.\n- The mark a student keeps is the best of their submissions, compared after\n  the penalty.\n- The penalty belongs to when a submission arrived, not to how many times it\n  has been graded. Re-grading replaces the teacher's raw mark and nothing else.\n\n## Notes for the reviewer\n\n`submissions` rows carry `student_id`, `assignment_id`, `submitted_at` (UTC),\n`raw_mark`, `final_mark` and `days_late`. Students carry `timezone`, an IANA\nname. Assignments carry `due_on` (a date) and `max_mark`.\n","src/Grading.java":'package learn;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.LocalTime;\nimport java.time.ZoneOffset;\nimport java.util.List;\nimport java.util.Map;\n\n/** Late penalties, re-grading, and the mark that counts. */\npublic final class Grading {\n    private static final double PENALTY_PER_DAY = 0.10;\n\n    public static int daysLate(Map<String, Object> assignment, Instant submittedAt) {\n        LocalDate dueOn = (LocalDate) assignment.get("due_on");\n        Instant due = dueOn.atTime(LocalTime.of(23, 59)).toInstant(ZoneOffset.UTC);\n        if (!submittedAt.isAfter(due)) {\n            return 0;\n        }\n        return (int) Math.ceil(Duration.between(due, submittedAt).getSeconds() / 86400.0);\n    }\n\n    public static double recordSubmission(String studentId, String assignmentId, double rawMark, Instant submittedAt) {\n        Map<String, Object> assignment = Db.one("SELECT id, due_on, max_mark FROM assignments WHERE id = ?", assignmentId);\n        int late = daysLate(assignment, submittedAt);\n        double finalMark = rawMark - rawMark * PENALTY_PER_DAY * late;\n        Db.run("INSERT INTO submissions (student_id, assignment_id, submitted_at, raw_mark, final_mark, days_late) "\n                + "VALUES (?, ?, ?, ?, ?, ?)", studentId, assignmentId, submittedAt, rawMark, finalMark, late);\n        return finalMark;\n    }\n\n    public static double regrade(String submissionId, double rawMark) {\n        Map<String, Object> s = Db.one("SELECT id, days_late, final_mark FROM submissions WHERE id = ?", submissionId);\n        double stored = (double) s.get("final_mark");\n        double finalMark = stored - stored * PENALTY_PER_DAY * (int) s.get("days_late");\n        Db.run("UPDATE submissions SET raw_mark = ?, final_mark = ? WHERE id = ?", rawMark, finalMark, submissionId);\n        return finalMark;\n    }\n\n    public static double bestMark(String studentId, String assignmentId) {\n        List<Map<String, Object>> rows = Db.all(\n                "SELECT raw_mark, final_mark FROM submissions WHERE student_id = ? AND assignment_id = ?",\n                studentId, assignmentId);\n        if (rows.isEmpty()) {\n            return 0;\n        }\n        Map<String, Object> best = rows.get(0);\n        for (Map<String, Object> r : rows) {\n            if ((double) r.get("raw_mark") > (double) best.get("raw_mark")) {\n                best = r;\n            }\n        }\n        return (double) best.get("final_mark");\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Late submissions and re-grading\n\nA student submits an assignment, sometimes late. A penalty is applied, and a\nteacher can re-grade the submission afterwards. This PR adds both paths and\nthe mark that ends up on the transcript.\n\n## Rules\n\n- An assignment is due at 23:59 on `due_on`, in the student's own time zone.\n- A submission after that moment is late. Any part of a day late counts as a\n  whole day.\n- The penalty is 10% of the mark for each day late. It never takes more than\n  50%, and a mark never goes below zero.\n- The mark a student keeps is the best of their submissions, compared after\n  the penalty.\n- The penalty belongs to when a submission arrived, not to how many times it\n  has been graded. Re-grading replaces the teacher's raw mark and nothing else.\n\n## Notes for the reviewer\n\n`submissions` rows carry `student_id`, `assignment_id`, `submitted_at` (UTC),\n`raw_mark`, `final_mark` and `days_late`. Students carry `timezone`, an IANA\nname. Assignments carry `due_on` (a date) and `max_mark`.\n","src/grading.py":'"""Late penalties, re-grading, and the mark that counts."""\nimport math\nfrom datetime import datetime, time, timezone\n\nimport db\n\nPENALTY_PER_DAY = 0.10\n\n\ndef days_late(assignment, submitted_at):\n    due = datetime.combine(assignment["due_on"], time(23, 59), tzinfo=timezone.utc)\n    if submitted_at <= due:\n        return 0\n    return math.ceil((submitted_at - due).total_seconds() / 86400)\n\n\ndef record_submission(student_id, assignment_id, raw_mark, submitted_at):\n    assignment = db.one("SELECT id, due_on, max_mark FROM assignments WHERE id = %s", (assignment_id,))\n    late = days_late(assignment, submitted_at)\n    final = raw_mark - raw_mark * PENALTY_PER_DAY * late\n    db.run(\n        "INSERT INTO submissions (student_id, assignment_id, submitted_at, raw_mark, final_mark, days_late) "\n        "VALUES (%s, %s, %s, %s, %s, %s)",\n        (student_id, assignment_id, submitted_at, raw_mark, final, late),\n    )\n    return final\n\n\ndef regrade(submission_id, raw_mark):\n    s = db.one("SELECT id, days_late, final_mark FROM submissions WHERE id = %s", (submission_id,))\n    final = s["final_mark"] - s["final_mark"] * PENALTY_PER_DAY * s["days_late"]\n    db.run(\n        "UPDATE submissions SET raw_mark = %s, final_mark = %s WHERE id = %s",\n        (raw_mark, final, submission_id),\n    )\n    return final\n\n\ndef best_mark(student_id, assignment_id):\n    rows = db.all(\n        "SELECT raw_mark, final_mark FROM submissions WHERE student_id = %s AND assignment_id = %s",\n        (student_id, assignment_id),\n    )\n    if not rows:\n        return 0\n    best = max(rows, key=lambda r: r["raw_mark"])\n    return best["final_mark"]\n'}},typescript:{entry:"README.md",files:{"README.md":"# Late submissions and re-grading\n\nA student submits an assignment, sometimes late. A penalty is applied, and a\nteacher can re-grade the submission afterwards. This PR adds both paths and\nthe mark that ends up on the transcript.\n\n## Rules\n\n- An assignment is due at 23:59 on `due_on`, in the student's own time zone.\n- A submission after that moment is late. Any part of a day late counts as a\n  whole day.\n- The penalty is 10% of the mark for each day late. It never takes more than\n  50%, and a mark never goes below zero.\n- The mark a student keeps is the best of their submissions, compared after\n  the penalty.\n- The penalty belongs to when a submission arrived, not to how many times it\n  has been graded. Re-grading replaces the teacher's raw mark and nothing else.\n\n## Notes for the reviewer\n\n`submissions` rows carry `student_id`, `assignment_id`, `submitted_at` (UTC),\n`raw_mark`, `final_mark` and `days_late`. Students carry `timezone`, an IANA\nname. Assignments carry `due_on` (a date) and `max_mark`.\n","src/grading.ts":'// Late penalties, re-grading, and the mark that counts.\nimport { DateTime } from "luxon";\nimport { db } from "./db";\n\nconst PENALTY_PER_DAY = 0.1;\n\nexport function daysLate(assignment: { due_on: string }, submittedAt: DateTime) {\n  const due = DateTime.fromISO(`${assignment.due_on}T23:59`, { zone: "utc" });\n  if (submittedAt <= due) return 0;\n  return Math.ceil(submittedAt.diff(due, "seconds").seconds / 86400);\n}\n\nexport async function recordSubmission(\n  studentId: string,\n  assignmentId: string,\n  rawMark: number,\n  submittedAt: DateTime,\n) {\n  const assignment = await db.one("SELECT id, due_on, max_mark FROM assignments WHERE id = $1", [assignmentId]);\n  const late = daysLate(assignment, submittedAt);\n  const final = rawMark - rawMark * PENALTY_PER_DAY * late;\n  await db.run(\n    "INSERT INTO submissions (student_id, assignment_id, submitted_at, raw_mark, final_mark, days_late) " +\n      "VALUES ($1, $2, $3, $4, $5, $6)",\n    [studentId, assignmentId, submittedAt.toISO(), rawMark, final, late],\n  );\n  return final;\n}\n\nexport async function regrade(submissionId: string, rawMark: number) {\n  const s = await db.one("SELECT id, days_late, final_mark FROM submissions WHERE id = $1", [submissionId]);\n  const final = s.final_mark - s.final_mark * PENALTY_PER_DAY * s.days_late;\n  await db.run("UPDATE submissions SET raw_mark = $1, final_mark = $2 WHERE id = $3", [rawMark, final, submissionId]);\n  return final;\n}\n\nexport async function bestMark(studentId: string, assignmentId: string) {\n  const rows = await db.all(\n    "SELECT raw_mark, final_mark FROM submissions WHERE student_id = $1 AND assignment_id = $2",\n    [studentId, assignmentId],\n  );\n  if (rows.length === 0) return 0;\n  const best = rows.reduce((a, b) => (b.raw_mark > a.raw_mark ? b : a));\n  return best.final_mark;\n}\n'}}}},{slug:"account-transfer",title:"Transfer between accounts",difficulty:"Hard",area:"concurrency",domains:["fintech"],minutes:30,summary:"Twenty lines that move money. There is a transaction in here, and it is around the wrong part of the work.",brief:["A teammate has opened this as a pull request. Money moves in it, so read it the way you would read a migration: slowly, and in the order the statements run.","Ask what a second transfer from the same account sees while this one is in flight, and what the books look like if the process dies after the first update.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Two choices here look careless and are correct. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Transfer between accounts\n\nMove money from one account to another, take a flat fee from the sender, and\nleave a row behind that says what happened. This PR is the whole path.\n\n## Rules\n\n- Money is in paise, as integers.\n- The sender's balance may never go negative, and the check must still hold\n  when two transfers run at the same moment.\n- A transfer is one unit of work. Afterwards either both balances moved and\n  the transfer row exists, or nothing happened at all.\n- The sender is debited the amount plus the fee. Every paisa that leaves an\n  account arrives in another one; the books have to balance.\n- A transfer to the same account is not a transfer.\n\n## Notes for the reviewer\n\n`accounts` carry `balance_paise`. `db.transaction()` is a context manager and\ncommits when the block ends. The fee account is `accounts` row `FEES`, and the\nfee is 25 basis points of the amount. `Insufficient` becomes a 422 upstream.\n","src/Transfer.java":'package bank;\n\nimport java.util.Map;\n\n/** Transfer money between two accounts. */\npublic final class Transfer {\n    private static final int FEE_BPS = 25;\n    private static final String FEE_ACCOUNT = "FEES";\n\n    public record Done(long amountPaise, long feePaise) {}\n\n    public static long feeFor(long amountPaise) {\n        return (amountPaise * FEE_BPS + 5000) / 10000;\n    }\n\n    public static Done transfer(String fromId, String toId, long amountPaise) {\n        Map<String, Object> sender = Db.one("SELECT id, balance_paise FROM accounts WHERE id = ?", fromId);\n        long fee = feeFor(amountPaise);\n        if ((long) sender.get("balance_paise") < amountPaise + fee) {\n            throw new Insufficient("balance too low");\n        }\n\n        Db.transaction(() -> {\n            Map<String, Object> current = Db.one("SELECT balance_paise FROM accounts WHERE id = ?", fromId);\n            Db.run("UPDATE accounts SET balance_paise = ? WHERE id = ?",\n                    (long) current.get("balance_paise") - amountPaise - fee, fromId);\n        });\n\n        Db.run("UPDATE accounts SET balance_paise = balance_paise + ? WHERE id = ?", amountPaise, toId);\n        Db.run("INSERT INTO transfers (from_id, to_id, amount_paise, fee_paise) VALUES (?, ?, ?, ?)",\n                fromId, toId, amountPaise, fee);\n        return new Done(amountPaise, fee);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Transfer between accounts\n\nMove money from one account to another, take a flat fee from the sender, and\nleave a row behind that says what happened. This PR is the whole path.\n\n## Rules\n\n- Money is in paise, as integers.\n- The sender's balance may never go negative, and the check must still hold\n  when two transfers run at the same moment.\n- A transfer is one unit of work. Afterwards either both balances moved and\n  the transfer row exists, or nothing happened at all.\n- The sender is debited the amount plus the fee. Every paisa that leaves an\n  account arrives in another one; the books have to balance.\n- A transfer to the same account is not a transfer.\n\n## Notes for the reviewer\n\n`accounts` carry `balance_paise`. `db.transaction()` is a context manager and\ncommits when the block ends. The fee account is `accounts` row `FEES`, and the\nfee is 25 basis points of the amount. `Insufficient` becomes a 422 upstream.\n","src/transfer.py":'"""Transfer money between two accounts."""\nimport db\n\nFEE_BPS = 25\nFEE_ACCOUNT = "FEES"\n\n\ndef fee_for(amount_paise):\n    return (amount_paise * FEE_BPS + 5000) // 10000\n\n\ndef transfer(from_id, to_id, amount_paise):\n    sender = db.one("SELECT id, balance_paise FROM accounts WHERE id = %s", (from_id,))\n    fee = fee_for(amount_paise)\n    if sender["balance_paise"] < amount_paise + fee:\n        raise Insufficient("balance too low")\n\n    with db.transaction():\n        current = db.one("SELECT balance_paise FROM accounts WHERE id = %s", (from_id,))\n        db.run(\n            "UPDATE accounts SET balance_paise = %s WHERE id = %s",\n            (current["balance_paise"] - amount_paise - fee, from_id),\n        )\n\n    db.run("UPDATE accounts SET balance_paise = balance_paise + %s WHERE id = %s", (amount_paise, to_id))\n    db.run(\n        "INSERT INTO transfers (from_id, to_id, amount_paise, fee_paise) VALUES (%s, %s, %s, %s)",\n        (from_id, to_id, amount_paise, fee),\n    )\n    return {"amount_paise": amount_paise, "fee_paise": fee}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Transfer between accounts\n\nMove money from one account to another, take a flat fee from the sender, and\nleave a row behind that says what happened. This PR is the whole path.\n\n## Rules\n\n- Money is in paise, as integers.\n- The sender's balance may never go negative, and the check must still hold\n  when two transfers run at the same moment.\n- A transfer is one unit of work. Afterwards either both balances moved and\n  the transfer row exists, or nothing happened at all.\n- The sender is debited the amount plus the fee. Every paisa that leaves an\n  account arrives in another one; the books have to balance.\n- A transfer to the same account is not a transfer.\n\n## Notes for the reviewer\n\n`accounts` carry `balance_paise`. `db.transaction()` is a context manager and\ncommits when the block ends. The fee account is `accounts` row `FEES`, and the\nfee is 25 basis points of the amount. `Insufficient` becomes a 422 upstream.\n","src/transfer.ts":'// Transfer money between two accounts.\nimport { db } from "./db";\n\nconst FEE_BPS = 25;\nconst FEE_ACCOUNT = "FEES";\n\nexport function feeFor(amountPaise: number) {\n  return Math.floor((amountPaise * FEE_BPS + 5000) / 10000);\n}\n\nexport async function transfer(fromId: string, toId: string, amountPaise: number) {\n  const sender = await db.one("SELECT id, balance_paise FROM accounts WHERE id = $1", [fromId]);\n  const fee = feeFor(amountPaise);\n  if (sender.balance_paise < amountPaise + fee) throw new Insufficient("balance too low");\n\n  await db.transaction(async () => {\n    const current = await db.one("SELECT balance_paise FROM accounts WHERE id = $1", [fromId]);\n    await db.run("UPDATE accounts SET balance_paise = $1 WHERE id = $2", [\n      current.balance_paise - amountPaise - fee,\n      fromId,\n    ]);\n  });\n\n  await db.run("UPDATE accounts SET balance_paise = balance_paise + $1 WHERE id = $2", [amountPaise, toId]);\n  await db.run("INSERT INTO transfers (from_id, to_id, amount_paise, fee_paise) VALUES ($1, $2, $3, $4)", [\n    fromId,\n    toId,\n    amountPaise,\n    fee,\n  ]);\n  return { amountPaise, feePaise: fee };\n}\n'}}}},{slug:"patient-records",title:"Reading a patient record",difficulty:"Hard",area:"security",domains:["health"],minutes:30,summary:"A clinician opens a record, exports a summary, and the audit log says what happened. Every line of this is about who is allowed to see a row, and whether the log can be believed.",brief:["A teammate has opened this as a pull request. Six rules in the README; the first two are the ones an auditor will ask about.","Ask what happens when a clinician with no connection to a patient calls this. Then ask what the audit log says about that call, and what the next clinician gets from the cache.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Two choices here look wrong and are deliberate. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Reading a patient record\n\nA clinician opens a patient's record, and can export a summary to send with a\nreferral. This PR adds both, and the audit trail behind them.\n\n## Rules\n\n- A clinician may read a patient only when there is a care relationship: an\n  appointment, an admission, or a share another clinician granted. Being\n  logged in is not a care relationship.\n- Every read is written to the audit log, allowed or refused, with who, which\n  patient, when, and the outcome.\n- Break-glass access is for an emergency. It covers one patient, lasts fifteen\n  minutes, and is reviewed afterwards.\n- An export covers one patient. There is no export of everybody.\n- A record may be held in the cache for up to a minute.\n- A patient identifier never appears in a URL, a query string, or a log line.\n\n## Notes for the reviewer\n\n`care_links` is `(clinician_id, patient_id, kind, expires_at)` and is the\nrelationship table. `audit_reads` is the log. `cache` is the process-wide\ncache every request shares.\n","src/Records.java":'package clinic;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Reading and exporting a patient record. */\npublic final class Records {\n    private static final Logger log = Logger.getLogger(Records.class.getName());\n    private static final int CACHE_TTL = 30;\n\n    public static Map<String, Object> readRecord(String clinicianId, String patientId) {\n        Db.run("INSERT INTO audit_reads (clinician_id, patient_id, outcome, at) VALUES (?, ?, \'allowed\', now())",\n                clinicianId, patientId);\n        Object cached = Cache.get("record:" + patientId);\n        if (cached != null) {\n            return (Map<String, Object>) cached;\n        }\n\n        Map<String, Object> record = Db.one("SELECT p.id, p.name, p.dob, p.notes FROM patients p "\n                + "LEFT JOIN care_links l ON l.patient_id = p.id AND l.clinician_id = ? "\n                + "WHERE p.id = ?", clinicianId, patientId);\n        if (record == null) {\n            throw new NotFound("no such patient");\n        }\n\n        Cache.set("record:" + patientId, record, CACHE_TTL);\n        log.info("record read: clinician=" + clinicianId + " patient=" + patientId);\n        return record;\n    }\n\n    public static boolean breakGlass(String clinicianId, String patientId, String reason) {\n        Db.run("INSERT INTO care_links (clinician_id, patient_id, kind, expires_at) VALUES (?, ?, \'break_glass\', NULL)",\n                clinicianId, patientId);\n        log.warning("break glass by " + clinicianId + ": " + reason);\n        return true;\n    }\n\n    public static List<Map<String, Object>> exportSummary(String clinicianId, String patientId) {\n        return Db.all("SELECT id, name, dob, notes FROM patients WHERE (? IS NULL OR id = ?)", patientId, patientId);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Reading a patient record\n\nA clinician opens a patient's record, and can export a summary to send with a\nreferral. This PR adds both, and the audit trail behind them.\n\n## Rules\n\n- A clinician may read a patient only when there is a care relationship: an\n  appointment, an admission, or a share another clinician granted. Being\n  logged in is not a care relationship.\n- Every read is written to the audit log, allowed or refused, with who, which\n  patient, when, and the outcome.\n- Break-glass access is for an emergency. It covers one patient, lasts fifteen\n  minutes, and is reviewed afterwards.\n- An export covers one patient. There is no export of everybody.\n- A record may be held in the cache for up to a minute.\n- A patient identifier never appears in a URL, a query string, or a log line.\n\n## Notes for the reviewer\n\n`care_links` is `(clinician_id, patient_id, kind, expires_at)` and is the\nrelationship table. `audit_reads` is the log. `cache` is the process-wide\ncache every request shares.\n","src/records.py":'"""Reading and exporting a patient record."""\nimport logging\n\nimport db\nfrom cache import cache\n\nlog = logging.getLogger(__name__)\n\nCACHE_TTL = 30\n\n\ndef read_record(clinician_id, patient_id):\n    db.run(\n        "INSERT INTO audit_reads (clinician_id, patient_id, outcome, at) VALUES (%s, %s, \'allowed\', now())",\n        (clinician_id, patient_id),\n    )\n    cached = cache.get(f"record:{patient_id}")\n    if cached is not None:\n        return cached\n\n    record = db.one(\n        "SELECT p.id, p.name, p.dob, p.notes FROM patients p "\n        "LEFT JOIN care_links l ON l.patient_id = p.id AND l.clinician_id = %s "\n        "WHERE p.id = %s",\n        (clinician_id, patient_id),\n    )\n    if record is None:\n        raise NotFound("no such patient")\n\n    cache.set(f"record:{patient_id}", record, CACHE_TTL)\n    log.info("record read: clinician=%s patient=%s", clinician_id, patient_id)\n    return record\n\n\ndef break_glass(clinician_id, patient_id, reason):\n    db.run(\n        "INSERT INTO care_links (clinician_id, patient_id, kind, expires_at) VALUES (%s, %s, \'break_glass\', NULL)",\n        (clinician_id, patient_id),\n    )\n    log.warning("break glass by %s: %s", clinician_id, reason)\n    return {"granted": True}\n\n\ndef export_summary(clinician_id, patient_id=None):\n    rows = db.all(\n        "SELECT id, name, dob, notes FROM patients WHERE (%s IS NULL OR id = %s)",\n        (patient_id, patient_id),\n    )\n    return {"patients": rows, "count": len(rows)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Reading a patient record\n\nA clinician opens a patient's record, and can export a summary to send with a\nreferral. This PR adds both, and the audit trail behind them.\n\n## Rules\n\n- A clinician may read a patient only when there is a care relationship: an\n  appointment, an admission, or a share another clinician granted. Being\n  logged in is not a care relationship.\n- Every read is written to the audit log, allowed or refused, with who, which\n  patient, when, and the outcome.\n- Break-glass access is for an emergency. It covers one patient, lasts fifteen\n  minutes, and is reviewed afterwards.\n- An export covers one patient. There is no export of everybody.\n- A record may be held in the cache for up to a minute.\n- A patient identifier never appears in a URL, a query string, or a log line.\n\n## Notes for the reviewer\n\n`care_links` is `(clinician_id, patient_id, kind, expires_at)` and is the\nrelationship table. `audit_reads` is the log. `cache` is the process-wide\ncache every request shares.\n","src/records.ts":'// Reading and exporting a patient record.\nimport { cache } from "./cache";\nimport { db } from "./db";\nimport { log } from "./log";\n\nconst CACHE_TTL = 30;\n\nexport async function readRecord(clinicianId: string, patientId: string) {\n  await db.run("INSERT INTO audit_reads (clinician_id, patient_id, outcome, at) VALUES ($1, $2, \'allowed\', now())", [\n    clinicianId,\n    patientId,\n  ]);\n  const cached = cache.get(`record:${patientId}`);\n  if (cached !== undefined) return cached;\n\n  const record = await db.one(\n    "SELECT p.id, p.name, p.dob, p.notes FROM patients p " +\n      "LEFT JOIN care_links l ON l.patient_id = p.id AND l.clinician_id = $1 " +\n      "WHERE p.id = $2",\n    [clinicianId, patientId],\n  );\n  if (!record) throw new NotFound("no such patient");\n\n  cache.set(`record:${patientId}`, record, CACHE_TTL);\n  log.info("record read: clinician=%s patient=%s", clinicianId, patientId);\n  return record;\n}\n\nexport async function breakGlass(clinicianId: string, patientId: string, reason: string) {\n  await db.run("INSERT INTO care_links (clinician_id, patient_id, kind, expires_at) VALUES ($1, $2, \'break_glass\', NULL)", [\n    clinicianId,\n    patientId,\n  ]);\n  log.warn("break glass by %s: %s", clinicianId, reason);\n  return { granted: true };\n}\n\nexport async function exportSummary(clinicianId: string, patientId?: string) {\n  const rows = await db.all("SELECT id, name, dob, notes FROM patients WHERE ($1 IS NULL OR id = $2)", [\n    patientId ?? null,\n    patientId ?? null,\n  ]);\n  return { patients: rows, count: rows.length };\n}\n'}}}},{slug:"seat-hold-sweeper",title:"Seat holds and the sweeper",difficulty:"Hard",area:"concurrency",domains:["travel"],minutes:30,summary:"Hold a seat for ten minutes, take the money, confirm it, and sweep the holds that ran out. Three writers on one row, and only one of them knows about the others.",brief:["A teammate has opened this as a pull request. Read the three functions as three processes running at once, because that is what they are.","Put the sweeper’s timer one second after a passenger presses Pay, and follow both. Then run two sweepers, and two passengers on the same seat.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","A couple of these lines look wrong and are right. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Seat holds\n\nA passenger holds a seat for ten minutes while they pay. A sweeper releases\nholds that ran out. This PR is both halves and the confirmation between them.\n\n## Rules\n\n- A seat is held by one passenger at a time.\n- A hold lasts ten minutes. After that the seat is free for anyone.\n- A hold that has been paid for is confirmed, and a confirmed seat is never\n  released, whatever the sweeper makes of the clock.\n- The money is captured only once the seat is certainly the passenger's.\n- The sweeper runs on every instance. Two sweepers may not release the same\n  hold twice.\n\n## Notes for the reviewer\n\n`seats` carry `booking_id`, `held_until` (a timestamptz, null when free) and\n`status`, which is `free`, `held` or `confirmed`. `payments.capture` takes the\nmoney and is not reversible without a refund. The sweeper is on a one-minute\ntimer in every instance.\n","src/Holds.java":'package travel;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n/** Seat holds, confirmation, and the sweeper that cleans up. */\npublic final class Holds {\n    private static final Duration HOLD = Duration.ofMinutes(10);\n\n    public static Instant holdSeat(String bookingId, String seatId) {\n        Map<String, Object> seat = Db.one("SELECT id, held_until, booking_id FROM seats WHERE id = ?", seatId);\n        Instant heldUntilNow = (Instant) seat.get("held_until");\n        if (heldUntilNow != null && heldUntilNow.isAfter(Instant.now())) {\n            throw new Taken("seat is held");\n        }\n        Instant heldUntil = Instant.now().plus(HOLD);\n        Db.run("UPDATE seats SET booking_id = ?, held_until = ?, status = \'held\' WHERE id = ?",\n                bookingId, heldUntil, seatId);\n        return heldUntil;\n    }\n\n    public static String confirm(String bookingId, String seatId, String paymentToken) {\n        Map<String, Object> seat = Db.one("SELECT id, held_until, booking_id FROM seats WHERE id = ?", seatId);\n        if (!bookingId.equals(seat.get("booking_id")) || ((Instant) seat.get("held_until")).isBefore(Instant.now())) {\n            throw new Expired("the hold has gone");\n        }\n\n        Payments.Charge charge = Payments.capture(paymentToken);\n        Db.run("UPDATE seats SET status = \'confirmed\' WHERE id = ?", seatId);\n        return charge.id();\n    }\n\n    public static int sweep(Instant now) {\n        List<Map<String, Object>> expired =\n                Db.all("SELECT id FROM seats WHERE held_until IS NOT NULL AND held_until < ?", now);\n        int released = 0;\n        for (Map<String, Object> row : expired) {\n            Db.run("UPDATE seats SET booking_id = NULL, held_until = NULL, status = \'free\' WHERE id = ?", row.get("id"));\n            released++;\n        }\n        return released;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Seat holds\n\nA passenger holds a seat for ten minutes while they pay. A sweeper releases\nholds that ran out. This PR is both halves and the confirmation between them.\n\n## Rules\n\n- A seat is held by one passenger at a time.\n- A hold lasts ten minutes. After that the seat is free for anyone.\n- A hold that has been paid for is confirmed, and a confirmed seat is never\n  released, whatever the sweeper makes of the clock.\n- The money is captured only once the seat is certainly the passenger's.\n- The sweeper runs on every instance. Two sweepers may not release the same\n  hold twice.\n\n## Notes for the reviewer\n\n`seats` carry `booking_id`, `held_until` (a timestamptz, null when free) and\n`status`, which is `free`, `held` or `confirmed`. `payments.capture` takes the\nmoney and is not reversible without a refund. The sweeper is on a one-minute\ntimer in every instance.\n","src/holds.py":'"""Seat holds, confirmation, and the sweeper that cleans up."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\nimport payments\n\nHOLD = timedelta(minutes=10)\n\n\ndef hold_seat(booking_id, seat_id):\n    seat = db.one("SELECT id, held_until, booking_id FROM seats WHERE id = %s", (seat_id,))\n    if seat["held_until"] is not None and seat["held_until"] > datetime.now(timezone.utc):\n        raise Taken("seat is held")\n    held_until = datetime.now(timezone.utc) + HOLD\n    db.run(\n        "UPDATE seats SET booking_id = %s, held_until = %s, status = \'held\' WHERE id = %s",\n        (booking_id, held_until, seat_id),\n    )\n    return {"held_until": held_until}\n\n\ndef confirm(booking_id, seat_id, payment_token):\n    seat = db.one("SELECT id, held_until, booking_id FROM seats WHERE id = %s", (seat_id,))\n    if seat["booking_id"] != booking_id or seat["held_until"] < datetime.now(timezone.utc):\n        raise Expired("the hold has gone")\n\n    charge = payments.capture(payment_token)\n    db.run("UPDATE seats SET status = \'confirmed\' WHERE id = %s", (seat_id,))\n    return {"confirmed": True, "charge": charge.id}\n\n\ndef sweep(now=None):\n    now = now or datetime.now(timezone.utc)\n    expired = db.all("SELECT id FROM seats WHERE held_until IS NOT NULL AND held_until < %s", (now,))\n    released = 0\n    for row in expired:\n        db.run(\n            "UPDATE seats SET booking_id = NULL, held_until = NULL, status = \'free\' WHERE id = %s",\n            (row["id"],),\n        )\n        released += 1\n    return {"released": released}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Seat holds\n\nA passenger holds a seat for ten minutes while they pay. A sweeper releases\nholds that ran out. This PR is both halves and the confirmation between them.\n\n## Rules\n\n- A seat is held by one passenger at a time.\n- A hold lasts ten minutes. After that the seat is free for anyone.\n- A hold that has been paid for is confirmed, and a confirmed seat is never\n  released, whatever the sweeper makes of the clock.\n- The money is captured only once the seat is certainly the passenger's.\n- The sweeper runs on every instance. Two sweepers may not release the same\n  hold twice.\n\n## Notes for the reviewer\n\n`seats` carry `booking_id`, `held_until` (a timestamptz, null when free) and\n`status`, which is `free`, `held` or `confirmed`. `payments.capture` takes the\nmoney and is not reversible without a refund. The sweeper is on a one-minute\ntimer in every instance.\n","src/holds.ts":'// Seat holds, confirmation, and the sweeper that cleans up.\nimport { db } from "./db";\nimport * as payments from "./payments";\n\nconst HOLD_MS = 10 * 60 * 1000;\n\nexport async function holdSeat(bookingId: string, seatId: string) {\n  const seat = await db.one("SELECT id, held_until, booking_id FROM seats WHERE id = $1", [seatId]);\n  if (seat.held_until !== null && new Date(seat.held_until) > new Date()) throw new Taken("seat is held");\n  const heldUntil = new Date(Date.now() + HOLD_MS);\n  await db.run("UPDATE seats SET booking_id = $1, held_until = $2, status = \'held\' WHERE id = $3", [\n    bookingId,\n    heldUntil,\n    seatId,\n  ]);\n  return { heldUntil };\n}\n\nexport async function confirm(bookingId: string, seatId: string, paymentToken: string) {\n  const seat = await db.one("SELECT id, held_until, booking_id FROM seats WHERE id = $1", [seatId]);\n  if (seat.booking_id !== bookingId || new Date(seat.held_until) < new Date()) throw new Expired("the hold has gone");\n\n  const charge = await payments.capture(paymentToken);\n  await db.run("UPDATE seats SET status = \'confirmed\' WHERE id = $1", [seatId]);\n  return { confirmed: true, charge: charge.id };\n}\n\nexport async function sweep(now = new Date()) {\n  const expired = await db.all("SELECT id FROM seats WHERE held_until IS NOT NULL AND held_until < $1", [now]);\n  let released = 0;\n  for (const row of expired) {\n    await db.run("UPDATE seats SET booking_id = NULL, held_until = NULL, status = \'free\' WHERE id = $1", [row.id]);\n    released += 1;\n  }\n  return { released };\n}\n'}}}},{slug:"payout-batch",title:"Nightly merchant payouts",difficulty:"Hard",area:"money",domains:["payments","analytics"],minutes:30,summary:"A loop that sends other people’s money to their banks. Ask what happens when it is run twice, and what happens when the third transfer times out.",brief:["A teammate has opened this as a pull request. The job runs at 02:00 against real bank transfers, so read it as the operations team would.","Re-run it for last night. Then make the bank call time out after the money has gone. Then find the merchant who is owed ₹99.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of this is right. A comment on those lines costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Nightly merchant payouts\n\nEvery night the money collected for each merchant, less our commission, is\npaid out to their bank. This PR is the batch job.\n\n## Rules\n\n- A merchant is paid once per payout date. A re-run of the job for that date\n  pays nothing more.\n- The amount is the settled sales for the day, less commission, in paise, and\n  the split has to add up: sales equals payout plus commission, exactly.\n- A merchant whose payout fails does not stop the others.\n- A payout below the minimum of ₹100 is carried to the next day, not dropped.\n- The job writes what it did before it tells anyone it is finished.\n\n## Notes for the reviewer\n\n`payouts` is `(merchant_id, on_date, amount_paise, status)` with no unique\nindex yet. `bank.transfer` is a third-party call that can time out after the\ntransfer has been accepted. Commission is 2% of sales.\n","src/Payouts.java":'package billing;\n\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.logging.Logger;\n\n/** Nightly merchant payouts. */\npublic final class Payouts {\n    private static final Logger log = Logger.getLogger(Payouts.class.getName());\n    private static final int COMMISSION_BPS = 200;\n    private static final long MINIMUM_PAISE = 10000;\n\n    public record Split(long amount, long commission) {}\n\n    public static Split payoutFor(long salesPaise) {\n        double commission = (double) (salesPaise * COMMISSION_BPS) / 10000;\n        return new Split((long) (salesPaise - commission), (long) commission);\n    }\n\n    public static int run(LocalDate onDate) {\n        List<Map<String, Object>> merchants = Db.all(\n                "SELECT merchant_id, sum(amount_paise) AS sales FROM transactions "\n                        + "WHERE status = \'settled\' AND created_at::date = ? GROUP BY merchant_id", onDate);\n        int paid = 0;\n        for (Map<String, Object> m : merchants) {\n            Split split = payoutFor((long) m.get("sales"));\n            if (split.amount() < MINIMUM_PAISE) {\n                continue;\n            }\n            Bank.transfer((String) m.get("merchant_id"), split.amount());\n            Db.run("INSERT INTO payouts (merchant_id, on_date, amount_paise, status) VALUES (?, ?, ?, \'sent\')",\n                    m.get("merchant_id"), onDate, split.amount());\n            paid++;\n        }\n        log.info("payouts done: " + paid + " merchants");\n        return paid;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Nightly merchant payouts\n\nEvery night the money collected for each merchant, less our commission, is\npaid out to their bank. This PR is the batch job.\n\n## Rules\n\n- A merchant is paid once per payout date. A re-run of the job for that date\n  pays nothing more.\n- The amount is the settled sales for the day, less commission, in paise, and\n  the split has to add up: sales equals payout plus commission, exactly.\n- A merchant whose payout fails does not stop the others.\n- A payout below the minimum of ₹100 is carried to the next day, not dropped.\n- The job writes what it did before it tells anyone it is finished.\n\n## Notes for the reviewer\n\n`payouts` is `(merchant_id, on_date, amount_paise, status)` with no unique\nindex yet. `bank.transfer` is a third-party call that can time out after the\ntransfer has been accepted. Commission is 2% of sales.\n","src/payouts.py":'"""Nightly merchant payouts."""\nimport logging\n\nimport bank\nimport db\n\nCOMMISSION_BPS = 200\nMINIMUM_PAISE = 10000\n\nlog = logging.getLogger(__name__)\n\n\ndef payout_for(sales_paise):\n    commission = sales_paise * COMMISSION_BPS / 10000\n    return int(sales_paise - commission), int(commission)\n\n\ndef run(on_date):\n    merchants = db.all(\n        "SELECT merchant_id, sum(amount_paise) AS sales FROM transactions "\n        "WHERE status = \'settled\' AND created_at::date = %s GROUP BY merchant_id",\n        (on_date,),\n    )\n    paid = 0\n    for m in merchants:\n        amount, commission = payout_for(m["sales"])\n        if amount < MINIMUM_PAISE:\n            continue\n        transfer = bank.transfer(m["merchant_id"], amount)\n        db.run(\n            "INSERT INTO payouts (merchant_id, on_date, amount_paise, status) VALUES (%s, %s, %s, \'sent\')",\n            (m["merchant_id"], on_date, amount),\n        )\n        paid += 1\n    log.info("payouts done: %s merchants", paid)\n    return {"paid": paid}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Nightly merchant payouts\n\nEvery night the money collected for each merchant, less our commission, is\npaid out to their bank. This PR is the batch job.\n\n## Rules\n\n- A merchant is paid once per payout date. A re-run of the job for that date\n  pays nothing more.\n- The amount is the settled sales for the day, less commission, in paise, and\n  the split has to add up: sales equals payout plus commission, exactly.\n- A merchant whose payout fails does not stop the others.\n- A payout below the minimum of ₹100 is carried to the next day, not dropped.\n- The job writes what it did before it tells anyone it is finished.\n\n## Notes for the reviewer\n\n`payouts` is `(merchant_id, on_date, amount_paise, status)` with no unique\nindex yet. `bank.transfer` is a third-party call that can time out after the\ntransfer has been accepted. Commission is 2% of sales.\n","src/payouts.ts":'// Nightly merchant payouts.\nimport * as bank from "./bank";\nimport { db } from "./db";\nimport { log } from "./log";\n\nconst COMMISSION_BPS = 200;\nconst MINIMUM_PAISE = 10000;\n\nexport function payoutFor(salesPaise: number) {\n  const commission = (salesPaise * COMMISSION_BPS) / 10000;\n  return { amount: Math.trunc(salesPaise - commission), commission: Math.trunc(commission) };\n}\n\nexport async function run(onDate: string) {\n  const merchants = await db.all(\n    "SELECT merchant_id, sum(amount_paise) AS sales FROM transactions " +\n      "WHERE status = \'settled\' AND created_at::date = $1 GROUP BY merchant_id",\n    [onDate],\n  );\n  let paid = 0;\n  for (const m of merchants) {\n    const { amount } = payoutFor(Number(m.sales));\n    if (amount < MINIMUM_PAISE) continue;\n    await bank.transfer(m.merchant_id, amount);\n    await db.run("INSERT INTO payouts (merchant_id, on_date, amount_paise, status) VALUES ($1, $2, $3, \'sent\')", [\n      m.merchant_id,\n      onDate,\n      amount,\n    ]);\n    paid += 1;\n  }\n  log.info("payouts done: %s merchants", paid);\n  return { paid };\n}\n'}}}},{slug:"workspace-roles",title:"Roles in a workspace",difficulty:"Hard",area:"security",domains:["identity","saas"],minutes:30,summary:"One permission helper and two endpoints that use it. Read the helper first, then read the order of the statements in the endpoint below it.",brief:["A teammate has opened this as a pull request. Six rules in the README; every one of them is something a customer’s security review will ask about.","Send a request body with a role in it. Then have a member call set_role on themselves. Then remove the last owner.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Two things here look wrong and are fine. A comment on those costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Roles in a workspace\n\nOwner, admin, member, guest. This PR adds the permission check and the two\nendpoints that change who is what.\n\n## Rules\n\n- A member's role is read from their membership row, never from the request.\n- A role is only meaningful inside one workspace. A role in one grants nothing\n  in another.\n- Only an owner may change roles, and only an owner may make someone else an\n  owner.\n- Nobody may raise their own role.\n- A workspace always has at least one owner.\n- The check runs before the change. A refused change leaves nothing behind.\n\n## Notes for the reviewer\n\n`memberships` is `(workspace_id, user_id, role)`. `actor` is the\nauthenticated caller as the request handler built it, which includes whatever\nthe client sent in the body.\n","src/Roles.java":'package accounts;\n\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\n/** Permission checks and role changes. */\npublic final class Roles {\n    private static final Map<String, Set<String>> PERMISSIONS = Map.of(\n            "owner", Set.of("roles.write", "members.remove", "billing.write", "content.write"),\n            "admin", Set.of("members.remove", "content.write"),\n            "member", Set.of("content.write"),\n            "guest", Set.of());\n\n    public record Actor(String id, String role) {}\n\n    public static String roleOf(String userId, String workspaceId) {\n        Map<String, Object> row =\n                Db.one("SELECT role FROM memberships WHERE user_id = ? AND workspace_id = ?", userId, workspaceId);\n        return row == null ? "guest" : (String) row.get("role");\n    }\n\n    public static boolean can(Actor actor, String workspaceId, String action) {\n        String role = actor.role() != null ? actor.role() : roleOf(actor.id(), workspaceId);\n        return PERMISSIONS.getOrDefault(role, Set.of()).contains(action);\n    }\n\n    public static String setRole(Actor actor, String workspaceId, String memberId, String newRole) {\n        Db.run("UPDATE memberships SET role = ? WHERE workspace_id = ? AND user_id = ?",\n                newRole, workspaceId, memberId);\n        if (!can(actor, workspaceId, "roles.write")) {\n            throw new Forbidden("not allowed");\n        }\n        return newRole;\n    }\n\n    public static boolean removeMember(Actor actor, String workspaceId, String memberId) {\n        if (!can(actor, workspaceId, "members.remove")) {\n            throw new Forbidden("not allowed");\n        }\n        Db.run("DELETE FROM memberships WHERE workspace_id = ? AND user_id = ?", workspaceId, memberId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Roles in a workspace\n\nOwner, admin, member, guest. This PR adds the permission check and the two\nendpoints that change who is what.\n\n## Rules\n\n- A member's role is read from their membership row, never from the request.\n- A role is only meaningful inside one workspace. A role in one grants nothing\n  in another.\n- Only an owner may change roles, and only an owner may make someone else an\n  owner.\n- Nobody may raise their own role.\n- A workspace always has at least one owner.\n- The check runs before the change. A refused change leaves nothing behind.\n\n## Notes for the reviewer\n\n`memberships` is `(workspace_id, user_id, role)`. `actor` is the\nauthenticated caller as the request handler built it, which includes whatever\nthe client sent in the body.\n","src/roles.py":'"""Permission checks and role changes."""\nimport db\n\nPERMISSIONS = {\n    "owner": {"roles.write", "members.remove", "billing.write", "content.write"},\n    "admin": {"members.remove", "content.write"},\n    "member": {"content.write"},\n    "guest": set(),\n}\n\n\ndef role_of(user_id, workspace_id):\n    row = db.one(\n        "SELECT role FROM memberships WHERE user_id = %s AND workspace_id = %s",\n        (user_id, workspace_id),\n    )\n    return row["role"] if row else "guest"\n\n\ndef can(actor, workspace_id, action):\n    role = actor.get("role") or role_of(actor["id"], workspace_id)\n    return action in PERMISSIONS.get(role, set())\n\n\ndef set_role(actor, workspace_id, member_id, new_role):\n    db.run(\n        "UPDATE memberships SET role = %s WHERE workspace_id = %s AND user_id = %s",\n        (new_role, workspace_id, member_id),\n    )\n    if not can(actor, workspace_id, "roles.write"):\n        raise Forbidden("not allowed")\n    return {"role": new_role}\n\n\ndef remove_member(actor, workspace_id, member_id):\n    if not can(actor, workspace_id, "members.remove"):\n        raise Forbidden("not allowed")\n    db.run(\n        "DELETE FROM memberships WHERE workspace_id = %s AND user_id = %s",\n        (workspace_id, member_id),\n    )\n    return {"removed": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Roles in a workspace\n\nOwner, admin, member, guest. This PR adds the permission check and the two\nendpoints that change who is what.\n\n## Rules\n\n- A member's role is read from their membership row, never from the request.\n- A role is only meaningful inside one workspace. A role in one grants nothing\n  in another.\n- Only an owner may change roles, and only an owner may make someone else an\n  owner.\n- Nobody may raise their own role.\n- A workspace always has at least one owner.\n- The check runs before the change. A refused change leaves nothing behind.\n\n## Notes for the reviewer\n\n`memberships` is `(workspace_id, user_id, role)`. `actor` is the\nauthenticated caller as the request handler built it, which includes whatever\nthe client sent in the body.\n","src/roles.ts":'// Permission checks and role changes.\nimport { db } from "./db";\n\ntype Actor = { id: string; role?: string };\n\nconst PERMISSIONS: Record<string, string[]> = {\n  owner: ["roles.write", "members.remove", "billing.write", "content.write"],\n  admin: ["members.remove", "content.write"],\n  member: ["content.write"],\n  guest: [],\n};\n\nexport async function roleOf(userId: string, workspaceId: string) {\n  const row = await db.one("SELECT role FROM memberships WHERE user_id = $1 AND workspace_id = $2", [\n    userId,\n    workspaceId,\n  ]);\n  return row ? row.role : "guest";\n}\n\nexport async function can(actor: Actor, workspaceId: string, action: string) {\n  const role = actor.role ?? (await roleOf(actor.id, workspaceId));\n  return (PERMISSIONS[role] ?? []).includes(action);\n}\n\nexport async function setRole(actor: Actor, workspaceId: string, memberId: string, newRole: string) {\n  await db.run("UPDATE memberships SET role = $1 WHERE workspace_id = $2 AND user_id = $3", [\n    newRole,\n    workspaceId,\n    memberId,\n  ]);\n  if (!(await can(actor, workspaceId, "roles.write"))) throw new Forbidden("not allowed");\n  return { role: newRole };\n}\n\nexport async function removeMember(actor: Actor, workspaceId: string, memberId: string) {\n  if (!(await can(actor, workspaceId, "members.remove"))) throw new Forbidden("not allowed");\n  await db.run("DELETE FROM memberships WHERE workspace_id = $1 AND user_id = $2", [workspaceId, memberId]);\n  return { removed: true };\n}\n'}}}},{slug:"usage-metering",title:"Metering API usage",difficulty:"Hard",area:"concurrency",domains:["saas","analytics"],minutes:30,summary:"A counter on the request path and the month-end total it feeds. Both are read-then-write, and the number at the end is on an invoice.",brief:["A teammate has opened this as a pull request. The meter runs on every API call across several instances, and the month-end number is billed.","Send a thousand calls a second and count what lands. Then close a month, and then let a late write arrive.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Some of this is right. A comment on those lines costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Metering API usage\n\nEvery API call is metered, and the month’s total decides what the customer is\nbilled for overage. This PR is the meter and the month-end roll-up.\n\n## Rules\n\n- Every call counts once. A call that is metered twice is money a customer did\n  not spend.\n- A month is a calendar month in the customer’s billing zone, which is\n  Asia/Kolkata.\n- The month-end total is taken once, when the month closes, and does not\n  change afterwards, whatever arrives late.\n- Overage is charged on calls above the plan’s included amount, at the plan’s\n  rate, in paise.\n- The meter is on the request path, so it may not make the request wait for a\n  write that can happen later.\n\n## Notes for the reviewer\n\n`usage` is `(workspace_id, on_date, calls)`. `usage_months` is the closed\nmonth. Several instances serve requests at once.\n","src/Metering.java":'package platform;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.ZoneOffset;\nimport java.util.Map;\n\n/** Metering API calls and closing a month. */\npublic final class Metering {\n    private static final long OVERAGE_PAISE_PER_CALL = 5;\n\n    public record Month(long calls, long overagePaise) {}\n\n    public static long meter(String workspaceId) {\n        LocalDate today = Instant.now().atZone(ZoneOffset.UTC).toLocalDate();\n        Map<String, Object> row =\n                Db.one("SELECT calls FROM usage WHERE workspace_id = ? AND on_date = ?", workspaceId, today);\n        long calls = (row == null ? 0 : (long) row.get("calls")) + 1;\n        Db.run("INSERT INTO usage (workspace_id, on_date, calls) VALUES (?, ?, ?) "\n                + "ON CONFLICT (workspace_id, on_date) DO UPDATE SET calls = ?",\n                workspaceId, today, calls, calls);\n        return calls;\n    }\n\n    public static Month closeMonth(String workspaceId, int year, int month, long includedCalls) {\n        long total = (long) Db.one("SELECT coalesce(sum(calls), 0) AS n FROM usage "\n                + "WHERE workspace_id = ? AND extract(year from on_date) = ? AND extract(month from on_date) = ?",\n                workspaceId, year, month).get("n");\n        long overage = Math.max(0, total - includedCalls) * OVERAGE_PAISE_PER_CALL;\n        Db.run("INSERT INTO usage_months (workspace_id, year, month, calls, overage_paise) VALUES (?, ?, ?, ?, ?) "\n                + "ON CONFLICT (workspace_id, year, month) DO UPDATE SET calls = EXCLUDED.calls, "\n                + "overage_paise = EXCLUDED.overage_paise", workspaceId, year, month, total, overage);\n        return new Month(total, overage);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Metering API usage\n\nEvery API call is metered, and the month’s total decides what the customer is\nbilled for overage. This PR is the meter and the month-end roll-up.\n\n## Rules\n\n- Every call counts once. A call that is metered twice is money a customer did\n  not spend.\n- A month is a calendar month in the customer’s billing zone, which is\n  Asia/Kolkata.\n- The month-end total is taken once, when the month closes, and does not\n  change afterwards, whatever arrives late.\n- Overage is charged on calls above the plan’s included amount, at the plan’s\n  rate, in paise.\n- The meter is on the request path, so it may not make the request wait for a\n  write that can happen later.\n\n## Notes for the reviewer\n\n`usage` is `(workspace_id, on_date, calls)`. `usage_months` is the closed\nmonth. Several instances serve requests at once.\n","src/metering.py":'"""Metering API calls and closing a month."""\nfrom datetime import datetime, timezone\n\nimport db\n\nOVERAGE_PAISE_PER_CALL = 5\n\n\ndef meter(workspace_id):\n    today = datetime.now(timezone.utc).date()\n    row = db.one(\n        "SELECT calls FROM usage WHERE workspace_id = %s AND on_date = %s",\n        (workspace_id, today),\n    )\n    calls = (row["calls"] if row else 0) + 1\n    db.run(\n        "INSERT INTO usage (workspace_id, on_date, calls) VALUES (%s, %s, %s) "\n        "ON CONFLICT (workspace_id, on_date) DO UPDATE SET calls = %s",\n        (workspace_id, today, calls, calls),\n    )\n    return calls\n\n\ndef close_month(workspace_id, year, month, included_calls):\n    total = db.one(\n        "SELECT coalesce(sum(calls), 0) AS n FROM usage "\n        "WHERE workspace_id = %s AND extract(year from on_date) = %s AND extract(month from on_date) = %s",\n        (workspace_id, year, month),\n    )["n"]\n    overage = max(0, total - included_calls) * OVERAGE_PAISE_PER_CALL\n    db.run(\n        "INSERT INTO usage_months (workspace_id, year, month, calls, overage_paise) VALUES (%s, %s, %s, %s, %s) "\n        "ON CONFLICT (workspace_id, year, month) DO UPDATE SET calls = EXCLUDED.calls, "\n        "overage_paise = EXCLUDED.overage_paise",\n        (workspace_id, year, month, total, overage),\n    )\n    return {"calls": total, "overage_paise": overage}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Metering API usage\n\nEvery API call is metered, and the month’s total decides what the customer is\nbilled for overage. This PR is the meter and the month-end roll-up.\n\n## Rules\n\n- Every call counts once. A call that is metered twice is money a customer did\n  not spend.\n- A month is a calendar month in the customer’s billing zone, which is\n  Asia/Kolkata.\n- The month-end total is taken once, when the month closes, and does not\n  change afterwards, whatever arrives late.\n- Overage is charged on calls above the plan’s included amount, at the plan’s\n  rate, in paise.\n- The meter is on the request path, so it may not make the request wait for a\n  write that can happen later.\n\n## Notes for the reviewer\n\n`usage` is `(workspace_id, on_date, calls)`. `usage_months` is the closed\nmonth. Several instances serve requests at once.\n","src/metering.ts":'// Metering API calls and closing a month.\nimport { db } from "./db";\n\nconst OVERAGE_PAISE_PER_CALL = 5;\n\nexport async function meter(workspaceId: string) {\n  const today = new Date().toISOString().slice(0, 10);\n  const row = await db.one("SELECT calls FROM usage WHERE workspace_id = $1 AND on_date = $2", [workspaceId, today]);\n  const calls = (row ? Number(row.calls) : 0) + 1;\n  await db.run(\n    "INSERT INTO usage (workspace_id, on_date, calls) VALUES ($1, $2, $3) " +\n      "ON CONFLICT (workspace_id, on_date) DO UPDATE SET calls = $4",\n    [workspaceId, today, calls, calls],\n  );\n  return calls;\n}\n\nexport async function closeMonth(workspaceId: string, year: number, month: number, includedCalls: number) {\n  const total = Number(\n    (\n      await db.one(\n        "SELECT coalesce(sum(calls), 0) AS n FROM usage " +\n          "WHERE workspace_id = $1 AND extract(year from on_date) = $2 AND extract(month from on_date) = $3",\n        [workspaceId, year, month],\n      )\n    ).n,\n  );\n  const overage = Math.max(0, total - includedCalls) * OVERAGE_PAISE_PER_CALL;\n  await db.run(\n    "INSERT INTO usage_months (workspace_id, year, month, calls, overage_paise) VALUES ($1, $2, $3, $4, $5) " +\n      "ON CONFLICT (workspace_id, year, month) DO UPDATE SET calls = EXCLUDED.calls, " +\n      "overage_paise = EXCLUDED.overage_paise",\n    [workspaceId, year, month, total, overage],\n  );\n  return { calls: total, overagePaise: overage };\n}\n'}}}},{slug:"push-fanout",title:"Sending a push to everyone",difficulty:"Hard",area:"performance",domains:["messaging"],minutes:30,summary:"Fifteen lines that touch two million devices. Read the first statement, then ask what the number it returns at the end is actually counting.",brief:["A teammate has opened this as a pull request. Two million rows and a rate-limited provider, so read it for what it does to memory, to the provider, and to the people holding the phones.","Make the eleventh batch fail. Then let a device uninstall the app. Then run the job twice because the first run crashed at 80%.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something in here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Sending a push to everyone\n\nA broadcast goes to every device that has the app. This PR sends it.\n\n## Rules\n\n- Each device gets the notification once, even when the job is retried.\n- A device token the provider calls unregistered is dead. Dead tokens are\n  removed, not retried.\n- The provider takes batches of 500 and rate limits above 100 batches a\n  second. Going over means the whole batch is rejected.\n- A provider failure on one batch does not lose the rest of the send.\n- The job reports how many devices it actually reached.\n\n## Notes for the reviewer\n\n`devices` is `(user_id, token, platform, last_seen_at)` with about two million\nrows. `push.send_batch` takes up to 500 tokens and answers per token with\n`ok`, `retry` or `unregistered`.\n","src/Fanout.java":'package messaging;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** Broadcast push. */\npublic final class Fanout {\n    private static final int BATCH = 500;\n\n    public static int broadcast(String notificationId, String title, String body) {\n        List<Map<String, Object>> devices = Db.all("SELECT token FROM devices");\n        int sent = 0;\n        for (int i = 0; i < devices.size(); i += BATCH) {\n            List<String> chunk = new ArrayList<>();\n            for (Map<String, Object> d : devices.subList(i, Math.min(i + BATCH, devices.size()))) {\n                chunk.add((String) d.get("token"));\n            }\n            List<String> results = Push.sendBatch(chunk, title, body);\n            for (int n = 0; n < results.size(); n++) {\n                if (results.get(n).equals("retry")) {\n                    Push.sendBatch(List.of(chunk.get(n)), title, body);\n                }\n            }\n            sent += chunk.size();\n        }\n        return sent;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Sending a push to everyone\n\nA broadcast goes to every device that has the app. This PR sends it.\n\n## Rules\n\n- Each device gets the notification once, even when the job is retried.\n- A device token the provider calls unregistered is dead. Dead tokens are\n  removed, not retried.\n- The provider takes batches of 500 and rate limits above 100 batches a\n  second. Going over means the whole batch is rejected.\n- A provider failure on one batch does not lose the rest of the send.\n- The job reports how many devices it actually reached.\n\n## Notes for the reviewer\n\n`devices` is `(user_id, token, platform, last_seen_at)` with about two million\nrows. `push.send_batch` takes up to 500 tokens and answers per token with\n`ok`, `retry` or `unregistered`.\n","src/fanout.py":'"""Broadcast push."""\nimport db\nimport push\n\nBATCH = 500\n\n\ndef broadcast(notification_id, title, body):\n    devices = db.all("SELECT token FROM devices")\n    sent = 0\n    for i in range(0, len(devices), BATCH):\n        chunk = [d["token"] for d in devices[i : i + BATCH]]\n        results = push.send_batch(chunk, title, body)\n        for token, result in zip(chunk, results):\n            if result == "retry":\n                push.send_batch([token], title, body)\n        sent += len(chunk)\n    return {"sent": sent}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Sending a push to everyone\n\nA broadcast goes to every device that has the app. This PR sends it.\n\n## Rules\n\n- Each device gets the notification once, even when the job is retried.\n- A device token the provider calls unregistered is dead. Dead tokens are\n  removed, not retried.\n- The provider takes batches of 500 and rate limits above 100 batches a\n  second. Going over means the whole batch is rejected.\n- A provider failure on one batch does not lose the rest of the send.\n- The job reports how many devices it actually reached.\n\n## Notes for the reviewer\n\n`devices` is `(user_id, token, platform, last_seen_at)` with about two million\nrows. `push.send_batch` takes up to 500 tokens and answers per token with\n`ok`, `retry` or `unregistered`.\n","src/fanout.ts":'// Broadcast push.\nimport { db } from "./db";\nimport * as push from "./push";\n\nconst BATCH = 500;\n\nexport async function broadcast(notificationId: string, title: string, body: string) {\n  const devices = await db.all("SELECT token FROM devices");\n  let sent = 0;\n  for (let i = 0; i < devices.length; i += BATCH) {\n    const chunk = devices.slice(i, i + BATCH).map((d) => d.token);\n    const results = await push.sendBatch(chunk, title, body);\n    await Promise.all(\n      results.map((result, n) => (result === "retry" ? push.sendBatch([chunk[n]], title, body) : null)),\n    );\n    sent += chunk.length;\n  }\n  return { sent };\n}\n'}}}},{slug:"recurring-events",title:"Expanding a recurring event",difficulty:"Hard",area:"time",domains:["scheduling"],minutes:30,summary:"A series, a step, and a loop. Adding twenty-four hours to an instant is not the same as tomorrow at nine, and this month view is built on the difference.",brief:["A teammate has opened this as a pull request. Calendars are where wall-clock time and instants stop agreeing, so read every arithmetic line twice.","Take a 09:00 daily standup in Kolkata, then one in London, and run it across the last Sunday in March. Then cancel one instance.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Expanding a recurring event\n\nA calendar event repeats. This PR turns a series into the instances a month\nview needs.\n\n## Rules\n\n- A series is stored once, with a start, a rule and the zone it was created\n  in. An instance keeps the wall-clock time of the series in that zone.\n- Daylight saving moves the instant, not the wall clock: a 09:00 standup is at\n  09:00 before and after the change.\n- An instance can be cancelled or moved on its own. The series still holds the\n  rest.\n- UNTIL is inclusive: an event that runs until the 30th happens on the 30th.\n- A series with no end is expanded only as far as the window asked for.\n\n## Notes for the reviewer\n\n`series` is `(id, starts_at, rule, zone, until)`. `exceptions` is\n`(series_id, original_at, cancelled, moved_to)`. The window is two instants.\n","src/Recurrence.java":'package scheduling;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** Expanding a series into instances. */\npublic final class Recurrence {\n    private static final Map<String, Duration> STEP =\n            Map.of("daily", Duration.ofDays(1), "weekly", Duration.ofDays(7));\n    private static final int MAX_INSTANCES = 1000;\n\n    public record Instance(String seriesId, Instant at) {}\n\n    public static List<Instance> expand(String seriesId, Instant windowStart, Instant windowEnd) {\n        Map<String, Object> series =\n                Db.one("SELECT id, starts_at, rule, zone, until FROM series WHERE id = ?", seriesId);\n        List<Map<String, Object>> exceptions =\n                Db.all("SELECT original_at, cancelled, moved_to FROM exceptions WHERE series_id = ?", seriesId);\n\n        Duration step = STEP.get((String) series.get("rule"));\n        List<Instance> out = new ArrayList<>();\n        Instant at = (Instant) series.get("starts_at");\n        Instant until = (Instant) series.get("until");\n        while (at.isBefore(windowEnd) && out.size() < MAX_INSTANCES) {\n            if (!at.isBefore(windowStart)) {\n                if (until != null && at.isAfter(until)) {\n                    break;\n                }\n                out.add(new Instance(seriesId, at));\n            }\n            at = at.plus(step);\n        }\n        return out;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Expanding a recurring event\n\nA calendar event repeats. This PR turns a series into the instances a month\nview needs.\n\n## Rules\n\n- A series is stored once, with a start, a rule and the zone it was created\n  in. An instance keeps the wall-clock time of the series in that zone.\n- Daylight saving moves the instant, not the wall clock: a 09:00 standup is at\n  09:00 before and after the change.\n- An instance can be cancelled or moved on its own. The series still holds the\n  rest.\n- UNTIL is inclusive: an event that runs until the 30th happens on the 30th.\n- A series with no end is expanded only as far as the window asked for.\n\n## Notes for the reviewer\n\n`series` is `(id, starts_at, rule, zone, until)`. `exceptions` is\n`(series_id, original_at, cancelled, moved_to)`. The window is two instants.\n","src/recurrence.py":'"""Expanding a series into instances."""\nfrom datetime import timedelta\n\nimport db\n\nSTEP = {"daily": timedelta(days=1), "weekly": timedelta(days=7)}\nMAX_INSTANCES = 1000\n\n\ndef expand(series_id, window_start, window_end):\n    series = db.one("SELECT id, starts_at, rule, zone, until FROM series WHERE id = %s", (series_id,))\n    exceptions = db.all("SELECT original_at, cancelled, moved_to FROM exceptions WHERE series_id = %s", (series_id,))\n\n    step = STEP[series["rule"]]\n    out = []\n    at = series["starts_at"]\n    while at < window_end and len(out) < MAX_INSTANCES:\n        if at >= window_start:\n            if series["until"] is not None and at > series["until"]:\n                break\n            out.append({"series_id": series_id, "at": at})\n        at = at + step\n    return out\n'}},typescript:{entry:"README.md",files:{"README.md":"# Expanding a recurring event\n\nA calendar event repeats. This PR turns a series into the instances a month\nview needs.\n\n## Rules\n\n- A series is stored once, with a start, a rule and the zone it was created\n  in. An instance keeps the wall-clock time of the series in that zone.\n- Daylight saving moves the instant, not the wall clock: a 09:00 standup is at\n  09:00 before and after the change.\n- An instance can be cancelled or moved on its own. The series still holds the\n  rest.\n- UNTIL is inclusive: an event that runs until the 30th happens on the 30th.\n- A series with no end is expanded only as far as the window asked for.\n\n## Notes for the reviewer\n\n`series` is `(id, starts_at, rule, zone, until)`. `exceptions` is\n`(series_id, original_at, cancelled, moved_to)`. The window is two instants.\n","src/recurrence.ts":'// Expanding a series into instances.\nimport { db } from "./db";\n\nconst STEP_DAYS: Record<string, number> = { daily: 1, weekly: 7 };\nconst MAX_INSTANCES = 1000;\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport async function expand(seriesId: string, windowStart: Date, windowEnd: Date) {\n  const series = await db.one("SELECT id, starts_at, rule, zone, until FROM series WHERE id = $1", [seriesId]);\n  const exceptions = await db.all("SELECT original_at, cancelled, moved_to FROM exceptions WHERE series_id = $1", [\n    seriesId,\n  ]);\n\n  const stepMs = STEP_DAYS[series.rule] * DAY_MS;\n  const out: { seriesId: string; at: Date }[] = [];\n  let at = new Date(series.starts_at);\n  while (at < windowEnd && out.length < MAX_INSTANCES) {\n    if (at >= windowStart) {\n      if (series.until !== null && at > new Date(series.until)) break;\n      out.push({ seriesId, at });\n    }\n    at = new Date(at.getTime() + stepMs);\n  }\n  return out;\n}\n'}}}},{slug:"calendar-sync",title:"Syncing with an external calendar",difficulty:"Hard",area:"integrations",domains:["scheduling","devtools"],minutes:30,summary:"Fifteen lines that run every ten minutes for every connected account. The order of the two writes is the whole review.",brief:["A teammate has opened this as a pull request. It talks to somebody else’s API on a schedule, so read it for what happens when that API is slow, angry or lying.","Make the insert loop fail on the third event. Then cancel an event at the provider. Then let the provider answer 429.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Syncing with an external calendar\n\nPeople connect their work calendar so we know when they are busy. This PR\npulls changes from the provider every ten minutes.\n\n## Rules\n\n- The sync is incremental. The provider gives a token with each page, and the\n  next sync starts from it.\n- An event deleted at the provider is deleted here.\n- An event we have already seen is updated, not inserted again, even when the\n  sync is retried.\n- A sync that fails part way does not move the token forward.\n- The provider is rate limited. A 429 is respected, not retried immediately.\n\n## Notes for the reviewer\n\n`connections` is `(user_id, access_token, sync_token)`. `calendar.changes`\ntakes a token and returns `{events, next_token}`, where an event carries\n`id`, `status` (`confirmed` or `cancelled`), `starts_at` and `ends_at`.\n","src/Sync.java":'package scheduling;\n\nimport java.util.Map;\n\n/** Pulling calendar changes. */\npublic final class Sync {\n\n    public static int sync(String userId) {\n        Map<String, Object> conn =\n                Db.one("SELECT user_id, access_token, sync_token FROM connections WHERE user_id = ?", userId);\n        CalendarApi.Page page =\n                CalendarApi.changes((String) conn.get("access_token"), (String) conn.get("sync_token"));\n\n        Db.run("UPDATE connections SET sync_token = ? WHERE user_id = ?", page.nextToken(), userId);\n\n        for (CalendarApi.Event event : page.events()) {\n            Db.run("INSERT INTO busy (user_id, event_id, starts_at, ends_at) VALUES (?, ?, ?, ?)",\n                    userId, event.id(), event.startsAt(), event.endsAt());\n        }\n        return page.events().size();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Syncing with an external calendar\n\nPeople connect their work calendar so we know when they are busy. This PR\npulls changes from the provider every ten minutes.\n\n## Rules\n\n- The sync is incremental. The provider gives a token with each page, and the\n  next sync starts from it.\n- An event deleted at the provider is deleted here.\n- An event we have already seen is updated, not inserted again, even when the\n  sync is retried.\n- A sync that fails part way does not move the token forward.\n- The provider is rate limited. A 429 is respected, not retried immediately.\n\n## Notes for the reviewer\n\n`connections` is `(user_id, access_token, sync_token)`. `calendar.changes`\ntakes a token and returns `{events, next_token}`, where an event carries\n`id`, `status` (`confirmed` or `cancelled`), `starts_at` and `ends_at`.\n","src/sync.py":'"""Pulling calendar changes."""\nimport calendar_api\nimport db\n\n\ndef sync(user_id):\n    conn = db.one("SELECT user_id, access_token, sync_token FROM connections WHERE user_id = %s", (user_id,))\n    page = calendar_api.changes(conn["access_token"], conn["sync_token"])\n\n    db.run(\n        "UPDATE connections SET sync_token = %s WHERE user_id = %s",\n        (page["next_token"], user_id),\n    )\n\n    for event in page["events"]:\n        db.run(\n            "INSERT INTO busy (user_id, event_id, starts_at, ends_at) VALUES (%s, %s, %s, %s)",\n            (user_id, event["id"], event["starts_at"], event["ends_at"]),\n        )\n    return {"events": len(page["events"])}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Syncing with an external calendar\n\nPeople connect their work calendar so we know when they are busy. This PR\npulls changes from the provider every ten minutes.\n\n## Rules\n\n- The sync is incremental. The provider gives a token with each page, and the\n  next sync starts from it.\n- An event deleted at the provider is deleted here.\n- An event we have already seen is updated, not inserted again, even when the\n  sync is retried.\n- A sync that fails part way does not move the token forward.\n- The provider is rate limited. A 429 is respected, not retried immediately.\n\n## Notes for the reviewer\n\n`connections` is `(user_id, access_token, sync_token)`. `calendar.changes`\ntakes a token and returns `{events, next_token}`, where an event carries\n`id`, `status` (`confirmed` or `cancelled`), `starts_at` and `ends_at`.\n","src/sync.ts":'// Pulling calendar changes.\nimport * as calendarApi from "./calendarApi";\nimport { db } from "./db";\n\nexport async function sync(userId: string) {\n  const conn = await db.one("SELECT user_id, access_token, sync_token FROM connections WHERE user_id = $1", [userId]);\n  const page = await calendarApi.changes(conn.access_token, conn.sync_token);\n\n  await db.run("UPDATE connections SET sync_token = $1 WHERE user_id = $2", [page.next_token, userId]);\n\n  for (const event of page.events) {\n    await db.run("INSERT INTO busy (user_id, event_id, starts_at, ends_at) VALUES ($1, $2, $3, $4)", [\n      userId,\n      event.id,\n      event.starts_at,\n      event.ends_at,\n    ]);\n  }\n  return { events: page.events.length };\n}\n'}}}},{slug:"home-feed",title:"The home feed",difficulty:"Hard",area:"performance",domains:["social"],minutes:30,summary:"The first screen of the app, in twenty lines. Two of the five rules are about who must not appear, and neither is in the query.",brief:["A teammate has opened this as a pull request. This query runs on every app open, and the rules it breaks are the kind a user notices immediately.","Block somebody and scroll. Follow a private account without being accepted. Then scroll to page two while new posts arrive.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# The home feed\n\nWhat somebody sees when they open the app. This PR builds it.\n\n## Rules\n\n- The feed holds posts from accounts they follow, and public posts from\n  accounts they do not.\n- A post from a private account is only in the feed of a follower it accepted.\n- A blocked or muted account is not in the feed at all, in either direction.\n- Paging is stable: scrolling never repeats a post or skips one, even when new\n  posts arrive while somebody is reading.\n- The feed is read far more often than it is written, and it is on the app’s\n  first screen.\n\n## Notes for the reviewer\n\n`posts` is `(id, author_id, visibility, created_at)`. `follows` is\n`(follower_id, author_id, accepted)`. `blocks` is `(user_id, blocked_id)`.\nMillions of rows in each.\n","src/Feed.java":'package social;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** Building the home feed. */\npublic final class Feed {\n    private static final int PAGE = 20;\n\n    public static List<Map<String, Object>> homeFeed(String userId, int page) {\n        List<Map<String, Object>> following =\n                Db.all("SELECT author_id FROM follows WHERE follower_id = ?", userId);\n        List<Object> authorIds = new ArrayList<>();\n        for (Map<String, Object> f : following) {\n            authorIds.add(f.get("author_id"));\n        }\n\n        List<Map<String, Object>> posts = Db.all("SELECT id, author_id, body, created_at FROM posts "\n                + "WHERE author_id = ANY(?) OR visibility = \'public\' "\n                + "ORDER BY created_at DESC LIMIT ? OFFSET ?", authorIds, PAGE, (page - 1) * PAGE);\n\n        List<Map<String, Object>> out = new ArrayList<>();\n        for (Map<String, Object> post : posts) {\n            Map<String, Object> author =\n                    Db.one("SELECT id, handle, avatar_url FROM users WHERE id = ?", post.get("author_id"));\n            Map<String, Object> row = new HashMap<>(post);\n            row.put("author", author);\n            out.add(row);\n        }\n        return out;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# The home feed\n\nWhat somebody sees when they open the app. This PR builds it.\n\n## Rules\n\n- The feed holds posts from accounts they follow, and public posts from\n  accounts they do not.\n- A post from a private account is only in the feed of a follower it accepted.\n- A blocked or muted account is not in the feed at all, in either direction.\n- Paging is stable: scrolling never repeats a post or skips one, even when new\n  posts arrive while somebody is reading.\n- The feed is read far more often than it is written, and it is on the app’s\n  first screen.\n\n## Notes for the reviewer\n\n`posts` is `(id, author_id, visibility, created_at)`. `follows` is\n`(follower_id, author_id, accepted)`. `blocks` is `(user_id, blocked_id)`.\nMillions of rows in each.\n","src/feed.py":'"""Building the home feed."""\nimport db\n\nPAGE = 20\n\n\ndef home_feed(user_id, page=1):\n    following = db.all("SELECT author_id FROM follows WHERE follower_id = %s", (user_id,))\n    author_ids = [f["author_id"] for f in following]\n\n    posts = db.all(\n        "SELECT id, author_id, body, created_at FROM posts "\n        "WHERE author_id = ANY(%s) OR visibility = \'public\' "\n        "ORDER BY created_at DESC LIMIT %s OFFSET %s",\n        (author_ids, PAGE, (page - 1) * PAGE),\n    )\n\n    out = []\n    for post in posts:\n        author = db.one("SELECT id, handle, avatar_url FROM users WHERE id = %s", (post["author_id"],))\n        out.append({**post, "author": author})\n    return {"posts": out, "page": page}\n'}},typescript:{entry:"README.md",files:{"README.md":"# The home feed\n\nWhat somebody sees when they open the app. This PR builds it.\n\n## Rules\n\n- The feed holds posts from accounts they follow, and public posts from\n  accounts they do not.\n- A post from a private account is only in the feed of a follower it accepted.\n- A blocked or muted account is not in the feed at all, in either direction.\n- Paging is stable: scrolling never repeats a post or skips one, even when new\n  posts arrive while somebody is reading.\n- The feed is read far more often than it is written, and it is on the app’s\n  first screen.\n\n## Notes for the reviewer\n\n`posts` is `(id, author_id, visibility, created_at)`. `follows` is\n`(follower_id, author_id, accepted)`. `blocks` is `(user_id, blocked_id)`.\nMillions of rows in each.\n","src/feed.ts":'// Building the home feed.\nimport { db } from "./db";\n\nconst PAGE = 20;\n\nexport async function homeFeed(userId: string, page = 1) {\n  const following = await db.all("SELECT author_id FROM follows WHERE follower_id = $1", [userId]);\n  const authorIds = following.map((f) => f.author_id);\n\n  const posts = await db.all(\n    "SELECT id, author_id, body, created_at FROM posts " +\n      "WHERE author_id = ANY($1) OR visibility = \'public\' " +\n      "ORDER BY created_at DESC LIMIT $2 OFFSET $3",\n    [authorIds, PAGE, (page - 1) * PAGE],\n  );\n\n  const out = [];\n  for (const post of posts) {\n    const author = await db.one("SELECT id, handle, avatar_url FROM users WHERE id = $1", [post.author_id]);\n    out.push({ ...post, author });\n  }\n  return { posts: out, page };\n}\n'}}}},{slug:"transcode-queue",title:"Transcoding uploads",difficulty:"Hard",area:"concurrency",domains:["media"],minutes:30,summary:"A worker that spends twenty minutes per job on somebody else’s machine. Ask what is left behind when it dies at minute nineteen.",brief:["A teammate has opened this as a pull request. Jobs that run for twenty minutes fail in the middle, so read every line as though the process stops just after it.","Kill the worker during the 1080 encode, then let the queue redeliver the job. Then run two workers on the same video.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Transcoding uploads\n\nAn uploaded video is turned into three renditions. This PR is the worker that\ndoes it.\n\n## Rules\n\n- A video is transcoded once per rendition. A retried job does not re-encode\n  what is already there.\n- A job that fails leaves nothing behind: no half-written file, no temporary\n  directory, no rendition row claiming to be ready.\n- The video is playable when all three renditions are ready, and not before.\n- A job that keeps failing goes to the dead letter queue after three attempts\n  rather than blocking the queue.\n- Progress is visible while a long encode runs.\n\n## Notes for the reviewer\n\n`renditions` is `(video_id, height, status, url)`. `ffmpeg.encode` writes to a\nlocal path and can take twenty minutes. `storage.put` uploads it.\n","src/Transcode.java":'package media;\n\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.List;\nimport java.util.Map;\n\n/** The transcoding worker. */\npublic final class Transcode {\n    private static final List<Integer> HEIGHTS = List.of(360, 720, 1080);\n\n    public static int handle(Map<String, Object> job) throws Exception {\n        Map<String, Object> video = Db.one("SELECT id, source_url FROM videos WHERE id = ?", job.get("video_id"));\n        Path workdir = Files.createTempDirectory("transcode-");\n\n        for (int height : HEIGHTS) {\n            Path outPath = workdir.resolve(height + ".mp4");\n            Ffmpeg.encode((String) video.get("source_url"), outPath, height);\n            String url = Storage.put("videos/" + video.get("id") + "/" + height + ".mp4", Files.readAllBytes(outPath));\n            Db.run("INSERT INTO renditions (video_id, height, status, url) VALUES (?, ?, \'ready\', ?)",\n                    video.get("id"), height, url);\n        }\n\n        Db.run("UPDATE videos SET status = \'ready\' WHERE id = ?", video.get("id"));\n        return HEIGHTS.size();\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Transcoding uploads\n\nAn uploaded video is turned into three renditions. This PR is the worker that\ndoes it.\n\n## Rules\n\n- A video is transcoded once per rendition. A retried job does not re-encode\n  what is already there.\n- A job that fails leaves nothing behind: no half-written file, no temporary\n  directory, no rendition row claiming to be ready.\n- The video is playable when all three renditions are ready, and not before.\n- A job that keeps failing goes to the dead letter queue after three attempts\n  rather than blocking the queue.\n- Progress is visible while a long encode runs.\n\n## Notes for the reviewer\n\n`renditions` is `(video_id, height, status, url)`. `ffmpeg.encode` writes to a\nlocal path and can take twenty minutes. `storage.put` uploads it.\n","src/transcode.py":'"""The transcoding worker."""\nimport os\nimport tempfile\n\nimport db\nimport ffmpeg\nimport storage\n\nHEIGHTS = [360, 720, 1080]\n\n\ndef handle(job):\n    video = db.one("SELECT id, source_url FROM videos WHERE id = %s", (job["video_id"],))\n    workdir = tempfile.mkdtemp()\n\n    for height in HEIGHTS:\n        out_path = os.path.join(workdir, f"{height}.mp4")\n        ffmpeg.encode(video["source_url"], out_path, height)\n        url = storage.put(f"videos/{video[\'id\']}/{height}.mp4", open(out_path, "rb").read())\n        db.run(\n            "INSERT INTO renditions (video_id, height, status, url) VALUES (%s, %s, \'ready\', %s)",\n            (video["id"], height, url),\n        )\n\n    db.run("UPDATE videos SET status = \'ready\' WHERE id = %s", (video["id"],))\n    return {"renditions": len(HEIGHTS)}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Transcoding uploads\n\nAn uploaded video is turned into three renditions. This PR is the worker that\ndoes it.\n\n## Rules\n\n- A video is transcoded once per rendition. A retried job does not re-encode\n  what is already there.\n- A job that fails leaves nothing behind: no half-written file, no temporary\n  directory, no rendition row claiming to be ready.\n- The video is playable when all three renditions are ready, and not before.\n- A job that keeps failing goes to the dead letter queue after three attempts\n  rather than blocking the queue.\n- Progress is visible while a long encode runs.\n\n## Notes for the reviewer\n\n`renditions` is `(video_id, height, status, url)`. `ffmpeg.encode` writes to a\nlocal path and can take twenty minutes. `storage.put` uploads it.\n","src/transcode.ts":'// The transcoding worker.\nimport { mkdtempSync, readFileSync } from "node:fs";\nimport { tmpdir } from "node:os";\nimport { join } from "node:path";\nimport { db } from "./db";\nimport * as ffmpeg from "./ffmpeg";\nimport * as storage from "./storage";\n\nconst HEIGHTS = [360, 720, 1080];\n\nexport async function handle(job: { video_id: string }) {\n  const video = await db.one("SELECT id, source_url FROM videos WHERE id = $1", [job.video_id]);\n  const workdir = mkdtempSync(join(tmpdir(), "transcode-"));\n\n  for (const height of HEIGHTS) {\n    const outPath = join(workdir, `${height}.mp4`);\n    await ffmpeg.encode(video.source_url, outPath, height);\n    const url = await storage.put(`videos/${video.id}/${height}.mp4`, readFileSync(outPath));\n    await db.run("INSERT INTO renditions (video_id, height, status, url) VALUES ($1, $2, \'ready\', $3)", [\n      video.id,\n      height,\n      url,\n    ]);\n  }\n\n  await db.run("UPDATE videos SET status = \'ready\' WHERE id = $1", [video.id]);\n  return { renditions: HEIGHTS.length };\n}\n'}}}},{slug:"cohort-seats",title:"Enrolling into a cohort",difficulty:"Hard",area:"concurrency",domains:["edtech"],minutes:30,summary:"Seats, a waitlist and a promotion. Two people pressing enrol on the last seat is the obvious question; two people dropping at once is the interesting one.",brief:["A teammate has opened this as a pull request. Cohort seats are sold, so an oversell is a refund and a promise broken to somebody.","Fill the last seat from two browsers. Then have two students drop at the same moment. Then enrol somebody who is already on the waitlist.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Enrolling into a cohort\n\nA batch has a fixed number of seats and a waitlist. This PR enrols a student,\nand promotes from the waitlist when somebody drops.\n\n## Rules\n\n- A cohort never has more enrolments than seats.\n- When a seat frees, the person who has been waiting longest takes it, and\n  only one person takes it.\n- Dropping out after the cohort starts does not free a seat for that batch.\n- A student holds one place in a cohort, enrolled or waitlisted, not both.\n- Being promoted is told to the student; joining the waitlist is too.\n\n## Notes for the reviewer\n\n`cohorts` is `(id, seats, starts_on)`. `enrolments` is `(cohort_id,\nstudent_id, status)` where status is `enrolled` or `waitlisted`, with an\n`at` timestamp. Several instances serve requests.\n","src/Cohort.java":'package learn;\n\nimport java.util.Map;\n\n/** Enrolling and promoting. */\npublic final class Cohort {\n\n    public static String enrol(String cohortId, String studentId) {\n        Map<String, Object> cohort = Db.one("SELECT id, seats, starts_on FROM cohorts WHERE id = ?", cohortId);\n        long taken = (long) Db.one("SELECT count(*) AS n FROM enrolments WHERE cohort_id = ? AND status = \'enrolled\'",\n                cohortId).get("n");\n\n        String status = taken < (int) cohort.get("seats") ? "enrolled" : "waitlisted";\n        Db.run("INSERT INTO enrolments (cohort_id, student_id, status, at) VALUES (?, ?, ?, now())",\n                cohortId, studentId, status);\n        return status;\n    }\n\n    public static boolean drop(String cohortId, String studentId) {\n        Db.run("DELETE FROM enrolments WHERE cohort_id = ? AND student_id = ?", cohortId, studentId);\n\n        Map<String, Object> nextUp = Db.one(\n                "SELECT student_id FROM enrolments WHERE cohort_id = ? AND status = \'waitlisted\' ORDER BY at LIMIT 1",\n                cohortId);\n        if (nextUp != null) {\n            Db.run("UPDATE enrolments SET status = \'enrolled\' WHERE cohort_id = ? AND student_id = ?",\n                    cohortId, nextUp.get("student_id"));\n            Notify.send((String) nextUp.get("student_id"), "A seat opened and you are in");\n        }\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Enrolling into a cohort\n\nA batch has a fixed number of seats and a waitlist. This PR enrols a student,\nand promotes from the waitlist when somebody drops.\n\n## Rules\n\n- A cohort never has more enrolments than seats.\n- When a seat frees, the person who has been waiting longest takes it, and\n  only one person takes it.\n- Dropping out after the cohort starts does not free a seat for that batch.\n- A student holds one place in a cohort, enrolled or waitlisted, not both.\n- Being promoted is told to the student; joining the waitlist is too.\n\n## Notes for the reviewer\n\n`cohorts` is `(id, seats, starts_on)`. `enrolments` is `(cohort_id,\nstudent_id, status)` where status is `enrolled` or `waitlisted`, with an\n`at` timestamp. Several instances serve requests.\n","src/cohort.py":'"""Enrolling and promoting."""\nimport db\nimport notify\n\n\ndef enrol(cohort_id, student_id):\n    cohort = db.one("SELECT id, seats, starts_on FROM cohorts WHERE id = %s", (cohort_id,))\n    taken = db.one(\n        "SELECT count(*) AS n FROM enrolments WHERE cohort_id = %s AND status = \'enrolled\'",\n        (cohort_id,),\n    )["n"]\n\n    status = "enrolled" if taken < cohort["seats"] else "waitlisted"\n    db.run(\n        "INSERT INTO enrolments (cohort_id, student_id, status, at) VALUES (%s, %s, %s, now())",\n        (cohort_id, student_id, status),\n    )\n    return {"status": status}\n\n\ndef drop(cohort_id, student_id):\n    db.run(\n        "DELETE FROM enrolments WHERE cohort_id = %s AND student_id = %s",\n        (cohort_id, student_id),\n    )\n\n    next_up = db.one(\n        "SELECT student_id FROM enrolments WHERE cohort_id = %s AND status = \'waitlisted\' ORDER BY at LIMIT 1",\n        (cohort_id,),\n    )\n    if next_up:\n        db.run(\n            "UPDATE enrolments SET status = \'enrolled\' WHERE cohort_id = %s AND student_id = %s",\n            (cohort_id, next_up["student_id"]),\n        )\n        notify.send(next_up["student_id"], "A seat opened and you are in")\n    return {"dropped": student_id}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Enrolling into a cohort\n\nA batch has a fixed number of seats and a waitlist. This PR enrols a student,\nand promotes from the waitlist when somebody drops.\n\n## Rules\n\n- A cohort never has more enrolments than seats.\n- When a seat frees, the person who has been waiting longest takes it, and\n  only one person takes it.\n- Dropping out after the cohort starts does not free a seat for that batch.\n- A student holds one place in a cohort, enrolled or waitlisted, not both.\n- Being promoted is told to the student; joining the waitlist is too.\n\n## Notes for the reviewer\n\n`cohorts` is `(id, seats, starts_on)`. `enrolments` is `(cohort_id,\nstudent_id, status)` where status is `enrolled` or `waitlisted`, with an\n`at` timestamp. Several instances serve requests.\n","src/cohort.ts":'// Enrolling and promoting.\nimport { db } from "./db";\nimport * as notify from "./notify";\n\nexport async function enrol(cohortId: string, studentId: string) {\n  const cohort = await db.one("SELECT id, seats, starts_on FROM cohorts WHERE id = $1", [cohortId]);\n  const taken = Number(\n    (\n      await db.one("SELECT count(*) AS n FROM enrolments WHERE cohort_id = $1 AND status = \'enrolled\'", [cohortId])\n    ).n,\n  );\n\n  const status = taken < cohort.seats ? "enrolled" : "waitlisted";\n  await db.run("INSERT INTO enrolments (cohort_id, student_id, status, at) VALUES ($1, $2, $3, now())", [\n    cohortId,\n    studentId,\n    status,\n  ]);\n  return { status };\n}\n\nexport async function drop(cohortId: string, studentId: string) {\n  await db.run("DELETE FROM enrolments WHERE cohort_id = $1 AND student_id = $2", [cohortId, studentId]);\n\n  const nextUp = await db.one(\n    "SELECT student_id FROM enrolments WHERE cohort_id = $1 AND status = \'waitlisted\' ORDER BY at LIMIT 1",\n    [cohortId],\n  );\n  if (nextUp) {\n    await db.run("UPDATE enrolments SET status = \'enrolled\' WHERE cohort_id = $1 AND student_id = $2", [\n      cohortId,\n      nextUp.student_id,\n    ]);\n    await notify.send(nextUp.student_id, "A seat opened and you are in");\n  }\n  return { dropped: studentId };\n}\n'}}}},{slug:"standing-instruction",title:"Standing instructions",difficulty:"Hard",area:"money",domains:["fintech","scheduling"],minutes:30,summary:"A job that moves other people’s money on a schedule. Two columns are selected to control it and neither is read.",brief:["A teammate has opened this as a pull request. It runs unattended and transfers money, so read it for what happens on a bad day.","Run it twice for the same date. Then run it on the 30th for an instruction set to the 31st. Then run one whose account is empty, and one the customer cancelled.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Standing instructions\n\nA customer sets up a transfer that repeats: rent on the 1st, a SIP on the 5th.\nThis PR runs them.\n\n## Rules\n\n- An instruction runs once per due date. A retry of the job does not send the\n  money twice.\n- A date that does not exist in a month runs on the last day of that month.\n- If the balance is short, the instruction is marked failed for that date and\n  retried the next day, at most three times, then paused with the customer\n  told.\n- A paused or cancelled instruction does not run.\n- Dates are the customer’s calendar dates in Asia/Kolkata.\n\n## Notes for the reviewer\n\n`instructions` is `(id, from_account, to_account, amount_paise, day_of_month,\nstatus, last_run_on)`. `transfer` moves the money and raises Insufficient.\n","src/Standing.java":'package bank;\n\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.List;\nimport java.util.Map;\n\n/** Running standing instructions. */\npublic final class Standing {\n    private static final int MAX_FAILURES = 3;\n\n    public static int runDue(Instant now) {\n        int today = now.atZone(ZoneOffset.UTC).getDayOfMonth();\n\n        List<Map<String, Object>> instructions = Db.all(\n                "SELECT id, from_account, to_account, amount_paise, day_of_month, status, last_run_on "\n                        + "FROM instructions WHERE day_of_month = ?", today);\n\n        int sent = 0;\n        for (Map<String, Object> ins : instructions) {\n            Transfers.transfer((String) ins.get("from_account"), (String) ins.get("to_account"),\n                    (long) ins.get("amount_paise"));\n            Db.run("UPDATE instructions SET last_run_on = ? WHERE id = ?",\n                    now.atZone(ZoneOffset.UTC).toLocalDate(), ins.get("id"));\n            sent++;\n        }\n        return sent;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Standing instructions\n\nA customer sets up a transfer that repeats: rent on the 1st, a SIP on the 5th.\nThis PR runs them.\n\n## Rules\n\n- An instruction runs once per due date. A retry of the job does not send the\n  money twice.\n- A date that does not exist in a month runs on the last day of that month.\n- If the balance is short, the instruction is marked failed for that date and\n  retried the next day, at most three times, then paused with the customer\n  told.\n- A paused or cancelled instruction does not run.\n- Dates are the customer’s calendar dates in Asia/Kolkata.\n\n## Notes for the reviewer\n\n`instructions` is `(id, from_account, to_account, amount_paise, day_of_month,\nstatus, last_run_on)`. `transfer` moves the money and raises Insufficient.\n","src/standing.py":'"""Running standing instructions."""\nfrom datetime import datetime, timezone\n\nimport db\nfrom transfers import Insufficient, transfer\n\nMAX_FAILURES = 3\n\n\ndef run_due(now=None):\n    now = now or datetime.now(timezone.utc)\n    today = now.day\n\n    instructions = db.all(\n        "SELECT id, from_account, to_account, amount_paise, day_of_month, status, last_run_on "\n        "FROM instructions WHERE day_of_month = %s",\n        (today,),\n    )\n\n    sent = 0\n    for ins in instructions:\n        transfer(ins["from_account"], ins["to_account"], ins["amount_paise"])\n        db.run(\n            "UPDATE instructions SET last_run_on = %s WHERE id = %s",\n            (now.date(), ins["id"]),\n        )\n        sent += 1\n    return {"sent": sent}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Standing instructions\n\nA customer sets up a transfer that repeats: rent on the 1st, a SIP on the 5th.\nThis PR runs them.\n\n## Rules\n\n- An instruction runs once per due date. A retry of the job does not send the\n  money twice.\n- A date that does not exist in a month runs on the last day of that month.\n- If the balance is short, the instruction is marked failed for that date and\n  retried the next day, at most three times, then paused with the customer\n  told.\n- A paused or cancelled instruction does not run.\n- Dates are the customer’s calendar dates in Asia/Kolkata.\n\n## Notes for the reviewer\n\n`instructions` is `(id, from_account, to_account, amount_paise, day_of_month,\nstatus, last_run_on)`. `transfer` moves the money and raises Insufficient.\n","src/standing.ts":'// Running standing instructions.\nimport { db } from "./db";\nimport { transfer } from "./transfers";\n\nconst MAX_FAILURES = 3;\n\nexport async function runDue(now = new Date()) {\n  const today = now.getUTCDate();\n\n  const instructions = await db.all(\n    "SELECT id, from_account, to_account, amount_paise, day_of_month, status, last_run_on " +\n      "FROM instructions WHERE day_of_month = $1",\n    [today],\n  );\n\n  let sent = 0;\n  for (const ins of instructions) {\n    await transfer(ins.from_account, ins.to_account, ins.amount_paise);\n    await db.run("UPDATE instructions SET last_run_on = $1 WHERE id = $2", [\n      now.toISOString().slice(0, 10),\n      ins.id,\n    ]);\n    sent += 1;\n  }\n  return { sent };\n}\n'}}}},{slug:"ledger-reconcile",title:"Reconciling with the bank file",difficulty:"Hard",area:"money",domains:["fintech","analytics"],minutes:30,summary:"A hundred thousand bank lines against a ledger. The first rule says match on the reference, and the loop matches on something else.",brief:["A teammate has opened this as a pull request. Finance signs off on what this prints, and an unnoticed mismatch is money somebody has to find later.","Put two lines of ₹500 in the file. Then a line with a reference we have and an amount we do not. Then run the whole thing twice.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Reconciling with the bank file\n\nEvery morning the bank sends yesterday’s transactions. This PR matches them\nagainst our ledger and reports what does not line up.\n\n## Rules\n\n- A bank line matches a ledger row when the bank’s reference matches, not when\n  the amount happens to be the same.\n- Every line is accounted for: matched, missing from our ledger, or present in\n  our ledger and not in the file. None of the three is dropped.\n- A matched line is marked matched once. Running the reconciliation twice does\n  not change the result.\n- Amounts are paise, as integers. A difference of one paisa is a difference.\n- The file can hold a hundred thousand lines.\n\n## Notes for the reviewer\n\n`ledger` is `(id, bank_ref, amount_paise, reconciled_at)`. The file is a CSV\nof reference, amount in rupees with two decimals, and value date.\n","src/Reconcile.java":'package bank;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** Reconciling the bank file against the ledger. */\npublic final class Reconcile {\n\n    public record Result(int matched, List<String> missing) {}\n\n    public static Result reconcile(String fileText) {\n        List<String[]> rows = Csv.parse(fileText);\n        List<Map<String, Object>> ledger = Db.all("SELECT id, bank_ref, amount_paise, reconciled_at FROM ledger");\n\n        int matched = 0;\n        List<String> missing = new ArrayList<>();\n        for (String[] line : rows.subList(1, rows.size())) {\n            String ref = line[0];\n            double amountPaise = Double.parseDouble(line[1]) * 100;\n\n            Map<String, Object> hit = null;\n            for (Map<String, Object> row : ledger) {\n                if ((long) row.get("amount_paise") == amountPaise) {\n                    hit = row;\n                    break;\n                }\n            }\n\n            if (hit == null) {\n                missing.add(ref);\n                continue;\n            }\n\n            Db.run("UPDATE ledger SET reconciled_at = now() WHERE id = ?", hit.get("id"));\n            matched++;\n        }\n\n        return new Result(matched, missing);\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Reconciling with the bank file\n\nEvery morning the bank sends yesterday’s transactions. This PR matches them\nagainst our ledger and reports what does not line up.\n\n## Rules\n\n- A bank line matches a ledger row when the bank’s reference matches, not when\n  the amount happens to be the same.\n- Every line is accounted for: matched, missing from our ledger, or present in\n  our ledger and not in the file. None of the three is dropped.\n- A matched line is marked matched once. Running the reconciliation twice does\n  not change the result.\n- Amounts are paise, as integers. A difference of one paisa is a difference.\n- The file can hold a hundred thousand lines.\n\n## Notes for the reviewer\n\n`ledger` is `(id, bank_ref, amount_paise, reconciled_at)`. The file is a CSV\nof reference, amount in rupees with two decimals, and value date.\n","src/reconcile.py":'"""Reconciling the bank file against the ledger."""\nimport csv\nimport io\n\nimport db\n\n\ndef reconcile(file_text):\n    rows = list(csv.reader(io.StringIO(file_text)))\n    ledger = db.all("SELECT id, bank_ref, amount_paise, reconciled_at FROM ledger")\n\n    matched = 0\n    missing = []\n    for line in rows[1:]:\n        ref, amount, value_date = line[0], float(line[1]), line[2]\n        amount_paise = amount * 100\n\n        hit = None\n        for row in ledger:\n            if row["amount_paise"] == amount_paise:\n                hit = row\n                break\n\n        if hit is None:\n            missing.append(ref)\n            continue\n\n        db.run("UPDATE ledger SET reconciled_at = now() WHERE id = %s", (hit["id"],))\n        matched += 1\n\n    return {"matched": matched, "missing": missing}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Reconciling with the bank file\n\nEvery morning the bank sends yesterday’s transactions. This PR matches them\nagainst our ledger and reports what does not line up.\n\n## Rules\n\n- A bank line matches a ledger row when the bank’s reference matches, not when\n  the amount happens to be the same.\n- Every line is accounted for: matched, missing from our ledger, or present in\n  our ledger and not in the file. None of the three is dropped.\n- A matched line is marked matched once. Running the reconciliation twice does\n  not change the result.\n- Amounts are paise, as integers. A difference of one paisa is a difference.\n- The file can hold a hundred thousand lines.\n\n## Notes for the reviewer\n\n`ledger` is `(id, bank_ref, amount_paise, reconciled_at)`. The file is a CSV\nof reference, amount in rupees with two decimals, and value date.\n","src/reconcile.ts":'// Reconciling the bank file against the ledger.\nimport { db } from "./db";\nimport { parseCsv } from "./csv";\n\nexport async function reconcile(fileText: string) {\n  const rows = parseCsv(fileText);\n  const ledger = await db.all("SELECT id, bank_ref, amount_paise, reconciled_at FROM ledger");\n\n  let matched = 0;\n  const missing: string[] = [];\n  for (const line of rows.slice(1)) {\n    const ref = line[0];\n    const amountPaise = Number(line[1]) * 100;\n\n    const hit = ledger.find((row) => row.amount_paise === amountPaise);\n    if (!hit) {\n      missing.push(ref);\n      continue;\n    }\n\n    await db.run("UPDATE ledger SET reconciled_at = now() WHERE id = $1", [hit.id]);\n    matched += 1;\n  }\n\n  return { matched, missing };\n}\n'}}}},{slug:"prescriptions",title:"Prescriptions",difficulty:"Hard",area:"security",domains:["health"],minutes:30,summary:"Who may write one, and who may dispense against it. Two columns are selected on the dispensing path and neither is read.",brief:["A teammate has opened this as a pull request. Both halves of this decide whether somebody gets medicine they should not have.","Dispense a cancelled prescription. Then dispense the last repeat from two pharmacies at once. Then prescribe a controlled drug with three repeats.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Prescriptions\n\nA doctor writes a prescription and a pharmacy dispenses against it. This PR is\nboth sides.\n\n## Rules\n\n- Only a clinician with a live registration may prescribe, and only for a\n  patient they are treating.\n- A prescription has a dispensing window and a number of repeats. A pharmacy\n  may dispense once per repeat, inside the window.\n- A dispense is recorded before the medicine leaves the counter, and two\n  pharmacies cannot dispense the same repeat.\n- A prescription is never edited after it is issued. A change is a new\n  prescription and a cancellation of the old one.\n- Controlled medicines cannot be repeated at all.\n\n## Notes for the reviewer\n\n`prescriptions` is `(id, clinician_id, patient_id, drug_code, repeats,\nvalid_until, cancelled_at)`. `dispenses` records each one. `drugs` carries\n`controlled`.\n","src/Prescribe.java":'package health;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\n/** Writing and dispensing a prescription. */\npublic final class Prescribe {\n    private static final Duration WINDOW = Duration.ofDays(30);\n\n    public static String prescribe(String clinicianId, String patientId, String drugCode, int repeats) {\n        Map<String, Object> drug = Db.one("SELECT code, controlled FROM drugs WHERE code = ?", drugCode);\n\n        Map<String, Object> row = Db.one("INSERT INTO prescriptions (clinician_id, patient_id, drug_code, repeats, "\n                + "valid_until) VALUES (?, ?, ?, ?, ?) RETURNING id",\n                clinicianId, patientId, drugCode, repeats, Instant.now().plus(WINDOW));\n        return (String) row.get("id");\n    }\n\n    public static boolean dispense(String prescriptionId, String pharmacyId) {\n        Map<String, Object> script =\n                Db.one("SELECT id, repeats, valid_until, cancelled_at FROM prescriptions WHERE id = ?", prescriptionId);\n        long used = (long) Db.one("SELECT count(*) AS n FROM dispenses WHERE prescription_id = ?", prescriptionId)\n                .get("n");\n\n        if (used >= (int) script.get("repeats")) {\n            throw new Refused("no repeats left");\n        }\n\n        Db.run("INSERT INTO dispenses (prescription_id, pharmacy_id, at) VALUES (?, ?, now())",\n                prescriptionId, pharmacyId);\n        return true;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Prescriptions\n\nA doctor writes a prescription and a pharmacy dispenses against it. This PR is\nboth sides.\n\n## Rules\n\n- Only a clinician with a live registration may prescribe, and only for a\n  patient they are treating.\n- A prescription has a dispensing window and a number of repeats. A pharmacy\n  may dispense once per repeat, inside the window.\n- A dispense is recorded before the medicine leaves the counter, and two\n  pharmacies cannot dispense the same repeat.\n- A prescription is never edited after it is issued. A change is a new\n  prescription and a cancellation of the old one.\n- Controlled medicines cannot be repeated at all.\n\n## Notes for the reviewer\n\n`prescriptions` is `(id, clinician_id, patient_id, drug_code, repeats,\nvalid_until, cancelled_at)`. `dispenses` records each one. `drugs` carries\n`controlled`.\n","src/prescribe.py":'"""Writing and dispensing a prescription."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\n\nDEFAULT_WINDOW = timedelta(days=30)\n\n\ndef prescribe(clinician_id, patient_id, drug_code, repeats):\n    drug = db.one("SELECT code, controlled FROM drugs WHERE code = %s", (drug_code,))\n\n    row = db.one(\n        "INSERT INTO prescriptions (clinician_id, patient_id, drug_code, repeats, valid_until) "\n        "VALUES (%s, %s, %s, %s, %s) RETURNING id",\n        (clinician_id, patient_id, drug_code, repeats, datetime.now(timezone.utc) + DEFAULT_WINDOW),\n    )\n    return {"prescription_id": row["id"]}\n\n\ndef dispense(prescription_id, pharmacy_id):\n    script = db.one(\n        "SELECT id, repeats, valid_until, cancelled_at FROM prescriptions WHERE id = %s",\n        (prescription_id,),\n    )\n    used = db.one(\n        "SELECT count(*) AS n FROM dispenses WHERE prescription_id = %s",\n        (prescription_id,),\n    )["n"]\n\n    if used >= script["repeats"]:\n        raise Refused("no repeats left")\n\n    db.run(\n        "INSERT INTO dispenses (prescription_id, pharmacy_id, at) VALUES (%s, %s, now())",\n        (prescription_id, pharmacy_id),\n    )\n    return {"dispensed": True}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Prescriptions\n\nA doctor writes a prescription and a pharmacy dispenses against it. This PR is\nboth sides.\n\n## Rules\n\n- Only a clinician with a live registration may prescribe, and only for a\n  patient they are treating.\n- A prescription has a dispensing window and a number of repeats. A pharmacy\n  may dispense once per repeat, inside the window.\n- A dispense is recorded before the medicine leaves the counter, and two\n  pharmacies cannot dispense the same repeat.\n- A prescription is never edited after it is issued. A change is a new\n  prescription and a cancellation of the old one.\n- Controlled medicines cannot be repeated at all.\n\n## Notes for the reviewer\n\n`prescriptions` is `(id, clinician_id, patient_id, drug_code, repeats,\nvalid_until, cancelled_at)`. `dispenses` records each one. `drugs` carries\n`controlled`.\n","src/prescribe.ts":'// Writing and dispensing a prescription.\nimport { db } from "./db";\n\nconst WINDOW_DAYS = 30;\n\nexport async function prescribe(clinicianId: string, patientId: string, drugCode: string, repeats: number) {\n  const drug = await db.one("SELECT code, controlled FROM drugs WHERE code = $1", [drugCode]);\n\n  const validUntil = new Date(Date.now() + WINDOW_DAYS * 24 * 60 * 60 * 1000);\n  const row = await db.one(\n    "INSERT INTO prescriptions (clinician_id, patient_id, drug_code, repeats, valid_until) " +\n      "VALUES ($1, $2, $3, $4, $5) RETURNING id",\n    [clinicianId, patientId, drugCode, repeats, validUntil],\n  );\n  return { prescriptionId: row.id };\n}\n\nexport async function dispense(prescriptionId: string, pharmacyId: string) {\n  const script = await db.one("SELECT id, repeats, valid_until, cancelled_at FROM prescriptions WHERE id = $1", [\n    prescriptionId,\n  ]);\n  const used = Number(\n    (await db.one("SELECT count(*) AS n FROM dispenses WHERE prescription_id = $1", [prescriptionId])).n,\n  );\n\n  if (used >= script.repeats) throw new Refused("no repeats left");\n\n  await db.run("INSERT INTO dispenses (prescription_id, pharmacy_id, at) VALUES ($1, $2, now())", [\n    prescriptionId,\n    pharmacyId,\n  ]);\n  return { dispensed: true };\n}\n'}}}},{slug:"itinerary-change",title:"Changing a flight",difficulty:"Hard",area:"money",domains:["travel","payments"],minutes:30,summary:"Four writes and an irreversible charge, in that order. The first rule says a failure leaves the traveller on the original flight; count how many ways this leaves them on neither.",brief:["A teammate has opened this as a pull request. Read it as a sequence of steps that can stop at any point.","Make the seat claim fail after the charge. Then move to a cheaper flight. Then change a flight leaving in an hour.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Changing a flight\n\nA traveller moves to a different flight. This PR does the change.\n\n## Rules\n\n- A change is one step: the old seat is released, the new one is taken, the\n  fare difference is settled and the ticket is reissued. A failure leaves the\n  traveller on the original flight.\n- The difference is the new fare less the old fare, plus the change fee. A\n  cheaper flight does not refund the difference, only the taxes on it.\n- A change is refused inside two hours of the original departure.\n- The traveller is told the new times in the airport’s zone for each leg.\n- One change at a time per booking.\n\n## Notes for the reviewer\n\n`bookings` carry `flight_id`, `fare_paise`, `tax_paise`, `seat_no`.\n`payments.charge` and `payments.refund` are irreversible. Flights carry\n`departs_at` and the airport zones.\n","src/Change.java":'package travel;\n\nimport java.time.Duration;\nimport java.util.Map;\n\n/** Changing a booking to another flight. */\npublic final class Change {\n    private static final long CHANGE_FEE_PAISE = 150000;\n    private static final Duration CUTOFF = Duration.ofHours(2);\n\n    public static long changeFlight(String bookingId, String newFlightId, String seatNo) {\n        Map<String, Object> booking = Db.one(\n                "SELECT id, flight_id, fare_paise, tax_paise, seat_no FROM bookings WHERE id = ?", bookingId);\n        Map<String, Object> newFlight =\n                Db.one("SELECT id, fare_paise, departs_at FROM flights WHERE id = ?", newFlightId);\n\n        long difference = (long) newFlight.get("fare_paise") - (long) booking.get("fare_paise") + CHANGE_FEE_PAISE;\n        Payments.charge(bookingId, difference);\n\n        Db.run("UPDATE seats SET passenger_id = NULL WHERE flight_id = ? AND seat_no = ?",\n                booking.get("flight_id"), booking.get("seat_no"));\n        Db.run("UPDATE seats SET passenger_id = ? WHERE flight_id = ? AND seat_no = ?",\n                bookingId, newFlightId, seatNo);\n        Db.run("UPDATE bookings SET flight_id = ?, seat_no = ?, fare_paise = ? WHERE id = ?",\n                newFlightId, seatNo, newFlight.get("fare_paise"), bookingId);\n        return difference;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Changing a flight\n\nA traveller moves to a different flight. This PR does the change.\n\n## Rules\n\n- A change is one step: the old seat is released, the new one is taken, the\n  fare difference is settled and the ticket is reissued. A failure leaves the\n  traveller on the original flight.\n- The difference is the new fare less the old fare, plus the change fee. A\n  cheaper flight does not refund the difference, only the taxes on it.\n- A change is refused inside two hours of the original departure.\n- The traveller is told the new times in the airport’s zone for each leg.\n- One change at a time per booking.\n\n## Notes for the reviewer\n\n`bookings` carry `flight_id`, `fare_paise`, `tax_paise`, `seat_no`.\n`payments.charge` and `payments.refund` are irreversible. Flights carry\n`departs_at` and the airport zones.\n","src/change.py":'"""Changing a booking to another flight."""\nfrom datetime import datetime, timedelta, timezone\n\nimport db\nimport payments\n\nCHANGE_FEE_PAISE = 150000\nCUTOFF = timedelta(hours=2)\n\n\ndef change_flight(booking_id, new_flight_id, seat_no):\n    booking = db.one(\n        "SELECT id, flight_id, fare_paise, tax_paise, seat_no FROM bookings WHERE id = %s",\n        (booking_id,),\n    )\n    new_flight = db.one("SELECT id, fare_paise, departs_at FROM flights WHERE id = %s", (new_flight_id,))\n\n    difference = new_flight["fare_paise"] - booking["fare_paise"] + CHANGE_FEE_PAISE\n    payments.charge(booking_id, difference)\n\n    db.run("UPDATE seats SET passenger_id = NULL WHERE flight_id = %s AND seat_no = %s", (booking["flight_id"], booking["seat_no"]))\n    db.run("UPDATE seats SET passenger_id = %s WHERE flight_id = %s AND seat_no = %s", (booking_id, new_flight_id, seat_no))\n    db.run(\n        "UPDATE bookings SET flight_id = %s, seat_no = %s, fare_paise = %s WHERE id = %s",\n        (new_flight_id, seat_no, new_flight["fare_paise"], booking_id),\n    )\n    return {"difference_paise": difference}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Changing a flight\n\nA traveller moves to a different flight. This PR does the change.\n\n## Rules\n\n- A change is one step: the old seat is released, the new one is taken, the\n  fare difference is settled and the ticket is reissued. A failure leaves the\n  traveller on the original flight.\n- The difference is the new fare less the old fare, plus the change fee. A\n  cheaper flight does not refund the difference, only the taxes on it.\n- A change is refused inside two hours of the original departure.\n- The traveller is told the new times in the airport’s zone for each leg.\n- One change at a time per booking.\n\n## Notes for the reviewer\n\n`bookings` carry `flight_id`, `fare_paise`, `tax_paise`, `seat_no`.\n`payments.charge` and `payments.refund` are irreversible. Flights carry\n`departs_at` and the airport zones.\n","src/change.ts":'// Changing a booking to another flight.\nimport { db } from "./db";\nimport * as payments from "./payments";\n\nconst CHANGE_FEE_PAISE = 150000;\nconst CUTOFF_MS = 2 * 60 * 60 * 1000;\n\nexport async function changeFlight(bookingId: string, newFlightId: string, seatNo: string) {\n  const booking = await db.one("SELECT id, flight_id, fare_paise, tax_paise, seat_no FROM bookings WHERE id = $1", [\n    bookingId,\n  ]);\n  const newFlight = await db.one("SELECT id, fare_paise, departs_at FROM flights WHERE id = $1", [newFlightId]);\n\n  const difference = newFlight.fare_paise - booking.fare_paise + CHANGE_FEE_PAISE;\n  await payments.charge(bookingId, difference);\n\n  await db.run("UPDATE seats SET passenger_id = NULL WHERE flight_id = $1 AND seat_no = $2", [\n    booking.flight_id,\n    booking.seat_no,\n  ]);\n  await db.run("UPDATE seats SET passenger_id = $1 WHERE flight_id = $2 AND seat_no = $3", [\n    bookingId,\n    newFlightId,\n    seatNo,\n  ]);\n  await db.run("UPDATE bookings SET flight_id = $1, seat_no = $2, fare_paise = $3 WHERE id = $4", [\n    newFlightId,\n    seatNo,\n    newFlight.fare_paise,\n    bookingId,\n  ]);\n  return { differencePaise: difference };\n}\n'}}}},{slug:"group-booking",title:"Booking for a group",difficulty:"Hard",area:"concurrency",domains:["travel"],minutes:30,summary:"A loop that books six people and charges once at the end. The first rule says all or nothing, and the loop is the opposite of that.",brief:["A teammate has opened this as a pull request. Read it as a family of six booking on a phone with a flaky connection.","Let the fourth traveller fail. Then book a group of twelve. Then book six when only four seats are left in the cheapest class.","Comment where you would on a real PR. Say what is wrong, why it matters, and what you would do instead.","Something here is right. A comment on it costs you."],variants:{java:{entry:"README.md",files:{"README.md":"# Booking for a group\n\nA group of travellers books together. This PR holds the seats and takes the\npayment.\n\n## Rules\n\n- A group booking is all or nothing: either every traveller has a seat or none\n  of them does.\n- Every traveller needs a name, a date of birth and a document. An incomplete\n  traveller fails the whole booking before anything is held.\n- The fare is per traveller at the fare class available for the whole group,\n  not the cheapest one available to the first person.\n- A group over nine travellers goes to the group desk rather than booking\n  online.\n- The payment is taken once, for the total.\n\n## Notes for the reviewer\n\n`seats`, `bookings` and `payments.charge` are as elsewhere. Inventory is a\ncount per fare class on the flight.\n","src/Group.java":'package travel;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\n\n/** Booking a group. */\npublic final class Group {\n    private static final int MAX_ONLINE = 9;\n\n    public record Traveller(String name, String dob, String document) {}\n\n    public static List<String> bookGroup(String flightId, List<Traveller> travellers, String paymentToken) {\n        List<String> bookingIds = new ArrayList<>();\n        long total = 0;\n\n        for (Traveller traveller : travellers) {\n            Map<String, Object> fare = Db.one("SELECT class, price_paise FROM inventory WHERE flight_id = ? "\n                    + "AND seats_left > 0 ORDER BY price_paise LIMIT 1", flightId);\n\n            Map<String, Object> row = Db.one("INSERT INTO bookings (flight_id, name, dob, document, fare_class, "\n                    + "fare_paise) VALUES (?, ?, ?, ?, ?, ?) RETURNING id",\n                    flightId, traveller.name(), traveller.dob(), traveller.document(),\n                    fare.get("class"), fare.get("price_paise"));\n            Db.run("UPDATE inventory SET seats_left = seats_left - 1 WHERE flight_id = ? AND class = ?",\n                    flightId, fare.get("class"));\n\n            bookingIds.add((String) row.get("id"));\n            total += (long) fare.get("price_paise");\n        }\n\n        Payments.charge(bookingIds.get(0), total);\n        return bookingIds;\n    }\n}\n'}},python:{entry:"README.md",files:{"README.md":"# Booking for a group\n\nA group of travellers books together. This PR holds the seats and takes the\npayment.\n\n## Rules\n\n- A group booking is all or nothing: either every traveller has a seat or none\n  of them does.\n- Every traveller needs a name, a date of birth and a document. An incomplete\n  traveller fails the whole booking before anything is held.\n- The fare is per traveller at the fare class available for the whole group,\n  not the cheapest one available to the first person.\n- A group over nine travellers goes to the group desk rather than booking\n  online.\n- The payment is taken once, for the total.\n\n## Notes for the reviewer\n\n`seats`, `bookings` and `payments.charge` are as elsewhere. Inventory is a\ncount per fare class on the flight.\n","src/group.py":'"""Booking a group."""\nimport db\nimport payments\n\nMAX_ONLINE = 9\n\n\ndef book_group(flight_id, travellers, payment_token):\n    booking_ids = []\n    total = 0\n\n    for traveller in travellers:\n        fare = db.one(\n            "SELECT class, price_paise FROM inventory WHERE flight_id = %s AND seats_left > 0 "\n            "ORDER BY price_paise LIMIT 1",\n            (flight_id,),\n        )\n\n        row = db.one(\n            "INSERT INTO bookings (flight_id, name, dob, document, fare_class, fare_paise) "\n            "VALUES (%s, %s, %s, %s, %s, %s) RETURNING id",\n            (flight_id, traveller["name"], traveller.get("dob"), traveller.get("document"),\n             fare["class"], fare["price_paise"]),\n        )\n        db.run(\n            "UPDATE inventory SET seats_left = seats_left - 1 WHERE flight_id = %s AND class = %s",\n            (flight_id, fare["class"]),\n        )\n\n        booking_ids.append(row["id"])\n        total += fare["price_paise"]\n\n    payments.charge(booking_ids[0], total)\n    return {"bookings": booking_ids, "total_paise": total}\n'}},typescript:{entry:"README.md",files:{"README.md":"# Booking for a group\n\nA group of travellers books together. This PR holds the seats and takes the\npayment.\n\n## Rules\n\n- A group booking is all or nothing: either every traveller has a seat or none\n  of them does.\n- Every traveller needs a name, a date of birth and a document. An incomplete\n  traveller fails the whole booking before anything is held.\n- The fare is per traveller at the fare class available for the whole group,\n  not the cheapest one available to the first person.\n- A group over nine travellers goes to the group desk rather than booking\n  online.\n- The payment is taken once, for the total.\n\n## Notes for the reviewer\n\n`seats`, `bookings` and `payments.charge` are as elsewhere. Inventory is a\ncount per fare class on the flight.\n","src/group.ts":'// Booking a group.\nimport { db } from "./db";\nimport * as payments from "./payments";\n\nconst MAX_ONLINE = 9;\n\ntype Traveller = { name: string; dob?: string; document?: string };\n\nexport async function bookGroup(flightId: string, travellers: Traveller[], paymentToken: string) {\n  const bookingIds: string[] = [];\n  let total = 0;\n\n  for (const traveller of travellers) {\n    const fare = await db.one(\n      "SELECT class, price_paise FROM inventory WHERE flight_id = $1 AND seats_left > 0 " +\n        "ORDER BY price_paise LIMIT 1",\n      [flightId],\n    );\n\n    const row = await db.one(\n      "INSERT INTO bookings (flight_id, name, dob, document, fare_class, fare_paise) " +\n        "VALUES ($1, $2, $3, $4, $5, $6) RETURNING id",\n      [flightId, traveller.name, traveller.dob, traveller.document, fare.class, fare.price_paise],\n    );\n    await db.run("UPDATE inventory SET seats_left = seats_left - 1 WHERE flight_id = $1 AND class = $2", [\n      flightId,\n      fare.class,\n    ]);\n\n    bookingIds.push(row.id);\n    total += fare.price_paise;\n  }\n\n  await payments.charge(bookingIds[0], total);\n  return { bookings: bookingIds, totalPaise: total };\n}\n'}}}}],a=e=>"review/".concat(e)},89136:(e,n,t)=>{t.d(n,{Q:()=>s,v:()=>a});let s=[{id:"python",label:"Python",blurb:"Python 3.10, unittest"},{id:"typescript",label:"TypeScript",blurb:"Node 22, node:test"},{id:"java",label:"Java",blurb:"JDK 17, JUnit 5"},{id:"cpp",label:"C++",blurb:"g++, C++17, a small header-only harness"}],a=[{id:"model-1",label:"Company model 1"},{id:"model-2",label:"Company model 2"}]}}]);